'use strict';

const debugging = require('dcp/debugging').scope('wallet/keystore');
const { DCPError } = require('dcp/common/dcp-error');
const DCP_ENV = require('dcp/common/dcp-env');
const { setTimeout, clearTimeout } = require('dcp/common/dcp-timers');

const { unlockFailErrorCode } = require('dcp/dcp-client/wallet/error-codes');
const { assert } = require('dcp/common/dcp-assert');

let useWasm = true;
let secp256k1 = null;

/* Place canonical versions of ethereumjs-util and ethereumjs-wallet on
 * exports._internalEth for reference by 'friend' modules.  Try to load 
 * native (fast) versions on NodeJS, but fallback to internal modules
 * when not present. Modules are argumented with fast keccak
 * hashing code via wasm for internal use.
 */
exports._internalEth = {};

if (require('dcp/common/dcp-env').platform === 'nodejs')
{
  /* Prefer peer dependencies over webpacked versions whenever possible, 
   * because they will have native crypto via scrypt.
   */
  const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
  try
  {
    exports._internalEth.util   = requireNative('ethereumjs-util');
    exports._internalEth.wallet = requireNative('ethereumjs-wallet').default;
    exports._internalEth.buffer = requireNative('buffer');
    exports._internalEth.impl   = 'native';
    useWasm = false;  /* only disable wasm when using node AND have native util, wallet available */
  }
  catch(e)
  {
    debugging() && console.log('Could not initialize native ethereumjs libraries', e);
  }
}

if (exports._internalEth.impl !== 'native')
{
  exports._internalEth.util   = require('ethereumjs-util');
  exports._internalEth.wallet = require('ethereumjs-wallet').default;
  exports._internalEth.buffer = require('buffer');
  exports._internalEth.impl   = 'default';
}

debugging() && console.log(`using ${exports._internalEth.impl} bindings for ethereumjs`);

const dcpEth = require('./eth');
const ethUtil   = exports._internalEth.util;
const ethWallet = exports._internalEth.wallet;
const Buffer    = exports._internalEth.buffer.Buffer;

const _ConstructOnly = Symbol('Construct Only');

/** Generate a new private key */
function generateNewPrivateKey() {
  return new dcpEth.PrivateKey(ethWallet.generate().getPrivateKey());
}

/** Accept json from any foreign ethereum wallet [that we understand] and a passphrase,
 *  returning the address and private key
 *
 *  @param      json            {string}        A JSON keystore, eg. ethereum V3 wallet
 *  @param      passphrase      {string}        The passphrase to unlock the keystore
 *  @returns    {Object|undefined}              An object having properties address and privateKey,
 *                                              or undefined if it couldn't be parsed
 */
async function parseForeignKeystore(json, passphrase) {
  var fks;

  try {
    fks = await ethWallet.fromV3(json, passphrase, { nonStrict: true });
  } catch(e) {
    debugging() && passphrase && console.debug('warning: incorrect passphrase or foreign keystore not in wallet-v3 format', e);
  }

  if (!fks) try {
    fks = await ethWallet.fromV1(json, passphrase);
  } catch(e) {}

  if (!fks) try {
    fks = await ethWallet.fromEthSale(json, passphrase);
  } catch(e) {}

  return fks && {
    address: fks.address,
    privateKey: fks.getPrivateKey(),
  };
}

/**
 * This method creates functions related to locking and unlocking Keystores which share a common set
 * of private variables and are added to the keystore as own property. The private key must never be
 * stored in a variable in dcp-client which is not part of this private scope.
 *
 * @param       ks      {Object}        instance of keystore
 * @param       ew      {String}        json which represents an Ethereum V3 keystore [ethereum wallet]
 */
function KeystoreLockFunctionsFactory(ks, ew)
{
  const { Synchronizer } = require('dcp/common/concurrency');
  
  var pkScope_privateKey;              /* The private key when unlocked; falsey when locked */
  var pkScope_autoUnlockDuration;      /* lock duration when doing auto-unlock (like sudo), or falsey */
  var pkScope_relockTime;              /* when the Keystore will be considered locked again */
  var pkScope_lockTimerHnd;            /* Timer handle when we have a pending automatic relock on the event queue */
  var pkScope_unlockBusy = new Synchronizer('idle', ['idle', 'busy']); /* mutex to single-thread unlock */
  var debugLabel = ks.label || ks.address;

  function pkScope_resetLockState() {
    debugging('timer') && console.debug(`wallet - reset lock timer state on ${debugLabel}`);

    if (pkScope_lockTimerHnd)
      clearTimeout(pkScope_lockTimerHnd)
    
    pkScope_privateKey         = undefined;
    pkScope_autoUnlockDuration = 0;
    pkScope_relockTime         = 0;
    pkScope_lockTimerHnd       = undefined;
  }
  pkScope_resetLockState();

  /* Check the timer state, re-locking the Keystore as needed. It is
   * important to call this at the start of timer-sensitive operations, as
   * we can't rely on setTimeout to re-lock Keystores; we must consider the
   * possibility that starving the event loop could cause the private key
   * to be stored for longer than intended
   */
  function pkScope_lockIfTimerExpired() {
    debugging('timer') && console.log(`wallet - lockIfTimerExpired on ${debugLabel}`);
    if (pkScope_lockTimerHnd && pkScope_relockTime <= Date.now()) {
      pkScope_lock()
    }
  }
    
  /**
   * This method unlocks the Keystore object for either a single use or a given amount of time. When the 
   * object is unlocked, `getPrivateKey` and related operations do not need to ask for a passphrase, as 
   * the private key is "remembered" internally.  If time is not specified, the object will be immediately 
   * locked after the next call to `getPrivateKey`; otherwise, it will remain unlocked until the timer runs out.
   * 
   * When the unlock timer is running, calling `unlock` can have multiple effects. In all cases the current
   * running timer will be increased to lockTimerDuration if that will increase the time left.
   *   1. If the autoReset flag is true for this invocation, the autoReset duration is updated only if it
   *      will be increased. Thus autoReset is a sticky setting, it can be turned on but not off (except by locking)
   *   2. If the autoReset flag is false for this invocation, the current unlock duration is increased, but 
   *      the autoReset duration remains the same.
   * @method module:dcp/wallet.Keystore#unlock
   * @param  {string} [passphrase] Passphrase to unlock keystore. If null|undefined, `passphrasePrompt` 
   *                               function is invoked to solicit it from the user if the keystore
   *                               is not already unlocked.
   * @param  {number} lockTimerDuration Number of seconds to keep keystore unlocked for. Intended to implement features like `sudo`
   * @param  {boolean} [autoReset] Flag to determine if unlock timer should reset on subsequent calls.
   * @access public
   * @async
   * @throws Error with code 'DCP_WA:UNLOCKX' when keystore could not be unlocked.
   */
  async function pkScope_unlock(passphrase, lockTimerDuration, autoReset)
  {
    do /* spin lock to single thread this per keystore */
    {
      await pkScope_unlockBusy.until('idle');
    } while(!pkScope_unlockBusy.testAndSet('idle', 'busy'))
    try
    {
      pkScope_lockIfTimerExpired();
      if (!pkScope_privateKey)
      {
        async function pkScope_extractAndSetPrivateKey()
        {
          var fks;
          
          /* used by passphraseTries */
          function unlock_tryFn(passphrase)
          {
            if (pkScope_privateKey) /* unlocked by other "thread" - ideally would never happen... */
              return { address: ks.address, privateKey: pkScope_privateKey };
            return parseForeignKeystore(ew, passphrase);
          }

          /* used by passphraseTries */
          function unlock_skipCheckFn()
          {
            return !!pkScope_privateKey;
          };

          if (passphrase !== undefined && passphrase !== null)
            fks = await parseForeignKeystore(ew, passphrase);
          else
          {
            if (ks.checkEmpty !== false)
              fks = await parseForeignKeystore(ew, '');
            if (!fks)
              fks = await require('../wallet').passphraseTries({ label: ks.label , address: ks.address }, unlock_tryFn, unlock_skipCheckFn);
          }
          
          if (fks)
            pkScope_privateKey = new dcpEth.PrivateKey(fks.privateKey);
        }

        await pkScope_extractAndSetPrivateKey();
        if (!pkScope_privateKey)
          throw new DCPError(`Could not unlock keystore '${debugLabel}'`, unlockFailErrorCode);
      }
      assert(pkScope_privateKey);
      ks.emit('unlock');

      /* If in autoReset mode, increase the autoUnlockDuration if a longer one was specified */
      if (autoReset && lockTimerDuration > pkScope_autoUnlockDuration)
        pkScope_autoUnlockDuration = lockTimerDuration;

      /* Make this unlock expire in lockTimerDuration seconds [or later if there was a previous longer one] */
      if (lockTimerDuration >= 0)
      {
        pkScope_scheduleRelock(lockTimerDuration);
      }
      debugging('locks') && console.log(`wallet - ${debugLabel} is unlocked`);
    }
    finally
    {
      pkScope_unlockBusy.set('busy', 'idle');
    }
    return pkScope_privateKey;
  }

  /** 
   * Lock the Keystore; make private key no longer accessible without password entry.
   * @method module:dcp/wallet.Keystore#lock
   * @access public
   */
  function pkScope_lock()
  {
    let debugMsg = `wallet - lock ${debugLabel}`;
    if (pkScope_isUnlocked()) debugMsg += ' (was not locked)';
    debugging('locks') && console.log(debugMsg);
    
    pkScope_resetLockState();
    ks.emit('lock');
  }

  /**
   * Returns private key, may prompt for password. If you need this you're probably doing something wrong.
   * @method module:dcp/wallet.Keystore#getPrivateKey
   * @returns {module:dcp/wallet.PrivateKey}
   * @async
   * @access public
   */
  async function pkScope_getPrivateKey()
  {
    let pk;

    pkScope_lockIfTimerExpired();
    if (pkScope_isLocked()) {
      pk = await pkScope_unlock();
      pkScope_lock();
    } else {
      pk = pkScope_privateKey;
    
      if (pkScope_autoUnlockDuration > 0) {
        debugging('timer') && console.log(`wallet - auto reset new lock expire time on ${debugLabel} - ${pkScope_autoUnlockDuration * 1000}ms`);
        pkScope_scheduleRelock(pkScope_autoUnlockDuration);
      } else if (!pkScope_lockTimerHnd) {
        pkScope_lock();
      }
   }
    
    debugging('getPrivateKey') && console.log(`wallet - ${debugLabel} pk=${pk}`);
    return pk;
  }

  /* Schedule the next automatic lock of this keystore, overriding any earlier-firing relock
   * @param {number} newDuration     seconds until the keystore gets re-locked
   */
  function pkScope_scheduleRelock(newDuration)
  {
    var newDurationMs = newDuration * 1000;
    var next_relockTime = Date.now() + newDurationMs;

    if (next_relockTime < pkScope_relockTime)
      return;
 
    debugging('timer') && console.log(`wallet - setting lock expire time on ${debugLabel} - ${next_relockTime}s`);
    pkScope_relockTime = next_relockTime;
    if (pkScope_lockTimerHnd)
      clearTimeout(pkScope_lockTimerHnd);
    pkScope_lockTimerHnd = setTimeout(pkScope_lock, newDurationMs);
    if (DCP_ENV.platform === 'nodejs')
      pkScope_lockTimerHnd.unref();
  }

  /**
   * Is the keystore presently unlocked?
   * @method module:dcp/wallet.Keystore#isUnlocked
   * @returns {boolean}
   * @access public
   */
  function pkScope_isUnlocked() {
    return !!pkScope_privateKey;
  }

  /**
   * Is the keystore presently locked?
   * @method module:dcp/wallet.Keystore#isLocked
   * @returns {boolean}
   * @access public
   */
  function pkScope_isLocked() {
    return !pkScope_isUnlocked();
  }
  
  ks.isLocked      = pkScope_isLocked;
  ks.isUnlocked    = pkScope_isUnlocked;
  ks.unlock        = pkScope_unlock;
  ks.lock          = pkScope_lock;
  ks.getPrivateKey = pkScope_getPrivateKey;
}

/**
 * Form 1
 * 
 * A Keystore object with a randomly generated privateKey and an address
 * that corresponds to it. This form will prompt the user for a password to encrypt itself with.
 * @async
 * @returns {module:dcp/wallet.Keystore}
 * @access public
 */
/**
 * Form 2
 * 
 * A Keystore object with the provided privateKey and an address that 
 * corresponds to it. This form will prompt the user for a password to encrypt itself with.
 * @async
 * @param {string|object} privateKey an Ethereum v3 Keystore object, or privateKey in hex string format
 * @returns {module:dcp/wallet.Keystore}
 * @access public
 */
/**
 * Form 3
 * 
 * A Keystore object with the provided privateKey and an address that 
 * corresponds to it, encrypted with the provided passphrase.
 * @async
 * @param {string|object} privateKey an Ethereum v3 Keystore object, or privateKey in hex string format
 * @param {string} passphrase
 * @returns {module:dcp/wallet.Keystore}
 * @access public
 */
/**
 * Form 4
 * 
 * A Keystore object parsed from the third party object. If the third party
 * object cannot be parsed the promise will reject.
 * @async
 * @param {object} privateKey an Ethereum v3 Keystore object
 * @param {string} passphrase
 * @returns {module:dcp/wallet.Keystore}
 * @access public
 */
/**
 * Form 5
 * 
 * A Keystore object parsed from the JSON string. If the JSON or resulting
 * object cannot be parsed the promise will reject.
 * @async
 * @param {string} JsonString - a JSON encoded keystore of some sort
 * @param {string} passphrase
 * @returns {module:dcp/wallet.Keystore}
 * @access public
 */
/**
 * Form 6
 * 
 * A Keystore object parsed from the third party object. If the third party
 * object cannot be parsed the promise will reject. The user will be prompted for a passphrase.
 * @async
 * @param {object} privateKey Ethereum v3 Keystore object
 * @returns {module:dcp/wallet.Keystore}
 * @access public
 */
/**
 * Form 7
 * 
 * A Keystore object with a randomly generated privateKey and an address
 * that corresponds to it. This form will used the supplied passphrase to encrypt the private key.
 * @async
 * @param {null} key unused in this form, when null it will be generated.
 * @param {string|null} passphrase the passphrase used to encrypt the new keystore
 * @returns Promise which resolves to {module:dcp/wallet.Keystore}
 * @access public
 * @example
 * let ks = await new Keystore(null, '');
 */
exports.Keystore = function wallet$$Keystore() {
  if (arguments[0] === _ConstructOnly)
    return;

  let ctor = {}
  let ew  /* ethereum wallet: (json) backing store for encrypted private keys */
  
  /**
   * Generate JSON object literal representation of this keystore. This can later be passed to
   * the constructor to generate a new Keystore object.
   * 
 
 
   * @access public
   * @returns {object}
   * @function module:dcp/wallet.Keystore#toJSON
   */
  this.toJSON = function wallet$$Keystore$toJSON() {
    let base = Object.assign({}, ctor.ks || JSON.parse(ew));

    if (this.label)
      base.label = this.label;
      
    base.timestamp = String(new Date());
    
    if (require('dcp/common/dcp-env').isBrowserPlatform)
    {
      const url = document.currentScript ? new URL(document.currentScript.src) : window.location
      base.process = url.origin + url.pathname;
    }
    else
    {
      if (require.main?.filename)
        base.process = require('path').basename(require.main.filename, '.js');
    }

    return base;
  }

  return (async () => {
    const { promptCreatePassphrase } = require('../wallet');
    
    if (arguments.length >= 2)
      ctor.passphrase = arguments[1]                              /* all forms which accept passphrases */
      
    if (arguments.length === 3)
      ctor.checkEmpty = arguments[2]                              /* for get form 4, setting checkempty to false */
    
    if (arguments.length === 0) {
      ctor.privateKey = generateNewPrivateKey();                  /* form 1 */
      this.address = ctor.privateKey.toAddress();
      const metaData = {
        label: "New key",
        address: this.address,
      };
      ctor.passphrase = await promptCreatePassphrase(metaData);
    }
    else if (arguments[0] === null)                               /* form 7 */
      ctor.privateKey = generateNewPrivateKey();
    else if (dcpEth.PrivateKey(arguments[0], true)) {            /* form 2, 3 */
      ctor.privateKey = new dcpEth.PrivateKey(arguments[0]);
      this.address = ctor.privateKey.toAddress();
      if (ctor.passphrase === false)
        ctor.passphrase = '';
      if (typeof ctor.passphrase === 'undefined') {
        const metaData = {
          label: "New key",
          address: this.address,
        };
        ctor.passphrase = await promptCreatePassphrase(metaData);       
      }
    }
    else if (arguments[0] instanceof exports.Keystore) {          /* form 6 */
      ctor.privateKey = await arguments[0].getPrivateKey();
      ew = JSON.stringify(arguments[0]);
    }
    else if (typeof arguments[0] === 'string' ||
             typeof arguments[0] === 'object') {                  /* form 4, 5 */
      let jsonO

      if (typeof arguments[0] === 'object') {     /* form 4 */
        ew = JSON.stringify(arguments[0])
        jsonO = arguments[0]
      } else {                                    /* form 5 */
        ew = arguments[0]
        jsonO = JSON.parse(ew.trim())
      }
      if (jsonO.address)
        this.address = new dcpEth.Address(jsonO.address)
      else {
        let fks
        
        if (ctor.passphrase)
          fks = await parseForeignKeystore(ew, ctor.passphrase)
        else {
          if (ctor.checkEmpty !== false)
            fks = await parseForeignKeystore(ew, '')
          if (!fks)
          {
            /* ks has password */
            let metaData = { label: jsonO.label || jsonO.id };
            fks = await require('../wallet').passphraseTries(metaData,
                                        async function wallet$$Keystore$Constructor$unlock_tryFn(passphrase) {
                                          await parseForeignKeystore(ew, passphrase)
                                        })
          }
        }

        if (!fks)
          throw new DCPError(`Could not unlock foreign keystore ${jsonO.label || jsonO.id} to determine public address`, unlockFailErrorCode);
        this.address = fks.address
      }
      if (jsonO.label)
        this.label = jsonO.label
    }

    /* By the bottom of this funnel, we have the 
     * - defined this.address
     * - dcpEth.PrivateKey or a ethereum wallet (JSON string)
     * - passphrase or '' if making a Keystore from a dcpEth.PrivateKey
     *
     * Now we make sure that we can find the private key by unlocking ew, 
     * have an address, and forget the private key
     */
    if (!ew) {
      let buf = ethUtil.toBuffer(ctor.privateKey);
      let i = ethWallet.fromPrivateKey(buf);
      ew = await i.toV3String(ctor.passphrase || '', { n: 1024 });
    }
    if (ctor.privateKey && !this.address) {
      this.address = ctor.privateKey.toAddress()
    }
    this.checkEmpty = ctor.checkEmpty;
    delete ctor.privateKey
    delete ctor.passphrase
    KeystoreLockFunctionsFactory(this, ew)

    return this
  })()
}

