/**
 * Creates and returns stringification of SignedMessageObject in the format:
 *       JSON.stringify({ owner: this.address, signature: signature, body: messageBody })
 * @async
 * @access public
 * @param {object} messageBody 
 * @returns {Promise<string>}
 * @function module:dcp/wallet.Keystore#makeSignedMessage
 */
exports.Keystore.prototype.makeSignedMessage = async function wallet$$Keystore$makeSignedMessage(messageBody) {
  return JSON.stringify(await this.makeSignedMessageObject(messageBody));
}

/** @typedef {object} SignedMessageObject
 * @property {object} body
 * @property {Signature} signature
 * @property {module:dcp/wallet.Address} owner
 */

/**
 * Creates and returns stringification of SignedMessageObject in the format:
 *       { owner: this.address, signature: signature, body: messageBody }
 * @async
 * @access public
 * @param {object} messageBody 
 * @returns {Promise<SignedMessageObject>}
 * @function module:dcp/wallet.Keystore#makeSignedMessageObject
 */
exports.Keystore.prototype.makeSignedMessageObject = async function wallet$$Keystore$makeSignedMessageObject(messageBody) {
  const signature = await this.makeSignature(messageBody);
  return { owner: this.address, signature: signature, body: messageBody };
}

/** @typedef {object} SignedLightWeightMessageObject
 * @property {object} body
 * @property {object} auth
 * @property {Signature} signature
 * @property {module:dcp/wallet.Address} owner
 */
  
/**
 * Creates and returns SignedLightWeightMessageObject in the format:
 *       { owner: this.address, signature: signature, auth: messageLightWeight, body: messageBody };
 * The signature is computed only on messageLightWeight, in order to improve perf when messageBody is large.
 * @async
 * @access public
 * @param {object} messageLightWeight 
 * @param {object} messageBody 
 * @returns {Promise<SignedLightWeightMessageObject>}
 * @function module:dcp/wallet.Keystore#makeSignedLightWeightMessageObject
 */
exports.Keystore.prototype.makeSignedLightWeightMessageObject = async function wallet$$Keystore$makeSignedLightWeightMessageObject(messageLightWeight, messageBody) {
  const signature = await this.makeSignature(messageLightWeight);
  return { owner: this.address, signature: signature, auth: messageLightWeight, body: messageBody };
}
  
/** @typedef {object} Signature
 * @property {Uint8Array} r
 * @property {Uint8Array} s
 * @property {Uint8Array} v
 */

/**
 * Creates and returns signature for messageBody
 *       { owner: this.address, signature: signature, auth: messageLightWeight, body: messageBody };
 * The signature is computed only on messageLightWeight, in order to improve perf when messageBody is large.
 * @async
 * @access public
 * @param {object} messageBody 
 * @returns {Promise<Signature>}
 * @function module:dcp/wallet.Keystore#makeSignature
 */
exports.Keystore.prototype.makeSignature = async function wallet$$Keystore$makeSignature(messageBody)
{
  if (typeof messageBody !== 'string') {
    messageBody = JSON.stringify(messageBody);
  }
  const privateKey = await this.getPrivateKey();

  if (useWasm && !secp256k1) {
    const { instantiateSecp256k1 } = await import('@bitauth/libauth');  
    secp256k1 = await instantiateSecp256k1();
    debugging() && console.log('initialized libauth secp256k1 code');
  } 
  const signFn = useWasm ? exports.ecsign : ethUtil.ecsign;
  const signature = signFn(ethUtil.hashPersonalMessage(Buffer.from(messageBody)), ethUtil.toBuffer(privateKey.toString()));
  
  return signature;
}

/**
 * IdKeystore is a class for holding keystores that describe identities.
 *
 * See {@link module:dcp/wallet.Keystore|Keystore constructor} for documentation on all the ways to call this constructor.
 * @classdesc Subclass of {@link module:dcp/wallet.Keystore|Keystore}
 * @class IdKeystore
 * @async
 * @extends module:dcp/wallet.Keystore
 * @access public
 */
exports.IdKeystore = function wallet$$IdKeystore(privateKey, passphrase) { 
  return this.constructor.prototype.constructor.apply(this, arguments);
}

/**
 * AuthKeystore is s class for holding keystores that describe authorizations to do things.
 *
 * See {@link module:dcp/wallet.Keystore|Keystore constructor} for documentation on all the ways to call this constructor.
 * @classdesc Subclass of {@link module:dcp/wallet.Keystore|Keystore}
 * @class AuthKeystore
 * @async
 * @extends module:dcp/wallet.Keystore
 * @access public
 */
exports.AuthKeystore = function wallet$$AuthKeystore(privateKey, passphrase) {
  return this.constructor.prototype.constructor.apply(this, arguments);
}

/**
 * BankAccountKeystore is a class for holding keystores that describe bank accounts.
 * Knowing the private key implicitly grants authorization to do everything related to 
 * the bank account.
 *
 * It inherits from Keystore.
 */
exports.BankAccountKeystore = function wallet$$BankAccountKeystore(privateKey, passphrase) {
  return this.constructor.prototype.constructor.apply(this, arguments);
}

exports.IdKeystore.prototype = new exports.Keystore(_ConstructOnly);
exports.AuthKeystore.prototype = new exports.Keystore(_ConstructOnly);
exports.BankAccountKeystore.prototype = new exports.Keystore(_ConstructOnly);

if (require('dcp/common/dcp-env').platform === 'nodejs')
{
  const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
  const inspect = requireNative('util').inspect.custom;
  exports.Keystore.prototype[inspect]            = function() { return `[Keystore ${           this.isLocked() ? 'l' : 'u'} ${this.address} (${this.label})]` };
  exports.IdKeystore.prototype[inspect]          = function() { return `[IdKeystore ${         this.isLocked() ? 'l' : 'u'} ${this.address} (${this.label})]` };
  exports.AuthKeystore.prototype[inspect]        = function() { return `[AuthKeystore ${       this.isLocked() ? 'l' : 'u'} ${this.address} (${this.label})]` };
  exports.BankAccountKeystore.prototype[inspect] = function() { return `[BankAccountKeystore ${this.isLocked() ? 'l' : 'u'} ${this.address} (${this.label})]` };
}

exports.ecsign = async function (msgHash, privateKey) {
  var sig = secp256k1.signMessageHashRecoverableCompact(privateKey, msgHash);
  sig.signature = Buffer.from(sig.signature, 'Uint8Array');

  var ret = {};
  ret.r = sig.signature.slice(0, 32);
  ret.s = sig.signature.slice(32, 64);
  ret.v = sig.recoveryId + 27;
  
  return ret;
}; 
