const utils = require('./utils');
const { setTimeout } = require('dcp/common/dcp-timers');

exports.config = {
  id: 'dcp-modal-password',
  required: ['dcp-modal-password-form', 'dcp-modal-password-hidden-username', 'dcp-modal-password-prompt', 'dcp-modal-password-input'],
  path: "./templates/password-entry-modal.html",
};

/**
 * @param {string} username The hidden username provided to give a hint to password managers.
 * @param {string} label We expect and use the label property to identify which thing this password is associated to.
 * @throws If modal is closed without the form being submitted (submitting the form closes the modal).
 */
exports.passwordEntry = async function (username, label, maxTries, tryPassphrase, onClose=null)
{
  const [elements, formPromise] = await utils.initModal(exports.config, onClose);
  let [modal, form, hiddenUsername, prompt, passwordInput] = elements;

  hiddenUsername.value = username;
  prompt.innerHTML = `Enter passphrase for <span style="color:#1aa473"><i>${label}</i></span><br>`;

  const submitHandler = function(e)
  {
    setTimeout(function(){
      history.replaceState(null, document.title); // This should signal to the browser that the login was successful.
    }, 1);
  };

  // Don't overwrite the existing event handler!
  let existingSubmitHandler = form.onsubmit;
  form.onsubmit = async function(e)
  {
    // waiting for password validation promise to resolve
    const passwordIsValid = await tryPassphrase(passwordInput.value);
    if (passwordIsValid)
    {
      submitHandler(e);
      existingSubmitHandler(e);
    }
    else
    {
      prompt.innerHTML = `Incorrect passphrase for <span style="color:#1aa473"><i>${label}</i></span><br><span style="color:#b83b33;text-align:center;">Please try again.</span>`;
      passwordInput.focus();
    }
    form.reset();
  };
  
  passwordInput.focus();
  await formPromise;

  // At this point, form validation has ensured that the last pasword entered was correct,
  // and this password was passed out of the modal via tryPassphrase.

  utils.MicroModal.close(modal.id);
}
