/**
 * @file        http-bearer.js
 *              Utility code for transports working with http (or https) bearers
 *
 * @author      Wes Garland, wes@kingsds.network
 * @date        Apr 2022
 */
'use strict';
const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
const debugging         = require('dcp/debugging').scope('dcp');

/**
 * Returns true if friendLocation should work in place of location from this host.
 * This allows us to transparently configure inter-daemon communication that uses
 * local LAN IPs instead of bouncing off the firewall for NAT.
 */
exports.a$isFriendlyUrl = async function httpBearer$$isFriendlyUrl(url)
{
  var remoteIp, dnsA;
  var ifaces;
  
  if (!url)
    return false;
  
  if (url.hostname === 'localhost')
    return true;

  switch(url.protocol)
  {
    case 'http:':
    case 'https:':
    case 'ws:':
    case 'tcp:':
    case 'udp:':
    case 'dcpsaw:':
      break;
    default:
      return false;
  }

  /* Consider same-origin match friendly */
  if (require('dcp/common/dcp-env').isBrowserPlatform)
    return url.origin === window.location.origin;

  /* Convert an IP address to a 32-bit int in network order */
  function i32(addr)
  {
    var ret = 0;
    var octets = addr.split('.');

    ret |= octets[0] << 24; /* Note: JS ints are signed 32, but that doesn't matter for masking */
    ret |= octets[1] << 16;
    ret |= octets[2] <<  8;
    ret |= octets[3] <<  0;

    return ret;
  }
  
  /* Consider machines in same IPv4 subnet friendly */
  dnsA = await requireNative('dns').promises.lookup(url.hostname, { family: 4 });
  if (!dnsA)
    return false;
  remoteIp = i32(dnsA.address);
  ifaces = requireNative('os').networkInterfaces();
  for (let ifaceName of Object.keys(ifaces))
  {
    for (let alias of ifaces[ifaceName])
    {
      if (alias.family !== 'IPv4')
        continue;

      let i32_addr = i32(alias.address);
      let i32_mask = i32(alias.netmask);

      if ((i32_addr & i32_mask) === (remoteIp & i32_mask))
        return true;
    }
  }

  return false;
}

/**
 * Factory which create instances of Server for targets/listeners, suitable for binding to
 * transports which use an underlying http (or https) bearer.
 *
 * @param {object}      config                  the configuration object for the listener; must have
 *                                              either a location (or ideally) a listen property which
 *                                              is an instance of URL or DcpURL.
 * @param {function}    listeningHandler        [optional] a function which is invoked as soon as the
 *                                              underlying server is listening for new connections. It
 *                                              receives as its sole argument an instance of Server.
 */
exports.httpServerFactory = function(config, listeningHandler)
{
  var bearer;
  var listen = config.listen || config.location;

  const listenOpts = {
    host: listen.hostname,
    port: listen.port
  };

  switch (listen.protocol)
  {
    case 'http:':
      bearer = requireNative('http');
      listenOpts.port = listenOpts.port || 80;
      break;
    case 'https:':
      bearer = requireNative('https');
      listenOpts.port = listenOpts.port || 443;
      break;
    default:
      throw new Error(`unknown bearer: '${listen.protocol}'`)
  }

  if (listenOpts.host === 'inaddr_any' || !listenOpts.host)
    delete listenOpts.host;
  if (listenOpts.host === 'localhost')
    listenOpts.host = '::'; /* transparently support IPv4 and IPv6 link-local addresses */
  
  debugging('http') && console.debug('creating http server for', listenOpts);
  const server = bearer.createServer();
  server.listen(listenOpts, () => {
    debugging() && console.debug('http server listening on', server.address().address + ':' + server.address().port);
    listeningHandler(server);
  });

  return server;
}
