/**
 * @file        transient-connections.js
 *
 *              Centralized management of transient DCP connections used on an ad-hoc basis by the
 *              process, eg those opened by dcp-client Compute API calls.
 *
 *              This code counts on event-emission order in the dcp Connection class -- specifically,
 *              that when the Connection class calls its `emit` even that the event handler is invoked
 *              immediateoy ("synchronously"), rather than on the next pass of the event loop.
 *
 * @author      Wes Garland, wes@distributive.network
 * @date        Nov 2022
 */
'use strict';

const protocol = require('dcp/protocol-v4');
const { assert } = require('dcp/common/dcp-assert');
const { setTimeout, clearTimeout } = require('dcp/common/dcp-timers');

const debugging = require('dcp/debugging').scope('transient-connections');
const tcStateMemos = {};
const defaultTimeout = 10;

/**
 * Factory to create a transient connection for a given service.  A transient connection is always ready
 * to transmit messages, but may not always have an underlying DCP or TCP connection. Connections are
 * created and destroyed based on demand. Messages to the same service are not guaranteed to be
 * delivered on the same connection, unless they are sent in the same pass of the event loop. Messages
 * which cannot be sent are rejected per usual DCP semantics. This usually means that the target is
 * currently unavailable (and retrying immediately is unlikely to succeed).
 * 
 * Only one transient connection per origin+pathname is supported.
 */
function makeTransientConnection(serviceConfig, serviceName, stateMemo, timeout)
{
  var timer;
  const timeoutMs = timeout * 1000;
  
  prepareNewConnection();
  return;

  /**
   * Prepare an instance of Connection for use via getConnection(). 
   */
  function prepareNewConnection()
  {
    stateMemo.preparedDate = new Date();
    stateMemo.connection = new protocol.Connection(serviceConfig);

    const connection = stateMemo.connection;
    connection.on('end',          tc$endHandler);
    connection.on('beforeSend',   tc$beforeSendHandler);
    connection.on('send',         tc$sendHandler);
    connection.on('recvResponse', tc$responseHandler);
  }

  function finalizeConnection(connection)
  {
    connection.off('end',          tc$endHandler);
    connection.off('beforeSend',   tc$beforeSendHandler);
    connection.off('send',         tc$sendHandler);
    connection.off('recvResponse', tc$responseHandler);
  }

  /**
   * Schedule or reschedule the close attempt.
   */
  function scheduleCloseAttempt(rescheduleOnly)
  {
    const nextCloseTimeMs = Date.now() + timeoutMs;

    if (!timer && rescheduleOnly)
      return;
    
    if (!timer || !(nextCloseTimeMs < stateMemo.closeTimeMs)) /* Previous timer is longer than this one */
    {
      stateMemo.closeTimeMs = nextCloseTimeMs;
      clearTimeout(timer);
      const connection = stateMemo.connection;
      timer = setTimeout(() => tc$closeIfNotActive(connection), timeoutMs);
      timer.unref();
    }

    debugging() && console.debug('tc - next close attempt in', (stateMemo.closeTimeMs - Date.now()) + 'ms');
  }

  /**
   * This handler is triggered in the same event loop pass as the invocation of the send
   * method. We reschedule any pending close attempts forward in case the close timer fires
   * right while we are off in async-land signing messages etc.  There is a small race here
   * if the timeout is so short we don't have time to send the message, but that can be
   * safely ignored in the real world.
   */
  function tc$beforeSendHandler(message)
  {
    scheduleCloseAttempt(true);
  }
  
  /**
   * Observe the transmission of a message, and memoize it so that we can pair up its response.
   * Future versions may just memoize a flag instead of the whole message to let the GC collect
   * more eagerly, but this version keeps a reference to the whole message to ease debugging.
   *
   * It is possible for the same message to be transmitted more than once due to the retry
   * algorithm. In this case, it will have the same message id and be the same message object.
   * We do not memoize the need for a response more than once in this case.
   */
  function tc$sendHandler(message)
  {
    assert(this === stateMemo.connection);

    if (stateMemo.active.hasOwnProperty(message.id))
    {
      debugging() && console.debug(`${serviceName} ${this.dcpsid} retransmitted ${message.id}`);
      assert(message === stateMemo.active[message.id]);
    }

    debugging() && console.debug(`tc - sending ${message.id}`);
    stateMemo.active[message.id] = message;
    debugging('active') && console.debug('+', message.id, Object.keys(stateMemo.active).length);
  }

  /**
   * Observe the receipt of the response to a message, and clear the message memo. Then,
   * observe the transition from 'responses pending' to 'no responses pending' and when
   * that happens, start the idle timer. When the idle is hit, we will shut down the
   * connection and replace it with one that is not yet connected.  Future versions of
   * this code might instead to elect to put the Connection in "disconnected" state rather
   * than doing full DCP session setup and teardown.
   *
   * This handler will trip more often than the send handler at the momemnt, because the two
   * events are not completely aligned at the protocol layer; the response event triggers on
   * multiple message types.
   */
  function tc$responseHandler(message)
  {
    debugging() && console.debug(`tc - response for ${message.id}; in memo=`, message.id in stateMemo.active);
    delete stateMemo.active[message.id];
    debugging('active') && console.debug('-', message.id, Object.keys(stateMemo.active).length);

    if (Object.keys(stateMemo.active).length === 0)
      scheduleCloseAttempt();
  }

  /**
   * Observe the closing of a DCP Connection which is or was a transient connection. API consumers
   * should not be closing these transient connections directly, but if they do, we get another one
   * ready.
   */
  function tc$endHandler()
  {
    const connection = stateMemo.connection;
    debugging() && console.debug(`${serviceName} ${this.dcpsid} closed,`, this === connection ? Object.keys(stateMemo.active) : '(retired)');
    if (this === connection)
      prepareNewConnection();
    finalizeConnection(this);
  }

  /**
   * Timer callback which closes a connection if it's not active.  When this happens, another one
   * is immediate prepared for use.
   */   
  function tc$closeIfNotActive()
  {
    if (Object.keys(stateMemo.active).length !== 0)
      return; /* still active - must have an event-firing race */

    debugging() && console.debug(`${serviceName} not active, closing ${stateMemo.connection.dcpsid}`);
    
    const oldConnection = stateMemo.connection;
    prepareNewConnection();
    finalizeConnection(oldConnection);
    setImmediate(() => oldConnection.close());
  }
}

/**
 * Get a transient Connection for a given service config. The connection may be shared
 * among other passes of the event loop, etc, however the return value of this function
 * MUST be on the same pass of the event loop as when it was acquired; otherwise the
 * behaviour is undefined.
 *
 * @example 
 *   await getTransientConnection(dcpConfig.scheduler.services.jobSubmit).send(message);
 *
 * @param {object} serviceConfig        a dcpConfig fragrament (or similar object) suitable for use as
 *                                      the target parameter of the dcp::Connection() constructor.
 * @param {number} timeout              [otional] the number of seconds to wait after the Connection
 *                                      becomes idle before we close it.
 * @returns instance of Connection. Do not cache the return value of this function!
 */
exports.getTransientConnection = function computeApi$$getTransientConnection(serviceConfig, timeout)
{
  const serviceName = serviceConfig.location.origin + serviceConfig.location.pathname;
  
  if (!tcStateMemos[serviceName])
  {
    tcStateMemos[serviceName] = {
      creationDate: new Date(),
      connection:   undefined,
      active:       { /* messages by id */ },
    };
    makeTransientConnection(serviceConfig, serviceName, tcStateMemos[serviceName], timeout || defaultTimeout);
  }
  
  return tcStateMemos[serviceName].connection;
}

exports.__state = tcStateMemos; /* debug only */
