    if (!this.hasOwnProperty(LISTENERS))
    {
      this[LISTENERS] = {}; /* must not be moved to ctor! */
      if (debugBuild && !this.breakpointEvents)
        this.breakpointEvents = {};
    }
    
    eventName = sanitizeEventName(eventName);
    if (!this[LISTENERS].hasOwnProperty(eventName))
      this[LISTENERS][eventName] = [];

    if (typeof eventHandler !== "function")
      throw new Error("eventHandler is not a function");

    this[LISTENERS][eventName].push(eventHandler);
    this.emit("newListener", eventName, eventHandler);
