const utils = require('./utils');
const { confirm } = require('./confirm');
const passwordModule = require('./passwordEntry');

exports.config = {
  id: 'dcp-modal-oauth-login',
  required: ['dcp-modal-oauth-login-form'],
  path: "./templates/oauth-login-modal.html",
  eagerLoad: [passwordModule.config]
};

/**
* @param {Object} options From `wallet.get_internal`
* @param {string} options.name - The name of the keystore type (wallet.get => 'default' and wallet.getId => 'id').
* @param {string} options.contextId - An optional, user-defined identifier used for caching keystores.
*                                     See `job.contextId` in the compute-api spec.
* @param {string} options.jobName - A user-defined job property provided to identify this job.
* @param {string} options.msg - Optional string denoting the purpose for fetching the keystore
* @param {function} [onClose] Override default onClose behavior. An instance of `modal` is handed to the function.
* @throws If modal is closed without the form being submitted (submitting the form closes the modal).
* @returns {string} contents of Keystore file
* @memberof module:dcp/client-modal
* @access public
* @async
* @alias getKeystoreFile
*/
exports.oauthLogin = async function (options, onClose=null) {
  const storageKey = `dcp-keystore-${options.name}-${options.contextId}`;
  
  let jobName = options.jobName;
  if (jobName) {
    jobName = `"${jobName}"`;
  } else {
    jobName = 'this job';
  }

  const keystoreType = "DCP Bank Account";

  let keystoreMsg = options.msg;

  let keystoreFile = await getKeystoreFromStorage(storageKey, jobName, onClose);
  if (!keystoreFile) {
    // currently only anonymous oauth access is implemented in this version
    keystoreFile = await anonGetKeystoreFromPopup(keystoreType, jobName, storageKey, onClose, keystoreMsg);
  }

  return keystoreFile;
};

/**
* Alert user that a key from storage will be used, give them a chance to ditch it.
* @param {string} storageKey key in local or session storage where the file is stored
* @param {string} jobName helps user know which key is retrieved from storage
* @returns {string} contents of Keystore file
*/
async function getKeystoreFromStorage (storageKey, jobName) {
  let keystoreFile = sessionStorage.getItem(storageKey);
  if (keystoreFile) return keystoreFile;
  
  keystoreFile = localStorage.getItem(storageKey);
  if (keystoreFile) {
    let ks = JSON.parse(keystoreFile);
    let label = ks.label || ks.address;
    let prompt;
    // alert is not necessarily for a job, specify jobname only if there is an actual job
    if(jobName)
      prompt = `You have keystore "${label}" saved for ${jobName}. Do you want to use it?`;
    else
      prompt = `You have keystore "${label}". Do you want to use it?`;
    let opts = { positive: "Yes", negative: "No", title: 'Keystore File' };
    let confirmation = await confirm(prompt, opts);
    if (confirmation) {
      sessionStorage.setItem(storageKey, keystoreFile)
      return keystoreFile;
    }
    localStorage.removeItem(storageKey);
    return false;
  };
};

/**
* Bring up anonymous (unregistered, default permissions) login prompt modal in browser
* @param {string} keystoreType Help user know whether to upload an identity or bank or whatever keystore.
* @param {string} jobName Help user identify the job this key will be used on.
* @param {string} storageKey Store the key in local/session storage under this key.
* @param {string} msg Custom message for the modal that specifies the purpose for providing a keystore
* @throws If modal is closed without the form being submitted (submitting the form closes the modal).
*/
async function anonGetKeystoreFromPopup (keystoreType, jobName, storageKey, onClose, msg) {
  if (!onClose) {
    onClose = ()=>{};
  }

  const [elements, formPromise] = await utils.initModal(exports.config, onClose);
  const [modal, form, prompt, fileInput] = elements;
  
  const loginBtn = document.getElementById('dcp-modal-oauth-login-button');
  // make button open a popup with the configured oauth server's reflector page
  loginBtn.onclick = () => window.open(dcpConfig.oAuth.location.resolve('/reflector'), 'DCP Login', 'popup=yes,left=200,top=200,width=400,height=360');
  
  let loginks = 'none';
  
  // wait for a message back from the popup with the bank account keystore
  await new Promise((resolve) => {
    window.addEventListener('message', function anonGetKeystoreFromPopup$$handleMessage(event) {
      // make sure it is coming from the reflector window
      if (event.origin && dcpConfig.oAuth.location.sameOrigin(event.origin)) 
      {
        loginks = event.data;
        window.removeEventListener('message', anonGetKeystoreFromPopup$$handleMessage);
        resolve();
      }
    });
  });
  
  const keystoreFile = loginks;
  
  utils.MicroModal.close(modal.id);
  return keystoreFile;
};
