const util = require('dcp/utils');

/** @typedef {import('./slice').Slice} Slice       */
/** @typedef {import('./sandbox').Sandbox} Sandbox */

/**
 *  Sandbox and Slice debugging and logging tools.
 *    dumpSlices               -- dump array of slices
 *    dumpSandboxes            -- dump array of sandboxes
 *    dumpSlicesIfNotUnique    -- dump array of slices when there are dups
 *    dumpSandboxesIfNotUnique -- dump array of sandboxes when there are dups
 *    isUniqueSlices           -- detect dups in an array of slices
 *    isUniqueSandboxes        -- detect dups in an array of sandboxes
 *********************************************************************************************/

/**
 * Log sliceArray.
 * @param {Slice[]} sliceArray
 * @param {string}  [header]
 */
exports.dumpSlices = function utils$$dumpSlices(sliceArray, header) {
  if (header) console.log(`\n${header}`);
  console.log(util.compressSlices(sliceArray));
}

/**
 * Log sandboxArray.
 * @param {Sandbox[]} sandboxArray
 * @param {string}    [header]
 */
exports.dumpSandboxes = function utils$$dumpSandboxes(sandboxArray, header) {
  if (header) console.log(`\n${header}`);
  console.log(util.compressSandboxes(sandboxArray));
}

/**
 * If the elements of sliceArray are not unique, log the duplicates and log the full array.
 * @param {Slice[]} sliceArray
 * @param {string}  [header]
 */
exports.dumpSlicesIfNotUnique = function utils$$dumpSlicesIfNotUnique(sliceArray, header) {
  if (!exports.isUniqueSlices(sliceArray, header))
    console.log(util.compressSlices(sliceArray));
}

/**
 * If the elements of sandboxArray are not unique, log the duplicates and log the full array.
 * @param {Sandbox[]} sandboxArray
 * @param {string}    [header]
 */
exports.dumpSandboxesIfNotUnique = function utils$$dumpSandboxesIfNotUnique(sandboxArray, header) {
  if (!exports.isUniqueSandboxes(sandboxArray, header))
    console.log(util.compressSandboxes(sandboxArray));
}

/**
 * Checks whether the elements of sliceArray are unique and if not, log the duplicates.
 * @param {Slice[]}  sliceArray
 * @param {string}   [header]
 * @param {function} [log]
 * @returns {boolean}
 */
exports.isUniqueSlices = function utils$$isUniqueSlices(sliceArray, header, log) {
  const slices = [];
  let once = true;
  sliceArray.forEach(x => {
    if (slices.indexOf(x) >= 0) {
      if (once && header) console.log(`\n${header}`); once = false;
      log ? log(x) : console.log(`\tFound duplicate slice ${x.identifier}.`);
    } else slices.push(x);
  });
  return sliceArray.length === slices.length;
}

/**
 * Checks whether the elements of sandboxArray are unique and if not, log the duplicates.
 * @param {Sandbox[]} sandboxArray
 * @param {string}    [header]
 * @param {function}  [log]
 * @returns {boolean}
 */
exports.isUniqueSandboxes = function utils$$isUniqueSandboxes(sandboxArray, header, log) {
  const sandboxes = [];
  let once = true;
  sandboxArray.forEach(x => {
    if (sandboxes.indexOf(x) >= 0) {
      if (once && header) console.log(`\n${header}`); once = false;
      log ? log(x) : console.log(`\tFound duplicate sandbox ${x.identifier}.`);
    } else sandboxes.push(x);
  });
  return sandboxArray.length === sandboxes.length;
}
