/**
 * @file dcp/src/dcp-client/worker/supervisor2/sandbox2.js
 *
 * A sandbox that when constructed and assigned can do work for
 * a distributed slice. A sandbox runs for a single slice at a time.
 *
 * Usage (simplified...):
 *  const sandbox = new Sandbox(this, { ...this.options.sandboxOptions });
 *  await sandbox.start();
 *  sandbox.slice = slice;
 *  await sandbox.assign(jobManager);
 *  return sandbox.work()
 *    .then((result) => {
 *      slice.collectResult(result, true);
 *      sandbox.checkSandboxReUse();
 *      this.supervisor.recordResult(slice)
 *    })
 *    .catch((error) => {
 *      slice.collectResult(error, false);
 *      const reason = this.supervisor.handleSandboxWorkError(sandbox, slice, error);
 *      this.supervisor.returnSlice(slice, reason);
 *      this.returnSandbox(sandbox);
 *    });
 *
 * Debug flags:
 *  Sandbox.debugWork = true // - turns off 30 second timeout to let user debug sandbox innards more easily
 *  Sandbox.debugState = true // - logs all state transitions for this sandbox
 *  Sandbox.debugEvents = true // - logs all events received from the sandbox
 *
 * Initial states:
 * UNREADY
 *
 * Terminal states:
 * TERMINATED
 *
 * Valid transitions:
 * ( sandbox.start )
 * UNREADY -> READYING -> READY_FOR_ASSIGN
 *            READYING -> TERMINATED
 * ( sandbox.assign )
 * READY_FOR_ASSIGN -> ASSIGNING -> ASSIGNED
 *                     ASSIGNING -> TERMINATED
 * ( sandbox.markAsWorking )
 * ASSIGEND -> WORKING
 * ( sandbox.work )
 * WORKING -> ASSIGNED
 *         -> TERMINATED
 * ( sandbox.terminate )
 * any -> TERMINATED
 *
 * @author Matthew Palma, mpalma@kingsds.network
 *         Ryan Rossiter, ryan@kingsds.network
 *         Wes Garland, wes@distributive.network
 *         Paul, paul@distributive.network
 * @date May 2019
 *       May 2019
 *       Decemeber 2020
 *       June, Dec 2022, Jan-May 2023
 * @module sandbox
 * @copyright Copyright (c) 2018-2024, Distributive Corp. All Rights Reserved
 */
// @ts-check
'use strict';

const debugging = require('dcp/debugging').scope('worker');
const dcp_timers = require('dcp/common/dcp-timers');
const { assert, assertEq3 } = require('dcp/common/dcp-assert');
const { Synchronizer } = require('dcp/common/concurrency');
const { DCPError } = require('dcp/common/dcp-error');
const nanoid = require('nanoid').nanoid;
const EventEmitter = require('events');
const kvin = require("kvin");
const common = require('./common');
const { selectiveDebug, truncateAddress, timeDilation, selectiveDebug2, selectiveSupEx } = common;
const { stringify } = require('dcp/utils');

/**
 * Wraps console.debug to emulate debug module prefixing messages on npm.
 * @param {...any} args
 */
const debug = (...args) => {
  if (debugging())
    console.debug('Sandbox:', ...args);
};

// Sandbox states
const UNREADY    = 'UNREADY'    // No Sandbox (web worker, saworker, etc) has been constructed yet
const READYING   = 'READYING'   // Sandbox is being constructed and environment (bravojs, env) is being set up
const READY_FOR_ASSIGN = 'READY_FOR_ASSIGN' // Sandbox is ready to be assigned
const ASSIGNED   = 'ASSIGNED'   // Sandbox is assigned but not working
const ASSIGNING  = 'ASSIGNING'  // Sandbox is in the process of being ASSIGNED
const WORKING    = 'WORKING'    // Sandbox is working
const TERMINATED = 'TERMINATED' // Sandbox is terminated.
const EVAL_RESULT_PREFIX = 'evalResult::';

class SandboxError extends Error
{
  /**
   * @param {string} errorCode
   * @param {string|Error} msg
   */
  constructor(errorCode, msg)
  {
    super((msg.constructor?.name === 'String') ? msg : msg['message']);
    /** @type {string} */
    this.errorCode = errorCode;
    if (msg.constructor?.name !== 'String')
      for (const prop of [ 'name', 'code', 'stack', 'lineNumber', 'columnNumber' ])
        if (msg[prop]) this[prop] = msg[prop];
  }
}
class NoProgressError        extends SandboxError { constructor(msg) { super('ENOPROGRESS',   msg); } }
class SliceTooSlowError      extends SandboxError { constructor(msg) { super('ESLICETOOSLOW', msg); } }
class UncaughtExceptionError extends SandboxError { constructor(msg) { super('EUNCAUGHT',     msg); } }

/** @typedef {import('./slice2').Slice} Slice                                */
/** @typedef {import('./config').Config} Config                                */
/** @typedef {import('./index').Supervisor} Supervisor                       */
/** @typedef {import('./job-manager').JobManager} JobManager                 */
/** @typedef {import('./module-cache').ModuleCache} ModuleCache              */
/** @typedef {import('dcp/utils/jsdoc-types').SandboxOptions} SandboxOptions */

/**
 * Public event emitter.
 * https://gitlab.com/Distributed-Compute-Protocol/dcp-docs-wes/-/blob/wip/worker/worker-events.md
 */
class SandboxHandle extends EventEmitter
{
  /** @type {{ id: number, public: { name: string, description: string, link: string }, jobManager: JobManager, slice: Slice }} */
  #info;

  /**
   * @constructor
   * @param {Sandbox} sandbox
   */
  constructor (sandbox)
  {
    super({ captureRejections: false });
    this.#info = sandbox.info;
  }
  /** @type {number} */
  get id ()          { return this.#info.id; }
  /** @type {{ name: string, description: string, link: string }} */
  get public ()      { return this.#info.public ?? { name: '<unassigned>', description: '', link: '' }; }
  /** @type {string} */
  get jobAddress ()  { return this.#info.jobManager?.address; }
  /** @type {number} */
  get sliceNumber () { return this.#info.slice?.sliceNumber ?? -1; }
}
exports.SandboxHandle = SandboxHandle;

//
// Index to functionality -- search for '_Idx' to toggle through the index.
//
// 1)  class Sandbox
// 2)  checkSandboxReUse, postMessageToEvaluator, changeState,
//     and punctuatedTimer is expiremental for replacing hard-coded timeouts.
// 3)  start, describe, assign, applyRequirements, assignEvaluator
// 4)  eval, resetState, work, resetProgressTimeout, resetSliceTimeout
// 5)  handleRing0Message, handleRing1Message, handleRing2Message, handleRing3Message
// 6)  onmessage, onerror, terminate
// 7)  updateTime, resetSliceReport, sandboxEmit, error, warning
//

// _Idx
//
// class Sandbox
//

class Sandbox extends EventEmitter
{
  /**
   * A Sandbox (i.e. a worker sandbox) which executes distributed slices.
   *
   * @constructor
   * @param {Supervisor} supervisor
   * @param {SandboxOptions} options
   */
  constructor (supervisor, options)
  {
    super({ captureRejections: false });
    /** @type {Supervisor} */
    this.supervisor = supervisor;
    /** @type {ModuleCache} */
    this.moduleCache = supervisor.moduleCache;
    /** @type {SandboxOptions} */
    this.options = {
      ignoreNoProgress: false,
      ...options,
      SandboxConstructor: options.SandboxConstructor || require('../evaluators').BrowserEvaluator,
    }
    /** @type {Synchronizer} */
    this.state = new Synchronizer(UNREADY, [ UNREADY, READYING, READY_FOR_ASSIGN, ASSIGNING, ASSIGNED, WORKING, TERMINATED ]);

    /** @type {{ id: number, public: { name: string, description: string, link: string }, jobManager: JobManager, slice: Slice }} */
    this.info = {
      id:         Sandbox.getNewId(),
      public:     null,
      jobManager: null,
      slice:      null,
    };

    /**
     * Event emitter containing info that describes the sandbox.
     * @type {SandboxHandle}
     */
    this.sandboxHandle = new SandboxHandle(this);

    /** Properties of type object. */
    this.evaluatorHandle = null;
    this.capabilities = null;
    this.progressTimeout = null;
    this.sliceTimeout = null;
    this.describeTimeout = null;
    this.requirementTimeout = null;
    this.resetStateTimeout = null;
    this.rejectionData = null;
    
    /**
     * Represents whether the tab entered a suspended state since the last progress event fired.
     * When the progress event fires, the handler will check the value of this variable and acknowledge it by resetting
     * it back to false.
     * @type {boolean}
     */
    this.tabSuspendedSinceLastProgressEvent = false;
    /** @type {number?} */
    this.progress = 100;
    /** @type {{ last: { deltaMs: number, value: any, throttledReports: number }, lastDeterministic: { deltaMs: number, progress: number, value: any, throttledReports: number } }} */
    this.progressReports = null; // cf. job-noProgress.js

    /** @type {{ total: number, CPU: number, webGL: number, webGPU: number }} */
    this.sliceTimeReport = null;
    /** @type {number} */
    this.moduleInDataSize = 0; // Sandbox level input size; set during assign, never reset.
    /** @type {number} */
    this.sliceOutDataSize = 0; // Slice level output size; reset for every slice executed.

    /** @type {number} */
    this.useCounter = 1; // Anticipating the initial use.
    /** @type {Config} */
    this.hive = this.supervisor.options;

    ///** @type {((data: any) => Promise<void>)[]} */
    this.ringMessageHandlers = [
      this.handleRing0Message,
      this.handleRing1Message,
      this.handleRing2Message,
      this.handleRing3Message,
    ];

    this.resetSliceReport();
  }

  /** @type {number} */
  get id ()         { return this.info.id; }
  /** @type {{ name: string, description: string, link: string }} */
  get public ()     { return this.info.public; }
  /** @type {{ name: string, description: string, link: string }} */
  set public (data) { this.info.public = data; }
  /** @type {JobManager} */
  get jobManager () { return this.info.jobManager; }
  /** @type {string} */
  get jobAddress () { return this.jobManager?.address; }
  /** @type {Slice} */
  get slice ()      { return this.info.slice; }
  /** @type {Slice} */
  set slice (slice) { this.info.slice = slice; }
  /** @type {number} */
  get sliceNumber () { return this.slice ? this.slice.sliceNumber : -1; }
  /** @type {number} */
  get sliceStartTime () { return this.slice?.startTime || 0; };
  /** @type {number} */
  get generalTimeoutMs () { return 2 * this.hive.generalTimeoutMs * timeDilation; }
  /** @type {number} */
  get punctuatedTimeoutMs () { return this.hive.generalTimeoutMs * timeDilation; }

  /**
   * Debug string that characterizes sandbox.
   * @type {string}
   */
  get identifier()
  {
    if (!this.jobAddress)
      return `${this.id}.${this.state}`;
    const address = truncateAddress(this.jobAddress);
    if (this.slice)
      return `${this.id}.${address}.${this.state}~${this.slice.sliceNumber}.${this.slice.state}`;
    return `${this.id}.${address}.${this.state}`;
  }

  /** @returns {number} */
  static getNewId() { return Sandbox.idCounter++; }

  /** @type {boolean} */
  get isReadyForAssign () { return this.state.is(READY_FOR_ASSIGN); }
  /** @type {boolean} */
  get isAssigned ()       { return this.state.is(ASSIGNED); }
  /** @type {boolean} */
  get isWorking ()        { return this.state.is(WORKING); }
  /** @type {boolean} */
  get isTerminated ()     { return this.state.is(TERMINATED); }

  // _Idx
  //
  // checkSandboxReUse, postMessageToEvaluator, changeState,
  // punctuatedTimer is expiremental for replacing hard-coded timeouts.
  //

  /**
   * Mark WORKING sandbox as ASSIGNED in preparation for possible reuse.
   * Allow use of sandbox on a given job up to a limit of dcpConfig.supervisor.sandbox.maxSandboxUse .
   */
  checkSandboxReUse ()
  {
    selectiveDebug2() && console.debug(`Sandbox2.checkSandboxReUse: useCounter ${this.useCounter}, ${this.identifier}`);
    if (this.useCounter++ < this.hive.maxSandboxUse)
    {
      this.state.set(WORKING, ASSIGNED);
      this.sandboxEmit('ready');
    }
    else
    {
      this.terminate(false);
    }
  }

  /** Transitions: ASSIGNED --> WORKING. */
  markAsWorking ()
  {
    if (!this.isAssigned)
      throw new Error(`Sandbox ${this.identifier} is not ready to work`);
    this.state.set(ASSIGNED, WORKING);
  }
  
  /**
   * Safely post message to evaluator.
   * @param {object} message
   */
  postMessageToEvaluator (message)
  {
    if (this.isTerminated) // When evaluator goes down, all sandboxes are terminated.
      throw new Error(`postMessageToEvaluator: Sandbox ${this.identifier} has been terminated.`);
    return this.evaluatorHandle.postMessage(message);
  }
  
  /**
   * Safely change state.
   * @param {string}  currentState
   * @param {string}  nextState
   */
  changeState (currentState, nextState)
  {
    if (this.isTerminated) // When evaluator goes down, all sandboxes are terminated.
      throw new Error(`changeState: Sandbox ${this.identifier} has been terminated.`);
    this.state.set(currentState, nextState);
  }

  /** Upon fatal error return slice to scheduler. */
  returnSlice ()
  {
    selectiveDebug() && console.debug('Sandbox.returnSlice', this.identifier);
    return this.supervisor.returnSlice(this.slice, 'Sandbox.returnSlice');
  }

  /**
   * @callback cbFn
   * @returns {void}
   */

  /**
   * UNUSED.
   * Future work.
   * Replaces the timers in:
   *   describe,
   *   applyRequirements,
   *   resetState,
   * The idea is to have a long timeout with a warning every
   * 6 seconds saying why it is waiting.
   * @param {cbFn} body
   * @param {string} waitMessage
   * @param {string} timerExpiredMessage
   * @returns {Promise<{ closeIntervalTimer: cbFn }>}
   */
  punctuatedTimer(body, waitMessage, timerExpiredMessage)
  {
    const that = this;
    return new Promise((resolve, reject) => {
      let intervalCounter = 0;
      let intervalHandle = null;
      function closeIntervalTimer()
      {
        intervalHandle = that.clearTimer(intervalHandle);
      }
      intervalHandle = dcp_timers.setInterval(() => {
        if (++intervalCounter > 12)
        {
          closeIntervalTimer();
          that.error(timerExpiredMessage);
        }
        that.warning(waitMessage);
        body();
      }, this.punctuatedTimeoutMs)
      // Allow workers and localExec to exit.
      intervalHandle.unref();
      resolve({ closeIntervalTimer });
    });
  }

  // _Idx
  //
  // start, describe, assign, applyRequirements, assignEvaluator
  //

  /**
   * Readies the sandbox. This will result in the sandbox being ready and not assigned.
   * It will need to be assigned with a job before it is able to do work.
   * Sandbox.start will terminate the sandbox upon failure.
   * @todo maybe preload specific modules or let the cache pass in what modules to load?
   *
   * @returns {Promise<void>}
   * @throws on failure to ready
   */
  async start ()
  {
    debug('Sandbox.start begin');
    await this.supervisor.delayManager.nextDelay('sandboxStart');
    this.changeState(UNREADY, READYING);

    try
    {
      // RING 0
      this.evaluatorHandle = new this.options.SandboxConstructor({
        name: `DCP Sandbox #${this.id}`,
      });
      // Annoying! onerror terminates sandbox which can happen independent of whether the slice
      // is ok or not. Since we don't know, we have to return the slice when onerror is called
      // during sandbox.work .
      /** @todo XXXpfr Beware of onerror firing often. */
      this.evaluatorHandle.onerror = this.onerror.bind(this);

      const messageHandler = this.onmessage.bind(this);
      this.evaluatorHandle.onmessage = function onmessage(event)
      {
        const data = (event.data.serialized)
          ? kvin.parse(event.data.message)
          : kvin.unmarshal(event.data);
        messageHandler({ data });
      }

      const evaluatorPostMessage = this.evaluatorHandle.postMessage.bind(this.evaluatorHandle);
      this.evaluatorHandle.postMessage = function postMessage(message)
      {
        evaluatorPostMessage(kvin.marshal(message));
      }

      const that = this;
      this.evaluatorHandle.addEventListener('end', function sandbox$start$addEventListener() {
        selectiveDebug() && console.debug("END:Sandbox evaluatorHandle end-handler", that.identifier, new Date());
        // Enable the is-screen-saver-down logic in the sandbox handle 'end' event handler
        // in Supervisor.hookUpSandboxListeners.
        that.supervisor.evaluator.beginShutDown();
        that.terminate(true);
      });

      // Don't let an open sockets prevent clean worker exit.
      if (this.evaluatorHandle.unref)
        this.evaluatorHandle.unref();

      // Now in RING 1

      // Now in RING 2
      await this.describe();
      this.changeState(READYING, READY_FOR_ASSIGN);

      // Emit the 'sandbox' event on the worker event emitter.
      this.supervisor.safeEmit(this.supervisor.worker, 'sandbox', this.sandboxHandle);
    }
    catch (error)
    {
      if (this.isTerminated)
        debug(`Failed to start sandbox because it is already terminated: ${this.identifier}.\n\tMay be due to screensaver worker being down or evaluator was stopped.`);
      else
      {
        debug(`Failed to start sandbox ${this.identifier}.`, error.message); // FIX s.b. error
        this.terminate(false);
      }
      throw error;
    }
  }

  /**
   * Sends a post message to describe its capabilities.
   * Side effect: Sets the capabilities property of the current sandbox.
   *
   * @returns {Promise<any>} Resolves with the sandbox's capabilities.
   * Rejects with an error saying a response was not received.
   * @memberof Sandbox
   */
  describe ()
  {
    debugging('sandbox') && debug('Beginning to describe evaluator', this.identifier);
    const that = this;

    return new Promise(function sandbox$describePromise(resolve, reject) {
      if (that.isTerminated) // When evaluator goes down, all sandboxes are terminated.
        reject(new Error(`Sandbox ${that.identifier} has been terminated.`));

      if (that.evaluatorHandle === null)
        reject(new Error(`Evaluator has not been initialized: ${that.identifier}`));

      function sandbox$describe$success(data)
      {
        if (that.describeTimeout)
        {
          dcp_timers.clearTimeout(that.describeTimeout);
          that.describeTimeout = null;

          if (!that.supervisor.worktimes)
            that.supervisor.worktimes = data.worktimes;

          const capabilities = data.capabilities;
          if (typeof capabilities === 'undefined')
            reject(new Error(`Did not receive capabilities from describe response: ${that.identifier}`));
          that.capabilities = capabilities;

          debugging('sandbox') && debug('Evaluator has been described');
          resolve(capabilities);
        }
      }
      // Emitted by handleRing2Message.
      that.once('describe', sandbox$describe$success);

      that.describeTimeout = dcp_timers.setTimeout(function sandbox$describe$fail() {
        if (that.describeTimeout)
        {
          that.describeTimeout = null;
          that.removeListener('describe', sandbox$describe$success);
          reject(new Error( `Describe message timed-out. No describe response was received from the describe command: ${that.identifier}`));
        }
      }, that.generalTimeoutMs);
      // Allow workers and localExec to exit.
      that.describeTimeout.unref();

      const message = {
        request: 'describe',
      };
      that.postMessageToEvaluator(message);
    });
  }

  /**
   * This will assign the sandbox with a job, loading its sandbox code into the sandbox.
   * Sandbox.assign will not terminate the sandbox upon failure.
   * The sandbox will be terminated in JobManager.assignSandbox .
   * @param {JobManager} jobManager - The job manager that will be the owner of this sandbox.
   * @returns {Promise<Sandbox>}
   * @throws on initialization failure
   */
  async assign (jobManager)
  {
    if (!this.slice) // Design assumption.
      throw new Error(`Must have valid sandbox.slice before sandbox.assign is called: ${this.identifier}`);

    await this.supervisor.delayManager.nextDelay('sandboxAssign');
    debug('Sandbox.assign', this.identifier, Date.now() - this.supervisor.lastTime);

    try
    {
      this.changeState(READY_FOR_ASSIGN, ASSIGNING);
      this.info.jobManager = jobManager;
      this.job = this.jobManager.jobMessage;

      // At this point, the worker has decided that this sandbox will be associated with a specific job.
      // Therefore, we emit the SandboxHandle<job> event.
      this.sandboxEmit('job', this.jobManager.jobHandle);

      assertEq3(this.job.address, this.jobAddress);
      assert(typeof this.job === 'object');
      assert(typeof this.job.requirements === 'object');
      assert(Array.isArray(this.job.dependencies));
      assert(Array.isArray(this.job.requirePath));

      // Extract public data from job, with defaults
      this.public = Object.assign({
        name:        `Anonymous Job ${truncateAddress(this.jobAddress)}`,
        description: 'Discreetly helping make the world smarter.',
        link:        'https://distributed.computer/about',
      }, this.job.public);

      // Future: We may want other filename tags for appliances // RR Nov 2019

      // Important: The order of applying requirements before loading the sandbox code
      // is important for modules and sandbox code to set globals over the whitelist.
      await this.applyRequirements(this.job.requirements);
      //const _t0 = Date.now();
      await this.assignEvaluator();
      //console.log('Finished Sandbox.assignEvaluator', Date.now() - _t0);
      this.changeState(ASSIGNING, ASSIGNED);
      this.sandboxEmit('ready');
    }
    catch (error)
    {
      if (this.isTerminated)
        debug(`Failed to assign sandbox ${this.identifier} to evaluator because it is already terminated.\n\tMay be due to screensaver worker being down or evaluator was stopped.`);
      else
      {
        debug(`Failed to assign sandbox ${this.identifier} to evaluator.`);
        this.terminate(false);
      }
      throw error;
    }

    return this;
  }

  /**
   * Passes the job's requirements object into the sandbox so that the global access lists can be updated accordingly.
   * E.g. disallow access to OffscreenCanvas without environment.offscreenCanvas=true present.
   * Must be called after @start.
   *
   * @returns {Promise<void>} - resolves on success, rejects otherwise
   */
  applyRequirements (requirements)
  {
    assert(typeof requirements === 'object');
    const that = this;

    return new Promise(function sandbox$applyRequirementsPromise(resolve, reject) {
      function sandbox$applyRequirements$success()
      {
        if (that.requirementTimeout)
        {
          dcp_timers.clearTimeout(that.requirementTimeout);
          that.requirementTimeout = null;
          resolve();
        }
      }
      // Emitted by handleRing1Message.
      that.once('applyRequirementsDone', sandbox$applyRequirements$success);

      that.requirementTimeout = dcp_timers.setTimeout(function sandbox$finishApplySandboxRequirements$fail() {
        if (that.requirementTimeout)
        {
          that.requirementTimeout = null;
          that.removeListener('applyRequirementsDone', sandbox$applyRequirements$success);
          reject(new Error(`applyRequirements never received 'applyRequirementsDone' response from sandbox: ${that.identifier}`));
        }
      }, that.generalTimeoutMs);
      // Allow workers and localExec to exit.
      that.requirementTimeout.unref();

      const message = {
        requirements,
        worktime: that.job.worktime?.name,
        request: 'applyRequirements',
      };
      that.postMessageToEvaluator(message);
    });
  }

  /**
   * Assign job to the evaluator.
   * @returns {Promise<any>} - resolves on success, rejects otherwise
   */
  assignEvaluator ()
  {
    debugging('sandbox') && console.debug('Begin assigning job to evaluator', this.identifier);
    const that = this;

    return new Promise(function sandbox$$assignEvaluatorPromise(resolve, reject) {
      function sandbox$assignEvaluator$success(event)
      {
        that.removeListener('reject', sandbox$assignEvaluator$fail);
        debugging('sandbox') && debug('Job assigned to evaluator');
        resolve(event);
      }

      function sandbox$assignEvaluator$fail(error)
      {
        that.removeListener('assigned', sandbox$assignEvaluator$success);
        that.error(`assignEvaluator failed(${that.identifier}): evaluator may be out of memory or the screensaver may be down.`, error);
        selectiveDebug() && console.debug('assignEvaluator failed', that.identifier, error);
        if (that.slice) // Normally the slice hasn't been set yet.
          that.returnSlice();
        reject(error);
      }

      // Emitted by handleRing2Message.
      that.once('assigned', sandbox$assignEvaluator$success);
      that.once('reject', sandbox$assignEvaluator$fail);

      // Had to add useStrict -- not sure if anything else was missed.
      const jobMessage = {
        address:        that.job.address,
        arguments:      that.job.arguments,
        dependencies:   that.job.dependencies,
        modulePath:     that.job.modulePath,
        public:         that.job.public,
        requireModules: that.job.requireModules,
        requirePath:    that.job.requirePath,
        workFunction:   that.job.workFunction,
        useStrict:      that.job.useStrict,
        worktime:       that.job.worktime,
      };

      const message = {
        request: 'assign',
        job: jobMessage,
        sandboxConfig: that.hive.sandboxConfig,
      };
      that.postMessageToEvaluator(message);
    });
  }

  // _Idx
  //
  // eval, resetState, work, resetProgressTimeout, resetSliceTimeout
  //

  /**
   * Evaluates a string inside the sandbox.
   * @todo XXXpfr -- Currently unused, but will be useful for appliances!
   *
   * @param {string} code     - the code to evaluate in the sandbox
   * @param {string} filename - the name of the 'file' to help with debugging,
   * @returns {Promise<any>}  - resolves with eval result on success, rejects otherwise
   */
  eval (code, filename)
  {
    const that = this;
    const msgId = nanoid();

    return new Promise(function sandbox$$eval$Promise(resolve, reject) {
      const eventId = EVAL_RESULT_PREFIX + msgId;

      function sandbox$eval$success(event)
      {
        that.removeListener('reject', sandbox$eval$fail);
        resolve(event);
      };

      function sandbox$eval$fail(error)
      {
        that.removeListener(eventId, sandbox$eval$success);
        reject(error);
      };

      that.once(eventId, sandbox$eval$success);
      that.once('reject', sandbox$eval$fail);

      const message = {
        request: 'eval',
        data: code,
        filename,
        msgId,
      };
      that.postMessageToEvaluator(message);
    });
  }

  /**
   * Resets the state of the bootstrap, without resetting the sandbox function if assigned.
   * Mostly used to reset the progress status before reusing a sandbox on another slice.
   * Must be called after @start.
   *
   * @returns {Promise<void>} - resolves with result on success, rejects otherwise
   */
  resetState ()
  {
    const that = this;
    assert(this.isWorking); // Design assumption.

    return new Promise(function sandbox$resetStatePromise(resolve, reject) {
      function sandbox$resetState$success ()
      {
        if (that.resetStateTimeout)
        {
          dcp_timers.clearTimeout(that.resetStateTimeout);
          that.resetStateTimeout = null;
          resolve();
        }
      }
      that.once('resetStateDone', sandbox$resetState$success);

      that.resetStateTimeout = dcp_timers.setTimeout(function sandbox$resetState$fail() {
        if (that.resetStateTimeout)
        {
          that.resetStateTimeout = null;
          that.removeListener('resetStateDone', sandbox$resetState$success);
          reject(new Error(`resetState never received resetStateDone event from sandbox: ${that.identifier}`));
        }
      }, that.generalTimeoutMs);
      // Allow workers and localExec to exit.
      that.resetStateTimeout.unref();

      const message = {
        request: 'resetState',
      };
      that.postMessageToEvaluator(message);
    });
  }

  /**
   * Executes a slice received from the supervisor.
   * Must be called after this.start, this.assign and this.markAsWorking .
   * Sandbox.work will not terminate the sandbox upon failure.
   * The sandbox will be terminated in Supervisor.handleSandboxWorkError .
   * @returns {Promise<any>} - resolves with result on success, rejects otherwise
   */
  async work ()
  {
    const that = this;
    // Memoize slice for error reporting.
    const _slice = this.slice;

    if (!this.slice) // Design assumption
      throw new Error(`Must have valid sandbox.slice before sandbox.assign is called: ${this.identifier}`);

    await this.supervisor.delayManager.nextDelay('sandboxWork');
    debug('Sandbox.work begin', this.identifier, Date.now() - this.supervisor.lastTime);

    if (!this.slice?.isWorking) // Should be impossible.
      throw new Error(`Slice ${_slice.identifier} must be marked as working in Sandbox.work: ${this.identifier}.`);
    if (this.isTerminated) // When evaluator goes down, all sandboxes are terminated.
      throw new Error(`Sandbox ${this.identifier} has been terminated.`);
    if (!this.isWorking) // Should be impossible.
      throw new Error(`Sandbox ${this.identifier} in Sandbox.work must be marked as working.`)

    // cf. DCP-1719,1720
    this.resetSliceReport();

    // Check that sandbox and slice have the same job.
    if (this.jobAddress !== this.slice.jobAddress)
      throw new Error(`Sandbox.work: sandbox ${this.identifier} and slice ${this.slice.identifier} are from different jobs`);

    /** @todo Should sliceHnd just be replaced with { sandbox: this } since this.public is part of this? */
    let sliceHnd = { job: this.public, sandbox: this };
    await this.resetState();
    if (!this.slice)
    {
      this.error(`Slice for job ${this.jobAddress} vanished during work initialization - aborting`);
      return;
    }

    const { datum: inputDatum, error: dataError } = this.slice;
    if (dataError)
    {
      that.postWorkEmit('error', {
        message: dataError.message,
        stack:   dataError.stack,
        name:    this.public.name
      });
    }

    return new Promise(function sandbox$$workPromise(resolve, reject) {
      function sandbox$$work$success (event)
      {
        that.removeListener('reject', sandbox$$work$fail);
        resolve(event);
      }

      function sandbox$$work$fail (error)
      {
        that.removeListener('resolve', sandbox$$work$success);
        reject(error);
      }

      that.once('resolve', sandbox$$work$success);
      that.once('reject', sandbox$$work$fail);

      that.slice.startTime = Date.now();
      that.progress = null;
      that.progressReports = {
        last: undefined,
        lastDeterministic: undefined,
      };

      that.supervisor.on('tabSuspended', function Sandbox$tabSuspended() {
        that.tabSuspendedSinceLastProgressEvent = true;
      });

      that.resetProgressTimeout();
      that.resetSliceTimeout();
      that.emit('start', sliceHnd);

      if (dataError)
      {
        that.removeListener('resolve', sandbox$$work$success);
        that.removeListener('reject', sandbox$$work$fail);
        dcp_timers.setTimeout(() => reject(dataError), 0)
      }
      else
      {
        // Do the work.
        const message = { request: 'main', data: inputDatum, };
        that.postMessageToEvaluator(message);
      }
    })
    .then(async function sandbox$$work$then(event) {
      try // Make sure then-handler does not throw.
      {
        selectiveSupEx() && console.debug(`Sandbox.work has finished: ${that.identifier}`, event?.timeReport);
        // Tell supervisor that the slice is done working and is no longer occupying core space.
        that.slice.markAsWorkDone();
        // Clear slice property.
        that.slice = null;
        // Allow reuse of sandbox (WORKING ==> ASSIGNED) up to a limit of dcpConfig.supervisor.sandbox.maxSandboxUse .
        that.checkSandboxReUse();
      }
      catch (thenHandlerError)
      {
        // DANGER: Never introduce code here that could throw.
        selectiveSupEx() && console.debug(`Sandbox.work ${that.identifier} with slice ${_slice.identifier}: then-handler caught error:`, thenHandlerError);
        // End up here due to bugs, so make noise and force WORKDONE.
        that.error(`Unexpected failure of ${_slice.identifier} in sandbox.work result handling ${that.identifier}:`, thenHandlerError);
        // Tell supervisor the slice is no longer occupying core space.
        _slice.forceWorkDone();
        // Don't throw, try to recover.
      }

      that.clearTimers();
      // The 'complete' event triggers fetchTask so checkSandboxReUse must happen before,
      // in order to free up the current sandbox for reuse, when possible.
      that.emit('complete', that.jobAddress);

      return event;
    })
    .catch(async function sandbox$$work$catch(error) {
      // DANGER: Never introduce code here that could throw.
      selectiveSupEx() && debug(`Sandbox.work-catch ${that.identifier} failed to execute slice ${_slice.identifier}`, error);
      // Current sandbox will not be reused.
      // Do not overwrite that.slice because it is needed in subsequent error reporting.

      // that.slice should be valid here, but we'll use the alias _slice since we know it's valid.
      if (!_slice.isWorking)
        that.error(`Unexpected sandbox.slice state ${_slice.identifier} in the sandbox.work catch handler: ${that.identifier}`, error);
      try
      {
        // Try what should be correct.
        _slice.markAsWorkDone(); // Tell supervisor the slice is no longer occupying core space.
      }
      catch (synchError)
      {
        // End up here due to bugs, so force WORKDONE.
        _slice.forceWorkDone();
      }

      that.clearTimers();

      if (error instanceof NoProgressError)
      {
        const payload = {
          name:      that.public.name,
          message:   error.message,
          timestamp: Date.now() - that.sliceStartTime,
        };
        that.postWorkEmit('error', payload);
        that.postWorkEmit('noProgress', { ...payload, progressReports: that.progressReports });
      }
      if (error.name === 'EWORKREJECT')
        that.handleRejectedWork(that.sliceTimeReport);

      debugging('supervisor') && debug(`Sandbox.work ${that.identifier} throwing exception:`, error);

      if (!that.slice) // Should be impossible.
        throw new DCPError(`Missing slice ${_slice.identifier} in sandbox.work catch-handler: ${that.identifier}`, error);
      throw error;
    });
  }

  clearTimer (timer)
  {
    if (timer)
      dcp_timers.clearTimeout(timer);
    return null;
  }

  clearTimers ()
  {
    this.progressTimeout  = this.clearTimer(this.progressTimeout);
    this.sliceTimeout  = this.clearTimer(this.sliceTimeout);
    this.describeTimeout  = this.clearTimer(this.describeTimeout);
    this.requirementTimeout  = this.clearTimer(this.requirementTimeout);
    this.resetStateTimeout  = this.clearTimer(this.resetStateTimeout);
  }

  resetProgressTimeout()
  {
    this.clearTimer(this.progressTimeout);
    this.tabSuspendedSinceLastProgressEvent = false;
    const that = this;
    this.progressTimeout = dcp_timers.setTimeout(function sandbox$ProgressTimeout() {
      if (that.options.ignoreNoProgress)
        return that.warning('ENOPROGRESS silenced by localExec: In a remote worker, this slice would be stopped for not calling progress frequently enough.');
      if (that.tabSuspendedSinceLastProgressEvent) 
      {
        that.tabSuspendedSinceLastProgressEvent = false;
        return that.warning('ENOPROGRESS ignored due to tab suspension.');
      }

      that.emit('reject', new NoProgressError(`No progress event was received in the last ${that.hive.progressTimeoutMs / 1000} seconds.`));
    }, this.hive.progressTimeoutMs * timeDilation);
    // Allow workers and localExec to exit.
    this.progressTimeout.unref();
  }

  resetSliceTimeout()
  {
    this.clearTimer(this.sliceTimeout);

    const that = this;
    this.sliceTimeout = dcp_timers.setTimeout(function sandbox$SliceTimeout() {
      if (Sandbox.debugWork)
        return that.warning('Sandbox.debugWork: Ignoring slice timeout');

      that.emit('reject', new SliceTooSlowError(`Slice took longer than ${that.hive.sliceTimeoutMs / 1000} seconds.`));
    }, this.hive.sliceTimeoutMs * timeDilation);
    // Allow workers and localExec to exit.
    this.sliceTimeout.unref();
  }

  /**
   * Send payload to the workEmit endpoint in the event router.
   * @param {string} eventName
   * @param {*} payload
   * @returns {Promise<*>}
   */
  postWorkEmit (eventName, payload)
  {
    // Need to check if the sandbox hasn't been assigned a slice yet.
    if (!this.slice)
      this.error(`Sandbox not assigned a slice before sending workEmit message to scheduler: payload\n${JSON.stringify(payload, null, 2)}`, `'workEmit' event originates from '${eventName}' event`);
    else
    {
      const slice = this.slice;
      // Authorization should always be valid.
      if (!slice.authorizationMessage)
        this.warning(`workEmit: missing authorization message for slice ${slice.identifier}`);
      else
      {
        const workEmitPayload = {
          eventName,
          payload,
          job: slice.jobAddress,
          slice: slice.sliceNumber,
          worker: this.supervisor.workerId,
          authorizationMessage : slice.authorizationMessage,
        };
        return this.supervisor.dcp4.safeWorkEmit(workEmitPayload, `Failed to send workEmit (${eventName}) payload for slice ${slice.identifier}`)
          .then((success) => {
            if (!success)
              this.warning(`Message sent to workEmit is unauthorized; not accepted '${eventName}'`);
          });
      }
    }
  }

  /**
   * Save rejected slice timeReport data in this.slice.rejectedTimeReport, then when needed in
   * Supervisor.recordResult, merge this.slice.rejectedTimeReport into this.slice.timeReport.
   * @param {{ total: number, CPU: number, webGL: number, webGPU: number }} timeReport
   */
  handleRejectedWork (timeReport)
  {
    selectiveDebug() && console.debug('handleRejectedWork', this.identifier);
    // If the slice already has rejectedTimeReport, add this timeReport to it.
    // If not, assign this timeReport to slices rejectedTimeReport property
    if (this.slice)
    {
      if (!this.slice.rejectedTimeReport)
        this.slice.rejectedTimeReport = timeReport;
      else
      {
        ['total', 'CPU', 'webGL', 'webGPU'].forEach((key) => {
          if (timeReport[key])
            this.slice.rejectedTimeReport[key] += timeReport[key];
        });
      }
    }
  }

  /**
   * Attach CGIO to result returned by a slice workFn.
   * @param {*} completeData - results
   */
  attachCGIOToResult (completeData)
  {
    if (!completeData)
      throw new Error('Slice result is not ready'); // Should never fire.
    if (completeData['timeReport'])
      throw new Error('Slice result already has timeReport'); // Should never fire.
    if (completeData['dataReport'])
      throw new Error('Slice result already has dataReport'); // Should never fire.
    if (this.listenerCount('resolve') > 0)
    {
      completeData['timeReport'] = this.sliceTimeReport;
      completeData['dataReport'] = {
        InDataSize:  this.moduleInDataSize + this.jobManager.inputDataSize + this.slice.inputDataSize,
        OutDataSize: this.sliceOutDataSize,
      };
      this.emit('resolve', completeData);
      selectiveDebug() && console.debug('attachCGIOToResult', this.moduleInDataSize, this.jobManager.inputDataSize, this.slice.inputDataSize, completeData['dataReport'].InDataSize);
    }
    else
    {
      // If there is no internal listener for 'resolve', the slice was rejected
      // and we need to update this.slice.rejectedTimeReport appropriately.
      this.handleRejectedWork(this.sliceTimeReport);
    }
    // Clear time and data reports so we can catch mistaken writes.
    this.sliceTimeReport = null;
    this.sliceOutDataSize = 0;
  }

  // _Idx
  //
  // handleRing0Message, handleRing1Message, handleRing2Message, handleRing3Message
  //

  async handleRing0Message(data) // eslint-disable-line require-await
  {
    debugging('ring0') && debug('Ring0', this.identifier, data.request);

    switch (data.request)
    {
      // The private '__sandboxLoaded' event is used by dcp-native; do not remove.
      // Otherwise, do not use __sandboxLoaded.
      case '__sandboxLoaded': // SAVE
        break;
      case 'scriptLoaded':
        if(data.result !== "success")
          this.onerror(data);
        break;
      case 'error':
        debug('Sandbox error in ring0', data.error);
        this.rejectWithCleanup('during initialization', data.error);
        break;
      default:
        this.error(`Received unhandled request from sandbox ring 0. Data: ${JSON.stringify(data, null, 2)}`);
        break;
    }
  }

  async handleRing1Message(data) // eslint-disable-line require-await
  {
    debugging('ring1') && debug('Ring1', this.identifier, data.request);

    switch (data.request)
    {
      case 'applyRequirementsDone':
        // emit internally
        this.emit(data.request, data)
        break;
      default:
        this.error(`Received unhandled request from sandbox ring 1. Data: ${JSON.stringify(data, null, 2)}`);
        break; 
    }
  }

  async handleRing2Message(data)
  {
    debugging('ring2') && debug('Ring2', this.identifier, data.request);

    switch (data.request)
    {
      case 'dependency': {
        try
        {
          const moduleData = await this.moduleCache.fetchModule(data.data, this.jobAddress);
          // Send module data to be evaluator.
          const message = {
            request: 'moduleGroup',
            data: moduleData,
            id: data.id,
          };
          // Module data is dynamic since it may only be required in a conditional branch.
          // Moreover, on a long job, the published module itself may be updated on the scheduler.
          let moduleLength = 0;
          for (const moduleGroup of Object.values(moduleData))
            for (const file of Object.values(moduleGroup))
              moduleLength += file.length;
          this.moduleInDataSize += moduleLength;
          selectiveDebug() && console.debug('Sandbox.Ring2.fetchModule size', this.moduleInDataSize, moduleLength);
          this.postMessageToEvaluator(message);
        }
        catch (error)
        {
          /*
           * In the event of an error here, we want to let the client know there was a problem in
           * loading their module. In principle we shouldn't need a valid sandbox.slice at sandbox.assign.
           * However, in the implementation of Sup2 there is precisely 1 callsite of sandbox.assign and
           * we do have an associated slice at this point. So we make the assumption that sandbox.slice
           * is valid here.
          */
          if (!this.slice) // Design assumption
            throw new Error(`Must have valid slice in sandbox before sandbox.assign is called: ${this.identifier}`);

          const payload = {
            name: error.name,
            message: error.message,
            timestamp: error.timestamp ? error.timestamp : new Date(),
          };

          this.postWorkEmit('error', payload);
          this.emit('reject', error);

          debugging() && console.debug(`Sandbox.Ring2: fetchModule failed ${this.identifier}`, payload, error, Date.now() - this.supervisor.lastTime);
        }
        break;
      }
      case 'error':
        /*
         * Ring 2 error messages will only fire for problems inside of the worker that are separate from
         * the work function. In most cases there are other handlers for situations where 'error' may be emitted
         * such as timeouts if the expected message isn't recieved.
         */
        debug('Sandbox error in ring2', data.error);
        this.rejectWithCleanup('during assignment and dependency resolution', data.error);
        break;
      case 'describe':
      case 'evalResult':
      case 'resetStateDone':
      case 'assigned':
        this.emit(data.request, data); // emit internally
        break;
      case 'reject':
        this.emit('reject', data.error); // emit internally
        break;
      default:
        this.error(`Received unhandled request from sandbox ring 2. Data: ${JSON.stringify(data, null, 2)}`);
        break;
    }
  }

  async handleRing3Message(data) // eslint-disable-line require-await
  {
    debugging('ring3') && debug('Ring3', this.identifier, data.request);

    switch (data.request)
    {
      case 'complete':
        this.clearTimers();
        if (this.progress === null)
        {
          if (this.options.ignoreNoProgress)
            this.warning("ENOPROGRESS silenced by localExec: Progress was not called during this slice's execution, in a remote sandbox this would cause the slice to fail.");
          else
          {
            // If a progress update was never received (progress === null) then reject
            this.emit('reject', new NoProgressError('Sandbox never emitted a progress event.'));
            this.handleRejectedWork(this.sliceTimeReport);
            break;
          }
        }
        
        this.progress = 100;
        this.sliceOutDataSize += kvin.stringify(data.result).length; /** @todo - fix per DCP-3750 */
        this.attachCGIOToResult(data);
        break;
      case 'progress':
      {
        const { progress, indeterminate, throttledReports, value } = data;
        this.progress = progress;
        // cf. job-noProgress.js
        const progressReport = {
          deltaMs: Date.now() - this.sliceStartTime,
          progress,
          value,
          throttledReports,
        }
        this.progressReports.last = progressReport;
        if (!indeterminate)
          this.progressReports.lastDeterministic = progressReport;

        this.resetProgressTimeout();
        this.sandboxEmit('progress', indeterminate || progress < 0 || progress > 100 ? undefined : progress);
        break;
      }
      case 'noProgress':
        this.emit('reject', new NoProgressError(data.message));
        break;
      case 'console':
        data.payload.message = kvin.marshal(data.payload.message);
        this.sliceOutDataSize += JSON.stringify(data.payload.message).length; /** @todo - fix per DCP-3750 */
        this.postWorkEmit('console', data.payload);
        break;
      case 'emitEvent': /* ad-hoc event from the sandbox (work.emit) */
        this.postWorkEmit('custom', data.payload);
        break;
      case 'measurement':
        this.updateTime(data);
        break;
      case 'sandboxError': /* the sandbox itself has an error condition */
        debug(`Ring3 received a 'sandboxError' event for sandbox ${this.identifier}`, data.error);
        this.emit('sandboxError', data.error);
        this.rejectWithCleanup('internal sandbox error while executing work function', data.error);
        break;
      case 'workError': /* the work function threw/rejected */
        debug(`Ring3 received a 'workError' event for sandbox ${this.identifier}`, data.error);
        this.postWorkEmit('error', data.error);
        const wrappedError = new UncaughtExceptionError(data.error);
        this.rejectWithCleanup('error while executing work function', wrappedError);
        break;
      default:
        this.error(`Received unhandled request from sandbox ring 3. Data: ${JSON.stringify(data, null, 2)}`);
        break; 
    }
  }

  /**
   * Try to send the error back to the reject handler in Sandbox.work.
   * But if the reject handler is not available (s.b. rare) then cleanup, emit error and throw.
   * @param {string} message
   * @param {Error|string} error
   */
  rejectWithCleanup (message, error)
  {
    if (this.listenerCount('reject') > 0)
      this.emit('reject', error);
    else
    {
      this.terminate(false);
      this.error(`Sandbox ${this.identifier} ${message}`, error);
      throw error;
    }
  }

  // _Idx
  //
  // onmessage, onerror, terminate
  //

  /**
   * Handles progress and completion events from sandbox.
   * Unless explicitly returned out of this function will re-emit the event
   * where the name of the event is event.data.request.
   *
   * @param {object} event - event received from the evaaluator sandbox
   * @returns {Promise<void>}
   */
  onmessage (event)
  {
    debugging('event') && debug('onmessage-event', event.data.ringSource);
    if (Sandbox.debugEvents)
      console.debug('sandbox - eventDebug:', { id: this.id, state: this.state.valueOf(), event: JSON.stringify(event) });

    const { data } = event;
    const ringLevel = data.ringSource

    // Give the data to a handler depending on ring level
    if (ringLevel === -1)
    {
      /** @todo XXXpfr Beware of this happening often. */
      this.error(`Message sent directly from raw postMessage. Terminating worker... Event:`, event);
      this.terminate(true);
    }
    else
    {
      const handler = this.ringMessageHandlers[ringLevel];
      if (handler)
        return handler.call(this, data.value);
      this.warning(`No handler defined for message from ring ${ringLevel} for event`, event);
    }
  }

  /**
   * Error handler for the internal sandbox.
   * Emits error event that gets handled up in the Worker class.
   */
  onerror (event)
  {
    /** @todo XXXpfr Beware of onerror firing often. */
    this.error('Sandbox.onerror emitted an error:', event);
    this.terminate(true, true);
  }

  /**
   * Terminates the sandbox, clears timeouts and emits a reject event when reject is true.
   * The only way to terminate a sandbox is through this function.
   *
   * @param {boolean} [reject=true]     - if true emit reject event
   * @param {boolean} [immediate=false] - passed to terminate, used by standaloneWorker to immediately close the connection
   */
  terminate (reject = true, immediate = false)
  {
    if (this.isTerminated)
      return;
    if (this.slice)
      this.returnSlice();
    // Leave this.slice intact for debugging purposes.

    selectiveDebug() && console.debug(`Terminate sandbox ${this.identifier}`);

    this.state = new Synchronizer(TERMINATED, [ UNREADY, READYING, READY_FOR_ASSIGN, ASSIGNING, ASSIGNED, WORKING, TERMINATED ]);

    this.clearTimers();

    if (this.evaluatorHandle && typeof this.evaluatorHandle.terminate === 'function')
    {
      try
      {
        this.evaluatorHandle.terminate(immediate);
      }
      catch (e)
      {
        this.error(`Error terminating sandbox ${this.id}:`, e);
      }
      finally
      {
        this.evaluatorHandle = null;
      }
    }

    // Don't leave an orphaned sandbox in supervisor.
    // This is redundant when called via supervisor.returnSandbox(sandbox).
    common.removeElement(this.supervisor.sandboxInventory, this);

    if (reject)
      this.emit('reject', new Error(`Sandbox ${this.identifier} was terminated.`));

    this.sandboxEmit('end');
  }

  // _Idx
  //
  // updateTime, resetSliceReport, sandboxEmit, error, warning
  //

  /**
   * ringNPostMessage can send a `measurement` request and update these
   * totals.
   */
  updateTime (measurementEvent)
  {
    ['total', 'CPU', 'webGL', 'webGPU'].forEach((key) => {
      if (measurementEvent[key])
        this.sliceTimeReport[key] += measurementEvent[key];
    });
  }

  /**
   * Start over sandbox work timers.
   */
  resetSliceReport ()
  {
    this.sliceTimeReport = {
      total: 0,
      CPU: 0,
      webGL: 0,
      webGPU: 0,
    };
    this.sliceOutDataSize = 0;
  }

  /**
   * Safe event emitter on sandboxHandle.
   * @param {string} event
   * @param  {...any} args
   */
  sandboxEmit(event, ...args)
  {
    this.supervisor.safeEmit(this.sandboxHandle, event, ...args);
  }

  /**
   * Error feedback to user.
   * @param {string} message
   * @param {Array<Error>|Error|string} [coreError=null]
   */
  error (message, coreError)
  {
    this.supervisor.error(message, coreError);
  }

  /**
   * Warning feedback to user.
   * @param {string[]} messages
   */
  warning (...messages)
  {
    this.supervisor.warning(...messages);
  }
}

Sandbox.idCounter = 1;
Sandbox.debugWork = false;
Sandbox.debugState = false;
Sandbox.debugEvents = false;

exports.Sandbox = Sandbox;
exports.SandboxError = SandboxError;
exports.NoProgressError = NoProgressError;
exports.SliceTooSlowError = SliceTooSlowError;
exports.UncaughtExceptionError = UncaughtExceptionError;
