/**
 * Supervisor constructor
 *
 * A supervisor manages the communication with the scheduler, manages sandboxes, and
 * decides which workload should be sent to which sandboxes when.
 *
 * Possible states: 'initial', 'ready', 'stopping', 'stopped', 'broken'
 * Start state:
 * - initial
 *
 * Intermediate states:
 * - ready
 * - stopping
 *
 * Terminal states:
 * - stopped
 * - broken
 *
 * Valid transitions:
 * - initial -> ready -> stopping -> stopped
 * - initial -> broken
 */
class Supervisor extends EventEmitter
{
  /**
   * @constructor
   * @param {Worker} worker
   * @param {Keystore} identity
   * @param {SupervisorOptions} options
   */
  constructor (worker, identity, options)
  {
    super({ captureRejections: false });

    if (!(identity instanceof Keystore))
      throw new Error(`identity ${JSON.stringify(identity)} must be an instance of Keystore`);

    debugging('supervisor') && console.debug('Supervisor.options', options);
    assert(options === worker.workerOptions);
    
    /** @type {Worker} */
    this.worker = worker;
    /** @type {Keystore} */
    this.identityKeystore = identity;
    /** @type {Options} */
    this.options = new Options(options, worker);

    selectiveDebug() && console.debug('Supervisor: cores.cpu, cores.gpu, maxSandboxes', options.cores?.cpu, options.cores?.gpu, this.options.maxSandboxes);

    /** @type {ModuleCache} */
    this.moduleCache = new ModuleCache(this);

    // Manage delays and exponential backoff.
    this.delayManager = new DelayManager(this, this.options.defaultDelayIncrementMs);

    /* See https://distributive.atlassian.net/browse/DCP-3175 */
    /** @type {OriginAccessManager} */
    this.originManager = OriginAccessManager.construct(this.options.allowOrigins);

    /** @type {ProtocolManager} */
    this.dcp4 = new ProtocolManager(this);

    /** @type {common.DebuggingTools} */
    this.dbg = new common.DebuggingTools(this);

    // Turn on for max speed debugging.
    if (false)
    {
      this.delayManager.delayScaler = 0.05;
      this.options.watchdogInterval = 0.25;
    }

    /** @type { Synchronizer } */
    this.state = new Synchronizer('initial', [ 'initial', 'ready', 'stopping', 'stopped', 'paused', 'broken' ]);
    /** @type {Object<string, JobManager>} */
    this.jobMap = {}; // jobAddress => jobManager

    /** @type {JobManager[]} */
    this.jobManagerInventory = common.InventoryArray('jobManagers');
    /** @type {Sandbox[]} */
    this.sandboxInventory = []; // All sandboxes that are being used by the job managers. Makes sure we don't lose sandboxes.
    /** @type {{ next: cbNext, commit: cbCommit, useGPU: cbUseGPU }} */
    this.cursor = null;
    /**  @type {FetchState} */
    this.fetchState = null;
    /**
     * this.quanta.localTime := fixed-up EMA times series of CPUTime + GPUTime over all jobs.
     * this.quanta.globalTime := fixed-up EMA times series of sliceCPUTime + sliceGPUTime over all jobs.
     * this.quanta.defaultQuanta := fixed-up ratio: this.quanta.localTime / this.quanta.globalTime
     * @type {Quanta}
     */
    this.quanta = new Quanta(this);

    /**
     * Evaluator down management.
     * @type {EvaluatorManager}
     **/
    this.evaluator = new EvaluatorManager();

    // There are 2 kinds of barriers.
    // 1) fetchTaskBarrier is a barrier for the task fetching from task distributor path.
    // 2) roundRobinBarrier is a barrier for the slice execution path.
    /** @type {boolean} */
    this.fetchTaskBarrier = false;
    /** @type {boolean} */
    this.roundRobinBarrier = false;
    /** @type {string[]} */
    this.unresolvedJobs = [];
    /**
     *  An N-slot ring buffer of job addresses. Stores all jobs that have been rejected by the worker
     *  Required for the implementation of work.reject
     *  @type {RingBuffer}
     */
    this.ringBufferOfRejects = new RingBuffer(200); //  N = 200 should be more than enough.
    /**
     *  An N-slot ring buffer of job addresses. Stores all jobs that have had no more than 1 slice run in the ring buffer.
     *  Required for the implementation of discrete jobs
     *  @type {RingBuffer}
     */
    this.ringBufferOfJobs = new RingBuffer(200); //  N = 200 should be more than enough.
    /**
     * When true we await waitUntilWorkIsReady until at least 1 job is ready with at least 1 ready slice.
     * waitUntilWorkIsReady
     * @type {boolean}
     */
    this.waitForWork = true;
    /**
     * Last repoMan time stamp.
     * @type {number}
     */
    this.lastRepoMan = Date.now();
    /**
     * Last prune time stamp.
     * @type {number}
     */
    this.lastPrune = Date.now();
    /**
     * General time stamp.
     * @type {number}
     */
    this.lastTime = Date.now();
    /**
     * Last time a request was sent to Task Distributor.
     * @type {number}
     */
    this.lastTDRequest = 0;
    /**
     * Run once at startup.
     * @type {boolean}
     */
    this.runOnceAtStartup = true;
    /**
     * Fetch started time stamp.
     * @type {number}
     */
    
    this.fetchTaskStarted = 0;
    /**
     * The capabilities of a random sandbox.
     * @todo XXXpfr Re-work this once fetchTask uses the capabilities of every sandbox to fetch slices.
     * @type {object}
     */
    this.capabilities = null;
    /**
     * The worktimes supported by the client environment.
     * The default of undefined means that in requestTask, worktimes will take on the op-router default specified.
     * @type {Array<{ name: string, versions: Array<string> }>}
     */
    this.worktimes = undefined;
    /**
     * When this.sliceTiming is set to be true, it displays the timings of a every slice
     * slice['queueingDelta'] = timespan of when slice is passed to jobManager.runQueuedSlice until sandbox.work
     * slice['executionDelta'] = timespan of execution in sandbox
     * slice['resultDelta'] = timespan of when sandbox finishes executing until recordResult completes.
     * @type {boolean}
     */
    this.sliceTiming = false;
    /**
     * Timestamp which represents the last time the checkForTabSuspension method was invoked.
     * @type {number}
     */
    this.lastSuspensionDetectionCheck = 0;
  }

  //
  // Compatibility layer between Sup1, Sup2 and the Sup interface exposed by Worker.
  //
  /**
   * Get all sandboxes.
   * @type {Sandbox[]}
   */
  get sandboxes () { return this.sandboxInventory.filter((sandbox) => !sandbox.isTerminated); }
  /**
   * Get all working sandboxes.
   * @type {Sandbox[]}
   */
  get workingSandboxes () { return this.sandboxInventory.filter((sandbox) => sandbox.isWorking); }
  /**
   * Get the number of working sandboxes.
   * @type {number}
   */
  get workingSandboxCount () { return this.workingSandboxes.length; }
  /**
   * Get all slices over all jobs..
   * @type {Slice[]}
   */
  get slices () {
    const slices = [];
    this.jobManagerInventory.forEach((jobManager) => { slices.push(...jobManager.sliceInventory); });
    return slices;
  }
  /**
   * Get all queued slices over all jobs..
   * @type {Slice[]}
   */
  get queuedSlices () {
    const slices = [];
    this.jobManagerInventory.forEach((jobManager) => { slices.push(...jobManager.queuedSlices); });
    return slices;
  }
  /**
   * Get all queued slices over all jobs..
   * @type {Slice[]}
   */
  get workingSlices () {
    const slices = [];
    this.jobManagerInventory.forEach((jobManager) => { slices.push(...jobManager.workingSlices); });
    return slices;
  }
  /** @type {opaqueId} */
  get workerId ()   { return this.options.workerId; }
  /** @type {opaqueId} */
  set workerId (id) { this.options.workerId = id; }
  /**
   * Ignore localStorage and set workerId directly.
   * When using multiple workers with different workerId's we don't want to
   * write to the localStorage 'workerId'; localWorkerId ignores localStorage.
   * @type {opaqueId|null}
   */
  set localWorkerId (id) { this.options.localWorkerId = id; }
   /** @type {string} */
  get version () { return '2.0.0'; }

  //
  // Miscellaneous properties.
  //

  /**
   * Dynamic maxWorkingCores.
   * The maximum number of cores that can be executing slices. Slices are scheduled
   * using density. E.g. suppose a job has GPUDensity is 0 and CPUDensity is 0.5,
   * then 2 slices of this job can be scheduled on a single core.
   * @type {number}
   */
  get maxWorkingCores () { return this.options.cores?.cpu; }
  /**
   * Dynamic maxWorkingGPUs.
   * The maximum number of GPUs that can be executing slices. Slices are scheduled
   * using density. E.g. suppose a job has GPUDensity is 0.5 and CPUDensity is 0.5,
   * then 2 slices of this job can be scheduled on a single GPU core and a single CPU core.
   * @type {number}
   */
  get maxWorkingGPUs () { return this.options.cores?.gpu; }
  /**
   * Indicates whether supervisor is ready for business.
   * @type {boolean}
   */
  get isReady () { return this.worker.working && this.state.is('ready'); }
  /**
   * The # of sandboxes not being used.
   * @type {number}
   */
  get unusedSandboxCount () { return this.options.maxSandboxes - this.workingSliceCount; }
  /**
   * The unused amount of CPU density in the cores.
   * @type {number}
   */
  get unusedCoreSpace () { return this.maxWorkingCores - this.workingSliceDensity; }
  /**
   * The unused amount of GPU density in the cores.
   * Use Math.max(1, this.maxWorkingGPUs) so there's always enough room to schedule
   * a GPU slice when this.workingGPUDensity = 0. In RoundRobinSlices we use the accumulated
   * recent history ( canScheduleGPU(maxWorkingGPUs) ) to check whether the average recent
   * density is within this.maxWorkingGPUs.
   * @type {number}
   */
  get unusedGPUSpace () { return Math.max(1, this.maxWorkingGPUs) - this.workingGPUDensity; }
  /** @type {number} */
  get workingSliceDensity ()
  {
    let density = 0;
    for (const jobMan of this.jobManagerInventory)
      density += jobMan.workingSliceDensity;
    return density;
  }
  /** @type {number} */
  get workingGPUDensity ()
  {
    let density = 0;
    for (const jobMan of this.jobManagerInventory)
      if (jobMan.useGPU)
        density += jobMan.workingGPUDensity;
    return density;
  }
  /** @type {number} */
  get workingSliceCount ()
  {
    let count = 0;
    for (const jobMan of this.jobManagerInventory)
      count += jobMan.workingSliceCount;
    return count;
  }
  /**
   * Compute the estimated time to completion of all work.
   * The time is measured as if there were only a single slice running at a time.
   * workRemaining is the amount of time until completion.
   * @type {number}
   */
  get workRemaining ()
  {
    let workRemaining = 0;
    for (const jobMan of this.jobManagerInventory)
      workRemaining += jobMan.workRemaining;
    return workRemaining;
  }
  /**
   * While a bit redundant, the concept of cores is so basic that we need an accessor.
   * Will prevent future mistakes.
   * @type {{ cpu: number, gpu: number }}
   */
  get cores () { return this.options.cores; }

  // _Idx
  //
  // work, checkCapabilities
  //

  /**
   * Set up sandboxes and interval timers, then start to search for work.
   * Called in Worker.start().
   * Initial entry point after Worker constructor.
   * We need to start searching for work here to allow starting and stopping a worker.
   */
  work ()
  {
    const abort = async (error) => {
      // May be in a stopping/stopped state, because dcp-worker was hit with ctrl-C.
      this.state.set(['ready', 'stopping', 'stopped'], 'broken');
      await this.worker.stop(true);
      throw error;
    };
    /* Provide opportunity for calling code to hook ready/error events. */
    dcp_timers.setImmediate(() => {
      try
      {
        // [ 'initial', 'ready', 'stopping', 'stopped', 'paused', 'broken' ]
        if (this.state.isNot('initial'))
        {
          if (this.state.in(['ready', 'stopping']))
          {
            this.warning(`Supervisor.work was called when supervisor is already ${this.state.valueOf()}.`, 'Please either wait and try again or restart worker.');
            return;
          }
          else if (this.state.is('broken'))
          {
            this.warning("Cannot call Supervisor.work when supervisor is in a 'broken' state. Please restart worker.");
            return;
          }
          this.state.set(['stopped', 'paused'], 'initial');
        }

        // Start up the connections.
        this.dcp4.instantiateAllConnections();
        this.evaluator.initialize();

        /**
         * Beacon interval timer.
         * @deprecated
         * @todo XXXpfr When Sheepdog dies get rid of this.progressReportTimer.
         * In fact, Soteria notification is good enough. But keep this around until Sheepdog dies.
         */
        this.progressReportTimer = dcp_timers.setInterval(() => this.emitProgressReport(), this.options.progressReportIntervalMs);
        /**
         * Watchdog: fetchTask-driven interval timer.
         * This is what drives the worker to always fetch slices.
         */
        this.watchdogTimer = dcp_timers.setInterval(() => this.fetchTask(), this.options.watchdogInterval);

        // Interval timers helps keep workers and localExec alive forever.
        this.progressReportTimer.unref();
        this.watchdogTimer.unref();

        // Interval timer used to detect when the tab becomes suspended
        this.suspensionDetectionInterval = dcp_timers.setInterval(() => this.checkForTabSuspension(), this.options.detectSuspensionIntervalMs);
        this.suspensionDetectionInterval.unref();
        
        if (false || debugging('supervisor'))
        {
          this.sliceDebuggingTimer = dcp_timers.setInterval(() => {
            this.jobManagerInventory.forEach((jobMan) => {
              const { unassigned, ready, reserved, working, workdone, complete, failed, finished } = jobMan.dumpSlices ('work', false, false);
              console.debug(`work(${this.workerId},${jobMan.identifier},${this.unusedSandboxCount},${this.unusedCoreSpace},${this.workingSliceCount},${this.workingSliceDensity}): u/r/rsv/w/wd/c/f/fsh/t ${unassigned}/${ready}/${reserved}/${working}/${workdone}/${complete}/${failed}/${finished}/${jobMan.sliceInventory.length}, totalSbxes ${this.sandboxInventory.length}`);
            });
          }, 30 * 1000);
          this.sliceDebuggingTimer.unref();
        }

        this.state.set('initial', 'ready');

        // Create 1 sandbox now to get the capabilities which are sent to Task Distributor by fetchTask.
        this.createSandbox()
          .then((sandbox) => {
            this.sandboxInventory.push(sandbox);
            debugging('supervisor') && console.debug('work() after createSandbox', this.sandboxInventory.length, sandbox.identifier, Date.now() - this.lastTime, this.options.watchdogInterval);
            this.fetchTask() // Don't wait for watchdog.
              .catch (async (error) => {
                this.warning('work() failed when calling fetchTask; will retry.', error);
                // fetchTask is allowed to fail w/o hurting the worker.
              });
          })
          .catch(async (error) => {
            this.error('work() failed when calling createSandbox, exiting...', error);
            await abort(error);
          });
      }
      catch(error)
      {
        this.error('work() failed', error);
        if (this.state.is('initial')) this.state.set('initial', 'broken');
        else if (!this.state.is('broken')) this.state.set('ready', 'broken');
        this.worker.stop(true).finally(() => { throw error; });
      }
    });
  }

  /** Construct capabilities when necessary. */
  checkCapabilities (sandbox)
  {
    /**
     * Assign the capabilities of one the sandboxes before fetching slices from the scheduler.
     * @todo XXXpfr Re-work this once fetchTask uses the capabilities of every sandbox to fetch slices.
     */
    this.capabilities = sandbox.capabilities;
    if (DCP_ENV.isBrowserPlatform && this.capabilities.browser)
      this.capabilities.browser.chrome = DCP_ENV.isBrowserChrome;

    debugging('supervisor') && console.debug('Supervisor.checkCapabilities computed',  Date.now() - this.lastTime);
  }

  // _Idx
  //
  // safeEmit, workerEmit, jobEmit,
  // error, warning, showSlices
  //

  /**
   * Safe event emitter.
   * @param {EventEmitter} emitter
   * @param {string} event
   * @param {...any} args
   */
  safeEmit(emitter, event, ...args)
  {
    try
    {
      emitter.emit(event, ...args);
    }
    catch (error)
    {
      this.error(`Event handler for event ${event} threw an exception`, error);
    }
  }

  /**
   * Safe event emitter on worker.
   * @param {string}  event
   * @param  {...any} args
   */
  workerEmit(event, ...args)
  {
    this.safeEmit(this.worker, event, ...args);
  }

  /**
   * Safe event emitter on slice.jobHandle.
   * @param {Slice}   slice
   * @param {string}  event
   * @param  {...any} args
   */
  jobEmit(slice, event, ...args)
  {
    this.safeEmit(slice.jobHandle, event, ...args);
  }

  /**
   * Error feedback to user.
   * Four forms:
   *     error(message, coreError) -- where coreError is an Error
   *     error(message, coreError, false) -- where coreError is an Error
   *     error(message, additionalInfo) -- where additionalInfo is a string
   *     error(message, additionalInfo, false) -- where additionalInfo is a string
   * When displayTopOfStack is false, then
   *     dcpError=this.error(msg, error, false)
   * has dcpError.stack === error.stack and
   *     dcpError=this.error(msg, additionalInfo, false)
   * has dcpError.stack === ''.
   * @param {string} message
   * @param {Array<Error>|Error|string} [coreError=null]
   * @param {boolean} [displayTopOfStack=true]
   */
  error (message, coreError = null, displayTopOfStack = true)
  {
    if (coreError instanceof AggregateError)
      coreError = coreError.errors;
    if (Array.isArray(coreError) && coreError.length > 0) // Emit error for every element of array.
      return coreError.flat().forEach((c_err) => this.error(message, c_err, displayTopOfStack));

    debugging('supervisor') && console.debug('Supervisor.error:', message, coreError);
    if (!message)
      message = 'Supervisor.error called w/o valid message';
    let additionalInfo  = (coreError instanceof Error) ? null : coreError;
    if (additionalInfo)
    {
      if (typeof additionalInfo === 'object')
        additionalInfo = JSON.stringify(additionalInfo);
      else if (typeof additionalInfo !== 'string')
        additionalInfo = String(additionalInfo);
    }

    const dcpError = (coreError instanceof Error)
      ? new DCPError(message, coreError, displayTopOfStack)
      : new DCPError(message, '', additionalInfo, displayTopOfStack);

    this.worker.emit('error', dcpError);
  }

  /**
   * Warning feedback to user.
   * @param {string[]} messages
   */
  warning (...messages)
  {
    debugging('supervisor') && console.debug('Supervisor.warning:', messages);
    if (messages.length < 1)
      messages = [ 'Supervisor.warning called w/o valid message(s)' ];
    messages.forEach((message) => this.worker.emit('warning', message));
  }

  /**
   * Dump the status of all slices.
   * @param {*} [tag]
   */
  showSlices (tag = '')
  {
    for (const jm of this.jobManagerInventory)
    {
      console.log(`showSlices:${tag}: estimation=${jm.isEstimation}, workerId=${this.workerId}, jobMan=${jm.identifier}, slices=${JSON.stringify(jm.sliceInventory.map((x) => x.sliceNumber))}`);
      for (const slice of jm.sliceInventory)
        console.log(`\t${slice.identifier}`);
    }
  }

  /**
   * Transition from state 'ready to 'paused'.
   * When paused, the worker will not execute new slices or fetch new work.
   * But it will be alive and well, waiting to be unpaused.
   * No slices will be returned to scheduler.
   */
  pause ()
  {
    selectiveSupEx() && console.debug(`Supervisor.pause: workerId ${this.workerId}`);
    if (this.state.isNot('paused'))
      this.state.set('ready', 'paused');
    //this.showSlices('pause');
  }
  /**
   * Transition to state 'paused' to 'ready'.
   * The worker will now execute new slices and fetch new work.
   */
  unpause ()
  {
    selectiveSupEx() && console.debug(`Supervisor.unpause: workerId ${this.workerId}`);
    if (this.state.isNot('ready'))
      this.state.set('paused', 'ready');
  }

  // _Idx
  //
  // returnAllSlices, stopAndShutdown
  // stopWork, purgeJob
  //

  /** @returns {Promise<*>} */
  async returnAllSlices ()
  {
    if (selectiveDebug())
    {
      const activeSlices = this.jobManagerInventory.map((jm) => jm.activeSlices).flat();
      if (activeSlices.length > 0)
        this.warning(`Returning active slices : ${JSON.stringify(activeSlices.map((slice) => slice.identifier), null, 2)}`);
    }
    // The promises are all about returning the slices to the scheduler and there's no reason to await that.
    return Promise.all(this.jobManagerInventory.map((jm) => jm.destroy()));
  }

  /**
   * Use explicit awaits to make sure things get shutdown properly.
   * Probably being overly conservative, but there have been problems
   * shutting down before the function exits.
   * @returns {Promise<*>}
   */
  async stopAndShutdown ()
  {
    try
    {
      while (this.sandboxInventory.length)
        this.returnSandbox(this.sandboxInventory[0]);
      this.sandboxInventory = [];
    }
    finally
    {
      try
      {
        // There shouldn't be anything in the job managers, but just to be safe call returnAllSlices.
        // Clear jobManagerInventory, close all connections and set state to 'stopped'.
        await this.returnAllSlices();
      }
      finally
      {
        try
        {
          // Shutdown TD, RS, ER, PM
          await this.dcp4.closeConnections();

          // Reset job dependent structures.
          this.jobManagerInventory = common.InventoryArray('jobManagers');
          this.moduleCache = new ModuleCache(this);
          this.unresolvedJobs = [];
          this.dbg = new common.DebuggingTools(this);
        }
        finally
        {
          if (this.state.isNot('stopped'))
            this.state.set('stopping', 'stopped');
          // This log message assume slices were returned to scheduler in a previous operation, which is the only current use case.
          // If we use this function in a different way in the future, update the log message.
          selectiveDebug() && console.debug(`Supervisor.stopAndShutdown(${this.state}): terminated all sandboxes and returned all slices to scheduler...`);
        }
      }
    }
  }

  /**
   * Terminates sandboxes and returns slices.
   * Sets the working flag to false, call @this.work to start working again.
   *
   * If forceTerminate is true: Terminates all sandboxes and returns all slices.
   * If forceTerminate is false: Terminates non-working sandboxes and returns initial and ready slices.
   *
   * @param {boolean} [forceTerminate = true] - true if you want to stop the sandboxes from completing their current slice.
   * @returns {Promise<*>}
   */
  async stopWork (forceTerminate = true)
  {
    /** @returns {boolean} */
    const doNotWaitForWork = () => {
      return (this.evaluator.reallyDown || this.sandboxInventory.filter(sbx => !sbx.isTerminated).length < 1);
    }
    selectiveDebug() && console.debug(`Supervisor.stopWork(${forceTerminate}, ${this.state}): terminating sandboxes and returning slices to scheduler.`);

    // [ 'initial', 'ready', 'stopping', 'stopped', 'paused', 'broken']
    if (this.state.in(['stopping', 'stopped']))
    {
      this.warning(`Supervisor.stopWork was called when supervisor is in state ${this.state.valueOf()}.`, 'Please either wait and try again or restart worker.');
      return;
    }
    else if (this.state.is('initial'))
    {
      this.warning('Cannot call stopWork before worker has started. Please either wait and try again or restart worker.');
      return;
    }

    try
    {
      // Set state to 'stopping'.
      this.state.set(['ready', 'paused', 'broken'], 'stopping');
      
      // Clear the interval timers.
      if (this.progressReportTimer)
        dcp_timers.clearInterval(this.progressReportTimer);
      this.progressReportTimer = null;
      if (this.watchdogTimer)
        dcp_timers.clearInterval(this.watchdogTimer);
      this.watchdogTimer = null;

      this.dcp4.instantiateAllConnections();

      if (!forceTerminate)
      {
        const slicesToReturn = [];
        for (const jm of this.jobManagerInventory)
          slicesToReturn.push(...jm.queuedSlices);

        const reason = 'stopWork returning all queued slices';
        this.returnSlices(slicesToReturn, reason);

        for (let k = 0; k < 3; k++)
        {
          await new Promise((resolve) => {
            // Count the slices that have been working or close-to-working but haven't submitted results yet.
            let activeSliceCount = 0;
            for (const jm of this.jobManagerInventory)
              activeSliceCount += jm.activeSlices.length;
            // When no active slices we're done.
            if (activeSliceCount === 0)
              resolve();
            // When no work can be completed we return all slices and leave.
            if (doNotWaitForWork())
              resolve();
            selectiveDebug() && console.debug(`StopWork: waiting for ${activeSliceCount} working slices to finish`, k);
            // Resolve and finish stopWork once all sandboxes have finished submitting their results.
            this.worker.on('result', (...ev) => {
              selectiveSupEx() && console.debug(`StopWork(${this.workerId}): result handler, activeSliceCount ${activeSliceCount}`, JSON.stringify(ev, null, 2));
              if (--activeSliceCount === 0)
                resolve();
            });
            this.on('evalDown', () => {
              selectiveSupEx() && this.warning('Evaluator is down.', 'Return all slices to scheduler.');
              this.returnAllSlices();
              resolve();
            });
          });
        }

        if (selectiveDebug())
        {
          console.debug(`stopWork(${this.state.valueOf()}): After waiting for working slices to finish: workingSbxes: ${this.workingSandboxCount}, totalSbxes: ${this.sandboxInventory.length}, jobs: ${this.jobManagerInventory.length}`);
          this.jobManagerInventory.forEach((jm) => {
            console.debug('stopWork job', jm.identifier);
            console.debug(jm.countSliceStr('stopWork'));
          });
        }
      }
    }
    finally
    {
      selectiveSupEx() && this.warning('All sandboxes empty, stopping worker and closing all connections.');
      return this.stopAndShutdown();
    }
  }

  /**
   * Purge all traces of the job.
   * @param {JobManager} jobManager
   */
  purgeJob (jobManager)
  {
    selectiveDebug() && console.debug(`Supervisor.purgeJob ${jobManager.identifier}.`);
    if (!jobManager.dead)
    {
      // jobManager will be either in this.jobManagerInventory or this.unresolvedJobs.
      if (!common.removeElement(this.unresolvedJobs, jobManager.address))
        this.jobManagerInventory.delete(jobManager);
      this.moduleCache.removeJob(jobManager.address);
      common.debugQuanta() && this.dbg.cleanUpDeadJob(jobManager.address);
      // DANGER: Do not call JobManager.destroy(true) anywhere else.
      jobManager.destroy(true /*itsDeadJim*/);
    }
  }

  // _Idx
  //
  // roundRobinSlices, makeJobSelectionCursor, handleSandboxWorkError, handleFailedSlice
  //

  /**
   * Note: It's not currently necessary to wrap _roundRobinSlices in static and dynamic catch blocks.
   *       But in the future, changes happen and bugs exist.
   *
   * Round-robin through the job managers, picking 1 slice to run each time.
   * Try to have the same number of working sandboxes for each job.
   * Try to run a slice on every available sandbox.
   *
   * The basic idea behind the scheduling of slices in this implementation is to keep as
   * many slices from different jobs running as possible, so as to reduce the likelihood
   * of resource contention between sandboxes.
   *
   * Slices are scheduled based on the following ruleset:
   * 1) Order the jobs as described below and pick 1 slice from each job in a round-robin manner,
   *    so the order of the jobs is the determining factor for the slices that are chosen.
   *    Thus in what follows we'll only talk about job order.
   * 2) cursor = makeJobSelectionCursor(), then cursor.next() returns a slice chosen as follows.
   * 3) Let concurrency range from 1 to maxWorkingCores.
   * 4) For a given concurrency, let readyJobs be all jobs such that jobMan.workingSliceDensity < concurrency.
   * 5) Do an ascending sort of readyJobs wrt jobMan.emaElapsedTime.
   * 6) Pick the longest job in readyJobs that doesn't have any executing slices.
   * 7) Alternately shift a job from readyJobs vs choose a job from a random nearly finished job, and remove job from readyJobs.
   * 8) When there are no more almost finished jobs with slices, shift jobs from readyJobs.
   * 9) Jobs which have slicePriority set by the task-distributor may have slices chosen ahead of the above algorithm.
   * 10) Jobs with a slicePriority closer to 1 are more likely to be chosen.
   * 11) After finishing concurrency at maxWorkingCores, cursor.next() returns null, so create a new cursor.
   * @returns {Promise<any>}
   */
  async roundRobinSlices ()
  {
    if (!this.isReady) // When paused do not enter.
      return;

    try
    {
      return this._roundRobinSlices()
        .catch ((error) => {
          this.error('Failed to run slices!', error);
        });
    }
    catch (error)
    {
      this.error('Failed to run slices.', error); // Intentionally different error message than above.
    }
  }

  /**
   * Private, do not use; call this.roundRobinSlices() instead.
   *
   * Round-robin through the job managers, picking 1 slice to run each time.
   * Try to have the same number of working sandboxes for each job.
   * Try to run a slice on every available sandbox.
   * @private
   * @returns {Promise<any>}
   */
  async _roundRobinSlices ()
  {
    //
    // Should we try to put all runSlice promises in an array and return Promise.all(runslice-promises) ?
    //
    try
    {
      selectiveDebug2() && console.debug('BarrierState:RRS:', this.fetchTaskBarrier, this.roundRobinBarrier);
      // roundRobinBarrier is a barrier for the slice execution path.
      if (this.roundRobinBarrier)
        return;
      this.roundRobinBarrier = true;
      // When eval is down, don't execute slices.
      if (this.evaluator.down && this.evaluator.createSandboxRefCount > 0)
        return;

      /**
       * The amount of unusedCoreSpace available for new slices to run in sandboxes.
       * If unusedCoreSpace is 2.5 and there are 6 slices with density 0.4, and there are enough non-working usable
       * sandboxes, then all 6 slices will be scheduled to run.
       * @type {number}
       */
      const unusedCoreSpace = this.unusedCoreSpace;
      /**
       * The number of sandboxes not currently being used.
       * @type {number}
       */
      const unusedSandboxCount = this.unusedSandboxCount;

      if (unusedCoreSpace < common.doNotSchedule || unusedSandboxCount < 1)
      {
        selectiveDebug2() && console.debug('RRS: bail early space/barrier/unusedSlots', unusedCoreSpace, this.roundRobinBarrier, unusedSandboxCount);
        return;
      }

      if (selectiveDebug2())
      {
        this.jobManagerInventory.forEach((jobMan) => {
          const { unassigned, ready, reserved, working, workdone, complete, failed, finished } = jobMan.dumpSlices ('RRS', false, false);
          console.debug(`RRS(${jobMan.identifier},${unusedSandboxCount},${unusedCoreSpace}): u/r/rsv/w/wd/c/f/fsh ${unassigned}/${ready}/${reserved}/${working}/${workdone}/${complete}/${failed}/${finished}`, jobMan.identifier, this.sandboxInventory.length);
        });
      }

      if (false || selectiveDebug())
      {
        let totalReady = 0, totalReadyDensity = 0;
        for (const jobMan of this.jobManagerInventory)
        {
          const currentReady = jobMan.readySlices.length;
          const currentReadyDensity = jobMan.readySlices.length * jobMan.estimateDensity;
          totalReady += currentReady;
          totalReadyDensity += currentReadyDensity;
          console.debug(`RRS: job ${jobMan.identifier}, density ${jobMan.estimateDensity}, readySlices ${currentReady}, readyDensity ${currentReadyDensity}`);
        }
        console.debug(`RRS: space ${unusedCoreSpace}, unusedSandboxCount ${unusedSandboxCount}, totalReady ${totalReady}, totalReadyDensity ${totalReadyDensity}`);
      }

      /** @type {Slice[]} */
      const slices = [];
      /** @type {number} */
      let density = 0;
      /** @type {number} */
      let gpuDensity = 0;

      const isSpaceAvailable = (density) => {
        const result = density < unusedCoreSpace && slices.length < unusedSandboxCount;
        selectiveDebug2() && console.debug('RRS: isSpaceAvailable', density < unusedCoreSpace, slices.length < unusedSandboxCount);
        return result;
      }

      // When there's no more CPU space, break out of the loop.
      // When there's no more GPU space, tell the cursor to not pick any more slices from
      // GPU jobs, but continue trying to find slices from CPU jobs if there's CPU sapce.

      // Guarantee one full cursor pass.
      let recreateCursorCount = 0;

      if (this.cursor)
        this.cursor.useGPU(true); // Restore use of GPUs.

      while (isSpaceAvailable(density + common.schedulingSlop))
      {
        // Get existing cursor or create new one.
        if (!this.cursor)
          this.cursor = this.makeJobSelectionCursor();

        // Get the next slice, then check to see whether it can be used.
        const slice = this.cursor.next();
        if (!slice)
        {
          this.cursor = null;
          if (++recreateCursorCount > 1)
            break;
          // Start a new cursor.
          continue;
        }
        const job = slice.jobManager;
        // Check to see if slice fits into CPU space
        if (density + job.estimateDensity > unusedCoreSpace + common.schedulingSlop)
          break;
        // Check to see if slice fits into GPU space
        if (job.useGPU && canScheduleGPU(this.maxWorkingGPUs)
          && gpuDensity + job.estimateGPUDensity > this.unusedGPUSpace)
        {
          // Advance cursor and don't try to fetch slices from GPU jobs until the next RRS call.
          /** XXXpfr @todo Weakness: Another GPU could have smaller job.estimateGPUDensity which could fit. */
          // This weakness will be a problem when webGPU supports multiple concurrent kernels
          // on the same GPU, like CUDA does.
          this.cursor.commit();
          this.cursor.useGPU(false);
          continue;
        }

        this.cursor.commit(slice); // Advance cursor and reserve slice.
        density += job.estimateDensity;
        slices.push(slice);

        if (selectiveDebug2())
        {
          job.useGPU && console.debug(`RRS: GPU scheduling: gpuDensity/gpuSpace ${gpuDensity.toFixed(7)}/${this.unusedGPUSpace.toFixed(7)}, jobGPUDensity/jobCPUDensity ${job.estimateGPUDensity.toFixed(7)}/${job.estimateDensity.toFixed(7)}`);
          console.debug('RRS: density/space/numSlices/unusedSlots/jobDensity/workingSlices', density, unusedCoreSpace, slices.length, unusedSandboxCount, job.estimateDensity, this.workingSliceCount);
        }
      }

      selectiveSupEx() && density > 0 && console.debug(`roundRobinSlices(${this.workingSliceCount},${this.workingSliceDensity},${this.workerId}): Found density ${density.toFixed(7)}/${unusedCoreSpace} with ${slices.length} slices:`, slices.map((slice) => slice.identifier), this.jobManagerInventory.map((jm) => `${jm.identifier}:${jm.estimateDensity.toFixed(7)}:${jm.emaSliceTime.toFixed(0)}`));

      /** XXXpfr @todo Should we try to put all runSlice promises in an array and return Promise.all(runslice-promises) ? */
      /** XXXpfr @todo Create JobManager.runSlices(array_of_slices) ? */
      // Execute the slices.
      if (slices.length > 0)
      {
        const lastSlice = slices.pop();
        for (const slice of slices)
          slice.jobManager.runSlice(slice);
        return lastSlice.jobManager.runSlice(lastSlice);
      }
    }
    finally
    {
      this.roundRobinBarrier = false;
    }
  }

  /**
   * @private
   * @callback cbNext
   * @returns {Slice}
   */
  /**
   * @private
   * @callback cbCommit
   * @param {Slice} [slice]
   */
  /**
   * @private
   * @callback cbUseGPU
   * @param {boolean} b
   */

  /**
   * Factory function which instantiates a JobSelectionCursor.  A JobSelectionCursor
   * steps the order that job slices should be selected for execution in the supervisor,
   * given the current state of the supervisor and the availability of jobs when the
   * inventory was snapshot.  The entire slice scheduling algorithm is represented by
   * this cursor.
   *
   * The basic idea behind the scheduling of slices in this implementation is to keep as
   * many slices from different jobs running as possible, so as to reduce the likelihood
   * of resource contention between sandboxes.
   *
   * Slices are scheduled based on the following ruleset:
   * 1) Order the jobs as described below and pick 1 slice from each job in a round-robin manner,
   *    so the order of the jobs is the determining factor for the slices that are chosen.
   *    Thus in what follows we'll only talk about job order.
   * 2) cursor = makeJobSelectionCursor(), then cursor.next() returns a slice chosen as follows.
   * 3) Let concurrency range from 1 to maxWorkingCores.
   * 4) For a given concurrency, let readyJobs be all jobs such that jobMan.workingSliceDensity < concurrency.
   * 5) Do an ascending sort of readyJobs wrt jobMan.emaElapsedTime.
   * 6) Pick the longest job in readyJobs that doesn't have any executing slices.
   * 7) Alternately shift a job from readyJobs vs choose a job from a random nearly finished job, and remove job from readyJobs.
   * 8) When there are no more almost finished jobs with slices, shift jobs from readyJobs.
   * 9) Jobs which have slicePriority set by the task-distributor may have slices chosen ahead of the above algorithm.
   * 10) Jobs with a slicePriority closer to 1 are more likely to be chosen.
   * 11) After finishing concurrency at maxWorkingCores, cursor.next() returns null, so create a new cursor.
   *
   * A custom selection of jobs can be passed in via the argument jobManagers.
   *
   * @param {JobManager[]} [jobManagers]
   * @returns {{ next: cbNext, commit: cbCommit, useGPU: cbUseGPU }}
   */
  makeJobSelectionCursor (jobManagers)
  {
    /* Variables in this scope function as state information for next() */
    /** @type {JobManager[]} */
    var candidateJobs;       // The jobs available with slices ready to execute.
    /** @type {JobManager[]} */
    var readyJobs;           // The jobs from which slices are selected for a given concurrency level.
    /** @type {JobManager[]} */
    var preferedJobs = [];   // Those jobs in readyJobs with a slicePreference property.
    /** @type {JobManager[]} */
    var lowDensityJobs = []; // Jobs with density <= 0.6, will be scheduled again.
    /**
     * Upper bound of the sum of the working slices densities allowed for a given job.
     * type {number}
     **/
    var concurrency = 0;
    /** type {number} */
    var jobIdx = 0;
    /** @type {boolean} */
    var lowDensityPass = false;
    /** @type {number} */
    var longSlicesAvailableToSchedule = Number.MAX_SAFE_INTEGER;
    /** @type {boolean} */
    var peekPrefered = false;
    /** @type {boolean} */
    var skipGPUJobs = false;

    const that = this;
    if (!jobManagers)
      jobManagers = this.jobManagerInventory;

      /** @param {JobManager[]} jobs */
    const jobStateStr = (jobs) => {
      return jobs.map((jm) => `${jm.identifier} : ${jm.readySlices.length} : ${jm.workingSliceDensity} : ${Math.round(jm.emaElapsedTime)}`);
    }
    const jobState = (hdr, jobs) => { console.debug(hdr, jobStateStr(jobs)); }

    /**
     * Do not allow excessive working long slices to block short slices from completing in a
     * reasonable amount of time. We don't want slices from all long jobs to consume more than
     * X% of cores.cpu, when there still exist short slices, This function limits the # of long
     * slices that can be scheduled by limiting longSlicesAvailableToSchedule.
     * Note: There can be no more than cores.cpu long slices in a worker.
     */
    function preventLongSlicesFromHoggingCompute ()
    {
      let workingLongSliceCount = 0, shortSlicesExist = false, longSlicesExist = false;
      for (const jm of jobManagers)
        if (!jm.isLong && jm.queuedSlices.length > 0)
          shortSlicesExist = true;
        else
        {
          longSlicesExist = true;
          workingLongSliceCount += jm.workingSliceCount;
        }
      longSlicesAvailableToSchedule = (shortSlicesExist && longSlicesExist)
        ? Math.max(0, Math.floor(that.options.maxProportionOfLongJobs * that.maxWorkingCores) - workingLongSliceCount)
        : Number.MAX_SAFE_INTEGER
    }

    /**
     * Populate readyJobs with jobs which are ready and have at least one slice which is ready,
     * and whose # of working slice density is less than concurrency. A reserved slice has a
     * finite lifetime and if exceeded, transition it back to ready.
     * @param {JobManager[]} jobManagers
     * @param {number}       concurrency
     */
    function filterJobsAndCheckOldReservedSlices (jobManagers, concurrency) // eslint-disable-line no-shadow
    {
      candidateJobs = [], readyJobs = [];
      const reservedThreshold = Date.now() - that.options.reservedSliceLifetimeMs;
      for (const jobMan of jobManagers)
      {
        if (!jobMan.ready || skipGPUJobs && jobMan.useGPU || jobMan.isLong && longSlicesAvailableToSchedule < 1)
          continue;
        let readyCount = 0;
        for (const slice of jobMan.sliceInventory)
        {
          if (slice.isReady)
            readyCount++;
          else if (slice.isReserved && reservedThreshold > slice.startTime)
          {
            slice.unReserve();
            readyCount++;
          }
        }
        if (readyCount > 0)
        {
          candidateJobs.push(jobMan);
          if (jobMan.workingSliceDensity < concurrency)
            readyJobs.push(jobMan);
        }
      }
    }

    function seed (concurrency) // eslint-disable-line no-shadow
    {
      /* Reset. */
      jobIdx = 0;

      /* Populate readyJobs with jobs which are ready and have at least one slice which is ready,
          and whose # of working slice density is less than concurrency. */
      filterJobsAndCheckOldReservedSlices(jobManagers, concurrency);
      /* Do not allow excessive working long slices to block short slices from completing in a
         reasonable amount of time. */
      preventLongSlicesFromHoggingCompute();
      // candidateJobs = jobManagers.filter((jobMan) => jobMan.readySlices.length > 0);
      // readyJobs = candidateJobs.filter((jobMan) => jobMan.workingSliceDensity < concurrency);

      if (!lowDensityPass && lowDensityJobs.length === 0)
        lowDensityJobs = jobManagers.filter((jm) => jm.estimateDensity > 0 && jm.estimateDensity <= 0.6);

      if (readyJobs.length > 1)
      {
        /* Asc sort by shortest average slice completion time. */
        const shortestSliceJobs = readyJobs.sort((a, b) => Math.round(a.emaElapsedTime) - Math.round(b.emaElapsedTime));
        const almostDoneIndices = shortestSliceJobs.filter((jm) => jm.almostDone).map((_, idx) => idx);
        readyJobs = [];

        /* Find longest job that isn't working. */
        for (let k = shortestSliceJobs.length - 1; k >= 0; k--)
        {
          const jobMan = shortestSliceJobs[k];
          if (jobMan.isNotWorking)
          {
            readyJobs.push(jobMan);
            shortestSliceJobs.splice(k, 1);
            break;
          }
        }

        /* Alternate the next shortest slice with a random almost done job. */
        if (almostDoneIndices.length > 0)
        {
          while (shortestSliceJobs.length > 0)
          {
            readyJobs.push(shortestSliceJobs.shift());
            if (almostDoneIndices.length < 1)
              break;
            else
            {
              const almostDoneIdx = almostDoneIndices[Math.floor(Math.random() * almostDoneIndices.length)];
              readyJobs.push(shortestSliceJobs[almostDoneIdx]);
              shortestSliceJobs.splice(almostDoneIdx, 1);
            }
          }
        }
        if (shortestSliceJobs.length > 0)
          readyJobs.push(...shortestSliceJobs);
      }
      /* Populate preferedJobs with jobs from readyJobs which also have a slicePreference set. */
      preferedJobs = candidateJobs.filter((jm) => jm.hasOwnProperty('slicePreference'));
      selectiveDebug2() && jobState(`makeJobSelectionCursor:seed(${concurrency}): readyJobs:`, readyJobs);
    }

   /**
    * Each invocation of next() identifies one slice to run, or returns false if none can run.
    * @returns {Slice}
    */
    function next ()
    {
      if (concurrency === 0)
        seed(++concurrency);

      selectiveDebug2() && console.debug(`makeJobSelectionCursor(cc/idx/ready/working):next(${concurrency},${jobIdx},${readyJobs.length},${that.workingSliceDensity}): maxWorkingCores ${that.maxWorkingCores}: begin`);
      while (true)
      {
        if (jobIdx >= readyJobs.length)
        {
          if (++concurrency > that.maxWorkingCores)
            break;
          seed(concurrency);
        }

        if (readyJobs.length < 1)
        {
          if (candidateJobs.length < 1)
            break;
          continue; /* No ready jobs at current concurrency level. */
        }

        selectiveDebug2() && console.debug(`makeJobSelectionCursor:next(${concurrency},${jobIdx},${readyJobs.length},${that.workingSliceDensity}): before loop`);

        /* Schedule a prefered job slice based on random chance. */
        if (preferedJobs.length > 0)
        {
          let prioRan = Math.random();
          let list = preferedJobs.filter((jm) => jm['slicePreference'] >= prioRan);

          if (list.length > 0)
          {
            const jobMan = list[list.length * Math.random()];
            const slice = jobMan.readySlice();
            // Need to know we have a long slice before decrementing longSlicesAvailableToSchedule.
            // If there's no more space for long slices then proceed to readyJobs.
            if (slice && (!jobMan.isLong || longSlicesAvailableToSchedule-- > 0))
            {
              peekPrefered = true;
              return slice;
            }
          }
        }

        /* Schedule a slice from next ready job. */
        while (jobIdx < readyJobs.length)
        {
          const jobMan = readyJobs[jobIdx];
          const slice = jobMan.readySlice();
          if (false || selectiveDebug2())
          {
            slice && console.debug(`makeJobSelectionCursor:next(${concurrency},${lowDensityPass},${jobIdx},${readyJobs.length},${that.workingSliceDensity}): found slice(slice:ready:working)`, `${slice.identifier} : ${slice.jobManager.readySlices.length} : ${slice.jobManager.workingSliceDensity}`);
            !slice && console.debug(`makeJobSelectionCursor:next(${concurrency},${lowDensityPass},${jobIdx},${readyJobs.length},${that.workingSliceDensity}): no slices ready for job`, jobMan.identifier);
          }
          // Need to know we have a long slice before decrementing longSlicesAvailableToSchedule.
          if (slice && (!jobMan.isLong || longSlicesAvailableToSchedule-- > 0))
            return slice;
          jobIdx++;
        }

        /*
         * We did not schedule a slice with current seed. We need to re-seed to look for newly-available work
         * and sandboxes, ratcheting up the concurrency (max # of each job running) until we find something.
         */
        selectiveDebug2() && console.debug(`makeJobSelectionCursor:next(${concurrency},${jobIdx},${readyJobs.length},${that.workingSliceDensity}): after loop`);
      }
      if (!lowDensityPass && lowDensityJobs.length > 0)
      {
        jobManagers = lowDensityJobs;
        concurrency = 0;
        lowDensityPass = true;
        return next();
      }
      selectiveDebug2() && console.debug(`makeJobSelectionCursor:next(${concurrency},${jobIdx},${readyJobs.length},${that.workingSliceDensity}): null`, lowDensityPass);
      return null; /* Did not find any more work that fits. */
    }
    /** @param {Slice} [slice] */
    function commit (slice)
    {
      if (slice)
        slice.markAsReserved();
      if (peekPrefered)
        peekPrefered = false;
      else
        jobIdx++;
    }
    /** @param {boolean} b */
    function useGPU (b) { skipGPUJobs = !b; }

    return { next, commit, useGPU };
  }


  /**
   * Handle sandbox.work(...) errors.
   * @param {Sandbox} sandbox
   * @param {Slice} slice
   * @param {Error} error
   * @returns {string}
   */
  handleSandboxWorkError (sandbox, slice, error)
  {
    if (debugBuild && !(slice.isWorking || slice.isWorkDone)) // Sanity. Exception should never fire.
      throw new Error(`handleSandboxWorkError: slice ${slice.identifier} must be WORKING.`);

    /** @type {boolean} */
    const isSandboxError = error instanceof SandboxError;
    /** @type {string} */
    let reason;
    const jobAddress = common.truncateAddress(slice.jobAddress);

    if (isSandboxError)
      reason = error['errorCode']
    else
    {
      // This error was unrelated to the work being done.
      reason = 'Slice has failed to complete execution';
      if (!error)
        error = new Error(`Slice ${slice.sliceNumber} in state ${slice.state} of job ${jobAddress} failed to complete execution`);
    }
    selectiveDebug() && console.debug('handleSandboxWorkError', slice.identifier, error);

    let errorString, onlyDisplayErrorString = true;
    if (error.name === 'EWORKREJECT')
    {
      reason = 'EWORKREJECT'; // The status.js processing does not have a case for 'EWORKREJECT'.
      errorString = !slice.hasBeenRejected
        ? `Slice rejected work: ${error.message}.`
        : `Slice rejected work twice; terminate job: ${error.message}.`
      error.stack = 'Sandbox was terminated by work.reject()';
      sandbox.slice = null;
      this.handleWorkReject(slice, error);
    }
    else
    {
      if (false && !this.evaluator.down)
      {
        /** XXXpfr @todo Be more careful about retrying a slice. */
        if (/*!isSandboxError ||*/ slice['useRetryLogic'])
        {
          slice['sandboxErrorCount'] = ( slice['sandboxErrorCount'] ?? 0) + 1;
          if (slice['sandboxErrorCount'] <= this.options.maxSliceRetries)
            slice.jobManager.cloneSlice(slice); // Try to reuse the slice.
        }
      }
      if (!slice.isReady)
      {
        selectiveDebug() && console.debug(`handleSandboxWorkError: returning slice ${slice.identifier}`);
        this.returnSlice(slice, reason)
          .finally (() => {
            this.handleFailedSlice(slice, error)
          });
      }

      switch (reason)
      {
        case 'ENOPROGRESS':
          errorString = 'No progress error in sandbox.';
          break;
        case 'ESLICETOOSLOW':
          errorString = 'Slice too slow error in sandbox.';
          break;
        case 'EPERM_ORIGIN':
          errorString = `Could not fetch data; origin not allowed: ${error.message}.`;
          break;
        case 'EFETCH':
          errorString = `Could not fetch data: ${error.message}.`;
          break;
        case 'EUNCAUGHT':
          onlyDisplayErrorString = false;
          errorString = `Uncaught error in sandbox: ${error.message}.`;
          break;
        default:
          onlyDisplayErrorString = false;
          errorString = `Slice failed in sandbox: ${error.message}.`;
          break;
      }
    }

    // Always terminate sandbox.
    this.returnSandbox(sandbox);

    // Always display max info under debug builds, otherwise maximal error.
    // messages are displayed to the worker, only if both worker and client agree.
    const displayMaxInfo = slice.jobManager.displayMaxDiagInfo;

    const errorObject = {
      jobAddress,
      sliceNumber: slice.sliceNumber,
      sandbox:     sandbox.id,
      jobName:     sandbox.public ? sandbox.public.name : 'unnamed',
    };

    if (!displayMaxInfo && onlyDisplayErrorString)
      this.error(errorString, '', false /*displayTopOfStack*/);
    else
    {
      Object.entries(errorObject).forEach(([k,v]) => (errorString += `\n  ${k}: ${v}`));
      this.error(errorString, error, false /*displayTopOfStack*/);
    }

    return reason;
  }

  /**
   * Slice has thrown error during execution:
   * Mark slice as failed, compensate when job is dicrete, emit events.
   * @param {Slice} slice
   * @param {Error} error
   */
  handleFailedSlice (slice, error)
  {
    debugging('supervisor') && console.debug(`handleFailedSlice: ${slice.identifier}`, error);
    slice.collectResult(error, false /*success*/);

    // If the slice from a job never completes and the job address exists in the ringBufferOfJobs,
    // then we remove it to allow for another slice (from the same job) to be obtained by fetchTask
    const removeIdx = this.ringBufferOfJobs.indexOf(slice.jobAddress);
    if (removeIdx >= 0)
      this.ringBufferOfJobs.remove(removeIdx);

    this.workerEmit(    'result', error, slice.jobAddress, slice.sliceNumber);
    this.jobEmit(slice, 'result', error, slice.sliceNumber);
  }

  // _Idx
  //
  // returnSlices, returnSlice, emitProgressReport, checkForTabSuspension
  //

  /**
   * Bulk-return multiple slices, possibly for assorted jobs.
   * Returns slices to the scheduler to be redistributed.
   * Called in the sandbox terminate handler and purgeAllWork(jobAddress)
   * and stopWork(forceTerminate).
   *
   * @param {Slice[]} slices - The slice candidates to check if they can be returned to the scheduler.
   * @param {string}  reason - Reason for the return: 'ENOPROGRESS', 'EUNCAUGHT', 'ESLICETOOSLOW', 'EPERM_ORIGIN', 'EFETCH', 'unknown'.
   * @returns {Promise<*>} - Response from the scheduler.
   */
  async returnSlices (slices, reason)
  {
    /** @param {Slice[]} verifiedSlices */
    const compressPayload = (verifiedSlices) => {
      assert(verifiedSlices?.length > 0);
      if (verifiedSlices.length > 1)
        return {
          worker: this.workerId,
          slices: common.constructReturnSliceBuckets(verifiedSlices, reason),
        };
      return verifiedSlices[0].getReturnMessagePayload(this.workerId, reason);
    }

    if (!slices?.length)
      return;

    debugging('supervisor') && console.debug(`Supervisor.returnSlices(${this.state}): Return slice candidates`, slices.map(slice => slice.identifier));

    // Only return those slices which still exist in their respective jobManagers sliceInventory .
    const verifiedSlices = slices.filter((slice) => slice.jobManager.removeSlice(slice));
    if (verifiedSlices.length > 0)
    {
      selectiveSupEx() && console.debug('Supervisor.returnSlices: Returning slices', verifiedSlices.map(slice => slice.identifier), `for worker ${this.workerId}`);
      return this.dcp4.sliceReturn(compressPayload(verifiedSlices), slices);
    }
  }

  /**
   * Takes a slice and returns it to the scheduler to be redistributed.
   * Usually called when an exception is thrown by sandbox.work(...) .
   * Or when the supervisor tells it to forcibly stop working.
   *
   * @param {Slice}  slice  - The slice to return to the scheduler.
   * @param {string} reason - Reason for the return: ''ENOPROGRESS', 'EUNCAUGHT', 'ESLICETOOSLOW', 'EPERM_ORIGIN', 'EFETCH', 'unknown'.
   * @returns {Promise<*>}  - Response from the scheduler.
   */
  returnSlice (slice, reason) { return this.returnSlices([ slice ], reason); }

  /**
   * Send beacon to status.js for 'progress' and sliceStatus.scheduled.
   *
   * Run in an interval created in the ctor.
   * @returns {void|Promise<*>}
   */
  emitProgressReport ()
  {
    const readySlices = [], workingSlices = [];
    this.jobManagerInventory.forEach((jobManager) => {
      readySlices.push(...jobManager.readySlices);
      workingSlices.push(...jobManager.workingSlices);
    });
    /** @type {SliceObj[]} */
    const slices = common.constructSliceBuckets( readySlices, sliceStatus.scheduled );
    common.constructSliceBuckets( workingSlices, 'progress', slices );

    debugging('supervisor') && console.debug('emitProgressReport:', JSON.stringify(slices, null, 2));

    if (slices.length > 0)
    {
      const payload = { worker: this.workerId, slices };
      return this.dcp4.safeRSStatus(payload, 'Failed to emit progress report');
    }
  }

  /**
   * Called by setInterval. This method will measure the time span between its calls. If the 
   * actual interval between invocations is longer than detectSuspensionLateMultiplier * detectSuspensionIntervalMs
   * the JS context is considered to be suspended. If suspension is detected, a tabSuspended event is emitted.
   */
  checkForTabSuspension() {
    const now = Date.now();
    if (this.lastSuspensionDetectionCheck)
    {
      const actualIntervalMs = now - this.lastSuspensionDetectionCheck;
      if (actualIntervalMs > this.options.detectSuspensionLateMultiplier * this.options.detectSuspensionIntervalMs)
        this.emit('tabSuspended');
    }
    this.lastSuspensionDetectionCheck = now;
  }

  // _Idx
  //
  // repoMan, predictLoad(viz., clairvoyance), waitUntilWorkIsReady
  //

  /**
   * @todo XXXpfr Should we not schedule long slices to a worker with too low defaultQuanta?
   *
   * When the estimated time to completion of all work is more than
   *   repoManMultiplier * targetTaskDuration * this.maxWorkingCores,
   * return slices until the excess is removed.
   * Be fair. Round-robin over all jobs until excess is eliminated.
   * Kill the long jobs 1st.
   */
  repoMan()
  {
    const threshold = this.options.repoManMultiplier * this.options.targetTaskDurationMs * this.maxWorkingCores;
    const workRemaining = this.workRemaining;
    let excess = workRemaining - threshold;
    selectiveDebug() && console.debug(`repoMan: excess ${excess}, workerRemaining ${workRemaining}, threshold ${threshold}`);
    if (excess > 0)
    {
      const slices = [];
      /** @param {JobManager[]} jmi */
      const returnFrom = (jmi) => {
        while (true)
        {
          const _excess = excess;
          for (const jobMan of jmi)
          {
            const _readySlices = jobMan.readySlices;
            if (_readySlices.length > 0)
            {
              const slice = _readySlices[0];
              slice.repoMan(); // Mark as FINISHED
              slices.push(slice);
              excess -= jobMan.adjSliceTime;
              if (excess <= 0)
                break;
            }
          }
          if (_excess === excess || excess <= 0)
            break;
        }
      }
      // Be fair. Round-robin over all jobs until excess is eliminated.
      // Except the long jobs are killed 1st.
      const longJobs = this.jobManagerInventory.filter((jobMan) => jobMan.emaSliceTime >= this.options.targetTaskDurationMs);
      if (longJobs.length > 0)
        returnFrom(longJobs);
      if (excess > 0)
        returnFrom(this.jobManagerInventory);
      selectiveDebug() && (slices.length > 0) &&  console.debug(`repoMan: excess ${excess}, workerRemaining ${workRemaining}, threshold ${threshold}, returned-slice-count ${slices.length}`);
      this.returnSlices(slices, 'repoMan');
    }
  }

  /**
   * Predict the total reduction in density of working sandboxes timeSpanMs from now.
   * This function is called right before fetchTask, in order to calculate how much space is available.
   * @returns {{ queued: Slice[], working: number }}
   */
  predictLoad()
  {
    const timeSpanMs = this.options.prefetchIntervalMs;
    const queued = [];
    let working = 0;
    for (const jobMan of this.jobManagerInventory)
    {
      const { queued: jmQueued, working: jmWorking } = jobMan.predictLoad(timeSpanMs);
      queued.push(...jmQueued);
      // Optimize to short-circuit when queued > 1, because we won't call fetchWork in that case.
      if (queued.length > 1)
        break;
      working += jmWorking;
    }
    selectiveDebug() && console.debug(`Supervisor.predictLoad: queued ${queued.length}/${this.queuedSlices.length}, working ${working}/${this.workingSlices.length}`)
    return { queued, working };
  }

  /**
   * On the first call to fetchTask
   *  or when the last call to fetchTask found nothing,
   *  or when there are no ready slices,
   * wait until at least 1 job is ready with at least 1 ready slice.
   * @param {Array<Promise<any>>} jobManagerPromises
   * @returns {Promise<any>}
   */
  waitUntilWorkIsReady (jobManagerPromises)
  {
    if (this.waitForWork)
    {
      debugging('supervisor') && console.debug(`waitUntilWorkIsReady: promise count ${jobManagerPromises?.length}`);
      this.waitForWork = false;
      // Promise.any is supported in Node 15, Chrome 85, Edge 85, Firefox 79, Safari 14, Opera 71.
      // It was implemented in node and browsers in 2nd half of 2020, so there's a good chance many
      // customers will not have browsers that support it. And currently (Jan. 2023) DCP uses node 14.
      return Promise_any(jobManagerPromises);
    }
    // Flush microtask queue
    return utils.a$sleepMs(0);
  }

  // _Idx
  //
  // availableSandboxSpace, fetchTask, createTDRequest, addTaskToWorkload, fetchFromTD, clearUnusedJobManagersAndModuleCache
  //

  /**
   * Returns the number of unused sandbox slots to fill -- sent to fetchTask.
   * @param {Slice[]} queued
   * @param {number}  working
   * @returns {number}
   */
  availableSandboxSpace (queued, working)
  {
    // If we find more than 1 queued slices, bail early.
    if (queued.length > 1)
      return 0; // We have more than 1 ready slices, no need to fetch.

    let longSliceCount = 0;
    if (queued.length < 1)
      this.waitForWork = true; // There are no ready slices.
    else if (queued[0].isLong)
      longSliceCount = 1;

    // There are almost no ready slices (there may be 0 or 1), fetch a full task.
    // The task is full, in the sense that it will contain slices whose
    // aggregate execution time is roughly this.maxWorkingCores * 5-minutes.
    // However, there can only be this.maxWorkingCores # of long slices on a worker,
    // Thus we need to know whether the last slice in this.readySlices() is long or not.
    // (A long slice has estimated execution time >= 5-minutes or is an estimation slice.)

    const numCores = this.maxWorkingCores - working - longSliceCount;
    selectiveDebug2() && console.debug('availableSandboxSpace', numCores, working, longSliceCount);
    return numCores;
  }

  /**
   * Ask the scheduler (task distributor) for work (Rq).
   * @returns {Promise<*>}
   */
  async fetchTask ()
  {
    if (!this.isReady)
      return;

    /**  @type {FetchState} */
    const fetchState = new FetchState();

    const now = Date.now();
    const notifySoteria = !this.fetchTaskBarrier && (now - this.lastTDRequest >  this.options.soteriaFrequencyMs);
    if (notifySoteria)
    {
       // At startup, Soteria checks for orphaned slices belonging to this worker.
      if (!this.runOnceAtStartup)
        fetchState.notifySoteria = true;
      else
      {
        fetchState.startupCheck = true;
        this.runOnceAtStartup = false;
      }
    }

    const { queued, working } = this.predictLoad();
    selectiveDebug() && console.debug(`fetchTask::PredictLoad(${now-this.lastTime}): queued ${queued.length}, working ${working}, workingSliceCount ${this.workingSliceCount}, workingDensity ${this.workingSliceDensity}, workingSandboxCOunt ${this.workingSandboxCount}, maxSboxes ${this.maxWorkingCores}`);
    const unusedFutureCoreSpace = this.maxWorkingCores - working;
    if (unusedFutureCoreSpace < common.doNotSchedule)
    {
      selectiveDebug2() && console.debug(`fetchTask(${now - this.lastTime}): Insufficient future core space to schedule a slice; will try again.`);
      if (!notifySoteria)
         return;
      fetchState.normal = false;
    }

    // Record fetch start time.
    this.fetchTaskStarted = now;

    // We check for pruning about every 30 seconds, or when must prune level is reached.
    if (this.sandboxInventory.length > this.options.mustPruneSandboxLevel
      || now > this.lastPrune + this.options.pruneFrequencyMs)
    {
      this.lastPrune = now;
      this.pruneSandboxes();
    }

    // Every 60 seconds check to see if the estimated time to completion of all work is more than
    //   repoManMultiplier * this.options.targetTaskDurationMs * this.maxWorkingCores,
    // and then return slices until the excess is removed.
    // Be fair. Round-robin over all jobs until excess is eliminated. Kill the long jobs 1st.
    if (now > this.lastRepoMan + this.options.repoManFrequencyMs)
    {
      this.lastRepoMan = now;
      this.repoMan();
    }

    // There are 2 barriers wrt fetchTask,
    // 1) fetchTaskBarrier is a barrier for the task fetching from task distributor path.
    // 2) roundRobinBarrier is a barrier for the slice execution path.
    try
    {
      const cpuCoreSpace = this.availableSandboxSpace(queued, working);
      selectiveDebug2() && console.debug(`Supervisor.fetchTask:, cpuSpace ${cpuCoreSpace}, queued ${queued.length}, working ${working}`);
      if (cpuCoreSpace < 1)
      {
        selectiveDebug2() && console.debug(`Supervisor.fetchTask(${now-this.lastTime}): Sufficient slices exist; execute slices instead of fetching a task: cpuSpace ${cpuCoreSpace}, queued ${queued.length}, working ${working}`);
        if (!notifySoteria)
          return this.roundRobinSlices();
        fetchState.normal = false;
        fetchState.roundRobin = true;
      }
      selectiveDebug() && console.debug(`fetchTask(${now-this.lastTime}, ${this.fetchTaskBarrier}) begin q/w/cpuSpace/slots/space/future-space`, queued.length, working, cpuCoreSpace, this.unusedSandboxCount, this.unusedCoreSpace, unusedFutureCoreSpace);

      if (this.fetchTaskBarrier)
        return;
      // fetchTaskBarrier is a barrier for the task fetching from task distributor path.
      // When fetchTaskBarrier is true, notifySoteria must be false, which prevents excessive
      // Soteria notifications.
      this.fetchTaskBarrier = true;

      // Initialize this.fetchState with the local state.
      // It's only safe to modify this.fetchState when it's in the critical region specified by:
      //    this.fetchTaskBarrier = true;
      this.fetchState = new FetchState(fetchState.valueOf());

      // Call Task Distributor and handle response with this.addTaskToWorkload.
      return this.fetchFromTD(cpuCoreSpace, (request, response) => this.addTaskToWorkload(request, response));
    }
    catch (error)
    {
      this.fetchTaskBarrier = false;
      this.error('Supervisor.fetchTask failed!', error);
    }
  }

  /**
   * Create jobAddress -> sliceNumbers for non-finished slices.
   * @returns {Object<string, number[]>}
   */
  soteriaJobSlices ()
  {
    let hasSoteriaSlices = false;
    /** @type {Object<string, number[]>} */
    const soteriaJobs = {};
    for (const jobManager of this.jobManagerInventory)
    {
      if (jobManager.ready)
      {
        const sliceNumbers = jobManager.sliceNumbers;
        if (sliceNumbers.length > 0)
        {
          soteriaJobs[jobManager.address] = sliceNumbers;
          hasSoteriaSlices = true;
        }
      }
    }
    if (!hasSoteriaSlices)
      return null;
    selectiveSupEx() && console.debug('soteriaJobSlices:', soteriaJobs);
    return soteriaJobs;
  }

  /**
   * Finds overdue slices for Soteria to mark as overdue in activeSlices.
   * @returns {Object<string, number[]>}
   */
  checkForOverdueSlices ()
  {
    let hasOverdueSlices = false;
    /** @type {Object<string, number[]>} */
    const overdueSlices = {};
    if (this.options.useLifetimeAnalysis)
    {
      for (const jobManager of this.jobManagerInventory)
      {
        let threshold = jobManager.computeOverdueThreshold();
        if (threshold < 0) // Don't do estimation slices here (yet).
          continue;
        if (threshold < this.options.targetTaskDurationMs)
          threshold = this.options.targetTaskDurationMs; // threshold must be at least targetTaskDurationMs.
        const workingSlices = jobManager.workingSlices, now = Date.now();
        selectiveSupEx() && (workingSlices.length < 1) && console.debug(`checkForOverdueSlices: job=${jobManager.identifier}, threshold=${threshold}: no working slices`);
        for (const slice of workingSlices)
        {
          const sliceThreshold = threshold * (slice.cotaskCount + 1);
          if (!slice.overdue && (now - slice.startTime > sliceThreshold))
          {
            selectiveSupEx() && console.debug(`checkForOverdueSlices: now-startTime=${now - slice.startTime}, sliceThreshold=${sliceThreshold}`);
            slice.overdue = (hasOverdueSlices = true);
            if (!overdueSlices[jobManager.address])
              overdueSlices[jobManager.address] = [ slice.sliceNumber ];
            else
              overdueSlices[jobManager.address].push(slice.sliceNumber);
          }
        }
      }
      selectiveSupEx() && hasOverdueSlices && console.debug('checkForOverdueSlices:', JSON.stringify(overdueSlices));
    }
    if (!hasOverdueSlices)
      return null;
    selectiveSupEx() && console.debug('checkForOverdueSlices:', overdueSlices);
    return overdueSlices;
  }

  /**
   * Create request for TD.requestTask .
   * @param {number} cpuCoreSpace
   * @returns {object}
   */
  createTDRequest (cpuCoreSpace)
  {
    /* @todo XXXpfr Think about how to do targetLoad.longSlices better.
     * Ideas:
     * 1) While branchy Javascript is CPU bound, that doesn't mean hyperthreading isn't useful.
     *    When a branch is mispredicted the whole CPU instruction pipeline is flushed, which is
     *    a huge perf hit and while waiting to fill the pipeline again, a hyperthread can get
     *    a whole bunch of work done.
     * 2) Setting the Sup2.cores.cpu to #lCores is probably too much, but I've had great success with
     *       Sup2.cores.cpu = Math.ceil(1.5 * #lCores)
     *    Which is very close to optimal throughput of work done.
     * 3) When the scheduler is 1/2 very long slices, the short slices will tend to get starved.
     *    The config property dcpConfig.scheduler.preventSliceStarvation when set to true (default false)
     *    will always leave one vCore open for short slices in every worker. In the future, I want the
     *    scheduler to detect short slice starvation and dynamical turn preventSliceStarvation on until
     *    short slice starvation is alleviated and then turn it back off.
     * 4) maxSandboxes is currently set to
     *       factor * Sup2.cores.cpu
     *    where 1.2 <= factor <= 1.5 depending upon how many lCores a worker has. Where I assume that a
     *    machine with a large number of lCores has sufficient memory to handle a bigger factor.
     *    The factor boundaries can be adjusted in dcpConfig.supervisor, but I intend to also allow them
     *    to be overridden at the dcpConfig.worker level, so if somebody has a 32 lCore machine with
     *    8GB of RAM they can adjust factor to be closer to 1. Ideally we could adjust the factor
     *    boundaries at the job/CG level.
     */
    // Only notify Soteria when there are loaded jobs or worker just started,
    // or there are overdue slices.
    let overdueSlices = null, soteriaJobs = null;
    if (this.fetchState.notifySoteria)
    {
      //this.showSlices('createTDRequest');
      soteriaJobs = this.soteriaJobSlices();
      overdueSlices = this.checkForOverdueSlices();
      if (!soteriaJobs && !overdueSlices)
        this.fetchState.notifySoteria = false;
    }
    if (selectiveSupEx() && (false || overdueSlices || this.fetchState.valueOf() !== 1))
      console.debug(`createTDRequest(${Date.now() - this.lastTime}): fetchState=${this.fetchState.valueOf()}, workerId=${this.workerId}, overdueSlices=${JSON.stringify(overdueSlices)}, soteriaFrequencyMs=${this.options.soteriaFrequencyMs}`);

    let request =  null;
    if (this.fetchState.normal)
    {
      request = {
        supervisor:           this.version,
        numCores:             cpuCoreSpace,        /** @deprecated This is for legacy schedulers. */
        numGPUs:              this.maxWorkingGPUs, /** @deprecated This is for legacy schedulers. */
        targetLoad:           { cpu: cpuCoreSpace, gpu: this.maxWorkingGPUs, longSlices: Math.floor(cpuCoreSpace) },
        coreStats:            this.options.getStatisticsCPU(),
        jobQuanta:            this.quanta.calculateJobQuanta(),
        capabilities:         this.capabilities,
        paymentAddress:       this.options.paymentAddress,
        jobAddresses:         this.options.jobAddresses || [], // When set, only fetches slices for these jobs.
        workerComputeGroups:  this.dcp4.generateWorkerComputeGroups(),
        minimumWage:          this.options.minimumWage,
        soteriaJobs,
        overdueSlices,
        previouslyWorkedJobs: this.ringBufferOfJobs.buf, // Only discrete jobs.
        rejectedJobs:         this.ringBufferOfRejects.buf,
        unresolvedJobs:       this.unresolvedJobs, // Still downloading/resolving artifacts, don't fetch until resolved.
        fetchState:           this.fetchState.valueOf(),
        worktimes:            this.worktimes,
      };

      // Workers should be part of the public compute group by default.
      if (!utils.booley(this.options.leavePublicGroup))
        request.workerComputeGroups.push(constants.computeGroups.public);
    }
    else if (this.fetchState.notifySoteria)
    {
      request = {
        coreStats:      { worker: this.workerId, lCores: 0, pCores: 0, sandbox: 0 },
        jobQuanta:      { 0: 1 },
        paymentAddress: this.options.paymentAddress,
        soteriaJobs,
        overdueSlices,
        fetchState:     this.fetchState.valueOf(),
      };
    }

    selectiveDebug2() && console.debug(`createTDRequest(${Date.now() - this.lastTime}): fetchState=${request?.fetchState}, workerId=${this.workerId}, overdueSlices=${JSON.stringify(overdueSlices, null, 2)}`, request);

    return request;
  }

  /**
   * Callback for fetchFromTD.
   * @param {object} request
   * @param {object} response
   */
  async addTaskToWorkload (request, response)
  {
    const constructFetchHandle = (size, jobs, slices) => {
      return {
        fetchStart: this.fetchTaskStarted,
        fetchEnd: Date.now(),
        fetchSize: size,
        jobs,
        slices,
      };
    };
    /**
     * jobs: object map: jobAddress -> sliceNumber[] from slices with jobAddress
     * @todo Try to talk Wes into using the 'fetch2' pattern for 'fetch' or combine the two.
     * @param {number} size
     * @param {Object<string, { jobHandle: EventEmitter, slices: number[] }>} jobs
     * @returns {{ fetchStart: number, fetchEnd: number, fetchSize: number, jobs: Object<string, { jobHandle: EventEmitter, slices: number[] }>, fetchState: number }}
     */
    const constructFetchHandle2 = (size, jobs) => {
      return {
        fetchStart: this.fetchTaskStarted,
        fetchEnd: Date.now(),
        fetchSize: size,
        jobs,
        fetchState: request.fetchState,
      };
    };

    try
    {
      /** @type {TDPayload} */
      const payload = response.payload;
      if (!response.success)
      {
        debugging() && console.debug('Task fetch failure; request=', request);
        debugging() && console.debug('Task fetch failure; response=', payload);
        this.error(`Unable to request task from scheduler; will try again on a new connection: payload ${JSON.stringify(payload, null, 2)}`);
        return;
      }

      if (!payload.body?.newJobs) // No slices found.
      {
        // Reset first fetch logic.
        this.waitForWork = true;
        /**
         * The 'fetch' event fires when the stask distributor found no work.
         * @link https://gitlab.com/Distributed-Compute-Protocol/dcp-docs-wes/-/blob/wip/worker/worker-events.md
         * @event Supervisor#fetch
         */
        this.workerEmit('fetch', constructFetchHandle(0, {}, {}));
        debugging('supervisor') && console.debug('Task distributor found no slices...');
        // There may be an existing slice to process.
        return this.roundRobinSlices();
      }

      /** @todo XXXpfr At this point the line #'s are short by 42 -- figure out why. */

      /*
       * payload:   { TDPayload }
       * TDPayload: { owner: Address, signature: Signature, auth: Auth, body: Body };
       * Auth:      { workerId: string, authSlices: Object<string, number[]>, schedulerId: { address: Address }, jobCommissions: Object<string, { rate: number, account: number }> }
       * Body:      { newJobs: Object<string, object>, task: Object<string, SliceMessage[]>, computeGroupJobs: Object<string, string[]>, computeGroupOrigins: Object<string, Object<string, string[]>>, schedulerConfig: {{ shared: *, targetTaskDuration: number }} }
       *
       * NOTE: authorizationMessage has type AuthMessage
       */

      const { body,  ...authorizationMessage } = payload;
      const { newJobs, task, schedulerConfig } = body;
      const newJobKeys = Object.keys(newJobs);
      const jobCount = newJobKeys.length;

      let jobSliceMap = task;
      if (jobSliceMap.length) /** @deprecated Task came from legacy scheduler */
        // @ts-ignore
        jobSliceMap = utils.toJobMap(task, sliceMsg => sliceMsg);

      if (schedulerConfig)
      {
        this.options.soteriaHive = new wd.SoteriaSharedHive(schedulerConfig);
        selectiveDebug() && console.debug(`Supervisor: soteriaFrequencyMs=${1e-3 * this.options.soteriaFrequencyMs}s`);
      }

     /*
      * Ensure all jobs received from the scheduler (task distributor) are:
      * 1. If we have specified specific jobs the worker may work on, the received jobs are in the specified job list
      * 2. If we are in localExec, at most 1 unique job type was received (since localExec workers are designated for only one job)
      * If the received jobs are not within these parameters, stop the worker since the scheduler cannot be trusted at that point.
      */
      if (request.jobAddresses?.length > 0 && !newJobKeys.every((ele) => request.jobAddresses.includes(ele)))
      {
        // "fetchTask:" because that should make sense to somebody that doesn't know the internals of Supervisor.
        this.error("fetchTask: Worker received slices it shouldn't have; rejecting the work and stopping.");
        this.stopWork(true);
        return;
      }

      // Clear out job managers w/o any queued slices,
      // and remove corresponding job references from module cache.
      // When a cached module no longer has any job references it is removed from the cache.
      this.clearUnusedJobManagersAndModuleCache(newJobs);

      /** @todo XXXpfr Figure out how not to construct this every time. */
      this.jobMap = {};
      this.jobManagerInventory.forEach(jobManager => {
        this.jobMap[jobManager.address] = jobManager;
      });

      selectiveDebug2() && console.debug(`addTaskToWorkload(${Date.now() - this.lastTime}): newJobs ${common.truncateAddress(newJobKeys)}, jobSliceMap ${common.compressJobMap(jobSliceMap, (s) => s.sliceNumber)}`);

      let sliceCount = 0;
      /** @type {Array<Promise<*>>} */
      const jobManagerPromises = [];
      const jobs = {}, slices = {};
      /** @type {Object<string, { jobHandle: EventEmitter, slices: number[] }>} */
      const fetch2Jobs = {};
      // Populate the job managers with slices, creating new job managers when necessary.
      // Set up discrete job ring buffer.
      for (const [jobAddress, jobMessage] of Object.entries(newJobs))
      {
        assert(jobAddress);
        assert(jobMessage);
        /** @type {JobManager} */
        let jobManager;
        const sliceMessages = jobSliceMap[jobAddress];
        sliceCount += sliceMessages.length;

        if (this.jobMap.hasOwnProperty(jobAddress))
        {
          jobManager = this.jobMap[jobAddress];
          jobManager.update(jobMessage, sliceMessages, authorizationMessage);
        }
        else
        {
          // Add the slice messages to the job manager ctor, so that slice construction is after job manager is ready.
          jobManager = new JobManager(this, jobMessage, sliceMessages, authorizationMessage);
          this.jobMap[jobAddress] = jobManager;

          // Do not fetch slices from any unresolved job managers.
          // We may end up with more slices than we should, but repoMan will take care of that.
          this.unresolvedJobs.push(jobAddress);

          // Populate the ring buffer based on job's discrete property.
          if (jobMessage.requirements.discrete && this.ringBufferOfJobs.find(address => address === jobAddress) === undefined)
            this.ringBufferOfJobs.push(jobAddress);
        }
        jobs[jobAddress] = jobManager.jobHandle;
        slices[jobAddress] = task[jobAddress].length;
        fetch2Jobs[jobAddress] = { jobHandle: jobManager.jobHandle, slices: [ ...(authorizationMessage.auth.authSlices[jobAddress]) ] };

        jobManagerPromises.push(jobManager.jobPromise);
      }

      const payloadLength = kvin.stringify(payload).length; /** @todo - fix per DCP-3750 */
      /**
       * The 'fetch' event fires when the supervisor has found work from the task distributor.
       * @link https://gitlab.com/Distributed-Compute-Protocol/dcp-docs-wes/-/blob/wip/worker/worker-events.md
       * @event Supervisor#fetch
       */
      this.workerEmit('fetch', constructFetchHandle(payloadLength, jobs, slices));
      /** @todo Try to talk Wes into using the 'fetch2' pattern for 'fetch' or combine the two.
       * The fetch2 payload is:
       * {
       *   fetchStart: number;
       *   fetchEnd:   number;
       *   fetchSize:  number;
       *   jobs: {
       *     [x: string]: {
       *       jobHandle: EventEmitter;
       *       slices: number[];
       *   };
       * };
       */
      this.workerEmit('fetch2', constructFetchHandle2(payloadLength, fetch2Jobs));

      const compressTask = () => { return common.compressJobMap(authorizationMessage.auth.authSlices); }
      selectiveSupEx() && console.debug(`addTaskToWorkload(${Date.now() - this.lastTime},${this.workerId}): task: ${sliceCount}/${request.targetLoad.cpu}/${this.maxWorkingCores}, jobs: ${jobCount}, authSlices: ${compressTask()}, conversion:`, request.jobQuanta);

      // On the first call to fetchTask,
      //  or when the last call to fetchTask found nothing,
      //  or when there are no ready slices,
      // wait until at least 1 job with 1 slice is ready.
      await this.waitUntilWorkIsReady(jobManagerPromises);

      debugging('supervisor') && console.debug('addTaskToWorkload: Before calling roundRobinSlices; job states', this.jobManagerInventory.map((jm) => jm.identifier));

      // Start working on the new slices.
      return dcp_timers.setImmediate(() => this.roundRobinSlices());
    }
    catch (error)
    {
      this.workerEmit('fetch', error);
      this.error('Supervisor.fetchTask failed!', error);
    }
    finally
    {
      this.fetchTaskBarrier = false; // Redundant, but keep it anyway.
    }
  }

  /**
   * @private
   * @callback cbAddTaskToWorkload
   * @param {*} request
   * @param {*} response
   * @returns {Promise<void>}
   */

  /**
   * Call to fetch new slices from task distributor.
   * @param {number} cpuCoreSpace
   * @param {cbAddTaskToWorkload} addTaskToWorkload
   * @returns {Promise<any>}
   */
  async fetchFromTD (cpuCoreSpace, addTaskToWorkload)
  {
    selectiveDebug2() && console.debug(`fetchFromTD(${Date.now()-this.lastTime}) begin; BarrierState:`, this.fetchTaskBarrier, this.roundRobinBarrier);
    // Fetch a new task if we have insufficient slices queued, then start workers
    if (!this.fetchTaskBarrier)
      throw new Error('fetchTaskBarrier must be set when entering fetchFromTD.');

    let fetchTimeout = dcp_timers.setTimeout(() => {
      fetchTimeout = null;
      this.fetchTaskBarrier = false;
      this.warning('Fetch exceeded timeout, will reconnect at next watchdog interval');
    }, 3 * 60 * 1000);  // Max out at 3 minutes to fetch.
    // Allow workers and localExec to exit.
    fetchTimeout.unref();

    const finalize = () => {
      this.fetchTaskBarrier = false;
      if (fetchTimeout)
        dcp_timers.clearTimeout(fetchTimeout);
      fetchTimeout = null;
    }

    // Ensure result submitter and task distributor connections before fetching tasks.
    try
    {
      await Promise.all([
        this.dcp4.taskDistributor.keepalive(),
        this.dcp4.resultSubmitter.keepalive(),
      ]);
    }
    catch (error)
    {
      selectiveDebug() && console.debug('fetchTaskFromTD: Keep slices failed', error);
      this.warning('Failed to connect to result submitter, refusing to fetch slices.', 'Will try again at next fetch cycle.');
      return finalize();
    }

    // The 'beforeFetch' event allows the user to cancel the requestTask request.
    let canceled = false;
    /**
     * The 'beforeFetch' event fires before the request is sent to requestTask in task distributor.
     * @link https://gitlab.com/Distributed-Compute-Protocol/dcp-docs-wes/-/blob/wip/worker/worker-events.md
     * @event Supervisor#beforeFetch
     */
    this.workerEmit('beforeFetch', () => { canceled = true; })
    selectiveDebug() && canceled && console.debug('User canceled the fetch task.');
    if (canceled)
      return finalize();

    // Create the request.
    const request = this.createTDRequest(cpuCoreSpace);
    selectiveDebug2() && console.debug(`FetchFromTD(${Date.now()-this.lastTime}): Before sending message(${this.dcp4.taskDistributor?.id})`, this.fetchState.valueOf()); //, request);
    
    // It's possible that a call to stopWork could slip in right after the above keepalives,
    // and hence this.dcp4.taskDistributor could be closed, so check whether Supervisor is ready.

    if (!this.isReady || !this.fetchState.normal && !this.fetchState.notifySoteria)
      return finalize();
    assert(request && FetchState.check(request.fetchState));

    return this.dcp4.taskDistributor.request('requestTask', request)
      .then((response) => {
        assert(this.fetchState.valueOf() === request?.fetchState);
        // Record Soteria notify time stamp.
        if (FetchState.notifySoteria(request.fetchState))
          this.lastTDRequest = Date.now();
        // Process task fetched from TD.
        if (FetchState.normal(request.fetchState))
          return addTaskToWorkload(request, response); // Process the task.
        // Call this.roundRobinSlices if there's nothing else to do.
        assert(FetchState.notifySoteria(request.fetchState));
        if (FetchState.roundRobin(request.fetchState))
          return this.roundRobinSlices();
        return response;
      })
      .catch((error) => {
        this.workerEmit('fetch', error);
        /** @todo Check error.code so we don't display errors like 'EPIPE' or 'ECONNRESET'. Is that enough? */
        if (error.code === 'EPIPE' || error.code === 'ECONNRESET') // Don't display error.
          selectiveSupEx() && console.debug('Unable to request task from scheduler. Will try again on a new connection.', error);
        else
          this.error('Unable to request task from scheduler. Will try again on a new connection.', error);
      })
      .finally(() => {
        return finalize();
      });
  }

  /**
   * Remove all unreferenced jobs in this.jobManagerInventory and this.moduleCache.
   * Since job-managers are inserted into this.jobManagerInventory with a push, the job managers at the beginning are oldest.
   * Only delete #deleteCount of the oldest job-managers:
   *     let deleteCount = this.jobManagerInventory.length - cachedJobsThreshold;
   * Edit cachedJobsThreshold to adjust the cache cleanup threshold.
   * @param {Object<string, number[]>} newJobMap - Jobs that should not be removed from this.jobManagerInventory and this.moduleCache.
   */
  clearUnusedJobManagersAndModuleCache (newJobMap)
  {
    const emptyJobs = [];
    for (const jobMan of this.jobManagerInventory) // Grab oldest 1st
    {
      if (!newJobMap[jobMan.address])
      {
        let isEmpty = true;
        for (const slice of jobMan.sliceInventory)
          if (slice.isQueuedOrActive)
          {
            isEmpty = false;
            break;
          }
        if (isEmpty)
        {
          // Walk through whole list to purge empty jobs with no assigned sandboxes to save.
          if (jobMan.assignedSandboxes.length < 1)
            this.purgeJob(jobMan);
          else
            emptyJobs.push(jobMan)
        }
      }
    }
    let deleteCount = this.jobManagerInventory.length - this.options.cachedJobsThreshold;
    if (deleteCount > 0)
    {
      selectiveDebug() && console.debug(`Supervisor.clearUnusedJobManagersAndModuleCache: deleteCount ${deleteCount}/${this.jobManagerInventory.length}/${this.options.cachedJobsThreshold}.`);
      for (const jobMan of emptyJobs) // Grab oldest 1st
      {
        this.purgeJob(jobMan);
        if (--deleteCount < 1)
          break;
      }
    }
  }

  // _Idx
  //
  // createSandbox, returnSandbox, hookUpSandboxListeners, pruneSandboxes
  //

  /**
   * Automatically handle when the evaluator is down.
   *
   * With the screensaver worker, when the screensaver goes down, so does the evaluator.
   * And when the screensaver starts running again, so does the evaluator. The evaluator
   * may be stopped and started again with sa worker running, and have good behavior.
   * However, browser workers cannot have their evaluators stopped without also stopping
   * the worker (otherwise file-a-bug...)
   *
   * @param {boolean} [throwError=false]
   * @returns {Promise<Sandbox>}
   */
  async createSandbox (throwError = false)
  {
    selectiveDebug2() && console.debug('createSandbox', this.sandboxInventory.length, Date.now() - this.lastTime);
    // See if there are any READY_FOR_ASSIGN sandboxes (viz., sandbox.isReadyForAssign is true.)
    // If the evaluator just came back up (while worker is still running) there should not be any non-assigned sandboxes.
    // We're only considering sa worker (e.g. screensaver worker), because browser workers cannot stop the
    // evaluator w/o stopping the worker (I think -- if not true, file-a-bug.)
    if (this.sandboxInventory.length > 0 && this.sandboxInventory[0].isReadyForAssign)
    {
      selectiveDebug2() && console.debug(`Supervisor.createSandbox: Found ready-for-assign sandbox ${this.sandboxInventory[0].identifier}`);
      return this.sandboxInventory.shift();
    }

    // If the evaluator cannot start (e.g. if the evalServer is not running),
    // then the while loop will keep retrying until the evalServer comes online.
    try
    {
      this.evaluator.createSandboxRefCount++;

      let retry = 0;
      while (true)
      {
        let sandbox;
        try
        {
          sandbox = new Sandbox(this, { ...this.options.sandboxOptions });
          selectiveDebug2() && console.debug(`Supervisor.createSandbox(${sandbox.id}): Calling sandbox.start: ${this.evaluator.createSandboxRefCount}, eval-down ${this.evaluator.down}, really-down ${this.evaluator.reallyDown}`);
          this.hookUpSandboxListeners(sandbox);
          await sandbox.start();
          if (!this.capabilities)
            this.checkCapabilities(sandbox);
          if (this.evaluator.down)
          {
            this.evaluator.reset();
            selectiveSupEx() && this.evaluator.reallyDown && console.debug('Supervisor.createSandbox: Evaluator is up again.');
          }
          return sandbox;
        }
        catch (error)
        {
          if (throwError)
            throw error;
          selectiveDebug() && console.debug(`Supervisor.createSandbox: Failed to start sandbox ${sandbox.identifier}`, this.evaluator.createSandboxRefCount, this.evaluator.down, this.evaluator.reallyDown, retry, error.message);
          if (error.code === 'ENOWORKER')
            throw new DCPError("Cannot use localExec without dcp-worker installed. Use the command 'npm install dcp-worker' to install the neccessary modules.", 'ENOWORKER');

          if (throwError)
            throw error;

          // The evaluator may be down or shutting down, keep retrying.
          if ((retry % 60) === 0)
            this.warning('Failed to start a sandbox; will keep retrying; screensaver worker or evaluator may be down...');
          await utils.a$sleepMs(1000 * Math.min(5, ++retry));
        }
      }
    }
    finally
    {
      this.evaluator.createSandboxRefCount--;
    }
  }

  /**
   * Remove sandbox from inventory and terminate.
   * @param {Sandbox} sandbox
   */
  returnSandbox (sandbox)
  {
    // If sandbox is not in this.sandboxInventory then sandbox must already be terminated
    // <==> this.sandboxInventory.includes(sandbox) || sandbox.isTerminated().
    selectiveDebug2() && console.debug(`returnSandbox: ${sandbox.identifier}`);
    if (common.removeElement(this.sandboxInventory, sandbox))
    {
      sandbox.slice = null; // Don't auto-return slice when terminating through returnSandbox.
      sandbox.terminate(false);
    }
    else if (!sandbox.isTerminated)
    {
      // If sandbox is not in this.sandboxInventory then sandbox must already be terminated
      if (debugBuild)
        throw new Error(`returnSandbox: Non-terminated sandbox ${sandbox.identifier} has already been removed.`);
      this.warning(`returnSandbox: Non-terminated sandbox ${sandbox.identifier} has already been removed.`);
    }
  }

  /**
   * For a given sandbox, hook up all the Sandbox listeners.
   * @param {Sandbox} sandbox
   */
  hookUpSandboxListeners (sandbox)
  {
    sandbox.addListener('start', () => {
      if (!sandbox.slice) return;
      const payload = sandbox.slice.getMessagePayload(this.workerId, 'begin');
      return this.dcp4.safeRSStatus(payload, `Failed to send 'begin' status for slice ${sandbox.slice.identifier}`);
    });

    const that = this;
    // Sandbox error handler.
    sandbox.on('sandboxError', function Supervisor$sandboxError(error) {
      selectiveDebug() && console.debug(`Sandbox ${sandbox.identifier} sandboxError-handler; error while executing work function`, error);
      const slice = sandbox.slice;
      if (!slice?.isWorking) // Sanity -- warning should never fire.
        this.warning(`handleSandboxError: slice ${slice?.identifier} must be WORKING.`);
      if (slice)
        slice['useRetryLogic'] = true;
      that.returnSandbox(sandbox);
    });

    // Sandbox complete handler.
    // When any sandbox completes, go through the Supervisor.fetchTask protocol.
    sandbox.addListener('complete', () => {
      // Try not to call fetchTask unless there's something there.
      selectiveDebug2() && console.debug('Sandbox complete listener', this.fetchTaskBarrier, this.roundRobinBarrier, this.unusedSandboxCount, Date.now() - this.lastTime);
      if (!this.fetchTaskBarrier)
        this.fetchTask();
    });

    // If the sandbox terminated and we are not shutting down, then we should return all work which is
    // currently not being computed if all sandboxes are dead and the attempt to create a new one fails.
    sandbox.sandboxHandle.on('end', async () => {
      if (this.evaluator.enterSandboxHandleEndHandler)
      {
        try
        {
          selectiveDebug() && console.debug(`hookUpSandboxListeners: Sandbox "${sandbox.identifier}" terminated handler`, this.sandboxInventory.length, Date.now() - this.lastTime);

          // Does there exist a non-terminated sandbox?
          let allSandboxesTerminated = true;
          for (const sbx of this.sandboxInventory)
            if (!sbx.isTerminated)
            {
              allSandboxesTerminated = false;
              break;
            }

          if (allSandboxesTerminated && !this.evaluator.downInterlock)
          {
            //
            // When we get here, all sandboxes have been terminated.
            // Set downInterlock to prevent interleaving when handling multiple 'end' events.
            //
            this.evaluator.downInterlock = true;
            selectiveDebug() && console.debug('hookUpSandboxListeners: Try to create 1 sandbox in the sandbox-terminated-handler...', sandbox.identifier);
            await this.createSandbox(true /*throwError*/)
              .then((sbx) => {
                this.evaluator.state.set('shuttingDown', 'normal');
                // This is the only place where non-assigned sandboxes are added to this.sandboxInventory.
                this.sandboxInventory.unshift(sbx);
                selectiveDebug() && console.debug('Sandbox terminate handler was able to create new sandbox', sandbox.identifier);
              })
              .catch(() => {
                //
                // Since all sandboxes have been terminated, if we cannot create a new sandbox,
                // that probably means we're on a screensaver worker and the screensaver is down.
                // Try to submit results for completed slices, but return all other non-finished
                // slices to the scheduler -- after a brief delay.
                //
                selectiveDebug() && console.debug('Sandbox terminate handler cannot create new sandbox; evaluator is down', sandbox.identifier);
                this.evaluator.state.set('shuttingDown', 'reallyDown');
                this.emit('evalDown');
                this.jobManagerInventory.forEach((jm) => jm.evaluatorDownCleanup());
                this.warning('Stopping all work.', 'Screensaver worker or evaluator may be down.');
              })
              .finally(() => {
                this.sandboxInventory = this.sandboxInventory.filter(sbx => !sbx.isTerminated);
                // Put this.evaluator back to its initial state, which also disables
                // is-screen-saver-down logic for the sandbox handle 'end' event handler.
                // This call is redundant but cheap, just in case the above this.createSandbox
                // is made asynchronous someday.
                this.evaluator.clearEndHandlerFlags();
              });
          }
        }
        finally
        {
          // Put this.evaluator back to its initial state, which also disables
          // is-screen-saver-down logic for the sandbox handle 'end' event handler,
          this.evaluator.clearEndHandlerFlags();
        }
      }
    });
  }

  /**
   * Terminate extra sandboxes over the limit.
   * @todo XXXpfr Prioritize keeping expensive to assign sandboxes.
   */
  pruneSandboxes ()
  {
    this.sandboxInventory = this.sandboxInventory.filter((sandbox) => !sandbox.isTerminated);
    let pruneCount = this.sandboxInventory.length - this.options.maxSandboxes;
    if (pruneCount <= 0)
      return;

    selectiveDebug() && console.debug(`Supervisor.pruneSandboxes START: pruneCount ${pruneCount}/${this.sandboxInventory.length}/${this.options.maxSandboxes}.`, this.dbg.dumpSandboxState());
    selectiveDebug2() && console.debug(this.sandboxInventory.map((sbx) => sbx.identifier));

    // Prune ready-for-assign sandboxes first.
    while (pruneCount > 0)
    {
      if (this.sandboxInventory[0].isReadyForAssign)
      {
        const startedSandbox = this.sandboxInventory.shift();
        startedSandbox.terminate(false); // Don't call returnSandbox.
        pruneCount--;
      }
      else
        break;
    }

    // Don't purge jobs here: can accidentally purge a job that TD just fetched (XXXpfr)

    /**
     * Do we really want to do a bunch of work to keep empty job assigned sandboxes around?
     * When in a private compute group, there will be fewer jobs and it's likely
     * that a given job will be seen again.
     * @todo XXXpfr Prioritize keeping expensive to assign sandboxes.
     */
    const liveJobs = [], emptyJobs = [];
    let maxAssignedSandboxCount = 0;
    for (const jobMan of this.jobManagerInventory)
    {
      let isAlive = false;
      for (const slice of jobMan.sliceInventory)
        if (slice.isQueuedOrActive)
        {
          isAlive = true;
          break;
        }
      if (isAlive)
        liveJobs.push(jobMan);
      else
      {
        const _assignedSandboxes = jobMan.assignedSandboxes;
        if (maxAssignedSandboxCount < _assignedSandboxes.length)
          maxAssignedSandboxCount = _assignedSandboxes.length;
        emptyJobs.push(jobMan);
      }
    }

    if (emptyJobs.length > 0)
    {
      // Prune the sandboxes from all jobs with no current work.
      // Try to keep approximately the same # of assigned sandboxes per job.
      for (let k = maxAssignedSandboxCount; k >= 0; k--)
      {
        for (const jobMan of emptyJobs)
        {
          const _assignedSandboxes = jobMan.assignedSandboxes;
          if (_assignedSandboxes.length > k)
          {
            debugging('supervisor') && console.debug(`pruneSandboxes(empty): sandbox${_assignedSandboxes[0].id}`, Date.now() - this.lastTime);
            // Terminate and remove from this.sandboxInventory.
            this.returnSandbox(_assignedSandboxes[0]);
            if (--pruneCount < 1)
            {
              debugging('supervisor') && console.debug(`Supervisor.pruneSandboxes FINISH1: ${pruneCount}/${this.sandboxInventory.length}/${this.options.maxSandboxes}.`);
              return;
            }
          }
        }
      }
    }

    // Round-robin prune 1 extra assigned sandbox from each non-empty jobmanager.
    while (pruneCount > 0)
    {
      const _pruneCount = pruneCount;
      for (const jobMan of liveJobs)
      {
        const _assignedSandboxes = jobMan.assignedSandboxes;
        if (_assignedSandboxes.length > 0)
        {
          debugging('supervisor') && console.debug(`pruneSandboxes(non-empty): sandbox${_assignedSandboxes[0].id}`, Date.now() - this.lastTime);
          // Terminate and remove from this.sandboxInventory.
          this.returnSandbox(_assignedSandboxes[0]);
          if (--pruneCount < 1)
          {
            debugging('supervisor') && console.debug(`Supervisor.pruneSandboxes FINISH2: ${pruneCount}/${this.sandboxInventory.length}/${this.options.maxSandboxes}.`);
            return;
          }
        }
      }
      if (_pruneCount === pruneCount) // Nothing left to prune.
        break;
    }

    debugging('supervisor') && console.debug(`Supervisor.pruneSandboxes FINISH: incomplete-prune ${pruneCount}/${this.sandboxInventory.length}/${this.options.maxSandboxes}.`);
  }

  // _Idx
  //
  // recordResult, sendToResultSubmitter, sendResultToRemote
  //

  /**
   * Submits the slice results to the result-submitter service.
   * Then remove the slice from the its job manager.
   *
   * @param {Slice}         slice - The slice to submit.
   * @param {SandboxHandle} sandboxHandle - The sandbox handle associated to the slice.
   * @returns {Promise<any>}
   */
  async recordResult (slice, sandboxHandle)
  {
    // It is possible for slice.result to be undefined when there are upstream errors.
    if (!slice.result)
      throw new Error(`Slice ${slice.identifier} completed work, but there is no result. This is ok when there are upstream errors.`);
    if (!slice.isComplete)
      throw new Error(`Cannot record result for slice ${slice.identifier} that has not completed execution successfully.`);
    if (!slice.timeReport)
      throw new Error(`Invalid time report for slice ${slice.identifier} in recordResult`);
    if (!slice.dataReport)
      throw new Error(`Invalid data report for slice ${slice.identifier} in recordResult`);

    const metrics = slice.jobManager.updateStatistics(slice, sandboxHandle);
    selectiveDebug() && console.debug(`Supervisor: recording result for slice ${slice.identifier} with metrics`, metrics);

    /** @see result-submitter::result for full message details */
    const payloadData = {
      slice:          slice.sliceNumber,
      job:            slice.jobAddress,
      worker:         this.workerId,
      paymentAddress: this.options.paymentAddress,
      metrics,
      authorizationMessage: slice.authorizationMessage,
    };

    let canceled = false;
    const resultUrl = slice.resultStorageDetails?.length ? slice.resultStorageDetails : false;
    this.workerEmit(    'beforeResult', () => { canceled = true; }, resultUrl, slice.jobAddress, slice.sliceNumber);
    this.jobEmit(slice, 'beforeResult', () => { canceled = true; }, resultUrl, slice.sliceNumber);
    selectiveDebug && canceled && console.debug(`User canceled the result submission operation for slice ${slice.identifier}.`);
    if (canceled)
      return this.returnSlice(slice, 'Canceled via beforeResult event');

    if (slice.resultStorageType === 'pattern')
      return this.sendResultToRemote(slice)
        .then((response) => {
          return this.sendToResultSubmitter(slice, sandboxHandle, payloadData, response);
        });

    return this.sendToResultSubmitter(slice, sandboxHandle, payloadData, utils.encodeDataURI(slice.result.result));
  }

  /**
   * Send result to result submitter.
   * @param {Slice}  slice
   * @param {SandboxHandle} sandboxHandle
   * @param {*}      payloadData
   * @param {string} [result]
   * @returns {Promise<any>}
   */
  async sendToResultSubmitter (slice, sandboxHandle, payloadData, result)
  {
    // When a given slice hits the retry limit (6 retries) the slice is returned to scheduler.
    const handleRSError = (error, slice) => { // eslint-disable-line no-shadow
      const msg = `Failed to submit results to scheduler for slice ${slice.identifier}`;
      if (!error)
        error = new Error(msg);

       // Don't display 'EPIPE' or 'ECONNRESET' errors.
      if (error.code === 'EPIPE' || error.code === 'ECONNRESET')
        selectiveSupEx() && console.debug(msg, error);
      else
        this.error(msg, error);
    }

    try
    {
      if (result)
        payloadData.result = result;

      await this.delayManager.nextDelay('recordResult', 2);
      //->console.log('recordResult', slice.identifier, this.evaluator.down, Date.now() - this.lastTime); // SAVE

      selectiveDebug2() && console.debug(`Supervisor.sendToResultSubmitter: Before sending message(${this.dcp4.resultSubmitter?.id}`, slice.identifier);

      return this.dcp4.resultSubmitter.request('result', payloadData)
        .then((resp) => {
          const payload = resp.payload;
          if (!resp.success)
          {
            if (payload)
            {
              selectiveDebug() && console.debug('resultSubmitter.send failed', payload);
              throw new DCPError(`Call to result submitter failed when recording results for ${slice.identifier} with payload ${utils.stringify(payload)}.`);
            }
            if (debugBuild)
            {
              selectiveDebug() && console.debug('resultSubmitter.send failed with no payload', slice.identifier);
              // Look inside
              for (const [ key, value ] of Object.entries(resp))
                if (key !== 'connection')
                  console.debug(`${key}:`, value);
            }
            throw new Error(`Call to result submitter failed when recording results for ${slice.identifier}.`);
          }

          selectiveSupEx() && console.debug(`Successfully submitted results for slice ${slice.identifier} and worker ${this.workerId}`, Date.now()-this.lastTime);

          common.debugQuanta() && this.dbg.addGlobal(slice, payload.metrics);
          slice.jobManager.update({ metrics: payload.metrics }); // Update metrics

          slice.markAsFinished();

          // Remove the slice from the job manager.
          slice.jobManager.removeSlice(slice);
          // First running slice often waits 7 seconds until fetchTask() -- detect it and call fetchTask().
          selectiveDebug2() && console.debug(`resultSubmitter(slice=${slice.identifier}, transition_to_running=${slice.isEstimation && payload.running})`, slice.isEstimation, payload.running, this.fetchTaskBarrier);
          if (slice.isEstimation && payload.running) // Indicates job just transitioned estimation -> running.
          {
            // The extra few seconds we eliminate is noticeable in Dan's demos.
            utils.a$sleepMs(1000) // getSuitableJobs has a 1 second job cache...
              .then(() => {
                selectiveSupEx() && console.debug(`resultSubmitter(slice=${slice.identifier}) has transitioned to running...`, Date.now()-this.lastTime);
                this.fetchTask(); // Speed up 1st running slice.
              });
          }

          // Emit the 3 'payment' events.
          const paymentAddress = payloadData.paymentAddress.toString();
          this.workerEmit(             'payment', payload.slicePaymentAmount, paymentAddress, slice.jobAddress, slice.sliceNumber);
          this.jobEmit(slice,          'payment', payload.slicePaymentAmount, paymentAddress, slice.sliceNumber);
          this.safeEmit(sandboxHandle, 'payment', payload.slicePaymentAmount, paymentAddress);

          const payloadLength = kvin.stringify(payloadData).length; /** @todo - fix per DCP-3750 */
          const resultUrl = slice.resultStorageDetails?.length ? slice.resultStorageDetails : false;
          this.workerEmit(    'result', resultUrl, payloadLength, slice.jobAddress, slice.sliceNumber);
          this.jobEmit(slice, 'result', resultUrl, payloadLength, slice.sliceNumber);

          if (this.sliceTiming)
          {
            slice['resultDelta'] = Date.now() - slice['resultDelta'];
            console.debug(`recordResult(${slice['queueingDelta']}, ${slice['executionDelta']}, ${slice['resultDelta']}): Completed slice ${slice.identifier}.`, Date.now() - this.lastTime);
          }
          if (false && common.debugQuanta())
          {
            console.debug('localRawData:', this.dbg.localRawData);
            console.debug('localData:', this.dbg.localData);
            console.debug('globalData:', this.dbg.globalData);
          }

          return resp;
        })
        .catch ((error) => {
          handleRSError (error, slice);
        });
    }
    catch (error)
    {
      handleRSError (error, slice);
    }
  }

  /**
   * Send a work function's result to a server that speaks our DCP Remote Data Server protocol.
   * E.g. https://gitlab.com/Distributed-Compute-Protocol/dcp-rds
   *
   * @param {Slice} slice - Slice object whose result we are sending.
   * @returns {Promise<string>}
   * @throws When HTTP status not in the 2xx range.
   */
  async sendResultToRemote (slice)
  {
    /** XXXpfr @todo: Support file upload. */
    function serializeContent(result, category = { isJSON: true, isKVIN: false, isBinary: false, isText: false }) {
      if (category.isJSON) return JSON.stringify(result);
      if (category.isKVIN) return kvin.serialize(result);
      if (category.isBinary) return new Uint8Array(result.buffer);
      return result;
    }

    // Construct postParams.
    const postParams = { ...slice.resultStorageParams };
    if (!postParams.contentType)
      postParams.contentType = 'application/json';
    if (!postParams.element)
      postParams.element = slice.sliceNumber;
    debugging('supervisor') && console.debug('sendResultToRemote postParams:', postParams);

    // Categorize postParams.contentType.
    const category = utils.categorizeContentType(postParams.contentType);

    // Construct result.
    const result = slice.result.result;
    if (result)
      postParams.content = serializeContent(result, category);
    else
      postParams.error = serializeContent(slice.error);
    debugging('supervisor') && console.debug('sendResultToRemote content:', (result ? postParams.content : postParams.error).slice(0, 128));

    // Construct url.
    const sliceResultUri = slice.resultStorageDetails;
    // cf.DCP-3679
    // const sliceResultUri = makeValueURI('pattern', slice.resultStorageDetails, {
    //   slice: slice.sliceNumber,
    //   job:   slice.jobAddress,
    // });
    debugging() && console.debug('sendResultToRemote sliceResultUri:', sliceResultUri);
    const url = new DcpURL(sliceResultUri);

    // Check allowed origins.
    if (!this.originManager.isAllowed(url.origin, 'sendResults'))
      throw new DCPError(`Invalid origin for remote result storage: '${url.origin}'`, 'EPERM_ORIGIN');

    let body = postParams, type = 'string';
    /**
     * @todo XXXpfr Need to properly implement FormData to support multipart/form-data POST
     * (cf. DCP branch improvement/dcp-3446-multipart-remote-results)
     *
     */
    // if (category.isBinary)
    // {
    //   // Set up a multipart/form-data POST in order to upload binary data.
    //   const entries = Object.entries(postParams);
    //   const form = new FormData();

    //   entries.forEach((kvp) => {
    //     if (ArrayBuffer.isView(kvp[1]))
    //     {
    //       if (!DCP_ENV.isBrowserPlatform)
    //         form.append(kvp[0].toString(), new Uint8Array(kvp[1].buffer));
    //       else
    //         form.append(kvp[0].toString(), new Blob([new Uint8Array(kvp[1].buffer)]));
    //     }
    //     else
    //       form.append(kvp[0].toString(), kvp[1].toString());
    //   });

    //   if (!DCP_ENV.isBrowserPlatform)
    //   {
    //     body = form.getBuffer();
    //     type = form.getHeaders()['content-type'];
    //   }
    //   else
    //   {
    //     body = form;
    //     type = 'multipart/form-data';
    //   }
    // }

    // Fetch.
    return justFetch(url, type, 'POST', false, body)
      .then((response) => utils.encodeDataURI(JSON.stringify(response)));
  }

  // _Idx
  //
  // handleWorkReject
  //

  /**
   * Handles reassigning or returning a slice that rejected.
   *
   * If error.message === 'false' and slice.hasBeenRejected is false, reschedule the slice.
   * Set the slice.hasBeenRejected to be true.
   *
   * If error.message !== 'false' or slice.hasBeenRejected is true (i.e. has been rejected once already)
   * then return all slices from the job to the scheduler and terminate all sandboxes with that jobAddress.
   *
   * @param {Slice}   slice
   * @param {Error}   error
   */
  handleWorkReject (slice, error)
  {
    debugging() && console.debug('handleWorkReject', error.message, slice.hasBeenRejected, slice.identifier);

    const jobManager = slice.jobManager;
    if (jobManager.dead)
       return; // Job has been already purged.

    // First time rejecting without a reason; try rescheduling the slice.
    if (error.message === 'false' && !slice.hasBeenRejected)
    {
      // Mark slice as rejected.
      slice.hasBeenRejected = true;
      // Reset slice state to allow re-execution.
      jobManager.cloneSlice(slice);
    }
    else
    {
      // Slice has been rejected twice, so add to array of rejected jobs.
      this.ringBufferOfRejects.push(slice.jobAddress);
      // Broadcast failure.
      this.workerEmit(    'result', error, slice.jobAddress, slice.sliceNumber);
      this.jobEmit(slice, 'result', error, slice.sliceNumber);
      // Purge the job.
      this.purgeJob(jobManager);
      // Tell everyone all about it, when allowed.
      if (jobManager.displayMaxDiagInfo)
      {
        const suffixMsg = 'All slices and sandboxes with the same jobAddress returned to the scheduler or terminated.';
        if (slice.hasBeenRejected)
          this.warning(`work.reject: The slice ${slice.identifier} was rejected twice.`, suffixMsg);
        else
          this.warning(`work.reject: The slice ${slice.identifier} was rejected with reason: ${error.message}.`, suffixMsg);
      }
    }
  }

}
exports.Supervisor = Supervisor;
