var _referer;
exports.getReferer = function dcpXhr$$getReferer() {
  _referer = process.env.DCP_XHR_REFERER || (dcpConfig?.network && dcpConfig.network['http-referer']);
  
  if (!_referer) {
    if (module && module.parent && module.parent.filename) {
      _referer = requireNative('path').basename(module.parent.filename) + '/dcp-xhr'
    } else {
      /* webpack, probably */
      _referer = String((new Error().stack || '').split('\n')[1].match(/\(.*\)/)).replace(/^\(/,'').replace(/\)$/,'').replace(/\?.*/,'')
      _referer = _referer.substring(_referer.lastIndexOf(requireNative('path').sep) + 1);
      _referer = _referer.substring(0, _referer.indexOf(':'));
    }
  }
}

exports.setReferer = function dcpXhr$$setReferer(referer) {
  _referer = referer;
}
