const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');

/** 
 * Parse a line into tokens, similar to the Bourne shell's `set` command. 
 * The following syntax is supported:
 * - backslash to escape - supported escape are double quote, space, single quote
 * - space as the token separator (IFS)
 * - double quotes to quote token groups that can contain escapes
 * - single quotes to quote token groups that cannot contain escapes
 * - empty tokens are ignored
 *
 * @param    {string}  inBuf           The string to parse or falsey
 * @returns  {array} array of parsed tokens
 */
exports.tokenize = function utils$$parseLine(inBuf) {
  var outBuf = '';
  var outBufs = [];
  var inSQSection = false; 
  var inDQSection = false;
  var escape = false;

  if (!inBuf)
    return outBufs;

  for (i=0; i < inBuf.length; i++) {
    escape = false;
    if (!inSQSection && inBuf[i] === '\\') {
      switch(inBuf[i + 1]) {
        case '"': case ' ': case "'":
          escape = true;
          i++;
          break;
      }
    }

    if (!inDQSection && !inSQSection && !escape && inBuf[i] === ' ') {
      if (outBuf.length)
        outBufs.push(outBuf);
      outBuf = '';
      continue;
    }

    if (!escape && !inSQSection && inBuf[i] === '"') {
      inDQSection = !inDQSection;
      continue;
    }
    
    if (!escape && !inDQSection && inBuf[i] === "'") {
      inSQSection = !inSQSection;
      continue;
    }

    outBuf += inBuf[i];
  }

  if (outBuf)
    outBufs.push(outBuf);

  return outBufs;
}

/** Resolve pathnames via usual bash tilde-expand rules. Does not glob.
 *  @note  Homedirs for other than the current user may be incorrect on 
 *         non-unix platforms.
 */
exports.expandPath = function utils$$sh$expandPath(pathname, homedir) {
  const os = requireNative('os');
  const path = requireNative('path');

  var re, match, self;

  if (!pathname)
    return pathname;

  if (path.isAbsolute(pathname))
    return pathname;

  if (pathname === '~')
    return os.homedir();
  
  if (pathname === '~+')
    return process.cwd();
  
  if (pathname.startsWith('~' + path.sep))
    return path.resolve(os.homedir(), pathname.slice(2));

  self = os.userInfo.username;

  re = new RegExp('~([^\\/]+)([\\/]|$)(.*)');
  if ((match = re.exec(pathname))) {
    let user = match[1];
    let rest = match[3];

    if (user === self)
      return path.resolve(os.homedir(), rest);

    return path.resolve(exports.locateHomeDir(user), rest);
  }

  if (pathname.startsWith('.' + path.sep) || pathname.startsWith('..' + path.sep))
    return path.resolve(process.cwd(), pathname);

  return path.resolve(pathname);
}

/** Locate a given user's home directory.  We guess on Win32 and read
 *  the passwd file on Unix.
 *
 * @todo  This is fine for a fall-back, but we should be using node's FFI
 *        to invoke getpwent in the fullness of time. /wg feb 2021
 */
exports.locateHomeDir = function utils$$sh$locateHomeDir(username) {
  const os = requireNative('os');
  const fs = requireNative('fs');
  
  if (os.platform() === 'win32')
    return path.resolve(os.homedir(), '..', username);

  var epw = fs.readFileSync('/etc/passwd', 'ascii');
  var entries = epw.split('\n');
  var names = entries.map((a) => a.replace(/:.*/,''));
  var idx = names.indexOf(username);

  if (idx === -1)
    throw new Error('No such user: ' + username);

  return entries[idx].split(':')[5];
}
