/**
 *  @file       shutdown.js     
 *
 *              Generic code to handle the trapping of uncaught promise
 *              rejections and POSIX signals in network daemons, with
 *              error reporting propagation to the clients.
 *
 *              There are three kinds of shutdown operations:
 *              1 - graceful tasks: these are always invoked and tell the graceful
 *                  shutdown handler whether or not they were successful. Async
 *                  functions are supported and functions returning promises are
 *                  awaited. Unsuccessful shutdown attempts return false.
 *
 *              2 - forced tasks: these are invoked if the graceful tasks do not
 *                  complete after a specified time. The process will exit in the
 *                  same pass of the event loop as the execution of the forced tasks.
 *
 *              3 - shutdown functions: these are always invoked and their return
 *                  values are ignored; similar to POSIX atexit()
 *
 *              Shutdown functions and forced shutdowns are hooked from process.exit,
 *              and as such always get invoked on exit if registered.  In order to
 *              perform a graceful shutdown, the exports.manage() should be used to
 *              wrap the program's main function OR the exports.shutdown() will need
 *              to be explicitly invoked.
 *
 *              IMPORTANT: Do not call process.exit() from a shutdown function or task.
 *                         Use process.exitCode to set a non-zero exit code. This 
 *                         library will not override a non-zero exit code from the 
 *                         application program.
 *
 *  @author     Wes Garland, wes@kingsds.network
 *  @date       July 2018, May 2021
 */
'use strict';

const process = require('process');
const { leafMerge } = require('dcp/utils');
const { assert } = require('dcp/common/dcp-assert');
const { setBackoffInterval, clearBackoffInterval } = require('dcp/common/dcp-timers');
const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');

const taskRegistry = [];
const registeredAtFunctions = [];
const debugging = require('dcp/debugging').scope('shutdown');

var timeDilation = 1;
try
{
  if (requireNative('module')._cache.niim instanceof requireNative('module').Module)
  {
    timeDilation = 10;
    debugging('timeDilation') && console.debug(`053: Running inside niim; timeDilation is ${timeDilation}`);
  }
}
catch (error)
{
  debugging('timeDilation') && console.debug(`058: Failed to requireNative('module'); probably not running in Node`);
}

const defaultOptions = {
  gracefulTimeout: "15.0",
  backoffFactor:   1.1,
  baseInterval:    1000,
  maxInterval:     3000
};

/**
 * Analogue of POSIX atexit(2). Invokes a function when the process is exiting.
 * Ideally, this is what process.on('exit') would do, but it doesn't fire in
 * the case of default signal handlers.
 */
exports.atExit = function shutdown$$atExit(fn)
{
  require('./signal-handler').init();
  process.on('dcpExit', fn);
}

exports.atExitCancel = function shutdown$$atExit(fn)
{
  process.off('dcpExit', fn);
}

/** Register a task which is to be executed during the shutdown of a server.
 *
 *  @param {Function} taskFn              The function to execute. When invoked, this function receives
 *                                        a single argument, which is the reason for the shutdown (the
 *                                        why object from inside the server manager).  The taskFn function
 *                                        must return true to indicate that its job has been completed;
 *                                        otherwise it will be tried again (and again) during shutdown.
 *                                        This function /must/ behave in a 'synchronous' (blocking) manner.
 *                                        The taskFn function will not be invoked until after we have tried
 *                                        to close all of the client sockets.
 *
 *  @param {boolean} [gracefulOnly=false] Execute only when performing graceful shutdown
 *  @param {boolean} [forcedOnly=false]   Execute only when performing forced shutdown
 */
exports.registerTask = function shutdown$$registerTask(taskFn, gracefulOnly, forcedOnly)
{
  var registration = {
    fn:       taskFn,
    graceful: !forcedOnly,
    forced:   !gracefulOnly
  };

  debugging() && console.debug(`shutdown: registered task ${taskFn.name} ${gracefulOnly ? '- graceful only' : ''} ${forcedOnly ? '- forced only' : ''}`);
  assert(!(forcedOnly && gracefulOnly));
  
  taskRegistry.push(registration);
}

/** Unregister all previously-registered shutdown tasks matching taskFn.
 *
 *  @see exports.registerTask
 *
 *  @param      taskFn          The function which was previously registered
 *  @param      gracefulOnly    Only unregister the graceful-shutdown invocation of this function
 *  @param      forcedOnly      Only unregister the forced-shutdown invocation of this function
 *
 *  @returns    true if the task was located in the task registry
 */
exports.unregisterTask = function shutdown$$unregisterTask(taskFn, gracefulOnly, forcedOnly)
{
  var ret = false;

  debugging() && console.debug(`shutdown: unregistering task ${taskFn.name} ${gracefulOnly ? '- graceful only' : ''} ${forcedOnly ? '- forced only' : ''}`);

  for (let i=0; i < taskRegistry.length; i++)
  {
    let registration = taskRegistry[i];

    if (registration.fn !== taskFn)
      continue;

    if (gracefulOnly)
      registration.graceful = false;
    if (forcedOnly)
      registration.forced = false;
    
    if ((!registration.forced && !registration.graceful) || (!gracefulOnly && !forcedOnly))
      taskRegistry.splice(i--, 1);

    debugging() && console.debug(`shutdown: unregistered ${taskFn.name}`);

    ret = true;
  }

  return ret;
}

/**
 * Shutdown reasons can be varied and are intended to be convenient to use for the caller
 * from whatever context/information happens to be at hand.
 *
 * Once this function returns, the new reason should be something we can handle elegantly
 * from inside this code or inside a shutdown task.  The following properties will always
 * be defined:
 *   why:    root cause of shutdown decision (eg SIGINT); should be short and unique so that
 *           shutdown tasks can inspect it to make choices
 *   mesage: root cause of shutdown decision in human-readable text.
 */
function fixReason(reason)
{
  if (typeof reason === 'string')
    reason = { why: reason, message: reason };
  if (!reason.why && reason instanceof Error)
    reason.why = reason.name;
  if (!reason.why && !reason.message)
  {
    reason.why = 'unknown';
    const stack = new Error().stack;
    if (stack)
      reason.message = stack.split('\n').slice(2).join('\n');
  }
  if (!reason.why)
    reason.why = reason.message;
  if (!reason.message)
    reason.message = reason.why;

  return reason;
}

/**
 * Invoke each graceful shutdown handler once, await their results, unregistering if they succeed. A "failing" 
 * task causes this function to bail without processing any further tasks. This allows us, for example, to 
 * implement a daemon that can stay alive during heavy traffic and then bounce when there is a break in user
 * activity.
 *
 * @param {Object}       reason          Reason object to pass to shutdown task
 * @returns true if no handlers returned false.
 */
async function invokeGracefulShutdownTasks(reason)
{
  reason = fixReason(reason);
  debugging() && console.debug('Graceful shutdown -', reason.message);
  
  while(taskRegistry.length)
  {
    let registration = taskRegistry[taskRegistry.length - 1];
    let taskFn = registration.fn;

    if (!registration.graceful)
      continue;
    
    try
    {
      let notOk = await taskFn(reason) === false;
      debugging() && console.debug(`shutdown: graceful task ${taskFn.name} ${notOk ? 'did not run' : 'ran'} ok`);
      if (notOk)
        return false;
    }
    catch(e)
    {
      if (!(e instanceof Error))
        console.warn(`Warning: Shutdown task ${taskFn.name} rejected with type=${typeof e}, which is not an instanceof Error`);
      debugging() && console.debug(`shutdown: graceful task ${taskFn.name} failed (will retry); ${e && e.message}`);
      return false;
    }
    
    exports.unregisterTask(taskFn);
    debugging() && console.log('debugging: tasks left:', taskRegistry.length);
  }

  return true;
}

/* Invoke each forced shutdown handler once.
 *
 * @param {Object}       reason          Reason object to pass to shutdown task
 */
function invokeForcedShutdownTasks(reason)
{
  reason = fixReason(reason);
  debugging() && console.debug('shutdown: starting forced shutdown -', reason);

  for (let registration of taskRegistry)
  {
    let taskFn = registration.fn;
    
    if (registration.forced)
    {
      try
      {
        taskFn(reason);
        debugging() && console.debug(`shutdown: ran forced task ${taskFn.name}`);
      }
      catch(e)
      {
        console.warn(`shutdown: forced shutdown task ${taskFn.name} failed`, e);
      }
    }

    exports.unregisterTask(taskFn);
    debugging() && console.log('debugging: tasks left:', taskRegistry.length);
  }
}

/** 
 * Register a shutdown function.
 *
 * These functions are invoked once during the shutdown process. They are different from shutdown 
 * tasks in that they are fire-and-forget rather than monitored and potentially retried. Functions are
 * run in LIFO order, and before any of the shutdown tasks.
 *
 * This function hooks process.exit, so the shutdown functions and the forced shutdown tasks are
 * run, if registered, regardless of whether or not this is a managed process.
 *
 * @param {function}    fn      a function to run at shutdown
 */ 
