    function gracefulTimeoutElapsed() {
      process.exitCode = 50;
      forceShutdown();
    }
    exports.shutdown.timer = setTimeout(gracefulTimeoutElapsed, 1000 * options.gracefulTimeout).unref();
    nodeKeepalive = setTimeout(Function, 1 << 31 /* "infinity" */);

    if (force === true)
    {
      forceShutdown();
      process.exit(60);
    }

    /* Try running the graceful shutdown tasks on an exponential backoff until no
     * tasks fail; when this happens, clear the forced shutdown timer and exit.
     * Note that this promise is purposefully never resolved. Process.exit is 
     * invoked via process.nextTick so that anything else on the event loop can
     * unwind but with no danger that new events will be handled.
     */
