{
  const shutdown = exports.shutdown;
  var jumpTable;

  function unhandledRejection(error, promise)
  {
    let options = leafMerge(defaultOptions, (typeof dcpConfig !== 'undefined' ? dcpConfig.daemons.shutdown : {}));
    
    if (!(error instanceof Error))
      error = new Error('Unhandled Rejection:'  + error);
    process.exitCode = process.exitCode || 53;
    console.error('\nunhandled rejection:', error, 'at:', promise);
    if (options.liveDangerously)
    {
      console.warn('living dangerously - not killing program');
      return;
    }
    error.why = 'unhandledRejection';
    shutdown(error, true);
  }

  function uncaughtException(error, origin)
  {
    let options = leafMerge(defaultOptions, (typeof dcpConfig !== 'undefined' ? dcpConfig.daemons.shutdown : {}));

    process.exitCode = process.exitCode || 53;
    console.error('\nuncaught exception:', error);
    error.why = 'uncaughtException';
    if (options.liveDangerously)
    {
      console.warn('living dangerously - not killing program');
      return;
    }
    shutdown(error, true);
  }

  function sigInt()
  {
    process.exitCode = process.exitCode || 63;
    shutdown({why: 'SIGINT', message: 'Trapped signal 2'});
    jumpTable.sigInt = doubleTap;
  }

  function sigQuit()
  {
    process.exitCode = process.exitCode || 70;
    shutdown({why: 'SIGQUIT', message: 'Trapped signal 10'});
    jumpTable.sigQuit = doubleTap;
  }

  function sigTerm()
  {
    process.exitCode = process.exitCode || 75;
    shutdown({why: 'SIGTERM', message: 'Trapped signal 15'});
    jumpTable.sigTerm = doubleTap;
  }

  function doubleTap()
  {
    exports.shutdown.timer._onTimeout(); /* expire the graceful shutdown right away */
  }
  
  delete exports.manageProcess; /* don't call twice! */
  
  process.on('unhandledRejection', (...a) => jumpTable.unhandledRejection(...a));
  process.on('uncaughtException',  (...a) => jumpTable.uncaughtException (...a));
  process.on('SIGINT',             (...a) => jumpTable.sigInt            (...a));
  process.on('SIGQUIT',            (...a) => jumpTable.sigQuit           (...a));
  process.on('SIGTERM',            (...a) => jumpTable.sigTerm           (...a));

  jumpTable = { unhandledRejection, uncaughtException, sigInt, sigQuit, sigTerm };
  return jumpTable;
}

/** 
 * Begin managing a program's shutdown.
 *
 * @param {function}  func      the program's main function - shutdown begins automatically when it returns or
 *                              the promise it returns resolves or rejects.
 * @param {array}     argv      arguments to pass to func
 *
 * @returns the value returned by func.apply(null, argv);, unless it is a Promise, in which case we return a
 *          Promise which awaits that value.
 */
exports.manage = async function shutdown$$manage(func, argv, options)
{
  const shutdown = exports.shutdown;
  let ret;

  exports.manageProcess();

  debugging() && console.debug('shutdown: managing function', func.name);
  try
  {
    ret = func.apply(null, argv || []);
  }
  catch(e)
  {
    process.exitCode = process.exitCode || 52;
    console.error(e);
    await shutdown({why: 'uncaughtException', message: e.message}).catch(process.exit);
    process.exit(60);
  }

  debugging() && console.debug(`shutdown: ${func.name} was ${ret instanceof Promise ? 'async' : 'sync'}`);
  if (!(ret instanceof Promise))
  {
    await shutdown({why: 'normal exit'})
    process.exit(60);
  }
  
  try
  {
    /* ret is a Promise => func is async */
    await ret
      .then((result) => shutdown({why: 'normal exit', message: 'normal exit (async)'}))
      .catch((error) => shutdown({why: `unhandled rejection ${error.message}`}))
  }
  catch(error)
  {
    console.log(error);
  }

  process.exit(60);
}
