/**
 * @file worker/supervisor.js
 *
 * The component that controls each of the sandboxes
 * and distributes work to them. Also communicates with the
 * scheduler to fetch said work.
 *
 * The supervisor readies sandboxes before/while fetching slices.
 * This means sometimes there are extra instantiated WebWorkers
 * that are idle (in this.readiedSandboxes). Readied sandboxes can
 * be used for any slice. After a readied sandbox is given a slice
 * it becomes assigned to slice's job and can only do work
 * for that job.
 *
 * After a sandbox completes its work, the sandbox becomes cached
 * and can be reused if another slice with a matching job is fetched.
 *
 * @author Matthew Palma, mpalma@kingsds.network
 *         Ryan Rossiter, ryan@kingsds.network
 * @date May 2019
 */

/* global dcpConfig */ // eslint-disable-line no-redeclare
// @ts-check
'use strict';

const constants = require('dcp/common/scheduler-constants');
const wallet = require('dcp/dcp-client/wallet');
const { Address } = require('dcp/dcp-client/wallet/eth');
const { Keystore } = require('dcp/dcp-client/wallet/keystore');
const protocolV4 = require('dcp/protocol-v4');
const DCP_ENV = require('dcp/common/dcp-env');
const { OriginAccessManager } = require('dcp/dcp-client/worker/origin-access-manager');
const debugging = require('dcp/debugging').scope('worker');
const { assert } = require('dcp/common/dcp-assert');
const EventEmitter = require('events');
const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
const { localStorage } = require('dcp/common/dcp-localstorage');
const { DCPError } = require('dcp/common/dcp-error');
const dcp_timers = require('dcp/common/dcp-timers');
const { sliceStatus } = require('dcp/common/scheduler-constants');
const { booley, encodeDataURI, leafMerge, a$sleepMs, compressJobMap, toJobMap, compressSandboxes,
        compressSlices, truncateAddress, generateOpaqueId } = require('dcp/utils');

const { dumpSandboxesIfNotUnique, dumpSlicesIfNotUnique } = require('./old_utils')
const { Sandbox, SandboxError } = require('./sandbox');
const { Slice, SLICE_STATUS_UNASSIGNED, SLICE_STATUS_FAILED } = require('./slice');
const { SupervisorCache } = require('./supervisor-cache');
const RingBuffer = require('dcp/utils/ringBuffer');
const supShared = require('./SupShared');

/** Make timers 10x slower when running in niim */
let timeDilation = 1;
if (DCP_ENV.platform === 'nodejs') {
  /** Make timers 10x slower when running in niim */
  timeDilation = (requireNative('module')._cache.niim instanceof requireNative('module').Module) ? 10 : 1;
}

/** @typedef {string} opaqueId */ // 22 character base64 string
/** @typedef {import('./index').Worker} Worker                                     */
/** @typedef {import('dcp/dcp-client/wallet/keystore').Keystore} Keystore          */
/** @typedef {import('dcp/utils/jsdoc-types').SliceMessage} SliceMessage           */
/** @typedef {import('dcp/utils/jsdoc-types').Auth} Auth                           */
/** @typedef {import('dcp/utils/jsdoc-types').Signature} Signature                 */
/** @typedef {import('dcp/utils/jsdoc-types').SupervisorOptions} SupervisorOptions */

/**
 * @typedef {object} SandboxSlice
 * @property {Sandbox} sandbox
 * @property {Slice} slice
 */

// Slightly different from descriptor in dcp/utils/jsdoc-types
/**
 * @typedef {object} TDPayload
 * @property {Address} owner
 * @property {Signature} signature
 * @property {Auth} auth
 * @property {Body} body
 */

// Slightly different from descriptor in dcp/utils/jsdoc-types
/**
 * @access public
 * @typedef {object} Body
 * @property {Object<string, object>} [newJobs]
 * @property {SliceMessage[]} task
 * @property {Object<string, string[]>} [computeGroupJobs]
 * @property {Object<string, Object<string, string[]>>} [computeGroupOrigins]
 * @property {{ targetTaskDuration: number }} [schedulerConfig]
 */

class Supervisor extends EventEmitter {
  /**
   * @constructor
   * @param {Worker} worker
   * @param {Keystore} identity
   * @param {SupervisorOptions} options
   */
  constructor (worker, identity, options) {
    super({ captureRejections: false });

    if (!(identity instanceof Keystore))
      throw new Error(`identity ${JSON.stringify(identity)} must be an instance of Keystore`);

    debugging('supervisor') && console.debug('Supervisor.options', options);
    assert(options === worker.workerOptions);

    /** @type {Worker} */
    this.worker = worker;
    this.setDefaultIdentityKeystore(identity);
    // Sup1/Sup2 compatibility.
    this._identityKeystore = identity;
    /** @type {SupervisorOptions} */
    this.options = options;

    debugging() && console.debug('Supervisor 1: cores.cpu, cores.gpu, maxSandboxes', options.cores?.cpu, options.cores?.gpu, this.maxSandboxes);

    // Verify options.jobAddresses exist
    if (!this.options.jobAddresses)
      this.options.jobAddresses = [];

    this.tuning = {
      watchdogInterval:     7,    /**< seconds - time between fetches when ENOTASK(? /wg nov 2019) */
      minSandboxStartDelay: 0.1,  /**< seconds - minimum time between WebWorker starts */
      maxSandboxStartDelay: 0.7,  /**< seconds - maximum delay time between WebWorker starts */
      ...dcpConfig.supervisor.tuning
    };
    
    /** @type {object} */
    this.jobHandles = {};
    
    /** @type {Sandbox[]} */
    this.sandboxes = [];

    /** @type {Sandbox[]} */
    this.readiedSandboxes = [];

    /** @type {Sandbox[]} */
    this.assignedSandboxes = [];

    /** @type {Slice[]} */
    this.slices = [];

    /** @type {Slice[]} */
    this.queuedSlices = [];

    /** @type {Slice[]} */
    this.lostSlices = [];

    /** @type {boolean} */
    this.matching = false;

    /** @type {boolean} */
    this.isFetchingNewWork = false;

    /** @type {number} */
    this.numberOfCoresReserved = 0;

    /** @type {number} */
    this.addressTruncationLength = 20; // Set to -1 for no truncation.

    /** @type {Array<{ address: string, reasons: string[] }>} */
    this.rejectedJobs = [];
    /** @type {Object<string, string[]>} */
    this.rejectedJobReasons = {};

    /** @type {number} */
    this.defaultMaxGPUs = 1;

    /** @type {boolean} */
    this.enterSandboxHandleEndHandler = false;

    /**
     * TODO: Remove this when the supervisor sends all of the sandbox
     * capabilities to the scheduler when fetching work.
     * @type {object}
     */
    this.capabilities = null;

    /** @type {number} */
    this.lastProgressReport = 0;
    this._t0 = Date.now();

    /** 
     *  An N-slot ring buffer of job addresses. Stores all jobs that have had no more than 1 slice run in the ring buffer.
     *  Required for the implementation of discrete jobs 
     *  @type {RingBuffer} 
     */
    this.ringBufferOfJobs = new RingBuffer(200); //  N = 200 should be more than enough.
    
    /** @type {OriginAccessManager} */
    this.originManager = OriginAccessManager.construct(this.options.allowOrigins);
  
    /** @type {SupervisorCache} */
    this.cache = new SupervisorCache(this);
    /** @type {object} */
    this._connections = {}; /* active DCPv4 connections */
    // Call the watchdog every 7 seconds.
    this.watchdogInterval = dcp_timers.setInterval(() => this.watchdog(), this.tuning.watchdogInterval * 1000);
    this.watchdogInterval.unref();

    const ceci = this;

    // Initialize to null so these properties are recognized for the Supervisor class
    this.taskDistributorConnection = null;
    this.eventRouterConnection = null;
    this.resultSubmitterConnection = null;
    this.packageManagerConnection = null;
    this.openTaskDistributorConn = function openTaskDistributorConn()
    {
      let config = dcpConfig.scheduler.services.taskDistributor;
      ceci.taskDistributorConnection = new protocolV4.Connection(config, connectionOptions(config.location, ceci.identityKeystore, 'taskDistributor'));
      ceci.taskDistributorConnection.on('end', ceci.openTaskDistributorConn);

      // Worker API connect and disconnect event propogation
      ceci.taskDistributorConnection.on('connect',    (event) => this.worker.emit('connect', event));
      ceci.taskDistributorConnection.on('disconnect', (event) => this.worker.emit('disconnect', event));
    }

    this.openEventRouterConn = function openEventRouterConn()
    {
      let config = dcpConfig.scheduler.services.eventRouter;
      ceci.eventRouterConnection = new protocolV4.Connection(config, connectionOptions(config.location, ceci.identityKeystore, 'eventRouter'));
      ceci.eventRouterConnection.on('end', ceci.openEventRouterConn);
      if (ceci.eventRouterMessageQueue.length)
        ceci.resendRejectedMessages(ceci.eventRouterConnection, ceci.eventRouterMessageQueue);

      // Worker API connect and disconnect event propogation
      ceci.eventRouterConnection.on('connect',    (event) => this.worker.emit('connect', event));
      ceci.eventRouterConnection.on('disconnect', (event) => this.worker.emit('disconnect', event));
    }
    this.eventRouterMessageQueue = [];
  
    this.openResultSubmitterConn = function openResultSubmitterConn()
    {
      let config = dcpConfig.scheduler.services.resultSubmitter;
      ceci.resultSubmitterConnection = new protocolV4.Connection(config, connectionOptions(config.location, ceci.identityKeystore, 'resultSubmitter'));
      ceci.resultSubmitterConnection.on('end', ceci.openResultSubmitterConn);
      if (ceci.resultSubmitterMessageQueue.length)
        ceci.resendRejectedMessages(ceci.resultSubmitterConnection, ceci.resultSubmitterMessageQueue);

      // Worker API connect and disconnect event propogation
      ceci.resultSubmitterConnection.on('connect',    (event) => this.worker.emit('connect', event));
      ceci.resultSubmitterConnection.on('disconnect', (event) => this.worker.emit('disconnect', event));
    }
    this.resultSubmitterMessageQueue = [];

    this.openPackageManagerConn = function openPackageManagerConn()
    {
      let config = dcpConfig.packageManager;
      ceci.packageManagerConnection = new protocolV4.Connection(config, connectionOptions(config.location, ceci.identityKeystore, 'packageManager'));
      ceci.packageManagerConnection.on('end', ceci.openPackageManagerConn);
      if (ceci.packageManagerMessageQueue.length)
        ceci.resendRejectedMessages(ceci.packageManagerConnection, ceci.packageManagerMessageQueue);

      // Worker API connect and disconnect event propogation
      ceci.packageManagerConnection.on('connect',    (event) => this.worker.emit('connect', event));
      ceci.packageManagerConnection.on('disconnect', (event) => this.worker.emit('disconnect', event));
    }
    this.packageManagerMessageQueue = [];

    //
    // Some properties that used to be static, but should not have been
    //
    /** @type {number | boolean} */
    this.lastAssignFailTimerMs = false;
    /** @type {boolean} */
    this.startSandboxWork_beenCalled = false;
    /** @type {boolean} */
    this.debugBuild = (require('dcp/common/dcp-build').build === 'debug');
    /**
     * When this.sliceTiming is set to be true, it displays the timings of a every slice
     * slice['pairingDelta'] = timespan of when slice is paired with sandbox until execution starts
     * slice['executionDelta'] = timespan of execution in sandbox
     * slice['resultDelta'] = timespan of when sandbox finishes executing until recordResult completes.
     * @type {boolean}
     */
    this.sliceTiming = false;
  }

  /**
   * This getter is the absolute source-of-truth for what the
   * identity keystore is for this instance of the Supervisor.
   * @type {Keystore}
   */
  get identityKeystore() {
    return this._identityKeystore || this.defaultIdentityKeystore;
  }
  /** @type {Keystore} */
  set identityKeystore(ks) {
    if (!(ks instanceof Keystore))
      throw new Error('Supervisor.identityKeystore: must be an instance of Keystore.');
    this._identityKeystore = ks;
  }
  
  /**
   * Maximum sandboxes allowed to work at a given time.
   * @type {number}
   */
  get maxSandboxes() { return Math.floor(this.options.cores?.cpu || 1); }
  /**
   * Maximum sandboxes allowed to work at a given time.
   * @type  {number}
   */
  set maxSandboxes(newVal) { this.options.cores.cpu = Math.floor(newVal); }

  /**
   * Return worker opaqueId.
   * @type {opaqueId}
   */
  get workerOpaqueId() {
    if (!this._workerOpaqueId)
      this._workerOpaqueId = localStorage.getItem('workerOpaqueId');

    if (!this._workerOpaqueId || this._workerOpaqueId.length !== constants.workerIdLength)
      this.workerOpaqueId = generateOpaqueId();

    return this._workerOpaqueId;
  }
  /** @type {opaqueId} */
  set workerOpaqueId(newId) {
    this._workerOpaqueId = newId;
    localStorage.setItem('workerOpaqueId', this._workerOpaqueId);
  }
  /**
   * Ignore localStorage and set workerId directly.
   * When using multiple workers with different workerId's we don't want to
   * write to the localStorage 'workerId'; localWorkerId ignores localStorage.
   * @type {opaqueId|null}
   */
  set localWorkerId (newId) { this._workerOpaqueId = newId ? newId : generateOpaqueId(); }

  /**
   * Sup1/Sup2 compatibility helpers.
   * @deprecated Rip this out when we kill sup1.
   * @todo XXXpfr Rip out this sup2/sup1 special-casing when we finally kill sup1.
   * We want to present a consistent interface, regardless whether it's sup1 or sup2.
   */
  /** @type {boolean} */
  get working() { return this.worker.working; }
  /** @type {opaqueId} */
  get workerId() { return this.workerOpaqueId; }
  /** @type {opaqueId} */
  set workerId(newWorkerId) { this.workerOpaqueId = newWorkerId; }
  /** @type {string} */
  get version () { return '1.5.0' }
  /** @type {Slice[]} */
  get workingSlices() { return this.allocatedSlices; }

  /**
   * Open all connections. Used when supervisor is instantiated or stopped/started
   * to initially open connections.
   */
  instantiateAllConnections() {
    if (!this.taskDistributorConnection)
      this.openTaskDistributorConn();
    
    if (!this.eventRouterConnection)
      this.openEventRouterConn();
    
    if (!this.resultSubmitterConnection)
      this.openResultSubmitterConn();

    if (!this.packageManagerConnection)
      this.openPackageManagerConn();
  }
  
  /**
   * Asynchronously send a result to the result submitter that was previously rejected.
   * Different from resendRejectedMessages below in the sense that the function only resolves
   * once we've delivered the result, or gone past our max number of attempts.
   * @param {object} result 
   * @returns the response payload from the result operation
   */
  async resendResult(result) {
    var protocolError = false;
    if (!result.sendRetries)
      result.sendRetries = 1;
    else
      result.sendRetries++;
    
    if (result.sendRetries > this.tuning.maxResultSubmissionRetries)
      throw new DCPError(`Could not submit result after ${dcpConfig.supervisor.tuning.maxResultSubmissionRetries} attempts. Aborting.`);
      
    debugging() && console.debug(`supervisor - failed to submit result ${result.sendRetries} time(s), trying again `)
    let res = await this.resultSubmitterConnection.request('result', result).catch(async (e) => {
      debugging('supervisor') && console.error(`Failed to submit result to scheduler for slice ${result.slice} of job ${result.job}:\n    ${e} \nWill try again on new connection.`);
      this.resultSubmitterConnection?.close();
      await a$sleepMs(10); /* let connection recycle */
      protocolError = true;
    });
    if ((!res.success && res.payload && res.payload.code === 'DCPS-01002') || protocolError)
      return this.resendResult(result)
    else
      return res;
  }
  
  /**
   * Try sending messages that were rejected on an old instance of the given connection.
   * These are messages that a) were rejected due to a protocol error and b) don't care when exactly
   * they're sent in the grand scheme of things.
   */
  resendRejectedMessages(connection, messageQueue) {
    var message, quitLoop;
    if (connection.resendingMessages) /* if the passed connection is already in the loop, exit */
      return;
        
    message = messageQueue.shift();

    do {
      connection.resendingMessages = true;
      quitLoop = false;
      
      connection.request(message.operation, message.data)
        .catch((e) =>
        {
          /* Protocol Error; Close connection (this will trigger the opening of a new connection that will try sending again) */
          debugging('supervisor') && console.error(`Failed to send message ${message.operation} to scheduler: ${e}. Will try again on a new connection.`);
          messageQueue.unshift(message);
          connection.close();
          quitLoop = true;
        });
      
      message = messageQueue.shift();
    
    } while (message && !quitLoop)

    connection.resendingMessages = false;
  }

  /** Set the default identity keystore -- needs to happen before anything that talks
   *  to the scheduler for work gets called.  This is a wart and should be removed by
   *  refactoring.
   *
   * The default identity keystore will be used if the Supervisor was not provided
   * with an alternate.  This keystore will be located via the Wallet API, and 
   * if not found, a randomized default identity will be generated. 
   *
   * @param {Keystore} [ks] - An instance of wallet::Keystore -- if undefined, we pick the best default we can.
   * @returns {Promise<void>}
   */
  async setDefaultIdentityKeystore(ks) {
    try {
      if (ks) {
        this.defaultIdentityKeystore = ks;
        return;
      }

      if (this.defaultIdentityKeystore)
        return;

      try {
        this.defaultIdentityKeystore = await wallet.getId();
      } catch(e) {
        debugging('supervisor') && console.debug('Error generating default identity, try to do it another way.');
        this.defaultIdentityKeystore = await new wallet.IdKeystore(null, '');
      }
    } finally {
      if (this.defaultIdentityKeystore)
        debugging('supervisor') && console.debug('Set default identity =', this.defaultIdentityKeystore.address);
      else
        debugging('supervisor') && console.debug('Failed to set default identity, worker cannot work.');
    }
  }

  //
  // What follows is a bunch of utility properties and functions for creating filtered views
  // of the slices and sandboxes array.
  //

  /**
   * Please do not use this.workingSandboxes; use this.allocatedSandboxes instead.
   * Sandboxes that are in WORKING state.
   *
   * Warning: Do not rely on this information being 100% accurate -- it may change in the next instant.
   * @type {Sandbox[]}
   */
  get workingSandboxes() {
    return this.sandboxes.filter(sandbox => sandbox.isWorking);
  }

  /**
   * Use instead of this.workingSandboxes.
   *
   * When a sandbox is paired with a slice, execution is pending and sandbox.allocated=true and
   * sandbox.slice=slice and sandbox.jobAddress=slice.jobAddress. This is what 'allocated' means.
   * Immediately upon the exit of sandbox.work, sandbox.allocated=false is set and if an exception
   * wasn't thrown the sandbox is placed in this.assignedSandboxes.
   * Thus from the pov of supervisor, this.allocatedSandboxes is deterministic and this.workingSandboxes is not.
   * Please try to not use this.workingSandboxes. It is deprecated.
   *
   * Warning: Do not rely on this information being 100% accurate -- it may change in the next instant.
   * @type {Sandbox[]}
   */
  get allocatedSandboxes() {
    return this.sandboxes.filter(sandbox => sandbox.allocated);
  }

  /**
   * Slices that are allocated.
   * Warning: Do not rely on this information being 100% accurate -- it may change in the next instant.
   * @type {Slice[]}
   */
  get allocatedSlices() {
    return this.slices.filter(slice => slice.allocated);
  }

  /**
   * This property is used as the target number of sandboxes to be associated with slices and start working.
   *
   * It is used in this.watchdog as to prevent a call to this.work when unallocatedSpace <= 0.
   * It is also used in this.distributeQueuedSlices where it is passed as an argument to this.matchSlicesWithSandboxes to indicate how many sandboxes
   * to associate with slices and start working.
   *
   * Warning: Do not rely on this information being 100% accurate -- it may change in the next instant.
   * @type {number}
   */
  get unallocatedSpace() {
    return this.maxSandboxes - this.allocatedSandboxes.length - this.numberOfCoresReserved;
  }
  
  /**
   *  Call acquire(numberOfCoresToReserve) to reserve numberOfCoresToReserve unallocated sandboxes as measured by unallocatedSpace.
   *  Call release() to undo the previous acquire.
   *  This pseudo-mutex technique helps prevent races in scheduling slices in Supervisor.
   * @param {number} numberOfCoresToReserve
   */
  acquire(numberOfCoresToReserve) { 
    this.numberOfCoresReserved = numberOfCoresToReserve; 
  }
  release() { 
    this.numberOfCoresReserved = 0; 
  }

  /**
   * Remove from this.slices.
   * @param {Slice} slice
   */
  removeSlice(slice) {
    this.removeElement(this.slices, slice);
    if (this.debugBuild) {
      if (this.queuedSlices.indexOf(slice) !== -1)
        throw new Error(`removeSlice: slice ${slice.identifier} is in queuedSlices; inconsistent state.`);
      if (this.lostSlices.length > 0) {
        debugging() && console.warn(`removeSlice: slice ${slice.identifier}, found lostSlices ${this.lostSlices.map(s => s.identifier)}`);
        if (this.lostSlices.indexOf(slice) !== -1)
          throw new Error(`removeSlice: slice ${slice.identifier} is in lostSlices; inconsistent state.`);
      }
    }
  }

  /**
   * Remove from this.slices.
   * @param {Slice[]} slices
   */
  removeSlices(slices) {
    this.slices = this.slices.filter(slice => slices.indexOf(slice) === -1);
  }

  /**
   * Remove from this.queuedSlices.
   * @param {Slice[]} slices
   */
  removeQueuedSlices(slices) {
    this.queuedSlices = this.queuedSlices.filter(slice => slices.indexOf(slice) === -1);
  }

  /**
   * Remove all terminated sandboxes.
   */
  removeTerminatedSanboxes () {
    this.sandboxes = this.sandboxes.filter((sbx) => !sbx.isTerminated);
    this.assignedSandboxes = this.assignedSandboxes.filter((sbx) => !sbx.isTerminated);
    this.readiedSandboxes = this.readiedSandboxes.filter((sbx) => !sbx.isTerminated);
  }

  /**
   * Remove from this.sandboxes, this.assignedSandboxes and this.readiedSandboxes.
   * @param {Sandbox} sandbox
   */
  removeSandbox(sandbox) {
    debugging('scheduler') && console.log(`removeSandbox ${sandbox.identifier}`);
    this.removeElement(this.sandboxes, sandbox);
    this.removeElement(this.assignedSandboxes, sandbox);
    this.removeElement(this.readiedSandboxes, sandbox);
  }

  /**
   * Remove from this.sandboxes and this.assignedSandboxes .
   * @param {Sandbox[]} sandboxes
   */
  async removeSandboxes(sandboxes) {
    debugging('scheduler') && console.log(`removeSandboxes: Remove ${sandboxes.length} sandboxes ${this.dumpSandboxes(sandboxes)}`);
    this.sandboxes = this.sandboxes.filter(sandbox => sandboxes.indexOf(sandbox) === -1);
    this.assignedSandboxes = this.assignedSandboxes.filter(sandbox => sandboxes.indexOf(sandbox) === -1);

    if (this.debugBuild) {
      const readied = this.readiedSandboxes.filter(sandbox => sandboxes.indexOf(sandbox) !== -1);
      if (readied.length > 0)
        throw new Error(`removeSandboxes: sandboxes ${readied.map(s => s.identifier)} are in readiedSandboxes; inconsistent state.`);
    }
  }

  /**
   * Remove element from theArray.
   * @param {Array<*>} theArray
   * @param {object|number} element
   */
  removeElement(theArray, element) {
    let index = theArray.indexOf(element);
    if (index !== -1) theArray.splice(index, 1);
  }

  /**
   * Log sliceArray.
   * @param {Slice[]} sliceArray
   * @param {string}  [header]
   * @returns {string}
   */
  dumpSlices(sliceArray, header) {
    if (header) console.log(`\n${header}`);
    return compressSlices(sliceArray, this.addressTruncationLength);
  }

  /**
   * Log sandboxArray.
   * @param {Sandbox[]} sandboxArray
   * @param {string}    [header]
   * @returns {string}
   */
  dumpSandboxes(sandboxArray, header) {
    if (header) console.log(`\n${header}`);
    return compressSandboxes(sandboxArray, this.addressTruncationLength);
  }

  /**
   * If the elements of sandboxSliceArray are not unique, log the duplicates and dump the array.
   * @param {SandboxSlice[]} sandboxSliceArray
   * @param {string} header
   */
  dumpSandboxSlicesIfNotUnique(sandboxSliceArray, header) {
    if (!this.isUniqueSandboxSlices(sandboxSliceArray, header))
      console.log(this.dumpSandboxSlices(sandboxSliceArray));
  }

  /**
   * Log { sandbox, slice }.
   * @param {Sandbox} sandbox
   * @param {Slice}   slice
   * @returns {string}
   */
  dumpSandboxAndSlice(sandbox, slice) {
    return `${sandbox.id}~${slice.sliceNumber}.${this.dumpJobAddress(slice.jobAddress)}`;
  }

  /**
   * Log { sandbox, slice } with state/status.
   * @param {Sandbox} sandbox
   * @param {Slice}   slice
   * @returns {string}
   */
  dumpStatefulSandboxAndSlice(sandbox, slice) {
    return `${sandbox.id}.${sandbox.state}~${slice.sliceNumber}.${this.dumpJobAddress(slice.jobAddress)}.${slice.status}`;
  }

  /**
   * Truncates jobAddress.toString() to this.addressTruncationLength digits.
   * @param {string} jobAddress
   * @returns {string}
   */
  dumpJobAddress(jobAddress) {
    return truncateAddress(jobAddress, this.addressTruncationLength /* digits*/);
  }

  /**
   * Dump sandboxSliceArray.
   * @param {SandboxSlice[]} sandboxSliceArray - input array of { sandbox, slice }
   * @param {string}         [header]          - optional header
   * @param {boolean}        [stateFul]        - when true, also includes slice.status and sandbox.state.
   * @returns {string}
   */
  dumpSandboxSlices(sandboxSliceArray, header, stateFul=false) {
    if (header) console.log(`\n${header}`);
    const jobMap = {};
    sandboxSliceArray.forEach(ss => {
      const sss = stateFul ? `${ss.sandbox.id}.${ss.sandbox.state}~${ss.slice.sliceNumber}.${ss.slice.status}` : `${ss.sandbox.id}~${ss.slice.sliceNumber}`;
      if (!jobMap[ss.slice.jobAddress]) jobMap[ss.slice.jobAddress] = sss;
      else jobMap[ss.slice.jobAddress] += `,${sss}`;
    });
    let output = '';
    for (const [jobAddress, sss] of Object.entries(jobMap))
      output += `${this.dumpJobAddress(jobAddress)}:[${sss}]:`;
    return output;
  }

  /**
   * Check sandboxSliceArray for duplicates.
   * @param {SandboxSlice[]} sandboxSliceArray
   * @param {string}         [header]
   * @param {function}       [log]
   * @returns {boolean}
   */
  isUniqueSandboxSlices(sandboxSliceArray, header, log) {
    const result = [], slices = [], sandboxes = [];
    let once = true;
    sandboxSliceArray.forEach(x => {
      const sliceIndex = slices.indexOf(x.slice);
      const sandboxIndex = sandboxes.indexOf(x.sandbox);

      if (sandboxIndex >= 0) {
        if (once && header) console.log(`\n${header}`); once = false;
        log ? log(x.sandbox) : console.log(`\tWarning: Found duplicate sandbox ${x.sandbox.identifier}.`);
      } else sandboxes.push(x.sandbox);

      if (sliceIndex >= 0) {
        if (once && header) console.log(`\n${header}`); once = false;
        log ? log(x.slice) : console.log(`\tWarning: Found duplicate slice ${x.slice.identifier}.`);
      } else {
        slices.push(x.slice);
        if (sandboxIndex < 0) result.push(x);
      }
    });
    return sandboxSliceArray.length === result.length;
  }

  /**
   * Attempts to create and start a given number of sandboxes.
   * The sandboxes that are created can then be assigned for a
   * specific job at a later time. All created sandboxes
   * get put into the readiedSandboxes array when allocateLocalSandboxes is false.
   *
   * @param {number}  numSandboxes                   - the number of sandboxes to create
   * @param {boolean} [allocateLocalSandboxes=false] - when true, do not place in this.readiedSandboxes
   * @returns {Promise<Sandbox[]>}                   - resolves with array of created sandboxes, rejects otherwise
   * @throws when given a numSandboxes is not a number or if numSandboxes is Infinity
   */
  async readySandboxes (numSandboxes, allocateLocalSandboxes = false) {
    debugging('supervisor') && console.debug(`readySandboxes: Readying ${numSandboxes} sandboxes, total sandboxes ${this.sandboxes.length}, matching ${this.matching}, fetching ${this.isFetchingNewWork}`);
    
    if (typeof numSandboxes !== 'number' || Number.isNaN(numSandboxes) || numSandboxes === Infinity) {
      throw new Error(`${numSandboxes} is not a number of sandboxes that can be readied.`);
    }
    if (numSandboxes <= 0) {
      return [];
    }

    const sandboxStartPromises = [];
    const sandboxes = [];
    const errors = [];
    for (let i = 0; i < numSandboxes; i++) {
      const sandbox = new Sandbox(this, {
        ...this.options.sandboxOptions,
      });
    
      sandbox.addListener('start', () => {
        // When sliceNumber == 0, result-submitter status skips the slice,
        // so don't send it in the first place.
        // The 'start' event is fired when a worker starts up, hence there's no way
        // to determine whether sandbox has a valid slice without checking.
        if (sandbox.slice) {
          const jobAddress = sandbox.jobAddress;
          const sliceNumber = sandbox.slice.sliceNumber;
          // !authorizationMessage <==> sliceNumber === 0.
          const authorizationMessage = sandbox.slice.getAuthorizationMessage();

          if (authorizationMessage) {
            let statusPayload = {
              worker: this.workerOpaqueId,
              slices: [{
                job: jobAddress,
                sliceNumber: sliceNumber,
                status: 'begin',
                authorizationMessage,
              }],
            }
            
            try /* resultSubmitterConnection can be null if worker is stopped */
            {
              this.resultSubmitterConnection.request('status', statusPayload).catch((error) => {
                debugging('supervisor') && console.error(`Error sending 'status' for slice ${sliceNumber} of job ${jobAddress}:\nWill try again on a new connection\nError:`, error);
                this.resultSubmitterMessageQueue.push({ operation: 'status', data: statusPayload });
                this.resultSubmitterConnection?.close();
              });
            } catch (error)
            {
              debugging('supervisor') && console.error(`Failed to send 'status' for slice ${sliceNumber} of job ${jobAddress}:, no connection to result submitter:`, error);
            }
          }
        }
      });
      sandbox.addListener('workEmit', ({ eventName, payload }) => {
        // Need to check if the sandbox hasn't been assigned a slice yet.
        if (!sandbox.slice) {
          if (this.debugBuild) {
            console.error(
              `Sandbox not assigned a slice before sending workEmit message to scheduler. 'workEmit' event originates from "${eventName}" event`, 
              payload,
            );
          }
        }
        else
        {
          const jobAddress = sandbox.slice.jobAddress;
          const sliceNumber = sandbox.slice.sliceNumber;
          // sliceNumber can be zero if it came from a problem with loading modules.
          assert(jobAddress && (sliceNumber || sliceNumber === 0));
          // Send a work emit message from the sandbox to the event router
          // !authorizationMessage <==> sliceNumber === 0.
          let authorizationMessage;
          try {
            // Sometimes a sliceNumber===0 workEmit comes in before the client bundle is properly loaded.
            // Also happens with minor dcp-client version mismatches.
            authorizationMessage = sandbox.slice.getAuthorizationMessage();
          } catch(e) {
            authorizationMessage = null;
          }

          if (!authorizationMessage)
          {
            this.worker.emit('warning', `workEmit: missing authorization message for job ${jobAddress}, slice: ${sliceNumber}`);
            return Promise.resolve();
          }
          
          let workEmitPayload = {
            eventName,
            payload,
            job: jobAddress,
            slice: sliceNumber,
            worker: this.workerOpaqueId,
            authorizationMessage,
          }

          const workEmitPromise = this.eventRouterConnection.request('workEmit', workEmitPayload).catch(error => {
            debugging('supervisor') && console.warn(`workEmit: unable to send ${eventName} for slice ${sliceNumber} of job ${jobAddress}: ${error.message}.\nTrying again on a new connection.`, error);
            this.eventRouterMessageQueue.push({ operation: 'workEmit', data: workEmitPayload })
            this.eventRouterConnection?.close();
          });

          if (this.debugBuild) {
            workEmitPromise.then(result => {
              if (!result || !result.success)
                this.worker.emit('warning', `workEmit: event router did not accept event: ${result}`);
            });
          }
        }
      });

      // When any sbx completes, 
      sandbox.addListener('complete', () => {
        this.watchdog();
      });

      sandbox.on('sandboxError', (error) => handleSandboxError(this, sandbox, error));
      
      sandbox.on('rejectedWorkMetrics', (data) =>{
        function updateRejectedMetrics(report) {
          ['total', 'CPU', 'webGL', 'webGPU'].forEach((key) => {
            if (report[key]) sandbox.slice.rejectedTimeReport[key] += report[key];
          })
        }
        
        // If the slice already has rejected metrics, add this data to it. If not, assign this data to slices rejected metrics property
        if (sandbox.slice && data.timeReport) {
          (sandbox.slice.rejectedTimeReport) ? updateRejectedMetrics(data.timeReport) : sandbox.slice.rejectedTimeReport = data.timeReport;
        }
      })
      
      // If the sandbox terminated and we are not shutting down, then should return all work which is currently
      // not being computed if all sandboxes are dead and the attempt to create a new one fails.
      sandbox.sandboxHandle.on('end', async () => {
        if (this.sandboxes.length > 0 && this.enterSandboxHandleEndHandler) {
          try
          {
            let terminatedSandboxes = this.sandboxes.filter(sbx => sbx.isTerminated);
            if (terminatedSandboxes.length === this.sandboxes.length) {
              debugging() && console.debug(`readySandboxes: Create 1 sandbox in the sandbox-terminated-handler, total sandboxes ${this.sandboxes.length}, matching ${this.matching}, fetching ${this.isFetchingNewWork}`);
              try {
                await this.readySandboxes(1);
              } catch (e) {
                // If we cannot create a new sandbox, that probably means we're on a screensaver worker
                // and the screensaver is down. So return the slices to the scheduler.
                debugging() && console.debug('Terminated handler: Evaluator is down');
                this.removeTerminatedSanboxes();
                const sliceToReturn = this.slices.filter((slice) => !slice.completed);
                this.returnSlices(sliceToReturn).then(() => {
                  this.slices.length = 0;
                });
              }
            }
          }
          finally
          {
            // Do not enter is-screen-saver-down logic in the sandbox handle 'end' event handler.
            this.enterSandboxHandleEndHandler = false;
          }
        }
      });

      const delayMs =
        1000 *
        (this.tuning.minSandboxStartDelay +
          Math.random() *
            (this.tuning.maxSandboxStartDelay - this.tuning.minSandboxStartDelay));
    
      sandboxStartPromises.push(
        sandbox
          .start(delayMs)
          .then(() => {
            this.worker.emit('sandbox', sandbox.sandboxHandle);
            if (!allocateLocalSandboxes) this.readiedSandboxes.push(sandbox);
            this.sandboxes.push(sandbox);
            sandboxes.push(sandbox);
          }).catch((err) => {
            errors.push(err);
            this.returnSandbox(sandbox);
            if (err.code === 'ENOWORKER') {
              throw new DCPError("Cannot use localExec without dcp-worker installed. Use the command 'npm install dcp-worker' to install the neccessary modules.", 'ENOWORKER');
            }
          }));
    }
    
    await Promise.all(sandboxStartPromises);

    if (errors.length) {
      debugging() && console.warn(`Failed to ready ${errors.length} of ${numSandboxes} sandboxes.`, errors);
      errors.forEach((e) => { this.worker.emit('error', e); });
      throw new Error('Failed to ready sandboxes.');
    }

    debugging('supervisor') && console.log(`readySandboxes: Readied ${sandboxes.length} sandboxes ${JSON.stringify(sandboxes.map(sandbox => sandbox.id))}`);
    
    return sandboxes;
  }

  /**
   * Accepts a sandbox after it has finished working or encounters an error.
   * If the sandbox was terminated or if "!slice || slice.failed" then
   * the sandbox will be removed from the sandboxes array and terminated if necessary.
   * Otherwise it will try to distribute a slice to the sandbox immediately.
   *
   * @param {Sandbox} sandbox                             - the sandbox to return
   * @param {Slice}   [slice]                             - the slice just worked on; !slice => terminate
   */
  returnSandbox (sandbox, slice) {
    if (!slice || slice.failed || sandbox.isTerminated) {
      
      this.removeSandbox(sandbox);
      
      if (!sandbox.isTerminated) {
        debugging('supervisor') && console.log(`Supervisor.returnSandbox: Terminating ${sandbox.identifier}~${slice ? slice.identifier : '<null>'}, # of sandboxes ${this.sandboxes.length}`);
        sandbox.terminate(false);
      } else {
        debugging() && console.log(`Supervisor.returnSandbox: Already terminated ${sandbox.identifier}~${slice ? slice.identifier : '<null>'}, # of sandboxes ${this.sandboxes.length}`);
      }
    }
  }

  /**
   * Terminates sandboxes, in order of creation, when the total started sandboxes exceeds the total allowed sandboxes.
   *
   * @returns {Promise<void>}
   */
  pruneSandboxes () {
    let numOver = this.sandboxes.length - this.maxSandboxes;
    if (numOver <= 0) return;

    // Don't kill readied sandboxes while creating readied sandboxes.
    for (let index = 0; index < this.readiedSandboxes.length; ) {
      const sandbox = this.readiedSandboxes[index];
      // If the sandbox is allocated, advance to the next one in the list.
      if (sandbox.allocated) {
        index++;
        continue;
      }
      // Otherwise, remove this sandbox but look at the same array index in the next loop.
      debugging('supervisor') && console.log(`pruneSandboxes: Terminating readied sandbox ${sandbox.identifier}`);
      this.readiedSandboxes.splice(index, 1);
      this.returnSandbox(sandbox);

      if (--numOver <= 0) break;
    }

    if (numOver <= 0) return;
    for (let index = 0; index < this.assignedSandboxes.length; ) {
      const sandbox = this.assignedSandboxes[index];
      // If the sandbox is allocated, advance to the next one in the list.
      if (sandbox.allocated) {
        index++;
        continue;
      }
      // Otherwise, remove this sandbox but look at the same array index in the next loop.
      debugging('supervisor') && console.log(`pruneSandboxes: Terminating assigned sandbox ${sandbox.identifier}`);
      this.assignedSandboxes.splice(index, 1);
      this.returnSandbox(sandbox);

      if (--numOver <= 0) break;
    }
  }
  
  /**
   * Basic watch dog to check if there are idle sandboxes and
   * attempts to nudge the supervisor to feed them work.
   *
   * Run in an interval created in the constructor .
   * @returns {Promise<void>}
   */
  async watchdog () {
    if (!this.watchdogState)
      this.watchdogState = {};

    // Every 5 minutes, report progress of all working slices to the scheduler
    if (Date.now() > ( (this.lastProgressReport || 0) + (dcpConfig.supervisor?.sandbox?.progressReportIntervalMs || 20 * 60 * 1000) )) {
      // console.log('454: Assembling progress update...');
      this.lastProgressReport = Date.now();

      //
      // Note: this.slices is the disjoint union of:
      //    this.allocatedSlices, 
      //    this.queuedSlices, 
      //    this.slices.filter(slice => !slice.isUnassigned) .
      // When a slice is not in these 3 arrays, the slice is lost.
      //
      
      const currentLostSlices = this.slices.filter(slice => slice.isUnassigned 
                                                         && this.queuedSlices.indexOf(slice) === -1
                                                         && this.allocatedSlices.indexOf(slice) === -1);

      if (currentLostSlices.length > 0) {
        this.lostSlices.push(...currentLostSlices);
        // Try to recover.
        // Needs more work and testing.
        // Test when we can come up with a decent lost slice repro case.
        // --> this.queuedSlices.push(...currentLostSlices);
      }

      if (this.lostSlices.length > 0) {
        if (debugging()) {
          console.warn('Supervisor.watchdog: Found lost slices!');
          for (const slice of this.lostSlices)
            console.warn('\t', slice.identifier);
        }
        this.lostSlices = this.lostSlices.filter(slice => slice.isUnassigned);
      }

      const slices = [];
      this.queuedSlices.forEach(slice => {
        assert(slice && slice.sliceNumber > 0);
        addToSlicePayload(slices, slice, sliceStatus.scheduled);
      });

      this.allocatedSlices.forEach(slice => {
        assert(slice && slice.sliceNumber > 0);
        addToSlicePayload(slices, slice, 'progress'); // Beacon.
      });

      if (slices.length) {
        // console.log('471: sending progress update...');
        const progressReportPayload = {
          worker: this.workerOpaqueId,
          slices,
        };

        this.resultSubmitterConnection.request('status', progressReportPayload)
        .catch(error => {
          debugging('supervisor') && console.error('479: Failed to send status update:', error/*.message*/);
          this.resultSubmitterMessageQueue.push({ operation: 'status', data: progressReportPayload })
          this.resultSubmitterConnection?.close();
        });
      }
    }

    if (this.worker.working) {
      if (this.unallocatedSpace > 0) {
        await this.work().catch(err => {
          if (!this.watchdogState[err.code || '0'])
            this.watchdogState[err.code || '0'] = 0;
          if (Date.now() - this.watchdogState[err.code || '0'] > ((this.tuning.watchdogLogInterval * timeDilation || 120) * 1000))
            this.worker.emit('error', `301: Failed to start work: ${err.message}`);
          this.watchdogState[err.code || '0'] = Date.now();
        });
      }

      this.pruneSandboxes();
    }
  }

  /**
   *  Gets the logical and physical number of cores and also
   *  the total number of sandboxes the worker is allowed to run
   *
   */
  getStatisticsCPU() {
    const pCores = dcpConfig.supervisor?.pCores;
    if (DCP_ENV.isBrowserPlatform) {
      return {
        worker: this.workerOpaqueId,
        lCores: pCores || window.navigator.hardwareConcurrency,
        pCores: pCores || window.navigator.hardwareConcurrency,
        sandbox: this.maxSandboxes
      }
    }

    return {
      worker: this.workerOpaqueId,
      lCores: pCores || requireNative('os').cpus().length,
      pCores: pCores || requireNative('physical-cpu-count'),
      sandbox: this.maxSandboxes
    }
  }

  static getLogicalCores () {
    if (DCP_ENV.isBrowserPlatform)
      return window.navigator.hardwareConcurrency;
    return requireNative('os').cpus().length;
  }

  /**
   * Returns the number of unallocated sandbox slots to send to fetchTask.
   *
   * @returns {number}
   */
  numberOfAvailableSandboxSlots() {
    let numCores;
    if (this.queuedSlices.length > 1) {
      // We have slices queued, no need to fetch
      numCores = 0;
    } else {
      // The queue is almost empty (there may be 0 or 1 element), fetch a full task.
      // The task is full, in the sense that it will contain slices whose
      // aggregate execution time is this.maxSandboxes * 5-minutes.
      // However, there can only be this.unallocatedSpace # of long slices.
      // Thus we need to know whether the last slice in this.queuedSlices is long or not.
      // (A long slice has estimated execution time >= 5-minutes.)
      const longSliceCount = (this.queuedSlices.length > 0 && this.queuedSlices[0].isLongSlice) ? 1 : 0;
      numCores = this.unallocatedSpace - longSliceCount;
    }
    return numCores;
  }

  /**
   * Retry wrapper around readySandboxes.
   * @param {number}  count
   * @param {boolean} [allocateLocalSandboxes=false] - When true does not populate this.readiedSandboxes .
   */
  async createSandboxes (count, allocateLocalSandboxes = false) {
   /**
    * If the evaluator cannot start (ie. if the evalServer is not running),
    * then the while loop will keep retrying until the evalServer comes online.
    */
    let sandboxes, retry = 0;
    while (true) {
      try {
        debugging() && console.debug(`Supervisor.createSandboxes(${allocateLocalSandboxes}): ready ${count} sandbox(es), unallocatedSpace ${this.unallocatedSpace}, queued slices ${this.queuedSlices.length}, # of sandboxes ${this.sandboxes.length}`);
        sandboxes = await this.readySandboxes(1, allocateLocalSandboxes);
        count--;
        const sbxes = await this.readySandboxes(count, allocateLocalSandboxes);
        sandboxes.push(...sbxes);
        debugging('supervisor') && console.debug(`Supervisor.createSandboxes(${allocateLocalSandboxes}): success`, sandboxes.length);
        break;
      } catch (error) {
        debugging() && console.warn(`906: failed to ready sandboxes(${allocateLocalSandboxes}); will retry`, this.sandboxes.length, error.code, error.message);
        // The evaluator may be down or shutting down, keep retrying.
        if ((retry % 60) === 0)
          this.worker.emit('warning', error);
        await a$sleepMs(1000 * Math.min(5, ++retry));
      }
    }
    debugging() && console.debug(`createSandboxes(${allocateLocalSandboxes}): created ${sandboxes.length} sandboxes`);
    return sandboxes;
  }

  /**
   * Call to start doing work on the network.
   * This is the one place where requests to fetch new slices are made.
   * After the initial slices are fetched it calls this.distributeQueuedSlices.
   *
   * @returns {Promise<void>}, unallocatedSpace ${this.unallocatedSpace}
   */
  async work ()
  {
    // When inside matchSlicesWithSandboxes, don't reenter Supervisor.work to fetch new work or create new sandboxes.
    if (this.matching) {
      // Interesting and noisy.
      // debugging('supervisor') && console.log(`Supervisor.work: Do not interleave work, fetch or matching slices with sandboxes: queuedSlices ${this.queuedSlices.length}, unallocatedSpace ${this.unallocatedSpace}, matching ${this.matching}, fetching ${this.isFetchingNewWork}`);
      return Promise.resolve();
    }

    // Instantiate connections that don't exist.
    this.instantiateAllConnections();

    const numCores = this.numberOfAvailableSandboxSlots();

    debugging() && console.log(`Supervisor.work: Try to get ${numCores} slices in working sandboxes, unallocatedSpace ${this.unallocatedSpace}, queued slices ${this.queuedSlices.length}, # of sandboxes ${this.sandboxes.length}, matching ${this.matching}, fetching: ${this.isFetchingNewWork}`);
    
    // Fetch a new task if we have no more slices queued, then start workers
    try {
      if (numCores > 0 && !this.isFetchingNewWork) {
        this.isFetchingNewWork = true;

        /**
         * This will only ready sandboxes up to a total count of
         * maxSandboxes (in any state). It is not possible to know the
         * actual number of sandboxes required until we have the slices because we
         * may have sandboxes assigned for the slice's job already.
         *
         * If the evaluator cannot start (ie. if the evalServer is not running),
         * then the while loop will keep retrying until the evalServer comes online.
         */
        if (this.maxSandboxes > this.sandboxes.length) {
          await this.createSandboxes(this.maxSandboxes - this.sandboxes.length);
        }
        /**
         * Temporary change: Assign the capabilities of one of readied sandboxes
         * before fetching slices from the scheduler.
         *
         * TODO: Remove this once fetchTask uses the capabilities of every
         * sandbox to fetch slices.
         */
        if (!this.capabilities)
          this.capabilities = this.sandboxes[0].capabilities;

        if (DCP_ENV.isBrowserPlatform && this.capabilities.browser)
          this.capabilities.browser.chrome = DCP_ENV.isBrowserChrome;

        const fetchTimeout = dcp_timers.setTimeout(() => {
          this.worker.emit('warning', 'Fetch exceeded timeout, will reconnect at next watchdog interval');
          
          this.taskDistributorConnection?.close().catch(error => {
            this.worker.emit('error', `Failed to close task-distributor connection ${error.message}`);
          });
          this.resultSubmitterConnection?.close().catch(error => {
            this.worker.emit('error', `Failed to close result-submitter connection ${error.message}`);
          });
          this.isFetchingNewWork = false;
          this.instantiateAllConnections();
        }, 3 * 60 * 1000);  // max out at 3 minutes to fetch

        // ensure result submitter and task distributor connections before fetching tasks
        try
        {
          await this.resultSubmitterConnection.keepalive();
          await this.taskDistributorConnection.keepalive();
        }
        catch (e)
        {
          this.worker.emit('error', `Failed to connect to result submitter, refusing to fetch slices. Will try again at next fetch cycle ${e.message}`);
          debugging('supervisor') && console.log(`Error: ${e}`);

          this.isFetchingNewWork = false;
          dcp_timers.clearTimeout(fetchTimeout);
          this.taskDistributorConnection?.close().catch(error => {
            this.worker.emit('error', `Failed to close task-distributor connection ${error.message}`);
          });
          this.resultSubmitterConnection?.close().catch(error => {
            this.worker.emit('error', `Failed to close result-submitter connection ${error.message}`);
          });

          return Promise.resolve();
        }
        await this.fetchTask(numCores).finally(() => {
          dcp_timers.clearTimeout(fetchTimeout);
          this.isFetchingNewWork = false;
        });
      }

      this.distributeQueuedSlices().then(() => debugging('supervisor') && 'supervisor: finished distributeQueuedSlices()').catch((e) => {
        // We should never get here, because distributeQueuedSlices was changed
        // to try to catch everything and return slices and sandboxes.
        // If we do catch here it may mean a slice was lost. 
        debugging() && console.error('Supervisor.work catch handler for distributeQueuedSlices.', e);
        this.worker.emit('error', e);
      });
      // No catch(), because it will bubble outward to the caller
    } finally {
    }
  }

  /**
   * Generate the workerComputeGroups property of the requestTask message. 
   * 
   * Concatenate the compute groups object from dcpConfig with the list of compute groups
   * from the supervisor, and remove the public group if accidentally present. Finally,
   * we transform joinSecrets/joinHash into joinHashHash for secure transmission.
   *
   * @note computeGroup objects with joinSecrets are mutated to record their hashes. This
   *       affects the supervisor options and dcpConfig. Re-adding a joinSecret property
   *       to one of these will cause the hash to be recomputed.
   */
  generateWorkerComputeGroups()
  {
    return supShared.generateWorkerComputeGroups(this, this.taskDistributorConnection);
  }

  /**
   * Remove all unreferenced jobs in `this.cache`.
   *
   * @param {Object<string, object>} newJobs - Jobs that should not be removed from `this.cache`.
   */
  cleanJobCache(newJobs) {
    /* Delete all jobs in the supervisorCache that are not represented in this newJobs,
     * or in this.queuedSlices, or there is no sandbox assigned to these jobs.
     * Note: There can easily be 200+ places to check; using a lookup structure to maintain O(n).
     */
    if (this.cache.jobs.length > 0) {
      const jobAddressMap = {};
      Object.keys(newJobs).forEach(jobAddress => { jobAddressMap[jobAddress] = 1; });
      this.slices.forEach(slice => { if (!jobAddressMap[slice.jobAddress]) jobAddressMap[slice.jobAddress] = 1; });
      this.cache.jobs.forEach(jobAddress => {
        if (!jobAddressMap[jobAddress]) {
          this.cache.remove('job', jobAddress);
          this.jobHandles[jobAddress].emit('flush');
          // Remove and return the corresponding sandboxes from this.sandboxes.
          const deadSandboxes = this.sandboxes.filter(sb => sb.jobAddress === jobAddress);
          if (deadSandboxes.length > 0) {
            deadSandboxes.forEach(sandbox => { this.returnSandbox(sandbox); });
            debugging('supervisor') && console.log(`Supervisor.fetchTask: Deleting job ${jobAddress} from cache and assigned sandboxes ${deadSandboxes.map(s => s.id)}, # of sandboxes ${this.sandboxes.length}.`);
          }
        }
      });
    }
  }

  /**
   * Fetches a task, which contains job information and slices for sandboxes and
   * manages events related to fetching tasks so the UI can more clearly display
   * to user what is actually happening.
   * @param {number} [numCores]
   * @returns {Promise<void>} The requestTask request, resolve on success, rejects otherwise.
   * @emits Supervisor#beforeFetch
   * @emits Supervisor#fetch
   */
  async fetchTask(numCores)  {
    // Don't reenter
    if (this.matching || numCores <= 0) {
      // Interesting and noisy.
      debugging('supervisor') && console.log(`Supervisor.fetchTask: Do not nest work, fetch or matching slices with sandboxes: queuedSlices ${this.queuedSlices.length}, unallocatedSpace ${this.unallocatedSpace}, matching ${this.matching}, fetching ${this.isFetchingNewWork}, numCores ${numCores}`);
      return;
    }

    //
    // Oversubscription mitigation.
    // Update when there are less available sandbox slots than numCores.
    const checkNumCores = this.numberOfAvailableSandboxSlots();
    if (!numCores || numCores > checkNumCores) numCores = checkNumCores;

    if (!(this.options.paymentAddress instanceof Address))
      throw new Error(`options.paymentAddress ${JSON.stringify(this.options.paymentAddress)} must be an instance of Address`);

    const fetchStartTime = Date.now();
    // The 'beforeFetch' event allows the user to cancel the requestTask request.
    let canceled = false;
    /**
     * The 'beforeFetch' event fires before the request is sent to requestTask in task distributor.
     * @link https://gitlab.com/Distributed-Compute-Protocol/dcp-docs-wes/-/blob/wip/worker/worker-events.md
     * @event Supervisor#beforeFetch
     */
    this.worker.emit('beforeFetch', () => { canceled = true; })
    debugging() && canceled && console.log('User canceled the fetch task.');
    if (canceled)
      return;

    debugging('supervisor') && console.debug('supervisor: fetching task', numCores);
    const requestPayload = {
      supervisor: this.version,
      numCores,
      coreStats: this.getStatisticsCPU(),
      numGPUs: this.defaultMaxGPUs,
      capabilities: this.capabilities,
      paymentAddress: this.options.paymentAddress,
      jobAddresses: this.options.jobAddresses || [], // force array; when set, only fetches slices for these jobs
      workerComputeGroups: this.generateWorkerComputeGroups(),
      minimumWage: this.options.minimumWage || { CPU: 0, GPU: 0, in: 0, out: 0 },
      readyJobs: [ /* list of jobs addresses XXXwg */ ],
      previouslyWorkedJobs: this.ringBufferOfJobs.buf, //Only discrete jobs
      rejectedJobs: this.rejectedJobs,
    };
    // workers should be part of the public compute group by default
    if (!booley(this.options.leavePublicGroup))
      requestPayload.workerComputeGroups.push(constants.computeGroups.public);
    debugging('computeGroups') && console.log(`Fetching work for ${requestPayload.workerComputeGroups.length} ComputeGroups: `, requestPayload.workerComputeGroups);
    debugging('supervisor') && console.log(`fetchTask wants ${numCores} slice(s), unallocatedSpace ${this.unallocatedSpace}, queuedSlices ${this.queuedSlices.length}`);
    try {
      debugging('requestTask') && console.debug('fetchTask: requestPayload', requestPayload);

      let result = await this.taskDistributorConnection.request('requestTask', requestPayload).catch((error) => {
        debugging('supervisor') && console.error(`Unable to request task from scheduler. Will try again on a new connection. Error:`, error);
        this.taskDistributorConnection?.close();
        throw error; /* caught below */
      });
      /** @type {TDPayload} */
      const responsePayload = result.payload;

      if (!result.success) {
        debugging() && console.log('Task fetch failure; request=', requestPayload);
        debugging() && console.log('Task fetch failure; response=', responsePayload);
        throw new DCPError('Unable to fetch task for worker', responsePayload);
      }
      
      if (!responsePayload.body?.task?.length) {
        /**
         * The 'fetch' event fires when the supervisor has found no work from the task distributor.
         * @link https://gitlab.com/Distributed-Compute-Protocol/dcp-docs-wes/-/blob/wip/worker/worker-events.md
         * @event Supervisor#fetch
         */
        this.worker.emit('fetch', {
          fetchStart: fetchStartTime,
          fetchEnd: Date.now(),
          fetchSize: 0, 
          jobs: {},
          slices: {}
        })
        return;
      }

      /*
       * payload:   { TDPayload }
       * TDPayload: { owner: Address, signature: Signature, auth: Auth, body: Body };
       * Auth:      { workerId: string, authSlices: Object<string, number[]>, schedulerId: { address: Address }, jobCommissions: Object<string, { rate: number, account: number }> }
       * Body:      { newJobs: Object<string, object>, task: SliceMessage[], computeGroupJobs: Object<string, string[]>, computeGroupOrigins: Object<string, Object<string, string[]>>, schedulerConfig: {{ shared: *, targetTaskDuration: number }} }
       *
       * NOTE: authorizationMessage has type AuthMessage
       */

      const { body,  ...authorizationMessage } = responsePayload;
      let { newJobs, task } = body;
      assert(newJobs); // It should not be possible to have !newJobs -- we throw on !success.
      
      /*
       * If we have specified specific jobs the worker may work on, the received jobs must be in the specified job list
       * Otherwise panic since the scheduler cannot be trusted at that point.
       */
      if (this.options.jobAddresses?.length > 0 && !Object.keys(newJobs).every((ele) => this.options.jobAddresses.includes(ele)))
      {
        this.worker.emit('error', "Worker received slices it shouldn't have. Rejecting the work and stopping.");
        process.exit(1);
      }

      debugging() && console.log(`Supervisor.fetchTask: task: ${task.length}/${numCores}, jobs: ${Object.keys(newJobs).length}, authSlices: ${compressJobMap(authorizationMessage.auth.authSlices, this.addressTruncationLength /* digits*/)}`);
      // Delete all jobs in the supervisorCache that are not represented in this task,
      // or in this.queuedSlices, or there is no sandbox assigned to these jobs.
      this.cleanJobCache(newJobs);

      for (const jobAddress of Object.keys(newJobs))
      {
        const jobHandle = new EventEmitter({ captureRejections: false });
        Object.assign(jobHandle, {
          address: newJobs[jobAddress].address,
          name: newJobs[jobAddress].public.name,
          description: newJobs[jobAddress].public.description,
          link: newJobs[jobAddress].public.link,
        });

        this.jobHandles[jobAddress] = jobHandle;
        this.worker.emit('job', jobHandle);
        
        if (!this.cache.cache.job[jobAddress])
          this.cache.store('job', jobAddress, newJobs[jobAddress]);
      }

      // Memoize authMessage onto the Slice object, this should
      // follow it for its entire life in the worker.
      const tmpQueuedSlices = task.map(taskElement => new Slice(taskElement, authorizationMessage));

      // Make sure old stuff is up front.
      // matchSlicesWithSandboxes dequeues this.queuedSlices as follows:
      //    slicesToMatch = this.queuedSlices.slice(0, numCores);
      this.slices.push(...tmpQueuedSlices);
      this.queuedSlices.push(...tmpQueuedSlices);
  
      // Populating the ring buffer based on job's discrete property 
      Object.values(newJobs).forEach(job => {
        if(job.requirements.discrete && this.ringBufferOfJobs.find(element => element === job.address) === undefined) {
          this.ringBufferOfJobs.push(job.address);
        }
      });

      // Construct the fetchHandle for 'fetch' event.
      const jobs = {}, slices = {};
      for (const jobAddress in newJobs)
      {
        jobs[jobAddress] = this.jobHandles[jobAddress]
        slices[jobAddress] = authorizationMessage.auth.authSlices[jobAddress].length;
      }
      const fetchHandle = {
        fetchStart: fetchStartTime,
        fetchEnd: Date.now(),
        fetchSize: 0, // need change to protocol branch to efficiently implement
        jobs,
        slices,
      };
      /**
       * The 'fetch' event fires when the supervisor has found work from the task distributor.
       * @link https://gitlab.com/Distributed-Compute-Protocol/dcp-docs-wes/-/blob/wip/worker/worker-events.md
       * @event Supervisor#fetch
       */
      this.worker.emit('fetch', fetchHandle);
      const fetchHandle2 = {
        fetchStart: fetchStartTime,
        fetchEnd: Date.now(),
        fetchSize: 0, // need change to protocol branch to efficiently implement
        jobs: {...authorizationMessage.auth.authSlices},
      };
      this.worker.emit('fetch2', fetchHandle2);

    } catch (error) {
      this.worker.emit('fetch', error);
      debugging('supervisor') && console.debug('Supervisor.fetchTask failed!: error:', error);
    }
  }

  /**
   * For each slice in this.queuedSlices, match with a sandbox in the following order:
   *  1. Try to find an already assigned sandbox in this.assignedSandboxes for the slice's job.
   *  2. Find a ready sandbox in this.readiedSandboxes that is unassigned.
   *  3. Ready a new sandbox and use that.
   *
   * Take great care in assuring sandboxes and slices are uniquely associated, viz.,
   *  a given slice cannot be associated with multiple sandboxes and a given sandbox cannot be associated with multiple slices.
   *  The lack of such uniqueness has been the root cause of several difficult bugs.
   *
   * Note: When a sandbox is paired with a slice, execution is pending and sandbox.allocated=true and
   * sandbox.slice=slice and sandbox.jobAddress=slice.jobAddress. This is what 'allocated' means.
   * Immediately upon the exit of sandbox.work, sandbox.allocated=false is set and if an exception
   * wasn't thrown, the paired slice is placed in this.assignedSandboxes.
   * Thus from the pov of supervisor, this.allocatedSandboxes is deterministic and this.workingSandboxes is not.
   * Please try to not use this.workingSandboxes. It is deprecated.
   *
   * The input is numCores, this,queuedSlices, this.assignedSandboxes and this.readiedSandboxes.
   * If there are not enough sandboxes, new readied sandboxes will be created using
   *     await this.readySandboxes(...)
   * And it is this await boundary that has caused many bugs.
   * We try not to make assumptions about non-local state across the await boundary.
   *
   * @param {number}  numCores               - The number of available sandbox slots.
   * @param {boolean} [throwExceptions=true] - Whether to throw exceptions when checking for sanity.
   * @returns {Promise<SandboxSlice[]>}   Returns SandboxSlice[], may have length zero.
   */
  async matchSlicesWithSandboxes (numCores, throwExceptions = true) {

    const sandboxSlices = [];
    if (this.queuedSlices.length === 0 || this.matching || numCores <= 0) {
      // Interesting and noisy.
      // debugging('supervisor') && console.log(`Supervisor.matchSlicesWithSandboxes: Do not nest work, fetch or matching slices with sandboxes: queuedSlices ${this.queuedSlices.length}, unallocatedSpace ${this.unallocatedSpace}, matching ${this.matching}, fetching ${this.isFetchingNewWork}, numCores ${numCores}`);
      return sandboxSlices;
    }

    //
    // Oversubscription mitigation.
    // Update when there are less available sandbox slots than numCores.
    // We cannot use this.unallocatedSpace here because its value is artificially low or zero, because in
    // this.distributedQueuedSlices we use the pseudo-mutex trick: this.acquire(howManySandboxSlotsToReserve)/this.release().
    // Note: Do not use this.numberOfCoresReserved outside of a function locked with this.acquire(howManySandboxSlotsToReserve) .
    const checkNumCores = this.numberOfCoresReserved; // # of locked sandbox slots.
    if (numCores > checkNumCores) numCores = checkNumCores;
    if (numCores <= 0) return sandboxSlices;

    // Don't ask for more than we have.
    if (numCores > this.queuedSlices.length)
      numCores = this.queuedSlices.length;

    // When evaluator goes down, all sandboxes are terminated.
    this.removeTerminatedSanboxes();

    debugging('supervisor') && console.log(`matchSlicesWithSandboxes: numCores ${numCores}, queued slices ${this.queuedSlices.length}: assigned ${this.assignedSandboxes.length}, readied ${this.readiedSandboxes.length}, unallocated ${this.unallocatedSpace}, # of sandboxes: ${this.sandboxes.length}`);

    if (debugging('supervisor')) {
      dumpSlicesIfNotUnique(this.queuedSlices, 'Warning: this.queuedSlices slices are not unique -- this is ok when slice is rescheduled.');
      dumpSandboxesIfNotUnique(this.readiedSandboxes, 'Warning: this.readiedSandboxes sandboxes are not unique!');
      dumpSandboxesIfNotUnique(this.assignedSandboxes, 'Warning: this.assignedSandboxes sandboxes are not unique!');
    }

    // Three functions to validate slice and sandbox.
    function checkSlice(slice, checkAllocated=true) {
      if (!slice.isUnassigned) throw new DCPError(`Slice must be unassigned: ${slice.identifier}`);
      if (checkAllocated && slice.allocated) throw new DCPError(`Slice must not already be allocated: ${slice.identifier}`);
    }
    function checkSandbox(sandbox, isAssigned) {
      if (sandbox.allocated) throw new DCPError(`Assigned sandbox must not be already allocated: ${sandbox.identifier}`);
      if (isAssigned && !sandbox.isAssigned) throw new DCPError(`Assigned sandbox is not marked as assigned: ${sandbox.identifier}`);
      if (!isAssigned && !sandbox.isReadyForAssign) throw new DCPError(`Readied sandbox is not marked as ready for assign: ${sandbox.identifier}`);
    }

    // Sanity checks.
    if (throwExceptions) {
      this.assignedSandboxes.forEach(sandbox => { checkSandbox(sandbox, true /* isAssigned*/); });
      this.readiedSandboxes.forEach(sandbox => { checkSandbox(sandbox, false /* isAssigned*/); });
      this.queuedSlices.forEach(slice => { checkSlice(slice); });
    } else {
      this.assignedSandboxes = this.assignedSandboxes.filter(sandbox => !sandbox.allocated && sandbox.isAssigned);
      this.readiedSandboxes = this.readiedSandboxes.filter(sandbox => !sandbox.allocated && sandbox.isReadyForAssign);
      this.queuedSlices = this.queuedSlices.filter(slice => !slice.allocated && slice.isUnassigned);
    }

    const sandboxKind = {
      assigned: 0,
      ready:    1,
      new:      2,
    };

    const ceci = this;
    /**
     * Auxiliary function to pair a sandbox with a slice and mark the sandbox as allocated.
     * An allocated sandbox is reserved and will not be released until the slice completes execution on the sandbox.
     *
     * @param {Sandbox} sandbox
     * @param {Slice}   slice
     * @param {number}  kind
     */
    function pair(sandbox, slice, kind) {
      checkSandbox(sandbox, kind === sandboxKind.assigned);
      checkSlice(slice, kind === sandboxKind.assigned);
      slice.allocated = true;
      sandbox.allocated = true;
      sandbox.jobAddress = slice.jobAddress; // So we can know which jobs to not delete from this.cache .
      sandbox.slice = slice;

      sandboxSlices.push({ sandbox, slice });
      if (ceci.sliceTiming) slice['pairingDelta'] = Date.now();
      if (debugging('supervisor')) {
        let fragment = 'New readied';
        if (kind === sandboxKind.assigned) fragment = 'Assigned';
        else if (kind === sandboxKind.ready) fragment = 'Readied';
        console.log(`matchSlicesWithSandboxes.pair: ${fragment} sandbox matched ${ceci.dumpSandboxAndSlice(sandbox, slice)}`);
      }
    }

    // These three arrays are used to track/store slices and sandboxes,
    // so that when an exception occurs, the following arrays are restored:
    // this.queuedSlices, this.assignedSandboxes, this.realizedSandboxes.
    let slicesToMatch = [];
    let trackAssignedSandboxes = [];
    let trackReadiedSandboxes = [];
    try
    {
      this.matching = true;

      let assignedCounter = 0; // How many assigned sandboxes are being used.
      let readyCounter = 0;    // How many sandboxes used from the existing this.readiedSandboxes.
      let newCounter = 0;      // How many sandboxes that needed to be newly created.

      //
      // The Ideas:
      //   1) We match each slice with a sandbox. First we match with assigned sandboxes in the order
      //      that they appear in this.queuedSlices. Then we match in-order with existing this.readiedSandboxes
      //      Then we match in-order with new new readied sandboxes created through
      //          await this.readySandboxes(newCounter, true /* allocateLocalSandboxes*/);
      //      This allows us to try different orderings of execution of slices.  E.g. Wes suggested
      //      trying to execute slices from different jobs with maximal job diversity -- specifically
      //      if there are 3 jobs j1,j2,j3, with slices s11, s12 from j1, s21, s22, s23 from j2 and
      //      s31, s32 from j3, then we try to schedule, in order s11, s21, s31, s12, s22, s32, s23.
      //
      //   2) Before matching slices with sandboxes, we allocate available assigned and readied sandboxes
      //   and if more are needed then we create and allocate new ones.
      //
      //   3) Finally we match slices with sandboxes and return an array of sandboxSlice pairs.
      //
      //   Note: The ordering of sandboxSlices only partially corresponds to the order of this.queuedSlices.
      //   It's easy to do. When pairing with assigned sandboxes, any slice in this.queuedSlices which doesn't
      //   have an assigned sandbox, will add null to the sandboxSlices array. Then when pairing with readied sandboxes,
      //   we fill-in the null entries in the sandboxSlices array.
      //

      // Get the slices that are being matched.
      slicesToMatch = this.queuedSlices.slice(0, numCores);
      this.queuedSlices = this.queuedSlices.slice(numCores);

      debugging('supervisor') && console.log(`matchSlicesWithSandboxes: slicesToMatch ${this.dumpSlices(slicesToMatch)}`);

      // Create object map: jobAddress -> sandboxes with sandboxes.jobAddress === jobAddress .
      const jobSandboxMap = toJobMap(this.assignedSandboxes, sandbox => sandbox);
      
      // Create array to hold slices which do not have assigned sandboxes.
      // These slices will need to be paired with existing and possibly new readied sandboxes.
      // Specifically, the sandboxes from existing this.readiedSandboxes and new sandboxes
      // created through await this.readySandboxes(newCounter, true /* allocateLocalSandboxes*/);
      const slicesThatNeedSandboxes = [];

      // Pair assigned sandboxes with slices.
      for (const slice of slicesToMatch) {
        const assigned = jobSandboxMap[slice.jobAddress];
        if (assigned && assigned.length > 0) {
          // Pair.
          const sandbox = assigned.pop();
          pair(sandbox, slice, sandboxKind.assigned);
          this.removeElement(this.assignedSandboxes, sandbox);
          // Track.
          trackAssignedSandboxes.push(sandbox);
          assignedCounter++;
        } else {
          // Don't lose track of these slices.
          slice.allocated = true;
          slicesThatNeedSandboxes.push(slice);
        }
      }

      // Pair readied sandboxes with slices.
      readyCounter = Math.min(slicesThatNeedSandboxes.length, this.readiedSandboxes.length);
      newCounter = slicesThatNeedSandboxes.length - readyCounter;
      // Track.
      trackReadiedSandboxes = this.readiedSandboxes.slice(0, readyCounter);
      this.readiedSandboxes = this.readiedSandboxes.slice(readyCounter);
      for (const sandbox of trackReadiedSandboxes) {
        // Pair.
        const slice = slicesThatNeedSandboxes.pop();
        pair(sandbox, slice, sandboxKind.ready);
      }
      debugging('supervisor') && console.log(`matchSlicesWithSandboxes: assignedCounter ${assignedCounter}, readyCounter ${readyCounter}, newCounter ${newCounter}, numCores ${numCores}`)

      // Validate algorithm consistency.
      if (this.debugBuild && assignedCounter + readyCounter + newCounter !== numCores) {
        // Structured assert.
        throw new DCPError(`matchSlicesWithSandboxes: Algorithm is corrupt ${assignedCounter} + ${readyCounter} + ${newCounter} !== ${numCores}`);
      }

      // Here is an await boundary.
      // Accessing non-local data across an await boundary may result in the unexpected.

      // Create new readied sandboxes to associate with slicesThatNeedSandboxes.
      if (newCounter > 0) {
        // When allocateLocalSandboxes is true, this.readySandboxes does not place the new sandboxes
        // on this.readiedSandboxes. Hence the new sandboxes are private and nobody else can see them.
        debugging('supervisor') && console.log(`matchSlicesWithSandboxes: creating ${newCounter} new sandboxes, # of sandboxes ${this.sandboxes.length}`);
        const readied = await this.createSandboxes(newCounter, true /* allocateLocalSandboxes*/);
        // Track.
        trackReadiedSandboxes.push(...readied);

        for (const sandbox of readied) {
          assert(slicesThatNeedSandboxes.length > 0);
          // Pair
          const slice = slicesThatNeedSandboxes.pop();
          pair(sandbox, slice, sandboxKind.new);
        }
        
        // Put back any extras. There should not be any unless readySandboxes returned less than asked for.
        if (slicesThatNeedSandboxes.length > 0) {
          slicesThatNeedSandboxes.forEach(slice => {
            slice.allocated = false;
            this.queuedSlices.push(slice);
          });
        }
      }

      if (debugging()) {
        console.log(`matchSlicesWithSandboxes: Matches: ${ this.dumpSandboxSlices(sandboxSlices) }`);
        this.dumpSandboxSlicesIfNotUnique(sandboxSlices, 'Warning: sandboxSlices; { sandbox, slice } pairs are not unique!');
      }
    } catch (e) {
      // Clear allocations.
      slicesToMatch.forEach(slice => { slice.allocated = false; });
      trackAssignedSandboxes.forEach(sandbox => { sandbox.allocated = false; sandbox.slice = null; });
      trackReadiedSandboxes.forEach(sandbox => { sandbox.allocated = false; sandbox.slice = null; sandbox.jobAddress = null; });
      
      // Filter out redundancies -- there shouldn't be any...
      slicesToMatch = slicesToMatch.filter(slice => this.queuedSlices.indexOf(slice) === -1);
      trackAssignedSandboxes = trackAssignedSandboxes.filter(sb => this.assignedSandboxes.indexOf(sb) === -1);
      trackReadiedSandboxes = trackReadiedSandboxes.filter(sb => this.readiedSandboxes.indexOf(sb) === -1);

      // Sanity checks.
      slicesToMatch.forEach(slice => { checkSlice(slice) });
      trackAssignedSandboxes.forEach(sandbox => { checkSandbox(sandbox, true /* isAssigned*/); });
      trackReadiedSandboxes.forEach(sandbox => { checkSandbox(sandbox, false /* isAssigned*/); });

      // Restore arrays.
      this.queuedSlices.push(...slicesToMatch);
      this.assignedSandboxes.push(...trackAssignedSandboxes);
      this.readiedSandboxes.push(...trackReadiedSandboxes);
      
      debugging() && console.error('Error in matchSlicesWithSandboxes: Attempting to recover slices and sandboxes.', e);
      return [];
    } finally {
      this.matching = false;
    }

    debugging('supervisor') && console.log(`matchSlicesWithSandboxes: allocated ${sandboxSlices.length} sandboxes, queuedSlices ${this.queuedSlices.length}, unallocatedSpace ${this.unallocatedSpace}, matching ${this.matching}, fetching ${this.isFetchingNewWork}, # of sandboxes: ${this.sandboxes.length}.`);

    return sandboxSlices;
  }

  disassociateSandboxAndSlice(sandbox, slice) {
    this.returnSandbox(sandbox);
    sandbox.slice = null;
    this.returnSlice(slice, 'none');
  }

  /**
   * This method will call this.startSandboxWork(sandbox, slice) for each element { sandbox, slice }
   * of the array returned by this.matchSlicesWithSandboxes(availableSandboxes) until all allocated sandboxes
   * are working. It is possible for a sandbox to interleave with calling distributeQueuedSlices and leave a sandbox
   * that is not working. Moreover, this.queuedSlices may be exhausted before all sandboxes are working.
   * @returns {Promise<void>}
   */
  async distributeQueuedSlices () {
    const numCores = this.unallocatedSpace;

    // If there's nothing there, or we're reentering, bail out.
    if (this.queuedSlices.length === 0 || numCores <= 0 || this.matching) {
      // Interesting and noisy.
      // debugging('supervisor') && console.log(`Supervisor.distributeQueuedSlices: Do not nest work, fetch or matching slices with sandboxes: queuedSlices ${this.queuedSlices.length}, matching ${this.matching}, fetching ${this.isFetchingNewWork}, numCores ${numCores}`);
      return Promise.resolve();
    }

    //
    // Use the pseudo-mutex to prevent uncontrolled interleaving with fetchTask,
    //  matchSlicesWithSandboxes and distributeQueuedSlices
    let sandboxSlices;
    this.acquire(numCores);
    try {
      sandboxSlices = await this.matchSlicesWithSandboxes(numCores);
    } finally {
      this.release();
    }

    debugging('supervisor') && console.log(`distributeQueuedSlices: ${sandboxSlices.length} sandboxSlices ${this.dumpSandboxSlices(sandboxSlices)}, matching ${this.matching}, fetching ${this.isFetchingNewWork}`);

    for (let sandboxSlice of sandboxSlices) {

      const { sandbox, slice } = sandboxSlice;
      try {
        if (sandbox.isReadyForAssign) {
          try {
            let timeoutMs = Math.floor(Math.min(+this.lastAssignFailTimerMs || 0, 10 * 60 * 1000 /* 10m */));
            await a$sleepMs(timeoutMs);
            await this.assignJobToSandbox(sandbox, slice.jobAddress);
          } catch (e) {
            debugging() && console.error(`Supervisor.distributeQueuedSlices: Could not assign slice ${slice.identifier} to sandbox ${sandbox.identifier}.`, e);
            this.worker.emit('error', e);
            this.lastAssignFailTimerMs = this.lastAssignFailTimerMs ? +this.lastAssignFailTimerMs * 1.25 : Math.random() * 200;
            this.disassociateSandboxAndSlice(sandbox, slice);
            continue;
          }
        }

        if (!this.lastAssignFailTimerMs)
          this.lastAssignFailTimerMs = Math.random() * 200;
        this.startSandboxWork(sandbox, slice);
        this.lastAssignFailTimerMs = false;

      } catch (e) {
        // We should never get here.
        debugging() && console.error(`Supervisor.distributeQueuedSlices: Failed to execute slice ${slice.identifier} in sandbox ${sandbox.identifier}.`, e);
        this.worker.emit('error', e);
        this.disassociateSandboxAndSlice(sandbox, slice);
      }
    }
  }

  /**
   *
   * @param {Sandbox} sandbox
   * @param {opaqueId} jobAddress
   * @returns {Promise<void>}
   */
  assignJobToSandbox(sandbox, jobAddress) {
    // Any error will be caught in distributeQueuedSlices.
    return sandbox.assign(jobAddress);
  }

  /**
   * Handles reassigning or returning a slice that was rejected by a sandbox.
   * 
   * The sandbox will be terminated by this.returnSandbox in finalizeSandboxAndSlice. In this case,
   * if the slice does not have a rejected property already, reassign the slice to a new sandbox
   * and add a rejected property to the slice to indicate it has already rejected once, then set slice = null
   * in the return SandboxSlice so that finalizeSandboxAndSlice won't return slice to scheduler.
   * 
   * If the slice rejects with a reason, or has a rejected time stamp (ie. has been rejected once already)
   * then return the slice and all slices from the job to the scheduler and
   * terminate all sandboxes with that jobAddress.
   * @param {Sandbox} sandbox 
   * @param {Slice}   slice
   * @param {Error}   error
   * @returns {Promise<SandboxSlice>}
   */
  async handleWorkReject(sandbox, slice, error) {
    if (!this.rejectedJobReasons[slice.jobAddress])
      this.rejectedJobReasons[slice.jobAddress] = [];

    this.rejectedJobReasons[slice.jobAddress].push(error.message); // memoize reasons

    debugging() && console.debug('handleWorkReject', error.message, slice.rejected, this.rejectedJobReasons, slice.identifier);

    // First time rejecting without a reason. Try assigning slice to a new sandbox.
    if (error.message === 'false' && !slice.rejected) {
      // Set rejected.
      slice.rejected = Date.now();
      // Schedule the slice for execution.
      this.scheduleSlice(slice, true /* placeInTheFrontOfTheQueue*/, false /* noDuplicateExecution*/);
      
      // Null out slice so this.returnSlice will not be called in finalizeSandboxAndSlice.
      // But we still want this.returnSandbox to terminate the sandbox.
      slice = null;
    } else { // Slice has a reason OR rejected without a reason already and got stamped.
      
      // Purge all slices and sandboxes associated with slice.jobAddress .
      this.purgeAllWork(slice.jobAddress);
      // Clear jobAddress from this.cache .
      this.cleanJobCache({});

      // Add to array of rejected jobs.
      let rejectedJob = {
        address: slice.jobAddress,
        reasons: this.rejectedJobReasons[slice.jobAddress],
      }
      this.rejectedJobs.push(rejectedJob);
      // Broadcast failure.
      this.worker.emit('result', error, slice.jobAddress, slice.sliceNumber);
      this.jobHandles[slice.jobAddress].emit('result', error, slice.sliceNumber);

      if (slice.rejected)
        this.worker.emit('warning', `Supervisor.handleWorkReject: The slice ${slice.identifier} was rejected twice.`);
      else
        this.worker.emit('warning', `Supervisor.handleWorkReject: The slice ${slice.identifier} was rejected with reason ${error.message}.`);
      this.worker.emit('warning', '    All slices with the same jobAddress returned to the scheduler.');
      this.worker.emit('warning', '    All sandboxes with the same jobAddress are terminated.');
      //
      // this.purgeAllWork(jobAddress) terminates all sandboxes with jobAddress,
      // and it also returns to scheduler all slices with jobAddress.
      // Therefore null out slice and sandbox so finalizeSandboxAndSlice doesn't do anything.
      // 
      sandbox = null;
      slice = null;
    }
    return { sandbox, slice };
  }

  /**
   * Schedule the slice to be executed.
   * If slice is already executing and noDuplicateExecution is true, return the slice with reason.
   * @param {Slice}   slice
   * @param {boolean} [placeInTheFrontOfTheQueue=false]
   * @param {boolean} [noDuplicateExecution=true]
   * @param {string}  [reason]
   */
  scheduleSlice(slice, placeInTheFrontOfTheQueue = false, noDuplicateExecution = true, reason) {
    // When noDuplicateExecution, if slice is already executing, do nothing.
    let allocatedSlices = [];
    if (noDuplicateExecution)
      allocatedSlices = this.allocatedSlices;

    if (!allocatedSlices.indexOf(slice)) {
      // Reset slice state to allow execution.
      slice.status = SLICE_STATUS_UNASSIGNED;
      slice.allocated = false;
      // Enqueue in the to-be-executed queue.
      if (placeInTheFrontOfTheQueue) this.queuedSlices.unshift(slice);
      else this.queuedSlices.push(slice);
    }
  }

  /**
   * Purge all slices and sandboxes with this jobAddress.
   * @param {string} jobAddress
   * @param {boolean} [onlyPurgeQueuedAndAllocated=false]
   */
  purgeAllWork(jobAddress, onlyPurgeQueuedAndAllocated = false) {
    // Purge all slices and sandboxes associated with jobAddress .
    const deadSandboxes = this.sandboxes.filter(sandbox => sandbox.jobAddress === jobAddress);

    if (deadSandboxes.length > 0) {
      debugging('supervisor') && console.log(`purgeAllWork(${this.dumpJobAddress(jobAddress)}): sandboxes purged ${deadSandboxes.map(s => s.id)}, # of sandboxes ${this.sandboxes.length}`);
      deadSandboxes.forEach(sandbox => this.returnSandbox(sandbox));
    }

    let deadSlices;
    if (onlyPurgeQueuedAndAllocated) {
      deadSlices = this.queuedSlices.filter(slice => slice.jobAddress === jobAddress);
      if (deadSlices.length > 0 || this.allocatedSlices.length > 0)
        debugging('supervisor') && console.log(`purgeAllWork(${this.dumpJobAddress(jobAddress)}): dead queuedSlices ${deadSlices.map(s => s.sliceNumber)}, dead allocatedSlices ${this.allocatedSlices.map(s => s.sliceNumber)}`);
      deadSlices.push(...this.allocatedSlices);
    } else {
      deadSlices = this.slices.filter(slice => slice.jobAddress === jobAddress);
    }

    if (deadSlices.length > 0) {
      debugging('supervisor') && console.log(`purgeAllWork(${this.dumpJobAddress(jobAddress)}): slices purged ${deadSlices.map(s => s.sliceNumber)}, # of sandboxes ${this.sandboxes.length}`);
      this.returnSlices(deadSlices);
      this.removeQueuedSlices(deadSlices);
    }
    debugging('supervisor') && console.log(`purgeAllWork(${this.dumpJobAddress(jobAddress)}): Finished: slices ${this.slices.length}, queuedSlices ${this.queuedSlices.length}, assigned ${this.assignedSandboxes.length}, readied ${this.readiedSandboxes.length}, # of sandboxes ${this.sandboxes.length}`);
  }

  /**
   * Gives a slice to a sandbox which begins working. Handles collecting
   * the slice result (complete/fail) from the sandbox and submitting the result to the scheduler.
   * It will also return the sandbox to @this.returnSandbox when completed so the sandbox can be re-assigned.
   *
   * @param {Sandbox} sandbox - the sandbox to give the slice
   * @param {Slice} slice - the slice to distribute
   * @returns {Promise<void>} Promise returned from sandbox.run
   */
  async startSandboxWork (sandbox, slice) {
    var startDelayMs, reason = 'unknown';

    try {
      slice.markAsWorking();
    } catch (e) {
      // This will occur when the same slice is distributed twice.
      // It is normal because two sandboxes could finish at the same time and be assigned the
      // same slice before the slice is marked as working.
      debugging() && console.debug('startSandboxWork: slice.markAsWorking exception:', e);
      return Promise.resolve();
    }

    // sandbox.requiresGPU = slice.requiresGPU;
    // if (sandbox.requiresGPU) {
    //   this.GPUsAssigned++;
    // }

    if (this.startSandboxWork_beenCalled)
      startDelayMs = 1000 * (this.tuning.minSandboxStartDelay + (Math.random() * (this.tuning.maxSandboxStartDelay - this.tuning.minSandboxStartDelay)));
    else {
      startDelayMs = 1000 * this.tuning.minSandboxStartDelay;
      this.startSandboxWork_beenCalled = true;
    }

    try {
      debugging() && console.log(`startSandboxWork: Started ${this.dumpStatefulSandboxAndSlice(sandbox, slice)}, sandboxes: ${this.sandboxes.length}, allocated slices ${this.allocatedSlices.length}, matching ${this.matching}, fetching ${this.isFetchingNewWork}`, Date.now() - this._t0);
      if (this.sliceTiming) {
        slice['pairingDelta'] = Date.now() - slice['pairingDelta'];
        slice['executionDelta'] = Date.now();
      }
      let result;
      try {
        result = await sandbox.work(slice, startDelayMs);
      } finally {
        sandbox.allocated = false;
        slice.allocated = false;
      }
      if (this.sliceTiming) {
        slice['executionDelta'] = Date.now() - slice['executionDelta'];
        slice['resultDelta'] = Date.now();
      }
      slice.collectResult(result, true);
      // In watchdog, all sandboxes in working state, have their slice status sent to result submitter.
      // However, this can happen after the sandbox/slice has already sent results
      // to result submitter, in which case, the activeSlices table has already removed the row
      // corresponding to slice and hence is incapable of updating status.
      sandbox.changeWorkingToAssigned();
      this.assignedSandboxes.push(sandbox);
      debugging() && console.log(`startSandboxWork: Finished ${this.dumpStatefulSandboxAndSlice(sandbox, slice)}, sandboxes: ${this.sandboxes.length}, allocated slices ${this.allocatedSlices.length}, matching ${this.matching}, fetching ${this.isFetchingNewWork}`);
    } catch(error) {
      let logLevel;

      if (error instanceof SandboxError) {
        logLevel = 'warn';
        // The message and stack properties of error objects are not enumerable,
        // so they have to be copied into a plain object this way
        const errorResult = Object.getOwnPropertyNames(error).reduce((o, p) => {
          o[p] = error[p]; return o;
        }, { message: 'Unexpected worker error' });
        slice.collectResult(errorResult, false);
      } else {
        logLevel = 'error';
        // This error was unrelated to the work being done, so just return the slice in the finally block.
        // For extra safety the sandbox is terminated.
        slice.result = null;
        slice.status = SLICE_STATUS_FAILED;
      }

      let errorString;
      switch (error.errorCode) {
        case 'ENOPROGRESS':
          reason = 'ENOPROGRESS';
          errorString = 'Supervisor.startSandboxWork - No progress error in sandbox.\n';
          break;
        case 'ESLICETOOSLOW':
          reason = 'ESLICETOOSLOW';
          errorString = 'Supervisor.startSandboxWork - Slice too slow error in sandbox.\n';
          break;
        case 'EUNCAUGHT':
          reason = 'EUNCAUGHT';
          errorString = `Supervisor.startSandboxWork - Uncaught error in sandbox ${error.message}.\n`;
          break;
        case 'EFETCH':
          // reason = 'EFETCH'; The status.js processing cannot handle 'EFETCH'
          reason = 'unknown';
          errorString = `Supervisor.startSandboxWork - Could not fetch data: ${error.message}.\n`;
          break;
      }
      
      const { getenv } = require('../../common/dcp-env');
      // Always display max info under debug builds, otherwise maximal error
      // messages are displayed to the worker, only if both worker and client agree.
      let workerConsole = sandbox.supervisorCache.cache.job[slice.jobAddress].workerConsole;
      const displayMaxInfo = Boolean(getenv('DCP_SUPERVISOR_DEBUG_DISPLAY_MAX_INFO')) || (workerConsole && this.options.allowConsoleAccess);

      const errorObject = {
        jobAddress:  slice.jobAddress.substr(0,10),
        sliceNumber: slice.sliceNumber,
        sandbox:     sandbox.id,
        jobName:     sandbox.public ? sandbox.public.name : 'unnamed',
      };
      
      if (error.name === 'EWORKREJECT') {
        error.stack = 'Sandbox was terminated by work.reject()';
        const ss = await this.handleWorkReject(sandbox, slice, error);
        sandbox = ss.sandbox; slice = ss.slice;
      }

      if (!displayMaxInfo && error.errorCode === 'EUNCAUGHTERROR') {
        this.worker.emit('error', `Supervisor.startSandboxWork - Uncaught error in sandbox, could not compute ${errorObject}`);
      } else if (!displayMaxInfo && error.errorCode === 'EPERM_ORIGIN') {
        this.worker.emit('error', `Supervisor.startSandboxWork - Could not fetch data: ${error.message}`);
      } else if (!displayMaxInfo && errorString) {
        this.worker.emit('error', `${errorString}: ${errorObject}`);
      } else if (!displayMaxInfo && error.name === 'EWORKREJECT') {
        this.worker.emit('error', `Supervisor.startSandboxWork - Sandbox rejected work: ${error.message}`);
      } else {
        if (displayMaxInfo && error.stack)
          errorObject.stack += '\n    --------------------\n' + (error.stack.split('\n').slice(1).join('\n'));
        this.worker.emit('error', `Supervisor.startSandboxWork - Sandbox failed: ${error.message}: ${errorObject}`);
      }
    } finally {
      await this.finalizeSandboxAndSlice(sandbox, slice, reason);
    }
  }

  /**
   * If slice && slice.result, then call await this.recordResult(slice) and this.returnSandbox(sandbox, slice) will have no effect.
   * If slice && !slice.result, then call this.returnSlice(slice, reason) and then this.returnSandbox(sandbox, slice) which terminates sandbox.
   * If !slice && sandbox, then terminate the sandbox with this.returnSandbox(sandbox, slice) .
   * If !slice && !sandbox, then do nothing.
   * @param {Sandbox} [sandbox]
   * @param {Slice}   [slice]
   * @param {string}  [reason]
   */
  async finalizeSandboxAndSlice(sandbox, slice, reason) {
    debugging('supervisor') && console.log(`finalizeSandboxAndSlice: sandbox ${sandbox ? sandbox.identifier : 'nade'}, slice ${slice ? slice.identifier : 'nade'}`);
    if (slice) {
      if (slice.result) await this.recordResult(slice, sandbox.sandboxHandle);
      else this.returnSlice(slice, reason);
    }
    // It is possible that sandbox is already terminated
    // Because sandbox.allocated=false as soon as sandbox.work(...) completes.
    // But the await at or in finalizeSandboxAndSlice may allow pruneSandboxes to slither in.
    if (sandbox) this.returnSandbox(sandbox, slice);
  }

  /**
   * Terminates sandboxes and returns slices.
   * Sets the working flag to false, call @this.work to start working again.
   * 
   * If forceTerminate is true: Terminates all sandboxes and returns all slices.
   * If forceTerminate is false: Terminates non-allocated sandboxes and returns queued slices.
   *
   * @param {boolean} [forceTerminate = true] - true if you want to stop the sandboxes from completing their current slice.
   * @returns {Promise<void>}
   */
  async stopWork (forceTerminate = true) {
    debugging('supervisor') && console.log('stopWork(${forceTerminate}): terminating sandboxes and returning slices to scheduler.');

    const jobs = [];
    for (const slice of this.slices)
      if (jobs.indexOf(slice.jobAddress) === -1)
        jobs.push(slice.jobAddress);
    
    if (forceTerminate) {
      while (this.sandboxes.length) {
        this.returnSandbox(this.sandboxes[0], null);
      }

      await this.returnSlices(this.slices).then(() => {
        this.queuedSlices.length = 0;
      });
    } else {
      // Only terminate idle sandboxes and return only queued slices
      let idleSandboxes = this.sandboxes.filter(w => !w.allocated);
      for (const sandbox of idleSandboxes) {
        this.returnSandbox(sandbox, null);
      }

      await this.returnSlices(this.queuedSlices).then(() => {
        this.queuedSlices.length = 0;
      });

      await new Promise((resolve, reject) => {
        let sandboxesRemaining = this.allocatedSandboxes.length;
        if (sandboxesRemaining === 0)
        {
          resolve();
        }
        // Resolve and finish work once all sandboxes have finished submitting their results.
        this.on('result', () => {
          sandboxesRemaining--;
          if (sandboxesRemaining === 0)
          {
            debugging() && console.log('All sandboxes empty, stopping worker and closing all connections');
            resolve();
          }
        });
      });
    }

    for (const jobAddress of jobs)
      this.jobHandles[jobAddress].emit('flush');

    if (this.resultSubmitterConnection) {
      this.resultSubmitterConnection.off('end', this.openResultSubmitterConn);
      this.resultSubmitterConnection.close();
      this.resultSubmitterConnection = null;
    }

    if (this.taskDistributorConnection) {
      this.taskDistributorConnection.off('end', this.openTaskDistributorConn);
      this.taskDistributorConnection.close();
      this.taskDistributorConnection = null;
    }

    if (this.packageManagerConnection) {
      this.packageManagerConnection.off('end', this.openPackageManagerConn);
      this.packageManagerConnection.close();
      this.packageManagerConnection = null;
    }

    if (this.eventRouterConnection) {
      this.eventRouterConnection.off('end', this.openEventRouterConn);
      this.eventRouterConnection.close();
      this.eventRouterConnection = null;
    }
  }

  /**
   * Takes a slice and returns it to the scheduler to be redistributed.
   * Usually called when an exception is thrown by sandbox.work(slice, startDelayMs) .
   * Or when the supervisor tells it to forcibly stop working.
   *
   * @param {Slice}  slice    - The slice to return to the scheduler.
   * @param {string} [reason] - Optional reason for the return: 'ENOPROGRESS', 'EUNCAUGHT', 'ESLICETOOSLOW', 'unknown'.
   * @returns {Promise<*>}    - Response from the scheduler.
   */
  returnSlice (slice, reason) {
    // When sliceNumber === 0 don't send a status message.
    if (slice.sliceNumber === 0) return Promise.resolve();
    
    debugging() && console.log(`Supervisor.returnSlice: Returning slice ${slice.identifier} with reason ${reason}.`);

    this.jobHandles[slice.jobAddress].emit('beforeReturn', slice.sliceNumber);

    const payload = slice.getReturnMessagePayload(this.workerOpaqueId, reason);
    try
    {
      return this.resultSubmitterConnection.request('status', payload) /* resultSubmitterConnection can be null if worker is stopped */
        .then(response => {
          this.jobHandles[slice.jobAddress].emit('return', slice.sliceNumber);
          return response;
        }).catch(error => {
          this.jobHandles[slice.jobAddress].emit('return', error, slice.sliceNumber);
          debugging('supervisor') && console.error('Failed to return slice', {
            sliceNumber: slice.sliceNumber,
            jobAddress: slice.jobAddress,
            status: slice.status,
            error,
          }, 'Will try again on a new connection.');
          this.resultSubmitterMessageQueue.push({ operation: 'status', data: payload });
          this.resultSubmitterConnection?.close();
        });
    }
    catch (error)
    {
      debugging('supervisor') && console.error(`Failed to return slice ${slice.identifier}, no connection to result submitter:`, error);
    }
  }

  /**
   * Bulk-return multiple slices, possibly for assorted jobs.
   * Returns slices to the scheduler to be redistributed.
   * Called in the sandbox terminate handler and purgeAllWork(jobAddress)
   * and stopWork(forceTerminate).
   *
   * @param {Slice[]} slices  - The slices to return to the scheduler.
   * @returns {Promise<void>} - Response from the scheduler.
   */
  async returnSlices(slices) {
    if (!slices || !slices.length)  return Promise.resolve();
    
    const slicePayload = [];
    slices.forEach((slice) => {
      this.jobHandles[slice.jobAddress].emit('beforeReturn', slice.sliceNumber);
      addToReturnSlicePayload(slicePayload, slice);
    });
    this.removeSlices(slices);

    debugging('supervisor') && console.log(`Supervisor.returnSlices: Returning slices ${this.dumpSlices(slices)}.`);

    return this.resultSubmitterConnection.request('status', {
      worker: this.workerOpaqueId,
      slices: slicePayload,
    }).then(response => {
      slices.forEach((slice) => { this.jobHandles[slice.jobAddress].emit('return', slice.sliceNumber); });
      return response;
    }).catch(error => {
      slices.forEach((slice) => { this.jobHandles[slice.jobAddress].emit('return', error, slice.sliceNumber); });
      const errorInfo = slices.map(slice => slice.identifier);
      debugging('supervisor') && console.error('Failed to return slice(s)', { errorInfo, error }, 'Will try again on new connection.');
      // Skipping emitting 'return' event when re-sending returned slices for Sup1.
      // It's done right in Sup2.
      this.resultSubmitterMessageQueue.push({ operation: 'status', data: { worker: this.workerOpaqueId, slices: slicePayload } })
      this.resultSubmitterConnection?.close();
      // Just in case the caller is expecing a DCP response
      return { success: false, payload: {} };
    });
  }

  /**
   * Submits the slice results to the scheduler, either to the
   * work submit or fail endpoints based on the slice status.
   * Then remove the slice from the @this.slices cache.
   *
   * @param {Slice} slice - The slice to submit.
   * @param {EventEmitter} sandboxHandle - The sandbox handle associated to the slice.
   * @returns {Promise<void>}
   */
  async recordResult (slice, sandboxHandle) {
    // It is possible for slice.result to be undefined when there are upstream errors.
    if ( !(slice && slice.result))
      throw new Error(`recordResult: slice.result is undefined for slice ${slice.identifier}. This is ok when there are upstream errors.`);

    if (!(this.options.paymentAddress instanceof Address))
      throw new Error(`options.paymentAddress ${JSON.stringify(this.options.paymentAddress)} must be an instance of Address`);

    debugging('supervisor') && console.log(`supervisor: recording result for slice ${slice.identifier}.`);

    const jobAddress = slice.jobAddress;
    const sliceNumber = slice.sliceNumber;
    const authorizationMessage = slice.getAuthorizationMessage();

    /* @see result-submitter::result for full message details */
    const metrics = { GPUTime: 0, CPUTime: 0, CPUDensity: 0, GPUDensity: 0, InDataSize: 0, OutDataSize: 0 };
    const payloadData = {
      slice:          sliceNumber,
      job:            jobAddress,
      worker:         this.workerOpaqueId,
      paymentAddress: this.options.paymentAddress,
      metrics,
      authorizationMessage,
    }

    const timeReport = slice.timeReport;
    if (timeReport && timeReport.total > 0) {
      metrics.GPUTime = timeReport.webGL + timeReport.webGPU;
      metrics.CPUTime = timeReport.CPU;
      metrics.CPUDensity = metrics.CPUTime / timeReport.total;
      metrics.GPUDensity = metrics.GPUTime / timeReport.total;
      metrics.CPUTime = 1 + Math.floor(metrics.CPUTime);
      if (metrics.GPUTime > 0)
        metrics.GPUTime = 1 + Math.floor(metrics.GPUTime);

      // Create dummy properties to keep op-router happy.
      metrics.InDataSize = 0;
      metrics.OutDataSize = 0;

      const eventMeasurements = {
        elapsed:  timeReport.total / 1000,
        CPU:      timeReport.CPU / 1000,
        GPU:      metrics.GPUTime / 1000,
        in:       0,
        out:      0,
      };

      this.jobHandles[slice.jobAddress].emit('metrics', slice.sliceNumber, eventMeasurements);
      sandboxHandle.emit('metrics', slice.sliceNumber, eventMeasurements);
    }
    
    let canceled = false;
    const resultUrl = slice.resultStorageDetails?.length ? slice.resultStorageDetails : false;
    this.worker.emit('beforeResult', () => { canceled = true; }, resultUrl);
    this.jobHandles[slice.jobAddress].emit('beforeResult', () => { canceled = true; }, resultUrl);
    if (canceled) 
    {
      debugging('supervisor') && console.log(`Sup1: User canceled the result submission operation for slice ${slice.identifier}.`);
      this.removeSlice(slice);
      return this.returnSlice(slice, 'Canceled via beforeResult event');
    }
    
    if (!slice.isFinished)
      throw new Error('Cannot record result for slice that is not finished');

    if (slice.resultStorageType === 'pattern') /* This is a remote-storage slice. */
      payloadData.result = await this.sendResultToRemote(slice);
    else
      payloadData.result = encodeDataURI(slice.result.result);   /* XXXwg - result.result is awful */
    debugging('supervisor') && console.log('Supervisor.recordResult: payloadData.result', payloadData.result.slice(0, 512));

    try {
      if (slice.completed) {

        /* work function returned a result */
        let resp = await this.resultSubmitterConnection.request(
          'result',
          payloadData,
        )
              
        if (!resp.success) {
          if (resp.payload && resp.payload.code === 'DCPS-01002') { /* result submitter cannot connect to event router; try again */
            try {
              resp = await this.resendResult(payloadData)
            } catch (error) {
              debugging('supervisor') && console.error(`supervisor - failed to submit result for job ${jobAddress} after ${payloadData.sendRetries} attempts`)
              throw error;
            }
          }
          else
          {
            throw new Error(`failed to submit result for slice ${slice.sliceNumber} of job ${jobAddress}`);
          }
        }

        if (false && resp.payload.isLastSlice) {
          //
          // Please do not turn this back on. It is buggy.
          //
          // The test showing a last slice failure was 10 emcoil jobs, 22 slices each.
          //  The last slice logic in recordResult killed a sandbox too soon.
          //  In Sandbox.handleRing3Message we fail because this.evaluatorHandle is null which means Sandbox.terminate was called on it.
          //  And there was no coscheduling from Soteria/Sheepdog, so that means the last slice logic is buggy.
          //  Please do not turn it back on, without fixing it, thoroughly testing (which didn't happen last time :sad-cowboy:) and showing it to @Paul for more destructive testing.
          //
          let redundantSlices = [];
          let redundantSandboxes = this.sandboxes.filter((sandbox) => {
            if (sandbox.slice)
              return sandbox.slice.jobAddress === slice.jobAddress
          });

          this.queuedSlices.filter((s) => {
            if (s.jobAddress === slice.jobAddress) {
              redundantSlices.push(s);
              return true;
            }
          });
          redundantSandboxes.forEach((sandbox) => {
            this.returnSandbox(sandbox);
            redundantSlices.push(sandbox.slice);
          });

          this.returnSlices(redundantSlices);
        }

        const paymentAddress = payloadData.paymentAddress.toString(); 
        const payment = resp.payload.slicePaymentAmount;
        this.worker.emit('payment', payment, paymentAddress, jobAddress, slice.sliceNumber);
        this.jobHandles[jobAddress].emit('payment', payment, paymentAddress, slice.sliceNumber);
        sandboxHandle.emit('payment', payment, paymentAddress);

        /**  @todo: Implement size once I/O added. For now its just 0. */
        this.worker.emit('result', resultUrl, 0, jobAddress, slice.sliceNumber);
        this.jobHandles[jobAddress].emit('result', resultUrl, 0, slice.sliceNumber);
      } else {
        /* slice did not complete for some reason */
        
        // If the slice from a job never completes and the job address exists in the ringBufferOfJobs,
        // then we remove it to allow for another slice (from the same job) to be obtained by fetchTask
        const removeIdx = this.ringBufferOfJobs.indexOf(slice.jobAddress);
        if (removeIdx >= 0)
          this.ringBufferOfJobs.remove(removeIdx);
        
        await this.returnSlice(slice);
      }
    } catch(error) {
      debugging() && console.info(`1014: Failed to submit results for slice ${payloadData.slice} of job ${payloadData.job}`, error);
      this.worker.emit('result', error, jobAddress, slice.sliceNumber);
      this.jobHandles[jobAddress].emit('result', error, slice.sliceNumber);
      this.worker.emit('error', error);
    } finally {
      // Remove the slice from the slices array.
      this.removeSlice(slice);
      if (!this.sliceTiming)
        debugging('supervisor') && console.log(`recordResult: Completed slice ${slice.identifier}.`);
      else
      {
        slice['resultDelta'] = Date.now() - slice['resultDelta'];
        console.log(`recordResult(${slice['pairingDelta']}, ${slice['executionDelta']}, ${slice['resultDelta']}): Completed slice ${slice.identifier}.`);
      }
    }
  }

  /**
   * Send a work function's result to a server that speaks our DCP Remote Data Server protocol.
   * E.g. https://gitlab.com/Distributed-Compute-Protocol/dcp-rds
   *
   * @param {Slice} slice - Slice object whose result we are sending.
   * @returns {Promise<string>}
   * @throws When HTTP status not in the 2xx range.
   */
  sendResultToRemote(slice) {
    return supShared.sendResultToRemote(this, slice);
  }
}

/**
 * Sandbox has had an error which is not from the work function: kill it
 * and try to redo the slice.
 */
function handleSandboxError(supervisor, sandbox, error) {
  const slice = sandbox.slice;

  slice.sandboxErrorCount = (slice.sandboxErrorCount || 0) + 1;
  sandbox.slice = null;
  supervisor.returnSandbox(sandbox); /* terminate the sandbox */
  slice.status = SLICE_STATUS_UNASSIGNED; /* ToT */
  slice.allocated = false;
  debugging() && console.warn(`Supervisor.handleSandboxError: Sandbox ${sandbox.identifier}...(${sandbox.public.name}/${slice.sandboxErrorCount}) with slice ${slice.identifier} had error.`, error);
  supervisor.worker.emit('error', error);

  if (slice.sandboxErrorCount <= supervisor.tuning.maxSandboxSliceRetries)
    supervisor.queuedSlices.push(slice);
  else {
    slice.error = error;
    supervisor.returnSlice(slice);
  }
}

/**
 *  Add a slice to the slice payload being built. If a sliceList already exists for the
 *  job-status-authMessage tuple, then the slice will be added to that, otherwise a new
 *  sliceList will be added to the payload.
 *
 *  @param {Object[]} slicePayload - Slice payload being built. Will be mutated in place.
 *  @param {Slice}    slice        - The slice.
 *  @param {String}   status       - Status update, eg. progress or scheduled.
 *
 *  @returns {Object[]} mutated slicePayload array
 */
function addToSlicePayload(slicePayload, slice, status) {
  // getAuthorizationMessage helps enforces the equivalence
  // !authorizationMessage <==> sliceNumber === 0
  const authorizationMessage = slice.getAuthorizationMessage();
  if (!authorizationMessage) return;

  // Try to find a sliceList in the payload which matches the job, status, and auth message
  let sliceList = slicePayload.find(desc => {
    return desc.job === slice.jobAddress
      && desc.status === status
      && desc.authorizationMessage === authorizationMessage;
  });

  // If we didn't find a sliceList, start a new one and add it to the payload
  if (!sliceList) {
    sliceList = {
      job: slice.jobAddress,
      sliceNumbers: [],
      status,
      authorizationMessage,
    };
    slicePayload.push(sliceList);
  }

  sliceList.sliceNumbers.push(slice.sliceNumber);

  return slicePayload;
}

/**
 *  Add a slice to the returnSlice payload being built. If a sliceList already exists for the
 *  job-isEstimation-authMessage-reason tuple, then the slice will be added to that, otherwise a new
 *  sliceList will be added to the payload.
 *
 *  @param {Object[]} slicePayload - Slice payload being built. Will be mutated in place.
 *  @param {Slice}    slice        - The slice.
 *  @param {String}   [reason]     - Optional reason to further characterize status; e.g. 'ENOPROGRESS', 'EUNCAUGHT', 'ESLICETOOSLOW', 'unknown'.
 *
 *  @returns {Object[]} mutated slicePayload array
 */
function addToReturnSlicePayload(slicePayload, slice, reason) {
  // getAuthorizationMessage helps enforces the equivalence
  // !authorizationMessage <==> sliceNumber === 0
  const authorizationMessage = slice.getAuthorizationMessage();
  if (!authorizationMessage) return;

  if (!reason) reason = slice.error ? 'EUNCAUGHT' : 'unknown';

  // Try to find a sliceList in the payload which matches the job, status, and auth message
  let sliceList = slicePayload.find(desc => {
    return desc.job === slice.jobAddress
      && desc.isEstimationSlice === slice.isEstimationSlice
      && desc.authorizationMessage === authorizationMessage
      && desc.reason === reason;
  });

  // If we didn't find a sliceList, start a new one and add it to the payload
  if (!sliceList) {
    sliceList = {
      job: slice.jobAddress,
      sliceNumbers: [],
      status: 'return',
      isEstimationSlice: slice.isEstimationSlice,
      authorizationMessage,
      reason,
    };
    slicePayload.push(sliceList);
  }

  sliceList.sliceNumbers.push(slice.sliceNumber);

  return slicePayload;
}

/**
 * Return DCPv4-specific connection options, composed of type-specific, URL-specific, 
 * and worker-specific options, any/all of which can override the dcpConfig.dcp.connectOptions.
 * The order of precedence is the order of specificity.
 */
function connectionOptions(url, identity, label) {
  return leafMerge(/* ordered from most to least specific */
    dcpConfig.supervisor.dcp.connectionOptions.default,
    dcpConfig.supervisor.dcp.connectionOptions[label],
    dcpConfig.supervisor.dcp.connectionOptions[url.href],
    { identity });
}

exports.Supervisor = Supervisor;
