/**
 * Construct the payload for updating job metrics in Supervisor.
 * Returned as part of getJobsForTask and in result submitter 'result' processing.
 * @param {*} job         - Row from jobs table.
 * @param {*} jobPerfData - Correpsonding row from jobPerfData table.
 * @returns {{sliceCPUTime: number, sliceGPUTime: number, sliceCPUDensity: number, sliceGPUDensity: number, lastSliceNumber: number, measuredSlices: number, alpha: number}}
 */
exports.collectMetrics = function utils$$collectMetrics(job, jobPerfData)
{
  const lastSliceNumber = Number(job.lastSliceNumber || 0);
  const nextSliceNumber = Number(job.nextSliceNumber || 0);
  // Invariant jobPerfData.measuredSlices <= min(job.nextSliceNumber-1,  job.lastSliceNumber)
  const measuredSlices = Math.min(Number(jobPerfData.measuredSlices), nextSliceNumber, lastSliceNumber);
  const alpha = exports.constructAlpha(lastSliceNumber, measuredSlices);
  const metrics = {
    sliceCPUTime:     Number(jobPerfData.sliceCPUTime || 0),
    sliceGPUTime:     Number(jobPerfData.sliceGPUTime || 0),
    sliceCPUDensity:  Number(jobPerfData.sliceCPUDensity || 0),
    sliceGPUDensity:  Number(jobPerfData.sliceGPUDensity || 0),
    //sliceInDataSize:  Number(jobPerfData.sliceInDataSize || 0),  -- Not used yet
    //sliceOutDataSize: Number(jobPerfData.sliceOutDataSize || 0), -- Not used yet
    // Transmit the EMA coefficient information to supervisor.
    lastSliceNumber,
    measuredSlices,
    alpha,
    running: job.status === jobStatus.running,
  };
  return metrics;
}

/**
 * Construct the EMA coefficient for computing jobPerfData columns.
 * @param {number} lastSliceNumber - job.lastSliceNumber
 * @param {number} measuredSlices  - Math.min(jobPerfData.measuredSlices, job.nextSliceNumber, job.lastSliceNumber)
 * @returns {number}               - 0 < retVal <= 0.5
 */
exports.constructAlpha = function utils$$constructAlpha(lastSliceNumber, measuredSlices)
{
  // lastSliceNumber - measuredSlices is # of slices which have not reported results.
  const alpha = Math.min(0.5, Math.max(1.0, lastSliceNumber - measuredSlices) / lastSliceNumber);
  return alpha;
}

/**
 * Construct the EMA coefficient for computing jobPerfData columns.
 * @param {*} job          - row in jobs table
 * @param {*} jobPerfData  - corresponding row in jobPerfData table
 * @returns {number}       - 0 < retVal <= 0.5
 */
exports.constructAlphaFromDb = function utils$$constructAlpha(job, jobPerfData)
{
  const last = Number(job.lastSliceNumber || 0);
  const next = Number(job.nextSliceNumber || 1);
  const measured = Math.min(Number(jobPerfData.measuredSlices), next, last);
  const alpha = exports.constructAlpha(last, measured);
  return alpha;
}

/**
 * Compute sum of CPU and GPU time span. (ok)
 * @param {{totalCPUTime: number, totalGPUTime: number}} metrics
 * @returns {number}
 */
exports.totalTime = function utils$$totalTime(metrics)
{
  if (!metrics) return 0;
  const gtime = metrics.totalCPUTime + metrics.totalGPUTime;
  return gtime;
}

/**
 * Compute sum of CPU and GPU time span. (ok)
 * @param {{CPUTime: number, GPUTime: number}} metrics
 * @returns {number}
 */
exports.localTime = function utils$$localTime(metrics)
{
  if (!metrics) return 0;
  const ltime = metrics.CPUTime + metrics.GPUTime;
  return ltime;
}

