/**
 * Compute the variance of the total amount of time it takes to execute a slice. (will be ok)
 *   Var(X/C)= Var(X)/(C * C)
 * @param {{CPUTime_variance: number, GPUTime_variance: number, CPUDensity: number, GPUDensity: number}} metrics
 * @returns {number}
 */
exports.localElapsedVariance = function utils$$localElapsedVariance (metrics)
{
  if (!metrics) return 0;
  const totalDensity = (metrics.CPUDensity + metrics.GPUDensity) || 1;
  const lev = (metrics.CPUTime_variance + metrics.GPUTime_variance) / (totalDensity * totalDensity);
  return lev;
}

