/** Used by index to detect webpack */
exports.myScript = (typeof document !== 'undefined') && document.currentScript;

/**
 * This function bypasses CORS with the help of a `cors-proxy.html` file on the
 * remote end. We just set that file as the src of an invisible iframe and then
 * it reads the url query params to determine what to fetch. Then it posts that
 * content back here to the parent.
 * 
 * We pass along a `lang` key as well so that the remote end can provide a little 
 * internationalization.
 * 
 * @param {string} src Full uri to special cors-proxy.html hosted at other origin.
 *     for example: https://cdn.kittens.org/path/to/cors-proxy.html
 * @param {string} relativePath Path to file you are fetching. Relative to 
 *     cors-proxy.html. For example: './stuff/content.js'.
 * @param {object} args  Arbitrary object passed to the other end.
 */
module.exports.fetchRelative = async function (src, relativePath) {
  // Build url params
  let params = new URLSearchParams();
  params.set("relative-url", relativePath);
  
  // Grab a promise's `resolve` to use in the iframe's onload
  let resolve, reject, iframe;
  const promise = new Promise ( (rslv, rjct) => { resolve = rslv, reject = rjct} );

  let errorHandler = function clientModal$$fetchRelative$errorHandler(ev) {
    if (!errorHandler)
      return;
    errorHandler = false;
    let url = new URL(iframe.src);
    let errMsg = `Could not fetch modal dialog loader ${url.origin}${url.pathname}`;
    resolve = false;
    alert(errMsg);
    reject(ev || new Error(errMsg));
    console.error(errMsg, ev || '');
  }

  function createIframe() {
    iframe = document.createElement('IFRAME');
    iframe.hidden = true;
    iframe.onload = () => {
      errorHandler = false;
      window.addEventListener("message", ({data}) => {
        if (data.relativePath === relativePath)
          resolve(data.content)
      });
    }
    iframe.onerror = errorHandler; /* will not fire xss */
    iframe.src = src + '?' + params.toString();
    document.body.appendChild(iframe);
  }
  if (document.body)
    createIframe();
  else
    window.addEventListener("load", createIframe);
  
  setTimeout(errorHandler, 20000);

  // Await first message from iframe, assume it is the desired data
  const content = await promise;
  iframe.remove();
  return content;
}
