/** @typedef {import('dcp/dcp-client/worker/supervisor').Supervisor} Supervisor */
/** @typedef {import('dcp/protocol-v4/connection/connection').Connection} Connection */

/**
 * Generate the workerComputeGroups property of the requestTask message.
 *
 * Concatenate the compute groups object from dcpConfig with the list of compute groups
 * from the supervisor, and remove the public group if accidentally present. Finally,
 * we transform joinSecrets/joinHash into joinHashHash for secure transmission.
 *
 * @note computeGroup objects with joinSecrets are mutated to record their hashes. This
 *       affects the supervisor options and dcpConfig. Re-adding a joinSecret property
 *       to one of these will cause the hash to be recomputed.
 *
 * @param {Supervisor} This
 * @param {Connection} taskDistributor
 * @returns array
 */
exports.generateWorkerComputeGroups = function Supervisor$generateWorkerComputeGroups (This, taskDistributor)
{
  let computeGroups = Object.values(This.options.computeGroups || {});
  computeGroups = computeGroups.filter(group => group.id !== constants.computeGroups.public.id);
  const hashedComputeGroups = [];
  for (const group of computeGroups)
  {
    const groupCopy = Object.assign({}, group);
    if ((group.joinSecret || group.joinHash) && (!group.joinHashHash || This.lastDcpsid !== taskDistributor.dcpsid))
    {
      let joinHash;
      if (group.joinHash)
        joinHash = group.joinHash.replace(/\s+/g, '');  // strip whitespace
      else
        joinHash = calculateJoinHash(groupCopy);

      groupCopy.joinHashHash = hash.calculate(hash.eh1, joinHash, taskDistributor?.dcpsid);
      delete groupCopy.joinSecret;
      delete groupCopy.joinHash;
      debugging('computeGroups') && console.debug(`Calculated joinHash ${joinHash} for`, groupCopy);
    }
    hashedComputeGroups.push(groupCopy);
  }
  This.lastDcpsid = taskDistributor.dcpsid;
  debugging('computeGroups') && console.debug(`Requesting ${computeGroups.length} non-public groups for session ${This.lastDcpsid}`);
  return hashedComputeGroups;
}

/**
 * Send a work function's result to a server that speaks our DCP Remote Data Server protocol.
 * @param {*} This  - Either Supervisor1 or Supervisor2
 * @param {*} slice - Either Slice1 or Slice2 object whose result we are sending.
 * @returns {Promise<string>}
 * @throws When HTTP status not in the 2xx range.
 */
exports.sendResultToRemote = function Supervisor$sendResultToRemote (This, slice)
{
   /** XXXpfr @todo: Support file upload. */
   function serializeContent(result, category = { isJSON: true, isKVIN: false, isBinary: false, isText: false }) {
    if (category.isJSON) return JSON.stringify(result);
    if (category.isKVIN) return require('kvin').serialize(result);
    if (category.isBinary) return new Uint8Array(result.buffer);
    return result;
  }

  // Construct postParams.
  const postParams = { ...slice.resultStorageParams };
  if (!postParams.contentType)
    postParams.contentType = 'application/json';
  if (!postParams.element)
    postParams.element = slice.sliceNumber;
  debugging('supervisor') && console.debug('sendResultToRemote postParams:', postParams);

  // Categorize postParams.contentType.
  const category = categorizeContentType(postParams.contentType);

  // Construct result.
  const result = slice.result.result;
  if (result)
    postParams.content = serializeContent(result, category);
  else
    postParams.error = serializeContent(slice.error);
  debugging('supervisor') && console.debug('sendResultToRemote content:', (result ? postParams.content : postParams.error).slice(0, 128));

  // Construct url.
  const sliceResultUri = slice.resultStorageDetails;
  // cf.DCP-3679
  // const sliceResultUri = makeValueURI('pattern', slice.resultStorageDetails, {
  //   slice: slice.sliceNumber,
  //   job:   slice.jobAddress,
  // });
  debugging() && console.debug('sendResultToRemote sliceResultUri:', sliceResultUri);
  const url = new DcpURL(sliceResultUri);

  // Check allowed origins.
  if (!This.originManager.isAllowed(url.origin, 'sendResults'))
    throw new DCPError(`Invalid origin for remote result storage: '${url.origin}'`, 'EPERM_ORIGIN');

  let body = postParams, type = 'string';
  /**
   * @todo XXXpfr Need to properly implement FormData to support multipart/form-data POST
   * (cf. DCP branch improvement/dcp-3446-multipart-remote-results)
   *
   */
  // if (category.isBinary)
  // {
  //   // Set up a multipart/form-data POST in order to upload binary data.
  //   const entries = Object.entries(postParams);
  //   const form = new FormData();

  //   entries.forEach((kvp) => {
  //     if (ArrayBuffer.isView(kvp[1]))
  //     {
  //       if (!DCP_ENV.isBrowserPlatform)
  //         form.append(kvp[0].toString(), new Uint8Array(kvp[1].buffer));
  //       else
  //         form.append(kvp[0].toString(), new Blob([new Uint8Array(kvp[1].buffer)]));
  //     }
  //     else
  //       form.append(kvp[0].toString(), kvp[1].toString());
  //   });

  //   if (!DCP_ENV.isBrowserPlatform)
  //   {
  //     body = form.getBuffer();
  //     type = form.getHeaders()['content-type'];
  //   }
  //   else
  //   {
  //     body = form;
  //     type = 'multipart/form-data';
  //   }
  // }

  // Fetch.
  return justFetch(url, type, 'POST', false, body)
    .then((response) => encodeDataURI(JSON.stringify(response)));
}
