/**
 * @file client-modal/utils.js
 * @author KC Erb
 * @date Mar 2020
 * 
 * All shared functions among the modals.
 */
const { fetchRelative } = require('./fetch-relative');
const { DCPError } = require('dcp/common/dcp-error');
const DCP_ENV = require('dcp/common/dcp-env');
exports.OnCloseErrorCode = 'DCP_CM:CANCELX';

if (DCP_ENV.isBrowserPlatform) {
  // Provide as export for the convenience of `utils.MicroModal` instead of a separate require.
  exports.MicroModal = require('micromodal').default;
}

/**
 * Return a unique string, formatted as a GET parameter, that changes often enough to
 * always force the browser to fetch the latest version of our resource.
 *
 * @note Currently always returns the Date-based poison due to webpack. 
 */
function cachePoison() {
  if ('a3cd15e8f51318dea97d475c00b09ee7998cdbe8' !== '__GIT_' + 'VERSION__')
    return '?ucp=a3cd15e8f51318dea97d475c00b09ee7998cdbe8'; /* installer token */
  return '?ucp=' + Date.now();
}
  
/* Detect load type - on webpack, load dynamic content relative to webpack bundle;
 * otherwise load relative to the current scheduler's configured portal.
 */
exports.myScript = (typeof document !== 'undefined') && document.currentScript;
exports.corsProxyHref  = undefined;
if (exports.myScript && exports.myScript === require('./fetch-relative').myScript) {
  let url = new (require('dcp/common/dcp-url').DcpURL)(exports.myScript.src);
  exports.corsProxyHref = url.resolve('../cors-proxy.html');
}

/**
 * Look for modal id and required ids on page based on config, if not found, provide from dcp-client.
 * The first id in the required array must be the id of the modal's form element.
 * @param {Object} modalConfig Modal configuration object
 * @param {string} modalConfig.id Id of parent modal element
 * @param {string[]} modalConfig.required Array of required ids in parent modal element
 * @param {string[]} [modalConfig.optional] Array of optional ids in parent modal element
 * @param {string} modalConfig.path Relative path to modal html in dcp-client
 * @returns {DOMElement[]} Array of modal elements on page [config.id, ...config.required]
 */
exports.initModal = async function (modalConfig, onClose) {
  exports.corsProxyHref = exports.corsProxyHref || dcpConfig.portal.location.resolve('dcp-client/cors-proxy.html');

  // Call ensure modal on any eager-loaded modals.
  if (modalConfig.eagerLoad) {
    Promise.all(
      modalConfig.eagerLoad.map(config => ensureModal(config))
    )
  };

  const [elements, optionalElements] = await ensureModal(modalConfig);

  // Wire up form to prevent default, resolve on submission, reject+reset when closed (or call onClose when closed)
  const [modal, form] = elements;
  form.reset(); // ensure that form is fresh
  let formResolve, formReject;
  let formPromise = new Promise( function(res, rej) {
    formResolve = res;
    formReject = rej;
  });
  form.onsubmit = function (submitEvent) {
    submitEvent.preventDefault();
    modal.setAttribute("data-state", "submitted");
    formResolve(submitEvent);
  }

  exports.MicroModal.show(modalConfig.id, { 
    disableFocus: true, 
    onClose: onClose || getDefaultOnClose(formReject)
  });
  return [elements, formPromise, optionalElements];
};

// Ensure all required modal elements are on page according to modalConfig
async function ensureModal(modalConfig) {
  let allRequiredIds = [modalConfig.id, ...modalConfig.required];
  let missing = allRequiredIds.filter( id => !document.getElementById(id) );
  if (missing.length > 0) {
    if (missing.length !== allRequiredIds.length)
      console.warn(`Some of the ids needed to replace the default DCP-modal were found, but not all. So the default DCP-Modal will be used. Missing ids are: [${missing}].`);
    let contents = await fetchRelative(exports.corsProxyHref, modalConfig.path + cachePoison());
    const container = document.createElement('div');
    container.innerHTML = contents;
    document.body.appendChild(container);
  }

  const elements = allRequiredIds.map(id => document.getElementById(id));
  const optionalElements = (modalConfig.optional || []).map(id => document.getElementById(id));
  return [elements, optionalElements];
};

// This onClose is called by MicroModal and thus has the modal passed to it.
function getDefaultOnClose (formReject) {
  return (modal) => {
    modal.offsetLeft; // forces style recalc
    const origState = modal.dataset.state;
    // reset form including data-state
    modal.setAttribute("data-state", "new");
    // reject if closed without submitting form.
    if (origState !== "submitted") {
      const err = new DCPError("Modal was closed but modal's form was not submitted.", exports.OnCloseErrorCode);
      formReject(err);
    }
  }
}
