/**
 * @file        connection-constants.js
 *              Constants for use by the Connection class and its friends
 * @author      Wes Garland, wes@kingsds.network
 * @date        March 2022
 */

exports.role = {
  initiator: { toString: () => 'initiator' },
  target:    { toString: () => 'target' },
};

exports.init = function connectionConstants$$init()
{
  if (require('dcp/common/dcp-env').platform === 'nodejs')
  {
    const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
    const inspect  = requireNative('util').inspect.custom;

    for (let role in exports.role)
      exports.role[role][inspect] = exports.role[role].toString;
  }
}

require('dcp/common/dcp-timers').setImmediate(exports.init);
