/* global dcpConfig */ // eslint-disable-line no-redeclare
// @ts-check
'use strict';

const { assert } = require('dcp/common/dcp-assert');
const constants = require('dcp/common/scheduler-constants');
const hash = require('dcp/common/hash');
const { calculateJoinHash } = require('dcp/dcp-client/compute-groups');
const debugging = require('dcp/debugging').scope('worker');
const proto4 = require('dcp/protocol-v4');
const { DCPError } = require('dcp/common/dcp-error');
const { leafMerge } = require('dcp/utils/obj-merge');
const { checkConnectionName, selectiveDebug, selectiveDebug2, compressSlices } = require('./common');
const { a$sleepMs } = require('dcp/utils');

/** @typedef {import('./slice2').Slice} Slice                             */
/** @typedef {import('./options').Options} Options                        */
/** @typedef {import('./index').Supervisor} Supervisor                    */
/** @typedef {import('./sandbox2').SandboxHandle} SandboxHandle           */
/** @typedef {import('./delay-manager').DelayManager} DelayManager        */
/** @typedef {import('dcp/dcp-client/wallet/eth').Address} Address        */
/** @typedef {import('dcp/common/concurrency').Synchronizer} Synchronizer */
/** @typedef {import('dcp/dcp-client/wallet/keystore').Keystore} Keystore */
/** @typedef {import('dcp/protocol-v4/connection/connection').Connection} Connection */

class Connector
{
  /**
   * @param {string} which - name of connection
   * @param {*} config     - dcpConfig scheduler properties
   * @param {*} options    - identity and dcpConfig supervisor properties
   */
  constructor (which, config, options)
  {
    this.which       = which;
    this.config      = config;
    this.options     = options;
    this.pendingData = [];
    this.connection  = null;
    this.handlers = {
      connect: this.connect.bind(this),
      sendPendingData: this.sendPendingData.bind(this),
    };
  }
  get id () { return this.connection?.id ?? -1; }
  connect ()
  {
    this.connection = new proto4.Connection(this.config, this.options);
    this.connection.on('session', this.handlers.sendPendingData);
    this.connection.on('end', this.handlers.connect);
  }
  close ()
  {
    this.connection.off('end', this.handlers.connect);
    this.connection.off('session', this.handlers.sendPendingData);
    this.connection.close();
  }
  keepalive () { return this.connection.keepalive(); }
  request (operation, data)
  {
    const message = { operation, data };
    this.pendingData.push(message);
    return this.connection.request(message.operation, message.data)
      .then((response) => {
        const index = this.pendingData.indexOf(message);
        if (index !== -1)
          this.pendingData.splice(index, 1);
        return response;
      })
      .catch((error) => {
        selectiveDebug() && console.debug(`Connector(${this.which},${operation}): connection.request failed:`, error);
        throw error;
    });
  }
  sendPendingData ()
  {
    const messages = this.pendingData.slice();
    this.pendingData.length = 0;
    for (let i = 0; i < messages.length; i++)
      this.request(messages[i].operation, messages[i].data);
  }
}
/**
 * Connection management.
 */
class ProtocolManager
{
  /**
   * @param {Supervisor} supervisor 
   */
  constructor(supervisor)
  {
    this.supervisor = supervisor;

    /** @type {string|boolean|null} */
    this.lastDcpsid      = null;
    /** @type {Connector} */
    this.taskDistributor = null;
    /** @type {Connector} */
    this.resultSubmitter = null;
    /** @type {Connector} */
    this.eventRouter     = null;
    /** @type {Connector} */
    this.packageManager  = null;
  }
  
  /** @type {Options} */
  get options () { return this.supervisor.options; }
  /** @type {Keystore} */
  get identity () { return this.supervisor.identityKeystore; }
  /** @type {Synchronizer} */
  get state () { return this.supervisor.state; }
  
  /**
   * Connect the supervisor to a given scheduler sub-service. Reconnection "DDoS" from workers
   * mitigated via an exponential backoff algorithm.
   *
   * DCPv4 connections are lazily-initiated. Successful connection establishment detected by
   * observing the payload event, which normally triggers during versioning.
   */
  connectTo (which)
  {
    const config = (which === 'packageManager') ? dcpConfig.packageManager : this.options.schedulerConfig.services[which];

    var options = leafMerge(/* ordered from most to least specific */
      this.options.connectionOptions.default,
      this.options.connectionOptions[which],
      this.options.connectionOptions[config.location.href],
      { identity: this.identity }
    );

    checkConnectionName(which);
    this[which] = new Connector(which, config, options);
    this[which].connect();
    this[which].connection.on('connect', (event) => this.workerEmit('connect', event));
    this[which].connection.on('disconnect', (event) => this.workerEmit('disconnect', event));

    selectiveDebug() && console.debug(`Opening new connection ${this[which].id} to ${which}.`, Date.now() - this.supervisor.lastTime);
  }
  
  /**
   * Close a connection properly.
   * @param {string} which -- Name of the connection to close.
   */
  closeConnection (which)
  {
    checkConnectionName(which);
    this[which].close();
  }

  /**
   * Close all connections.
   */
  async closeConnections ()
  {
    /** @todo Please remove a$sleepMs and mark this function as non-async when this bug is fixed: https://distributive.atlassian.net/browse/DCP-4248 */
    await a$sleepMs(1000);
    // Protocol 5.3 no longer exposes a promise in Connection.close().
    this.closeConnection('taskDistributor');
    this.closeConnection('resultSubmitter');
    this.closeConnection('eventRouter');
    this.closeConnection('packageManager');
  }

  /**
   * Open all connections. Called only in Supervisor.work() because the Connector class
   * is responsible for recreating whenever the 'end' event fires.
   */
  instantiateAllConnections ()
  {
    this.connectTo('taskDistributor');
    this.connectTo('eventRouter');
    this.connectTo('resultSubmitter');
    this.connectTo('packageManager');
  }

  /**
   * Generate the workerComputeGroups property of the requestTask message.
   *
   * Concatenate the compute groups object from dcpConfig with the list of compute groups
   * from the supervisor, and remove the public group if accidentally present. Finally,
   * we transform joinSecrets/joinHash into joinHashHash for secure transmission.
   *
   * @note computeGroup objects with joinSecrets are mutated to record their hashes. This
   *       affects the supervisor options and dcpConfig. Re-adding a joinSecret property
   *       to one of these will cause the hash to be recomputed.
   * @returns {object[]}
   */
  generateWorkerComputeGroups ()
  {
    // It's possible that this.taskDistributor is closed when the worker is shutting down via stopWork.
    let computeGroups = Object.values(this.options.computeGroups || {});
    computeGroups = computeGroups.filter(group => group.id !== constants.computeGroups.public.id);
    const hashedComputeGroups = [];
    for (const group of computeGroups)
    {
      const groupCopy = Object.assign({}, group);
      if ((group.joinSecret || group.joinHash) && (!group.joinHashHash || this.lastDcpsid !== this.taskDistributor?.connection?.dcpsid))
      {
        let joinHash;
        if (group.joinHash)
          joinHash = group.joinHash.replace(/\s+/g, '');  // strip whitespace
        else
          joinHash = calculateJoinHash(groupCopy);

        groupCopy.joinHashHash = hash.calculate(hash.eh1, joinHash, String(this.taskDistributor?.connection?.dcpsid));
        delete groupCopy.joinSecret;
        delete groupCopy.joinHash;
        debugging('computeGroups') && console.debug(`Calculated joinHash ${joinHash} for`, groupCopy);
      }
      hashedComputeGroups.push(groupCopy);
    }
    this.lastDcpsid = this.taskDistributor?.connection?.dcpsid;
    debugging('computeGroups') && console.debug(`Requesting ${computeGroups.length} non-public groups for session ${this.lastDcpsid}`);
    return hashedComputeGroups;
  }

  /**
   * Safely send result submitter status messages.
   * @param {object} data
   * @param {string} errorMsg
   * @returns {Promise<*>}
   */
  async safeRSStatus (data, errorMsg)
  {
    try
    {
      return this.resultSubmitter.request('status', data)
        .catch(error => {
          selectiveDebug() && console.error(`safeRSStatus: ${errorMsg}; will try again on new connection.`, error);
        });
    }
    catch (error)
    {
      selectiveDebug() && console.error(`safeRSStatus: ${errorMsg}; will try again on new connection.`, error);
    }
  }

  /**
   * Safely send return slices to RS status.
   * @param {object} data
   * @param {Slice[]} slices - The slice candidates to check if they can be returned to the scheduler.
   * @returns {Promise<*>}
   */
  async sliceReturn (data, slices)
  {
    const failedRequest = (error) => {
      error = new DCPError('Result submitter connection failed: will try again on new connection.', error);
      selectiveDebug() && console.error(`Failed to return slices ${compressSlices(slices)}`, error);
      slices.forEach((slice) => { this.jobEmit(slice, 'return', error, slice.sliceNumber); });
    };
    try
    {
      slices.forEach((slice) => { this.jobEmit(slice, 'beforeReturn', slice.sliceNumber); });
      return this.resultSubmitter.request('status', data)
        .then((resp) => {
          slices.forEach((slice) => { this.jobEmit(slice, 'return', slice.sliceNumber); });
          return resp;
        })
        .catch(error => {
          failedRequest(error);
        });
    }
    catch (error)
    {
      failedRequest(error);
    }
  }

  /**
   * Safely send event router workEmit messages.
   * @param {*} data
   * @param {string} errorMsg
   * @returns {Promise<*>}
   */
  async safeWorkEmit (data, errorMsg)
  {
    try
    {
      selectiveDebug2() && console.debug(`safeWorkEmit: Before sending message: (${this.eventRouter?.id}).`);
      return this.eventRouter.request('workEmit', data)
        .catch(error => {
          selectiveDebug() && console.error(`safeWorkEmit: ${errorMsg}; will try again on new connection.`, error);
        });
    }
    catch (error)
    {
      selectiveDebug() && console.error(`safeWorkEmit: ${errorMsg}; will try again on new connection.`, error);
    }
  }

  /**
   * Safe event emitter on worker.
   * @param {string}  event
   * @param  {...any} args
   */
  workerEmit(event, ...args)
  {
    this.supervisor.safeEmit(this.supervisor.worker, event, ...args);
  }

  /**
   * Safe event emitter on slice.jobHandle.
   * @param {Slice}   slice
   * @param {string}  event
   * @param  {...any} args
   */
  jobEmit(slice, event, ...args)
  {
    this.supervisor.safeEmit(slice.jobHandle, event, ...args);
  }
}
exports.ProtocolManager = ProtocolManager;
