/**
 *  @file       protocol/connection/connection.js
 *  @author     Ryan Rossiter ryan@kingsds.network
 *  @date       January 2020
 *
 *  @author     KC Erb kc@kingsds.network
 *  @date       Feb 2021
 *
 *  @author     Wes Garland, wes@distributive.network
 *  @date       Mar 2022, Nov 2022
 *
 *  A Connection object represents a connection to another DCP entity. 
 *  A DCP connection may 'live' longer than the underlying protocol's connection,
 *  and the underlying protocol connection (or, indeed, protocol) may change
 *  throughout the life of the DCP connection.
 * 
 *  DCP connections are uniquely identified by the DCP Session ID, specified by
 *  the dcpsid property, present in every message body. This session id is negotiated during connection,
 *  with the initiator and target each providing half of the string.
 *
 * Connection instance events:
 * - session:           dcpsid  new session established
 * - connect:           url     UI hint: internet available
 * - disconnect:        url     UI hint: internet not available
 * - readyStateChange:          *** DO NOT USE **
 * - error:             error   emitted when errors happen that would otherwise go uncaught
 * - end:                       Connection instance is closing, API users cannot use anymore
 * - close:                     Connection instance is closed (final)
 * - send:              msgObj  when a message is sent to the peer; does not wait for ack; may re-trigger on reconnect
 * - ready:                     when the connection is ready for traffic (constructor promises resolved)
 *
 * State Transition Diagram for Connection.state:
 *
 * initial         connecting            established                     disconnected                  closing         closed
 * ============================================================================================================================
 * |-- i:connect ----->
 * |-- t:accept ------>
 *                    |-- i:a$_connect -------->
 *                    |-- i:replaceTransport -->
 *                    |-- t:establishTarget --->
 *                    |--------------------------- transportDisconnectHandler -->
 *                                             |-- transportDisconnectHandler -->
 *                    <-- i:connect --------------------------------------------|
 *                    <-- t:replaceTransport -----------------------------------|
 *                                             |-- handleCloseRequest ------------------------------------->
 *                    |-- #close -------------------------------------------------------------------------->
 *                                             |-- #close ------------------------------------------------->
 *                                                                              |-- #close ---------------->
 *                                                                                                         |-- #shutdown -->
 * |-- #close (no dcpsid) ------------------------------------------------------------------------------------------------->
 *                    |-- #close (no dcpsid) ------------------------------------------------------------------------------>
 *
 * Not until the established state can we count on things like a dcpsid, 
 * peerAddress, identityPromise resolution and so on.
 */

'use strict';

const debugging = require('dcp/debugging').scope('dcp');
const dcpEnv = require('dcp/common/dcp-env');
const { EventEmitter } = require('events');
const wallet = require('dcp/dcp-client/wallet');
const { DcpURL } = require('dcp/common/dcp-url');
const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
const { assert } = require('dcp/common/dcp-assert');
const { leafMerge, a$sleep } = require('dcp/utils');
const { Synchronizer } = require('dcp/common/concurrency');
const { DCPError } = require('dcp/common/dcp-error');

const { Transport } = require('../transport');
const { Sender } = require('./sender');
const { Receiver } = require('./receiver');
const { MessageLedger } = require('./message-ledger');
const { getGlobalIdentityCache } = require('./identity-cache');
const { makeEBOIterator, setImmediate, setTimeout, clearTimeout, setInterval, clearInterval } = require('dcp/common/dcp-timers');

const { errorPayloadCtorFactory } = require('./error-payload');
const { messageCtorFactory }      = require('./message');
const { ackCtorFactory }          = require('./ack');
const { requestCtorFactory }      = require('./request');
const { responseCtorFactory }     = require('./response');
const { batchCtorFactory }        = require('./batch');

const { wireLog } = require('..');
const { role } = require('./connection-constants');

const usingDebugger = dcpEnv.platform === 'nodejs' && requireNative('module')._cache.niim instanceof requireNative('module').Module;
const isDebugBuild = require('dcp/common/dcp-build').build === 'debug';

let globalConnectionId = 0;
const maxConnectTries = 5;

const CONNECTION_STATES = [
  'initial',
  'connecting',     /* session is working to negotiate dcpsid */
  'established',    /* session has been fully established, have dcpsid */
  'disconnected',   /* session is still valid, but underlying transport is no longer connected */
  'closing',        /* session is still valid, trying to close, rejecting new messages at API boundary */
  'closed',
]

class Connection extends EventEmitter {
  static get VERSION() {
    return '5.2.0'; // Semver format
  }

  static get VERSION_COMPATIBILITY() {
    return '^5.0.0'; // Semver format, can be a range
  }

  /**
   * Connection form 2:
   * @constructor
   * @param {object}    [target]
   * @param {Promise}   idKsPromise     A promise which resolves to the identity keystore described
   *                                    in form 1
   * @param {object}    [options]
   * @see form 1
   */
  /**
   *              Connection form 1
   *              Create a DCP Connection object. This object could represent either the initiator or 
   *              target end of a connection, until it is specialized by either invoke the connect()
   *              or accept() methods. Note that send() invokes connect() internally if not in an established
   *              state.
   * @constructor
   * @note        Connection objects exist for the lifetime of a given DCP connection 
   *              (session), whether or not the underlying transport (eg internet protocol) is connected or not. Once 
   *              the DCP session has ended, this object has no purpose and is not reusable.
   * 
   * @param {object}    target          Object (usually a dcpConfig fragment) describing the target.
   *                                    This object may contain the following properties; 'location' is
   *                                    mandatory:
   *                                    - location: a URL or DcpURL that is valid from the Internet
   *                                    - friendLocation: a DcpURL that is valid from an intranet; if
   *                                      both location and friendLocation specified, the best one will
   *                                      be chosen by examining IP addresses (assuming an IP bearer).
   *                                    - identity: an object with an address property which is a promise
   *                                      that resolves to an instance of wallet.Address which represents
   *                                      to the target's identity; this overrides the initiator's 
   *                                      identity cache unless options.strict is truey.
   *    
   * @param {Keystore}  [idKeystore]    The keystore used to sign messages; used for non-repudiation.
   *                                    If not specified, a dynamically-generated keystore will be used.
   *                                           
   * @param {object}    [options]     Extra connection options that aren't defined via dcpConfig.dcp.connectionOptions.
   *                                                    These options include:
   *                                                    - identityUnlockTimeout: Number of (floating-point) seconds to leave the identity 
   *                                                      keystore unlocked between invocations of Connection.send
   *
   * @returns instance of Connection that is specific to a target URL but not a role
   */
  constructor(target, idKeystore, options)
  {
    super({ captureRejections: false });

    this.on('error', () => {}); /* avoid "special" behaviour of NodeJS */
    this.id = ++globalConnectionId;
    this.debugLabel = `connection(g:${this.id}):`;
    this.preEstablishedQueue = [];

    /* polymorphism strategy: rewrite to (configFragment, idksPromise, options) */
    if (!target)
      throw new DCPError('Connection constructor requires target argument', 'DCPC-0001');
    if (target instanceof String || typeof target === 'string')
      target = { location: new URL(target) };
    if (target instanceof DcpURL)
      target = { location: target };
    else if (DcpURL.isURL(target))
      target = { location: new DcpURL(target) };
    else if (target instanceof String || typeof target === 'string')
      target = { location: new DcpURL(target) };
    assert(typeof target === 'object', target.location);
    if (!target.location)
      throw new DCPError('Connection constructor requires target.location argument', 'DCPC-0002');
    assert(DcpURL.isURL(target.location));

    if (!options && !idKeystore)
      options = {};
    else if (!options && !(idKeystore instanceof wallet.Keystore) && !(idKeystore instanceof Promise))
    {
      options = idKeystore;
      idKeystore = undefined;
      if (options.identity instanceof wallet.Keystore || options.identity instanceof Promise)
        idKeystore = options.identity;
    }

    /* idKeystore is always resolved by the time a session is established. */
    if (!idKeystore)
      this.identityPromise = wallet.getId();
    else if (idKeystore instanceof Promise)
      this.identityPromise = idKeystore;
    else if (idKeystore instanceof wallet.Keystore)
      this.identityPromise = Promise.resolve(idKeystore);      
    else if (idKeystore instanceof wallet.Address)
      this.identityPromise = Promise.resolve(new wallet.Keystore(idKeystore, ''));      
    else
      throw new DCPError('Invalid argument provided for IdKeystore', 'DCPC-1018');

    /* This promise resolver is enqueued immediately after declaration in the same tick, so that it hits
     * the job queue first when the promise resolves. This guarantees that if `this.identityPromise` is
     * undefined that `identity` has resolved.
     */
    this.identityPromise.then((keystore) => {
      /* This always happens by the time a role is assumed */
      delete this.identityPromise;
      this.identity = keystore;
      this.emit('ready');
      debugging('connection') && console.debug(this.debugLabel, 'identity is', this.identity.address);
    });

    this.target = target;
    this.url    = this.target.location;

    // Init internal state / vars
    this.state = new Synchronizer(CONNECTION_STATES[0], CONNECTION_STATES);
    debugging('connection') && this.state.on('change', (neu, old) => console.debug(this.debugLabel, `state changed ${old}->${neu} (now ${this.state})`));

    this.dcpsid = null;
    this.peerAddress = null;
    this.transport = null;
    this.last = null;
    this.messageLedger = new MessageLedger(this);
    
    this.ErrorPayload   = errorPayloadCtorFactory(this);
    this.Ack            =          ackCtorFactory(this);
    this.Message        =      messageCtorFactory(this);
    this.Request        =      requestCtorFactory(this.Message);
    this.Response       =     responseCtorFactory(this.Message);
    this.Batch          =        batchCtorFactory(this.Message);

    this.connectTime = Date.now();

    this.receiver = new Receiver(this);
    this.sender = new Sender(this);

    debugging('connection') && console.debug(this.debugLabel, `new connection#${this.id}; ${this.url}`);

    /* Create a connection config as this.options which takes into
     * account system defaults and overrides for specific urls, origins, etc.
     */
    this.options = leafMerge(
      ({ /* hardcoded defaults insulate us from missing web config */
        'connectTimeout':        90,    /* how long an initiator will try to connect to a target */
        'reconnectTimeout':      600,   /* how long an initiator will try to reconnect to a target */
        'closeTimeout':          7,     /* how long we can wait for our close message to get sent */
        'maxRTT':                60,    /* how long we can wait an ack. @todo: calculate reasonable default during connect() /wg feb 2023 */
        'allowBatch':            true,
        'maxMessagesPerBatch':   100,
        'identityUnlockTimeout': 300,
        'ttl': {
          'min': 15,
          'max': 600,
          'default': 120
        },
        'transports': [ 'socketio' ],
        'maxTransmitAttempts': 10,
      }),
      dcpConfig.dcp.connectionOptions.default,
      this.url && dcpConfig.dcp.connectionOptions[this.url.hostname],
      this.url && dcpConfig.dcp.connectionOptions[this.url.origin],
      options
    );

    /* draw out errors quickly in dev */
    if ((process.env.DCP_NETWORK_CONFIG_BUILD || dcpConfig.build) === 'debug')
    {
      this.options.maxMessagesPerBatch /= 10;

      /* short timeouts and debuggers don't get along well */
      if (usingDebugger && !process.env.DCP_NETWORK_TIMEOUTS_DEBUG)
      {
        this.options.connectTimeout         *= 10;
        this.options.reconnectTimeout       *= 10;
        this.options.lingerTimeout          *= 20;
        this.options.closeTimeout           *= 50;
        this.options.identityUnlockTimeout  *= 10;
      }
    }

    assert(0 < this.options.identityUnlockTimeout);
    assert(0 < this.options.connectTimeout);
    assert(0 < this.options.lingerTimeout);
    assert(0 < this.options.closeTimeout);
    assert(0 < this.options.ttl.min);
    assert(0 < this.options.ttl.max);
    assert(0 < this.options.ttl.default);
    this.secureLocation = determineIfSecureLocation(this);
    this.hasRef = !this.options.autoUnref;
    debugging('connection') && console.debug(this.debugLabel, 'instanciated new Connection for', this.url.href);

    this.__firstTick = true;
    process.nextTick(() => delete this.__firstTick);
  }

  /** 
   * Returns a promise which resolve when the identity keystore resolves. Extra functionality
   * is only debugging output and shortcut-return when it has already resolved.
   */
  async a$resolveIdentity()
  {
    if (!this.identity)
    {
      assert(this.identityPromise);
      debugging('connection') && console.debug(this.debugLabel, 'waiting for identity resolution');
      await this.identityPromise;
      assert(this.identity);
    }
  }
  
  /**
   * Specialize an instance of Connection for either initiator or target behaviour. Once specialized,
   * the role cannot be changed. This happens based on methods invoked; connect() or accept() cause
   * the change.
   */
  assumeRole(myRole)
  {
    assert(myRole === role.initiator || myRole === role.target);
    assert(!this.role);
    const oldLabel = this.debugLabel;

    this.role = myRole;
    if (this.role === role.target)
    {
      this.debugLabel = `connection(t:${this.id}):`;
      this.hasNtp = true;
    }
    else
    {
      this.debugLabel = `connection(i:${this.id}):`;
      this.hasNtp = false;
    }

    debugging('connection') && console.debug(this.debugLabel, oldLabel, `connection #${this.id} is ${this.role} for ${this.url}`);
  }

  /**
   * API to establish a DCP connection. Used internally by multiple APIs, including send().
   *
   * When invoked by the initiator, this method establishes the connection by connecting
   * to the target url provided to the constructor.
   *
   * @returns a Promise which is resolved when the DCP session is established, or rejected when we
   *          determine that the session can never be established; eg unreachable host, timeout, or
   *          the connection has already been closed.
   */
  async connect()
  {
    assert(this.role !== role.target);
    const that = this;

    switch(this.state.valueOf())
    {
      default:
        assert(false);
        // eslint-disable-next-line no-fallthrough
      case 'disconnected':
        this.state.set('disconnected', 'connecting');
        break;
      case 'initial':
        this.assumeRole(role.initiator);
        this.state.set('initial', 'connecting');
        break;
      case 'connecting':
      case 'established':
        return this.connectingMemo.promise;
      case 'closing': /* treat closing like closed for API. Reconnect for 'close' message will reach around */
      case 'closed':
        throw new DCPError('Connection already closed', this.closeErrorCode);
    }

    /* At this point, we need to make a new connecting memo. Either there isn't one, or the old one has
     * been resolved or rejected. The connecting memo lets us await connect on the same instance of 
     * Connection from multiple places in userland code, without mutual knowledge about that.
     */
    this.connectingMemo = { intr: {} };
    this.connectingMemo.promise = new Promise((resolve, reject) => {
      this.connectingMemo.resolve = resolve;
      this.connectingMemo.reject = reject;
    });

    /* Warning: awaiting before _reconnect breaks the linger timeout feature+test. Why? /wg oct2023 */
    if (!this.dcpsid)
    {
      await this.a$resolveIdentity();
      await a$preConnectBackoffSleep(this);
      if (!this.state.is('connecting')) /* #close can reject the promise and transition state while we are awaiting */
        throw new DCPError('connecton closed during connect', 'EPIPE');
    }

    function cantConnectHandler(error)
    {
      if (!that.dcpsid || error.code === 'ETIMEDOUT') /* half-connected; clean up */
        that.#close(error, true);
      that.connectingMemo.reject(error);
    }

    /* If _connect or _reconnect reject, the catch handler will close the connection */
    if (this.dcpsid)
      this.a$_reconnect(this.options.reconnectTimeout).then(this.connectingMemo.resolve).catch(cantConnectHandler);
    else
      this.a$_connect  (this.options.connectTimeout)  .then(this.connectingMemo.resolve).catch(cantConnectHandler);

    return this.connectingMemo.promise;
  }

  /**
   * Performs a reconnection for connections which are in the disconnected state, and
   * tries to send any in-flight or enqueued messages as soon as that happens.
   */
  async a$_reconnect(timeout)
  {
    const giveUpNow = performance.now() + (timeout * 1000);
    var interrupt = false;
    var deltaMs;
    var transport;
    var lastError;

    assert(this.dcpsid);
    debugging('connection') && console.debug(this.debugLabel, `reconnecting session ${this.dcpsid}`);
    this.connectingMemo.intr.giveUp = () => { interrupt = true; };

    /* See analogous loop in a$_connect for detailed comment */
    for (let tries = maxConnectTries;
         tries && !interrupt && (deltaMs = giveUpNow - performance.now()) >= 0; // eslint-disable-line no-unmodified-loop-condition
         tries--)
    {
      try
      {
        transport = await this.a$connectToTargetTransport(deltaMs/1000);
        if (!this.state.is('connecting')) /* #close can reject the promise and transition state while we are awaiting */
          throw new DCPError('connecton closed during target connection; cannot reconnect', 'EPIPE');
        if (!interrupt && transport)
        {
          debugging('connection') && console.debug(this.debugLabel, `reconnected via transport ${transport.name}`);
          this.replaceTransport(transport);
          break;
        }
      }
      catch(error)
      {
        debugging('connection') && console.debug(this.debugLabel, 'reconnect error:', error);
        lastError = error;
      }
    }

    if (!transport)
      throw lastError || new DCPError(`Could not reconnect to ${this.url} within ${timeout}s`, 'ETIMEDOUT');
  }

  /**
   * Private function which connects to the target and establishes the DCP session. First we establish a
   * transport-layer connection, then we exchange DCP 'connect' messages, negotiate a session (dcpsid),
   * and move to the established state.
   *
   * An internal loop causes us to establish the target transport multiple times if we somehow
   * fail to establish a DCP session right after we establish an underlying connection. This
   * would be an extremely unusual case, like turning off WiFi right in the middle of the loop.
   */
  async a$_connect(timeout)
  { 
    var presharedPeerAddress;
    var targetIdentity = await this.target.identity;
    var transport;
    const giveUpNow = performance.now() + (timeout * 1000);
    var interrupt = false;
    var deltaMs;
    var lastError;

    assert(this.role === role.initiator);
    this.connectingMemo.intr.giveUp = () => { interrupt = true; };

    if (!this.state.is('connecting')) /* #close can reject the promise and transition state while we are awaiting */
      throw new DCPError('connecton closed during target identity resolution', 'EPIPE');

    /* Loop until we can establish a session right after establishing a transport-level connection. 
     * Tries probably never needs to be >2, so is not tunable. a$connectToTargetTransport understands
     * EBO and can occupy the total connectTimeout, but if the transport comes up and immediately
     * goes down before the dcpsid can be established, we go back a few times, just in case. Each try
     * means that we have fully connected and disconnected at the transport level, so if it happens
     * a 3rd time, this isn't a sysadmin bouncing a service; it's an outage of some kind.
     */
    for (let tries = maxConnectTries;
         tries && !interrupt && (deltaMs = giveUpNow - performance.now()) >= 0; // eslint-disable-line no-unmodified-loop-condition
         tries--)
    {
      /* XXX todo - this loop is nearly identical to the one in _reconnect, except it has better error handling 
       * and calls adopt/initiate instead of replaceTransport. We should maybe unify the two. /wg nov 2023
       */
      try
      {
        transport = await this.a$connectToTargetTransport(deltaMs/1000);
        if (!this.state.is('connecting')) /* #close can reject the promise and transition state while we are awaiting */
          throw new DCPError('connecton closed during target connection', 'EPIPE');
        if (!interrupt && transport)
        {
          this.adopt(transport);
          this.dcpsid = await this.sender.initiate(); /* Side effect: set this.peerAddress to first address seen */
          break;
        }
      }
      catch(error)
      {
        lastError = error;
        if (error.code === 'EVERSION' || error.code === 'EASSERT' ||
            error.name === 'ReferenceError' || error.name === 'SyntaxError' || error.name === 'TypeError')
        {
          /* No point in retrying errors that reach here - they'll just happen again */
          debugging() && console.debug(this.debugLabel, 'Permanent failure, cannot establish DCP session' +
                                       `${this.transport ? ' over ' + this.transport.name : '.'}:`, error.message);
          break;
        }

        /* This awkward section can swallow errors, because we consider mystery errors to be the
         * result of unknown transport errors, like maybe DNS timeout something, so we try to hit them a
         * few (maxConnectTries) times before reporting the last one.
         */
        debugging(tries ? 'connection' : undefined) && console.debug(this.debugLabel, 'Could not establish DCP session' +
                                                                     `${this.transport ? ' over ' + this.transport.name : '.'}` +
                                                                     ` (up to ${tries} more tries)`, error);
      }
    }

    if (!transport || !this.dcpsid)
      throw lastError || new DCPError(`Could not connect to ${this.url} within ${timeout}s`, 'ETIMEDOUT');

    debugging('connection') && console.debug(this.debugLabel, 'dcpsid is', this.dcpsid);

    if (!this.options.strict && targetIdentity && determineIfSecureConfig())
    {
      if (false
          || typeof targetIdentity !== 'object'
          || typeof targetIdentity.address !== 'object'
          || !wallet.isAddress(targetIdentity.address))
        targetIdentity = { address: new wallet.Address(targetIdentity) }; /* map strings and Addresses to ks ducks */

      presharedPeerAddress = targetIdentity.address;
      debugging('connection') && console.debug(this.debugLabel, 'Using preshared peer address', presharedPeerAddress);
    }

    this.ensureIdentity(this.peerAddress, presharedPeerAddress);

    /* At this point, new session is valid & security checks out - make Connection instance usable */
    this.state.set('connecting', 'established'); /* established => dcpsid has been set */
    this.sender.notifyTransportReady();
    this.emit('session', this.dcpsid);
    return;
  }

  /**
   * API to unreference any objects entrained by this connection so that it does not prevent the node
   * program from exiting naturally. This does not include unreferencing the request/response dialogues
   * in the message ledger; those messages need to be individually unreferenced if that's the behaviour
   * the calling programmer needs.
   */
  unref()
  {
    if (this.connectAbortTimer)
      this.connectAbortTimer.unref();
    if (this.ref.__interval)
      clearInterval(this.ref.__interval);
    this.hasRef = false;
    return this;
  }

  /** API - see unref() */
  ref()
  {
    this.hasRef = true;
    this.ref.__interval = setInterval(() => undefined, 867530901);
    if (this.connectAbortTimer)
      this.connectAbortTimer.ref();
    return this;
  }

  /**
   * Method is invoked when the transport disconnects. Transport instance is responsible for its own
   * finalization; Connection instance is responsible for finding a new transport, resuming the
   * connection, and retransmitting any in-flight message.
   *
   * This handler isn't registered until transport adoption, which means that it plays no direct 
   * part in the transport connection or reconnection process, but could in theory get triggered after
   * transport adoption before dcpsid negotiation, etc.
   *
   * @param {object} transport    the transport instance that triggered this handler. In some cases, it
   *                              is possible that this event is not serviced until after the connection
   *                              has already acquired a new transport instance, e.g. in a Target where
   *                              the initiator switched IP address.
   */
  transportDisconnectHandler(transport)
  {
    try
    {
      if (transport !== this.transport) /* event no longer relevant */
        return;

      if (this.transport)
      {
        transport.close();
        delete this.transport;
        this.emit('disconnect', this.url); /* UI hint: "internet unavailable" */
      }

      switch(this.state.valueOf())
      {
        case 'initial':
        default:
          assert(false);
          break;
        case 'disconnected':
        case 'closing':
        case 'closed':
          return; /* transports may fire this handler more than once */
        case 'established':
        case 'connecting': /* network interrupt during re-connection attempt, keep reconnecting until connectTimeout */
          this.state.set(['established', 'connecting'], 'disconnected');
          debugging('connection') && console.debug(this.debugLabel, `Transport disconnected from ${this.url} while ${this.state}`);
          break;
      }

      if (this.options.onDemand && !this.sender.hasPendingTx())
      {
        debugging('connection') && console.debug(this.debugLabel, `Not reconnecting ${this.dcpsid} until next message`);
        return;
      }

      if (this.role === role.target)
      {
        /* targets generally can't reconnect due to NAT and more - instead we linger */
        debugging('connection') && console.debug(this.debugLabel, `Waiting for initiator to reconnect for ${this.dcpsid}`);
        return;
      }

      /* At this point, we initiate a (re)connect attempt because either
       * - we haven't connected yet,
       * - we have something to send, or
       * - we are not an on-demand connection
       */
      if (!this.state.is('connecting'))
        this.connect();
    }
    catch(error)
    {
      debugging('connection') && console.debug(this.debugLabel, 'unexpected error handling disconnect:', error);
      this.#close(error);

      if (error.code !== 'ETIMEDOUT' && error.code !== 'EPIPE')
      {
        /* Unreached unless there are bugs. */
        throw error;
      }
    }
  }

  /* Interpret and emit HTTP status codes from transports using http bearers. Note that
   * socketio does not hit this when connecting with websockets, only polling. If any
   * HTTP status codes are discovered that are directs, we rewrite this.url accordingly
   * and return a transient failure.
   */
  #interpretHttpStatusCode(error, transportName)
  {
    switch(error.httpStatus)
    {
      /* HTTP Redirect: adjust the URL and report a transient "failure" */
      case 301: case 302: case 303: case 307: case 308:
      {
        if (error.httpHeaders.hasOwnProperty('location'))
        {
          const u = new URL(error.httpHeaders.location);
          if (u.origin !== this.url.origin || u.pathname !== this.url.pathname)
          {
            this.url.href = u.origin + u.pathname;
            debugging('connection') && console.debug(this.debugLabel, `HTTP status ${error.httpStatus}; redirecting to ${this.url.href}`);
            return 'DCP_TRANSPORT_FAILURE_TRANSIENT';
          }
        }
        debugging('connection') && console.debug(this.debugLabel, `HTTP status ${error.httpStatus}; won't try again with ${transportName}`);
        return 'DCP_TRANSPORT_FAILURE_PERMANENT';
      }

      /* These errors are not transient, no point in retrying */
      case 400: case 401: case 403: case 404: case 405: case 406: case 407: case 409: case 410: case 501: case 505:
      {
        debugging('connection') && console.debug(this.debugLabel, `HTTP status ${error.httpStatus}; won't try again.`);
        return 'DCP_TRANSPORT_FAILURE_PERMANENT';
      }

      /* These errors could be transient, eg server restarting, network outage, etc. retry before giving up on the connection. */
      case 408: case 500: case 502: case 503: case 504:
        debugging('connection') && console.debug(this.debugLabel, `HTTP status ${error.httpStatus}; will try again with ${transportName}`);
        return 'DCP_TRANSPORT_FAILURE_TRANSIENT';

      /* Unknown / unexpected error. Treat as a permanent failure */
      default:
        debugging('connection') && console.debug(this.debugLabel, `Unknown HTTP status ${error.httpStatus}; won't try again with ${transportName}`);
        return 'DCP_TRANSPORT_FAILURE_PERMANENT';
    }

    throw new Error('Reached unreachable code'); // eslint-disable-line no-unreachable
  }

  /**
   * Method to interrupt a Connection's ongoing attempts. Various loops and promises can happen during
   * the connecting process; eg network timeout waits, retries, and so on. This method interrupts any of
   * those that are pending. It knows how to do this because all of those methods are (or should be!)
   * memoized in connectPromise.intr, with a "this is how you can cancel" function.
   */
  #interruptConnectionAttempt()
  {
    if (!this.connectingMemo)
      return;
    debugging('connection') && console.debug(this.debugLabel, 'interrupting connection attempt');
    for (let which in this.connectingMemo.intr)
    {
      debugging('connection') && console.debug(this.debugLabel, ' . interrupting', which);
      this.connectingMemo.intr[which]();
      delete this.connectingMemo.intr[which];
    }
  }

  /**
   * Initiators only
   *
   * Connect to a target at the transport level.
   *
   * The connection attempt will keep a node program "alive" while it is happening.
   * The `autoUnref` connectionOption and unref() methods offer ways to make this not
   * happen.
   *
   * @returns a Promise which
   * - rejects when we give up on all transports.
   * - resolves with a transport instance when we connect to one.
   */
  async a$connectToTargetTransport(connectTimeout)
  {
    const that = this;
    const availableTransports = [].concat(this.options.transports);
    const backoffTimeIter = makeEBOIterator(1, Math.max(3, Math.ceil(connectTimeout / maxConnectTries)), 1.7); /* XXX make configurable and less magical /wg Nov 2022 */
    var quitMsg = false;       /* not falsey => reject asap, value is error message */

    assert(connectTimeout);

    if (availableTransports.length === 0)
      throw new DCPError('no transports defined', 'DCPC-1014');

    /* This timer has the lifetime of the entire connection attempt. When we time out,
     * we set the quitMsg to get the retry loop to quit, then we interrupt the timer so
     * that we don't have to wait for the current backoff to expire before we notice, and
     * we expire the current attempt to connect right away as well.
     */
    const connectAbortMs = 11 + connectTimeout * 1000;
    const connectAbortTimer = this.connectAbortTimer = setTimeout(() => {
      assert(connectAbortTimer === this.connectAbortTimer);
      cleanupConnectAbortTimer();
      debugging() && console.debug(this.debugLabel, 'triggered connection abort timer');
      /* Set the quit message so that the transport connect loop exits, and interrupt anything that
       * might be delaying us from evaluating the !quitMsg loop invariant.
       */
      this.#interruptConnectionAttempt();
      quitMsg = 'connection timeout';
    }, connectAbortMs);

    if (!this.hasRef)
      this.unref();
    debugging('connection') && console.debug(this.debugLabel, `transport connection attempt will abort in ${(connectAbortMs / 1000).toFixed(2)}s if not successful`);

    /* cleanup code called on return/throw */
    function cleanupConnectAbortTimer()
    {
      debugging('connection') && console.debug(that.debugLabel, `cleanup transport connection abort timer`);
      clearTimeout(that.connectAbortTimer);
      delete that.connectAbortTimer;
    }

    /* Connect to target with a specific transport.
     * - resolves with { transport } on successful connection
     * - resolves with { error } on connection failure
     * - rejects with { error } on connection failures that are so bad we don't want to retry this transport 
     */
    function a$connectWithTransport(transportName)
    {      
      delete that.connectingMemo.intr.transportConnect;

      return new Promise((connectWithTransport_resolve, connectWithTransport_reject) => {
        const TransportClass = Transport.require(transportName);
        const transport = new TransportClass(that.target, that.options[transportName]);

        function cleanup_cwt()
        {
          for (let eventName of transport.eventNames())
            for (let listener of transport.listeners(eventName))
              transport.off(eventName, listener);
        }

        /* In the case where we have a race condition in the transport implementation, arrange things
         * so that we resolve with whatever fired last if we have a double-fire on the same pass of 
         * the event loop.
         */
        transport.on('connect',        ()      => { cleanup_cwt(); connectWithTransport_resolve({ transport }); });
        transport.on('connect-failed', (error) => { cleanup_cwt(); connectWithTransport_resolve({ error }); });
        transport.on('error',          (error) => { cleanup_cwt(); connectWithTransport_reject (error); }); /* never try transport again */

        /* memoize mechanism for connectAbortTimer (etc) to interrupt this connect attempt */
        that.connectingMemo.intr.transportConnect = function transportConnectionIntr() {
          cleanup_cwt();
          connectWithTransport_resolve({ error: new DCPError('transport connect interrupted', 'EINTR') });
          setImmediate(() => transport.close()); /* late in case this triggers synchronous events */
        };
      });
    }

    /* Loop while trying each available transport in turn. Sleep with exponential backoff between runs */
    while (!quitMsg)
    {
      nextTransport: for (let transportName of availableTransports)
      {
        try
        {
          this.emit('connectionProgress', { begin: transportName }); /* UI hint */
          const { error, transport } = await a$connectWithTransport(transportName);

          /* Have connected to the remote at the transport level - OUT */
          if (transport && !quitMsg)
          {
            debugging('connection') && console.debug(this.debugLabel, 'established underlying connection via', transportName);
            assert(!error);
            assert(transport.ready());
            delete this.connectingMemo.intr.transportConnect;
            cleanupConnectAbortTimer();
            return transport;
          }

          debugging() && console.debug(that.debugLabel, `Error connecting to ${that.url} via ${transportName};`,
                                       error?.code || error?.message);
          if (transport)
            transport.close();
          /* quitMsg can be set by connectAbortTimer, which overrides the whole connect process, not just this transport */
          if (quitMsg)
            break;

          const errorCode = error.httpStatus ? this.#interpretHttpStatusCode(error, transportName) : error.code;
          const progress  = { fail: transportName, code: errorCode };
          if (error.httpStatus)
            progress.httpStatus = error.httpStatus;
          this.emit('connectionProgress', progress);

          switch (errorCode)
          {
            case 'DCP_TRANSPORT_FAILURE_PERMANENT':
              debugging('connection') && console.debug(this.debugLabel, `${error.code} connecting to ${this.url} with ${transportName}; won't try again:`);
              availableTransports.splice(availableTransports.indexOf(transportName), 1);
              break nextTransport;

            case 'DCP_TRANSPORT_FAILURE_TRANSIENT':
              debugging('connection') && console.debug(this.debugLabel, `${error.code} connecting to ${this.url} with ${transportName}; will try again:`);
              break nextTransport;
          }
        }
        catch (impossibleError)
        {
          /* transport connection attempts should never throw. */
          debugging('connection') && console.debug(this.debugLabel, `Error connecting to ${this.url} with ${transportName}; won't try again:`, impossibleError);
          availableTransports.splice(availableTransports.indexOf(transportName), 1);
          try
          {
            this.emit('connectionProgress', { fail: transportName, error: impossibleError });
          }
          finally
          {
            cleanupConnectAbortTimer();
          }
          throw impossibleError;
        }
      }

      if (availableTransports.length === 0)
      {
        quitMsg = 'all transports exhausted';
        break;
      }

      /* Go to (interruptible) sleep for a while before trying again */
      const backoffTime = backoffTimeIter.next().value;
      const boSleepPromise = a$sleep(backoffTime);
      debugging('connection') && console.debug(this.debugLabel, 'trying again in', backoffTime.toFixed(2), 'seconds');
      this.connectingMemo.intr.boSleep = boSleepPromise.intr; /* memoize mechanism to interrupt backoff sleep for use by other "threads" */
      await boSleepPromise;
      debugging('connection') && console.debug(this.debugLabel, `finished ${backoffTime.toFixed(2)}s backoff sleep`);
      delete this.connectingMemo.intr.boSleepIntr;
    }

    /* The only way we get here is for us to discover that the connection is unconnectable - eg 
     * reject timer has expired, have run out of transports which might be able to connect, etc.
     */
    cleanupConnectAbortTimer();
    debugging('connection') && console.debug(this.debugLabel, `exit connect-retry loop; ${quitMsg} connecting to ${this.url.href}`);
    throw new DCPError(`${quitMsg} connecting to ${this.url.href}`, 'ETIMEDOUT');
  }

  /**
   * Method which must be invoked whenever a new transport needs to be assigned to the connection. 
   * If we have previously adopted a transport, we close it first, which will prevent 
   * [by transport definition] any message handlers from firing, even if the old transport instance
   * has buffered traffic.
   *
   * @param {object} transport     transport instance
   */
  adopt(transport)
  {
    if (this.transport)
      this.transport.close();

    transport.on('message', (m) => this.handleRawMessage(m));
    transport.on('end',     ()  => this.transportDisconnectHandler(transport));
    transport.on('close',   ()  => this.transportDisconnectHandler(transport));

    this.transport = transport;
  }

  /**
   * Method that gets invoked when there is a new transport available for adoption.
   * This will adjust the state of the connection, adopt the transport then tell
   * the sender to pump the message queue.
   * @param {object} transport      transport instance 
   */
  replaceTransport(transport)
  {
    const that = this;

    /* Sometimes we have the replacement available so fast that the underlying transport for the
     * transport hasn't fired yet.
     */
    if (this.state.is('established') && this.transport)
      this.transportDisconnectHandler(this.transport);

    if (this.role === role.target)
      this.state.set('disconnected', 'connecting');
    if (!this.state.is('closing'))
      this.state.set('connecting', 'established');

    this.adopt(transport);
    this.sender.notifyTransportReady(true);

    if (this.role === role.initiator)
      setImmediate(pumpTransport);

    function pumpTransport()
    {
      const request = new that.Request({ operation: 'keepalive' });
      request.unref();
      request.send().catch(error => {
        (debugging('connection') || debugging('sender')) && console.debug(that.debugLabel, `transport-pumping keepalive failed during transport replacement (${error.code || error.message})`);
        debugging() && error.code === 'EASSERT' && console.error(that.debugLabel, error);
      });
    }
  }

  /**
   * Method that must be invoked by the target to "accept" a new DCP Connection request
   * at the transport layer.
   * @param {object} transport 
   */
  async accept(transport)
  {
    assert(!this.role);
    this.assumeRole(role.target);
    await this.a$resolveIdentity();
    this.state.set('initial', 'connecting');
    this.adopt(transport);
  }

  /**
   * This method is invoked by the target when it has handled the initial connect request from
   * the initiator, which contains the peerAddress and the first half of the dcpsid (the second half is
   * populated by receiver.handleFirstRequest before being passed here). It transitions the connection 
   * into an established state at the protocol level.
   * Note - this is really not the right design for this, but it is invoked from handleFirstRequest
   *        in ./receiver.js
   *
   * @note treat as infallible
   * @param {string} dcpsid dcpsid
   */
  establishTarget(dcpsid)
  {
    assert(this.role === role.target);
    assert(this.peerAddress);
    assert(this.dcpsid === null);
    assert(dcpsid);

    this.dcpsid = dcpsid;
    this.state.set('connecting', 'established'); /* established => dcpsid has been set */
    this.emit('session', this.dcpsid);
    debugging() && console.debug(this.debugLabel, `Established new session ${this.dcpsid} with ${this.peerAddress} for ${this.url}`);
    this.sender.requestQueueService();
  }

  /**
   * Check to see if the peer address conflicts with what we have in the global identity cache;
   * it does, throw an exception.
   */
  ensureIdentity (peerAddress, presharedPeerAddress)
  {
    let idc = getGlobalIdentityCache();
    let noConflict = idc.learnIdentity(this.url, peerAddress, presharedPeerAddress);

    if (!noConflict)
      throw new DCPError(`**** Security Error: Identity address ${peerAddress} does not match the saved key for ${this.url}`, 'DCPC-EADDRCHANGE');
  }

  /**
   * Handle a message originating from the message event of the underlying transport.
   * Treat as infallible.
   *
   * Maintenance note: must not await between invocation and sendAck; other the nonce can be
   * get out of order when receiving traffic very quickly.
   *
   * @param {string} sealedMessage
   * @param {object} [signedMessage] the result of JSON.parse(sealedMessage); only needed here if we
   *                                 are trying to avoid double-parsing.   
   */
  async handleRawMessage(sealedMessage, signedMessage)
  {
    if (this.state.is('closed'))
      return;

    try
    {
      if (!signedMessage)
        signedMessage = JSON.parse(sealedMessage);
      debugging('wire') && wireLog(this.debugLabel, sealedMessage, 'recv');
      if (!signedMessage.owner || !signedMessage.body || !signedMessage.signature)
        throw new DCPError('signed message has incorrect format', 'DCPC-1022');
    }
    catch(error)
    {
      debugging() && console.error(this.debugLabel, 'connection::handleRawMessage received invalid message from peer:', error);
      this.#close(error);
    }

    if (signedMessage.body.type !== 'ack')
    {
      const dupeDetected = await this.advanceNonce(signedMessage);
      if (dupeDetected || this.state.is('closed'))
        return;
    }

    if (this.dcpsid && signedMessage.body.dcpsid)
      this.handleSignedMessage_haveSession(signedMessage);
    else
      this.handleSignedMessage_noSession(signedMessage);
  }

  /**
   * Handle a signed message before we have established a session, dispatching all requests directly to
   * receiver.handleConnectOperation.
   * Treat as infallible.
   *
   * @param signedMessage {object}       An ethereum signed message object; must contain body, owner,
   *                                     and signature properties. This function will validate that
   *                                     the signature belongs to the owner.
   */
  handleSignedMessage_noSession(signedMessage)
  {
    debugging('connection') && console.debug(this.debugLabel, `received ${signedMessage.body.type} message during session establishment; nonce:`, signedMessage.body.nonce);

    try
    {
      /* Discover the peer's address by examining the envelope of the first signed message we receive */
      if (!this.peerAddress)
      {
        this.peerAddress = new wallet.Address(signedMessage.owner);
        debugging('connection') && console.debug(this.debugLabel, 'peer is', this.peerAddress);
      }

      /* Limited validation before session - just ensure the peer signed the message */
      this.validateMessageOwner(signedMessage);

      switch (signedMessage.body.type)
      {
        case 'request':
          if (!this.state.is('closing'))
            this.receiver.handleRequest_noSession(signedMessage);
          break;
        case 'response':
          this.receiver.handleResponse_noSession(signedMessage);
          break;
        case 'ack':
          this.receiver.handleAck(signedMessage);
          break;
        case 'batch':
          throw new DCPError('batch messages are prohibited before session establishment', 'EINVAL');
        default:
          throw new DCPError(`invalid message type '${signedMessage.body.type}'`, 'EINVAL');
      }
    }
    catch(error)
    {
      if (!error.code)
        error.code = 'DCPC-1025';
      debugging() && console.error(`Error processing pre-session ${signedMessage.body.type} message:`, error);
      this.#close(error);
    }
  }

  /**
   * This method validates the message owner, signature and body before passing it onto
   * either the receiver (for a request, response or batch) or the messageLedger (for an ack).
   * If it's a request, response or batch, this method also provokes the connection to 
   * send an acknowledgement (ack) to the peer to let them know we got their message.
   * Treat as infallible.
   *
   * @param signedMessage {object}       An ethereum signed message object; must contain body, owner,
   *                                     and signature properties. This function will validate that
   *                                     the signature belongs to the owner.
   *
   * @param {string} signedMessage   JSON-encoded unvalidated message object
   */
  handleSignedMessage_haveSession(signedMessage)
  {
    debugging('connection') && console.debug(this.debugLabel, `received ${signedMessage.body.type} message ${signedMessage.body.id}; nonce:`, signedMessage.body.nonce);

    try
    {
      this.validateMessageOwner(signedMessage);
      if (signedMessage.body.dcpsid !== this.dcpsid)
        throw new Error('message has incorrect dcpsid');
      this.validateMessageBody(signedMessage);

      switch (signedMessage.body.type)
      {
        case 'request':
          if (this.state.is('established'))
            this.receiver.handleRequest_haveSession(signedMessage);
          break;
        case 'response':
          this.receiver.handleResponse_haveSession(signedMessage);
          break;
        case 'ack':
          this.receiver.handleAck(signedMessage);
          break;
        case 'batch':
          if (this.state.is('established'))
            this.receiver.onBatch(signedMessage.body);
          break;
        default:
          throw new DCPError(`invalid message type '${signedMessage.body.type}'`, 'EINVAL');
      }
    }
    catch(error)
    {
      if (!error.code)
        error.code = 'DCPC-1024';
      debugging() && console.error(`Error processing ${signedMessage.body.type} message:`, error);
      this.#close(error);
    }
  }

  /**
   * A nonce may only be used once, and is required for every non-ack message. We advance the nonce
   * every time we receive a non-ack message by sending an 'ack' message to the other end with a new
   * nonce in it. This packet also serves as confirmation of message receipt [but not action], allowing
   * the peer to sensibly retry messages it suspects may have been lost at the transport layer.
   *
   * This routine will also recognize the retransmission of the most-recently-received message and
   * transparently re-ack it, without erroneously advancing the nonce.
   *
   * @param {object} signedMessage     signed message we have just received
   *
   * @throws on fatal error conditions, including invalid nonce.
   * @returns true when signedMesage is a duplicate of the most-recently-received message
   */
  async advanceNonce(signedMessage)
  {
    var ackMessage, retval;

    assert(signedMessage.body.type !== 'ack');

    if (this.last
        && signedMessage.body.id    === this.last.signedMessage.body.id
        && signedMessage.body.nonce === this.last.signedMessage.body.nonce)
    {
      /* It's possible to receive the same message twice, if the ack was lost in transit somehow. We
       * never act on a message twice, but we will acknowledge its receipt as many times as necessary.
       * When that happens, we don't generate a new nonce [which is a side effect of instanciating Ack],
       * and we return true to indicate this was a dup.
       */
      debugging('wire') && console.debug(this.debugLabel, 'DUP!', signedMessage.body.id);
      ackMessage = this.last.ackMessage;
      retval = true;
    }
    else
    {
      /* Ensure the nonce sent by the remote matches the nonce we were expecting to find. The first
       * message we receive will not, by definition, have an associated nonce. A nonce mismatch should
       * only happen if an someone is trying to pull off a MITM attack.
       */
      if (this.last === null)
        debugging('nonce') && (this.last === null) && console.debug(this.debugLabel, 'generating first nonce');
      else if (signedMessage.body.nonce !== this.last.ackMessage.nonce)
        throw new DCPError(`nonce mismatch (${signedMessage.body.nonce} !== ${this.last.ackMessage.nonce}) in ` + this.state + ' state', 'DCPC-1026');

      ackMessage = new this.Ack(signedMessage); /* side effect: generate next nonce */
      retval = false;
    }

    this.last = {
      signedMessage, /* the last signed message we received */
      ackMessage,    /* the message generated to acknowledge its receipt */
    };

    await this.sendAck(ackMessage);
    debugging('nonce') && console.debug(this.debugLabel, 'Next received nonce should be', this.last.ackMessage.nonce);

    return retval;
  }

  /* Send an ack message if possible. Not sending is equivalent to a send failure; it will get resent
   * when the peer retries 
   */
  async sendAck(ackMessage)
  {
    var sealedAckMessage;

    if (!this.transport)
      return;

    if (this.last && this.last.ackMessage === ackMessage && this.last.sealedMessage)
      sealedAckMessage = this.last.sealedMessage;
    else
      sealedAckMessage = await ackMessage.sign(this.identity);

    /* race during sign? */
    if (this.last?.ackMessage !== ackMessage)
    {
      debugging() && console.debug(this.debugLabel, 'detected ackMessage race for ', ackMessage.messageId);
      return;
    }
    this.last.sealedAckMessage = sealedAckMessage;

    debugging('wire') && wireLog(this.debugLabel, sealedAckMessage, 'send');
    this.emit('ack', this.last.ackMessage);

    if (!this.transport)
      return;
    this.transport.send(sealedAckMessage);
  }

  /**
   * Validate that the message came from the appropriate sender. This only looks at the enveloper, it
   * does not check the signature.
   *
   * @param {object} signedMessage Ethereum-style signed message
   * @throws when the signature does not match the owner property
   * @throws when the session's peerAddress does not match the owner property
   */
  validateMessageOwner(signedMessage)
  {
    if (!this.peerAddress.eq(signedMessage.owner))
      throw new Error('received message owner does not match peer address');

    if (!signedMessage.signature)
      throw new Error('message is missing signature');

    if (!this.peerAddress.verifySignature(signedMessage.body, signedMessage.signature))
      throw new Error('message has invalid signature');
  }

  /**
   * Ensures the shaped of the signed emssage body is correct.
   */
  validateMessageBody(signedMessage)
  {
    const body = signedMessage.body;

    if (this.state.in(['established', 'closing']))
    {
      if (body.type === 'request') 
      {
        if (body.payload.validity.time === undefined)
          throw new DCPError('received message does not have a valid time in its payload', 'EINVAL');
      }
    }
  }

  /**
   * Wrapper for this.emit('end') which throws IFF the end event is emitted on the same tick as the
   * constructor ran. There is no case where a Connection can do anything useful in one tick, so
   * detecting this situation implies that we have a bug and probably one which is hanging the process
   * with an endless loop.
   */
  emitEnd()
  {
    if (this.__firstTick)
      throw new DCPError('connection end event fired on same tick as constructor', 'DCPC-1027');
    this.emit('end');
  }

  /**
   * Implements Connection.close() API.
   *
   * This method sends a close message to the peer on this pass of the event loop or later. Once the 
   * response has been received, the protocol connection is closed; once the underlying connection has
   * been confirmed closed, the session is invalidated and the promise is resolved. Any messages that 
   * were queued before calling close will be delivered before sending the ‘close’ operation. If the
   * close message is not sent in a timely manner, the connection will be forcefully closed by rejecting
   * all pending message promises and then closing the underlying connection. (Timeout is configured by
   * connectionOptions.closeTimeout).
   *
   * SPEC ERRATA: spec says message happens on next pass of the event loop. It can happen on THIS pass.
   * 
   * The basic strategy is the same for both targets and initiators, it doesn't really matter which 
   * entity is which at this point, except for disconnected sessions, where the initiator can try to
   * reconnect in order to inform the target of the close.
   *
   * Entity:CLOSER
   * - Decides we are closing (eg due to close api call)
   * - Emits 'close' event; ->closing
   * - State?
   *   - established -> yay
   *   - disconnected -> reconnect if possible
   * - Sends all messages (unless immediate mode)
   * - Immediately starts rejecting any new send() API calls
   * - Queues up 'close' message
   * - Sends all messages
   * - Wait:
   *   - If Timeout => Done
   *   - Every ack/response, checks to see if outbound message queue is empty. Yes => Done
   * - Done:
   *   - Close underlying transport
   *   - Emit 'end' event
   *
   * Entity:CLOSEE
   * - Receives 'close' message
   * - Emits 'close' event; ->closing
   * - Rejects all unsent messages
   * - Immediately starts rejecting any new send() API calls
   * - Queues up 'close' message response
   * - goto Wait:
   *
   * Any subsequent calls to Connection.send() on a will result in an error due the invalidated session.
   * Internally, we transition directly to 'closed' state for connections that aren't established yet.
   * For established sessions, we briefly transition through the 'closing' state, so that we can still
   * send and receive messages, but not via Connection.send(), only internal API.
   *
   * @param {Error}   rejectError     Error with which to reject pending transmissions and the connect
   *                                  promise.
   * @param {boolean} [immediate]     When true (default), the connection will not deliver any pending
   *                                  messages and instead immediately send the peer a 'close' request.
   */
  #close(rejectError, immediate = true)
  {
    const that = this;
    assert(rejectError instanceof Error);

    /* Already started the close process? Get out. */
    if (this.state.in(['closing', 'closed']))
      return;

    debugging('connection') && console.debug(this.debugLabel, `tearing down connection (${rejectError.message})`);
    this.closeErrorCode = rejectError.code || 'EPIPE'; /* used for future "connection already closed" exceptions - set before ->closing */

    /* No session - don't bother coordinating with peer, just clean up and get out. */
    if (!this.dcpsid)
    {
      debugging('connection') && console.debug(this.debugLabel, `using fast close path; in ${this.state} with dcpsid=${this.dcpsid}`);
      this.state.set(['initial', 'connecting'], 'closed');
      this.emitEnd();
      this.#finalize(rejectError);
      return;
    }

    assert(this.state.in(['connecting', 'established', 'disconnected']));

    const startState = this.state.valueOf();
    this.state.set(['connecting', 'established', 'disconnected'], 'closing');
    this.emitEnd();

    if (immediate || this.role === role.target || startState !== 'disconnected' || !this.dcpsid)
      doShutdown();
    else
    {
      debugging('connection') && console.debug(this.debugLabel, 'reconnecting disconnected session so we can deliver the close mesage');
      /* Reach out to disconnected target and let it know we are ending the session. Not using
       * connect() because we don't want to change state enough to let API consumer start sending
       * new messages. It's possible that we will deliver/receive previously-queued messages on this
       * path, though, and that's okay. 
       */
      this.a$_reconnect(Math.min(this.options.closeTimeout, this.options.reconnectTimeout))
        .catch(e => {
          debugging('connection') && console.debug(this.debugLabel, 'could not reconnect during close', e);
          immediate = true;
        })
        .finally(doShutdown);
    }

    function doShutdown()
    {
      that.#shutdown(rejectError, immediate);
    }
  }

  /**
   * API - close the connection. Should be treated as infallible.
   */
  close()
  {
    this.#close(new DCPError('connection closed', 'EPIPE'), false);
  }

  /**
   * For use by "friend classes" until they can be properly refactored.
   */
  __close(a,b)
  {
    this.#close(a,b);
  }

  /**
   * Finalize / free up resources used by this connection, now that it is completely
   * dead; then emit the 'end' event.
   */
  #finalize(rejectError)
  {
    assert(this.state.is('closed'));
    assert(rejectError);

    if (this.transport)
      this.transport.close();
    this.transport = false;
    this.messageLedger.failAllTransmissions(rejectError, true);
    this.dcpsid = false;
    this.peerAddress = false;
    this.sender.shutdown();
    this.unref();
    this.emit('close', rejectError);
  }

  /**
   * Handler for the DCP 'close' request. This means our peer is closing and wants us to close as well.
   *
   * This function reproduces a lot of the functionality of #close, but we don't use #close because we
   * need a sort of half-closed socket in order to be able to snap the connection shut from the API
   * consumer's POV while still sending the "yes, I heard you, I'm closing" acknowledgement back to the
   * peer.
   */
  async handleCloseRequest(req)
  {
    debugging('connection') && console.debug(this.debugLabel, 'peer asking us to close connection');

    this.closeErrorCode = 'ECONNRESET'; /* used for future "connection already closed" exceptions - must always set before ->closing */
    this.state.set('established', 'closing');
    this.emitEnd();

    try
    {
      const closeResponse = new this.Response(req);
      const nextNonce = await this.sender.a$waitConsumeNonce(this.options.closeTimeout);

      this.sender.forceClearPendingTx();
      await this.sender.deliverMessage(closeResponse, nextNonce, true);
      /* By now, we have awaited until we have a nonce and a signed message, and probably sent the
       * message on the wire via transport.sendOutOfBand(), but we don't wait around response ack etc.
       */
      debugging('connection') && console.debug(this.debugLabel, 'peer close reason:', req.payload?.data ? new this.ErrorPayload(req.payload.data) : '<unspecified>');
    }
    catch(error)
    {
      /* swallow error we don't really care about */
      debugging() && console.debug(`handleCloseRequest could not respond to ${req.payload.operation} message: ${error.message} (${error.code})`);
    }
    finally
    {
      this.#shutdown(new DCPError('connection closed', 'ECONNRESET'), true);
    }
  }    

  /**
   * Meat and potates of the close process. When we arrive here, we have already transitioned
   * to the 'closing' state and emitted the 'close' event. Now we need to decide what to do
   * with pending transmissions, make sure we (try to) notify the other end, etc. If close
   * was invoked in immediate mode, all pending sends have already been rejected once, but it's
   * still possible that one slid into the queue in the intervening time.
   *
   * We have a small (currently 7s default) time window in which we will wait for the other end
   * to respond to our close message. This is done so that we have can give good user feedback and
   * proactively clear up datastructures in large multi-connection processes (eg result submitter)
   * that would otherwise have to stay alive for the linger period. That time window is cut short by
   * observing packets on the transport layer coming back from the peer.
   *
   * Note that it is possible to transition from the disconnected stated to the closing state, and
   * in the case of a target, this means there will be no possible transport layer packets, so this
   * this wait timeout is cut short in that case, as well as the case where we haven't fully
   * established a session, and the case where we are trying to exit as quickly as possible (error?).
   */
  async #shutdown(rejectError, immediate)
  {
    const that = this;
    var pendingTxWaitResolve;

    if (this.state.is('closed')) /* Don't throw if double-trigger due to timer/message races */
      return;
    assert(this.state.is('closing'));

    if (this.connectingMemo)
    {
      this.connectingMemo.reject(rejectError);
      this.#interruptConnectionAttempt();
    }

    const shutdownEndGoal = performance.now() + (this.options.closeTimeout * 1000);
    const shutdownTimer = setTimeout(finishShutdown, (this.role === role.target ? 23 : 24) + (this.options.closeTimeout * 1000));
    if (!this.hasRef)
      shutdownTimer.unref();
    this.messageLedger.unref();

    if (immediate || !this.dcpsid || !this.transport)
    {
      setImmediate(finishShutdown);
      this.messageLedger.failAllTransmissions(rejectError);
    }
    else
    {
      const pendingTxWaitPromise = new Promise((resolve, reject) => { pendingTxWaitResolve = resolve });

      /* Wait for the outbound message queue to drain. Pending transmissions eventually get cleared when
       * the receipt of the message has been confirmed by the peer with an ack message. The observer
       * delays a tick past the transport-layer receipt so that this can happen. We also expose the
       * resolve function as pendingTxWaitResolve so that it can be used by the shutdownTimer callback to
       * clean up.
       */
      const pendingTxObserver = function pendingTxObserver() {
        setImmediate(() => {
          if (!that.sender.hasPendingTx())
          {
            /* PendingTx is empty -> time to start tearing stuff down */
            if (that.transport)
            {
              that.transport.off('message', pendingTxObserver);
              that.transport.off('drain',   pendingTxObserver);
            }
            pendingTxWaitResolve(that.state.is('closed'));
          }
        });
      };
      if (this.transport)
      {
        this.transport.on('message', pendingTxObserver);
        this.transport.on('drain',   pendingTxObserver);
      }
      pendingTxObserver();

      if (await pendingTxWaitPromise)
        return; /* timer must have fired while we were waiting for pendingTx to clear */
    }

    try
    {
      /* There could be a race where we arrive here in close state - ignore it. Also don't send a
       * close request when the reason we're closing is because the other end asked us to close. When
       * we DO send a close request, we bypass (and jettison) the rest of the pending transmissions.
       */
      if (!this.state.is('closed') && (rejectError.code !== 'ECONNRESET'))
      {
        const closeRequest = new this.Request('close').unref();
        const messageResponsePromise = this.messageLedger.addMessage(closeRequest, new Error('shutdown-stack-memo'));

        messageResponsePromise
          .catch(e => "don't care")
          .finally(finishShutdown);

        const nextNonce = await this.sender.a$waitConsumeNonce(shutdownEndGoal - performance.now()).catch(error => {
          debugging() && console.error(this.debugLabel, 'no nonce available to send close request', error);
          return 'no-nonce-shutdown';
        });
        this.sender.forceClearPendingTx();

        closeRequest.payload.data = new this.ErrorPayload(rejectError);
        if (nextNonce && this.transport)
          await this.sender.deliverMessage(closeRequest, nextNonce, true);
      }
    }
    catch (error)
    {
      debugging() && console.debug(this.debugLabel, 'Ignoring error sending close request during shutdown phase:', error);
    }

    /* Transition from closing to closed and clean up pending close timers, etc */
    function finishShutdown()
    {
      if (pendingTxWaitResolve)
        pendingTxWaitResolve(true);

      if (!that.state.is('closed'))
      {
        clearTimeout(shutdownTimer);
        that.state.set('closing', 'closed');
        that.#finalize(rejectError);
      }
    }
  }

  /**
   * @param   {object}            message     an object which is not an instance of Message which will
   *                                          be used as the arguments to the Request constructor.
   */
  /**
   * Sends a message to the connected peer. If the connection has not yet been established,
   * this routine will first invoke this.connect(). 
   * 
   * The closing and established states are very similar, but a key difference is made in this
   * routine: new Requests cannot be sent during "closing", even though new Responses are allowed.
   *
   * @param   {object<Message>}   message     instance of Message, the message to send to the peer
   * @returns {Promise}    a promise which 
   *                         - resolves to the response sent by the peer if the message is a request
   *                         - resolves to true when the message is acknowledged by the peer when
   *                           the message is not a request
   *                         - rejects with an instance of Error when the connection closes
   */
  async send(message)
  {
    assert(arguments.length === 1);

    if (!(message instanceof this.Message))
      message = new this.Request(message /* payload */);

    /* In each possible connection state, we need to enqueue the message we are sending. Usually this
     * goes to a FIFO buffer, sender.#queue, but this buffer is re-used during initial session
     * establishment by sendConnectMessage() to establish the dcpsid. In order to preserve message
     * transmission order, then, we need to memoize the order that messages were sent in, without using
     * that FIFO -- so we implement a local FIFO, preEstablishedQueue, and use it to populate the sender
     * queue immediately after the session has been established.
     */
    switch(this.state.valueOf())
    {
      case 'closing':
        if (!(message instanceof this.Response))
          throw new DCPError('cannot send non-Response message while connection is closing', this.closeErrorCode);
        // fallthrough
      case 'established':
        if (this.preEstablishedQueue.length === 0)
        { 
          /* It's plausible that connect() moves the state to established and a message gets sent juuust
           * before the preEstablishedQueue is drained. In that case, we just let it get thrown onto 
           * that queue and drained by whoever wins the connect() promise race.
           */
          this.sender.enqueue(message);
          break;
        }
        // fallthrough
      case 'initial':
        // fallthrough
      case 'disconnected':
        // fallthrough
      case 'connecting':
      {
        if (this.role === role.target)
          this.sender.enqueue(message);
        else
        {
          /* We "send" the message pushing it onto the PEQ FIFO and then shifting into the real queue
           * when the connect promise resolves. If that promise rejects, this send operation rejects and
           * the previously-sent PEQ messages will have been rejected by virtue of their promise stored
           * in the message ledger.
           */
          this.preEstablishedQueue.push(message);
          await this.connect();
          debugging('sender') && console.debug(this.debugLog, `draining ${this.preEstablishedQueue.length} messages from preEstablishdQueue`);

          /* parallel access pathways can race on the connect promise, whoever wins drains the queue, in
           * the correct order -- eg the order that send() was called, not the order that the promises
           * happened to resolve.
           */
          let qmsg;
          while ((qmsg = this.preEstablishedQueue.shift()))
            this.sender.enqueue(qmsg);
        }
        break;
      }
      case 'default':
        assert(false);
        // fallthrough
      case 'closed':
        /* Ensure we always yield so the client dev can't accidentally think their code is in a safe
         * connection-replacement message-retry loop when in fact we wind up staying on the same "thread"
         * because we don't always await here nor always return the message reference promise.
         */
        await a$sleep(0);
        throw new DCPError(`cannot send message on ${this.state} connection`, this.closeErrorCode);
    }
    
    const stackMemo = require('dcp/common/dcp-build').build === 'debug' && new Error('connection-send-stack-memo');

    return this.messageLedger.addMessage(message, stackMemo);
  }

  /**
   * Sugar API which allows us to construct and transmit a request on the current connection in a single
   * statement.
   *
   * @param {string} operation
   * @param {object} data
   * @returns {Promise<Response>} a promise which resolves to the response sent by the peer
   */
  request(operation, data)
  {
    const payload = { operation, data };
    const req = new this.Request(payload);
    return this.send(req);
  }

  /**
   * This routine returns the current time for the purposes of
   * populating the Request message payload.validity.time property.
   * 
   * @returns {Number} the integer number of seconds which have elapsed since the epoch
   */
  currentTime() {
    let msSinceEpoch;
    if (this.hasNtp) {
      msSinceEpoch = Date.now();
    } else {
      const msSinceLastReceipt = performance.now() - this.receiver.lastResponseTiming.receivedMs;
      msSinceEpoch = this.receiver.lastResponseTiming.time * 1000 + msSinceLastReceipt;
    }
    return Math.floor(msSinceEpoch / 1000);
  }

  /**
   * This method sends a keepalive to the peer, and resolves when the response has been received
   * or rejects if the connection was closed before the response was received.
   */
  keepalive() {
    const request = new this.Request({ operation: 'keepalive', data: Date.now() });
    return request.send();
  }
}

/**
 * Implement a pre-connect backoff algorithm. Backoff amount is per URL, excluding hash and search params.
 * A successful session clears the backoff amount. The sleep can be interrupted by Connection::close(), or
 * by invoking the intr() function that is a property of the returned Promise.
 *
 * @param {Connection} conn     instance of Connection we are trying to connect()
 * @returns {Promise} that resolves after the backoff sleep time, with an intr function that makes it resolve immediately.
 */
function a$preConnectBackoffSleep(conn)
{
  const pcboMemo = a$preConnectBackoffSleep.pcboMemo = (a$preConnectBackoffSleep.pcboMemo || {});
  const pcboKey = conn.url.origin + conn.url.pathname;
  const pcboCount = (pcboMemo[pcboKey] || 0) + 1;
  const pcboTime = ((Math.min(60, Math.pow(2, pcboCount - 1))) - 1)/2; /* todo: make configurable /wg oct 2023 */
  const pcboPromise = a$sleep(pcboTime);

  pcboMemo[pcboKey] = pcboCount;
  conn.on('session', () => delete pcboMemo[pcboKey]);
  conn.on('end', () => pcboPromise.intr());                  /* wake up if API calls close */
  conn.connectingMemo.intr.pcboSleepIntr = pcboPromise.intr; /* tell connection abort timer how to wake us up */
  
  debugging('connection') && console.debug(conn.debugLabel, `Pre-connect sleep for ${pcboTime}s (cache hit #${pcboCount})`);
  return pcboPromise;
}

/** 
 * Determine if we got the scheduler config from a secure source, eg https or local disk.
 * We assume tha all https transactions have PKI-CA verified.
 *
 * @note protocol::getSchedulerConfigLocation() is populated via node-libs/config.js or dcp-client/index.js
 *
 * @returns true or falsey
 */
function determineIfSecureConfig()
{
  var schedulerConfigLocation = require('dcp/protocol-v4').getSchedulerConfigLocation();
  var schedulerConfigSecure;

  if (schedulerConfigLocation && (schedulerConfigLocation.protocol === 'https:' || schedulerConfigLocation.protocol === 'file:'))
  {
    debugging('strict-mode') && console.debug(`connection: scheduler config location ${schedulerConfigLocation} is secure`); /* from casual eavesdropping */
    schedulerConfigSecure = true;
  }

  if (isDebugBuild)
  {
    debugging('strict-mode') && console.debug('connection: scheduler config location is always secure for debug builds');
    schedulerConfigSecure = 'debug';
  }

  debugging('strict-mode') && console.debug(`connection: Config Location ${schedulerConfigLocation} is ${!schedulerConfigSecure ? 'not secure' : 'secure-' + schedulerConfigSecure}`);
  return schedulerConfigSecure;
}

/**
 * Determine if a URL is secure by examinining the protocol, connection, and information about the 
 * process; in particular, we try to determine if the dcp config was securely provided, because if 
 * it wasn't, then we can't have a secure location, since the origin could be compromised.
 * 
 * "Secure" in this case means "secure against casual eavesdropping", and this information should only
 * be used to refuse to send secrets over the transport or similar.
 *
 * @returns true or falsey
 */
function determineIfSecureLocation(conn)
{
  var isSecureConfig = determineIfSecureConfig();
  var secureLocation;

  if (!isSecureConfig) /* can't have a secure location without a secure configuration */
    return null;

  if (isDebugBuild || conn.url.protocol === 'https:' || conn.url.protocol === 'tcps:')
    secureLocation = true;
  else if (conn.role === role.initiator && conn.target.hasOwnProperty('friendLocation') && conn.url === conn.target.friendLocation)
    secureLocation = 'friend';
  else if (conn.options.allowUnencryptedSecrets)
    secureLocation = 'override';
  else
    secureLocation = false;

  debugging('strict-mode') && console.debug(`connection: Location ${conn.url} is ${!secureLocation ? 'not secure' : 'secure-' + secureLocation}`);

  return secureLocation;
}
exports.Connection = Connection;
