/**
 *  @file       protocol/connection/message-ledger.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @date       January 2020
 *
 * The MessageLedger is responsible for storing receipts for messages
 * that are given to the sender. The receipts are used to resolve the
 * promise that was returned from the sender, to indicate when the message
 * is complete.
 *
 * Request  receipt promises are resolved once the response has been received.
 * Response receipt promises are resolved once the ack for the response has been received.
 */
'use strict';

const { assert } = require('dcp/common/dcp-assert');
const { role } = require('./connection-constants');
const { DCPError } = require('dcp/common/dcp-error');
const { setImmediate, setInterval, clearInterval } = require('dcp/common/dcp-timers');

const debugging = require('dcp/debugging').scope('dcp');

/** @typedef {import('./connection').Connection} Connection */

class MessageLedger {
  #receipts;
  #refCount;

  constructor(connection) {
    this.connection = connection;
    this.#receipts = new Map(); // id => { message, resolve, reject, stackMemo, hasRef }
    this.hasRef = true;

    Object.defineProperty(this, 'debugLabel', { get: () => this.connection.debugLabel });
  }

  get size()
  {
    return this.#receipts.size;
  }

  ref()
  {
    this.hasRef = true;
    return this;
  }

  unref()
  {
    this.hasRef = false;
    this.#countReference(false);

    for (let receipt of this.#receipts.values())
      receipt.hasRef = false;

    return this;
  }

  /**
   * This method is invoked by the sender upon sending a new Message.
   * It stores a receipt of the message and returns a promise that will
   * be resolved when the message's lifecycle has completed.
   *
   * The ledger entry copies the message reference so that we can guarantee correct reference counts
   * even in the case where the API developer mutates the message's while the conversation is underway.
   *
   * @param {Connection.Message} message - The message to keep a receipt of its eventual transmission
   * @param {Error} stackMemo - an instance of Error with a stack property containing (preferably starting with) API call-site.
   */
  addMessage(message, stackMemo) {
    assert(message instanceof this.connection.Message);
    assert(stackMemo instanceof Error);

    if (this.#receipts.has(message.id))
      throw new DCPError(`Duplicate transmission receipt for ${JSON.stringify(message.id)}`, 'DCPC-1010');

    return new Promise((resolve, reject) => {
      const receipt = { message, hasRef: message.isRef() && this.hasRef, resolve, reject, stackMemo };
      this.#receipts.set(message.id, receipt);
      if (receipt.hasRef)
        this.#countReference(+1);
      debugging('message-ledger') && console.debug(this.debugLabel, '+ added to ledger:     ', message.id);
    });
  }

  /**
   * Remove a message from the ledger. Must be invoked by internal functions rather than mutating
   * this.#receipts directly, so that reference counts to the event loop reference get updated properly.
   */
  removeMessage(id)
  {
    const receipt = this.#receipts.get(id);
    if (receipt.hasRef)
      this.#countReference(-1);
    this.#receipts.delete(id);
    debugging('message-ledger') && console.debug(this.debugLabel, '- removed from ledger: ', id);
  }

  /**
   * Locate a message stored inside the receipts set. Returns false if it doesn't exist.
   */
  findMessage(id)
  {
    const receipt = this.#receipts.get(id);
    if (!receipt)
      return false;
    return receipt.message;
  }

  /**
   * debug-only
   */
  dump()
  {
    return Array.from(this.#receipts);
  }

  /**
   * Debug utility to find out the status of any message ledger references for a given connection.
   * Access as connection.messageLedger.showStatus().
   */
  showStatus()
  {
    function pad(jsval, sz)
    {
      const str = String(jsval === undefined ? '-' : jsval);
      return str.padStart(sz, ' ').slice(-sz);
    }

    console.log('');
    console.log(this.debugLabel, 'message ledger', '='.padStart(85, '='));
    console.log('has reference:', this.hasRef);
    console.log('num receipts:',  this.size);
    console.log('connection state: ' + this.connection.state);
    console.log('');
    console.log(`${pad('hasRef', 6)} ${pad('msgId', 21)} ${pad('type', 12)} ${pad('oper', 12)}  ${pad('origin', 60)}`);
    console.log('-'.padStart(117, '-'));
    this.#receipts.forEach(receipt => {
      const msg = receipt.message;
      const hasRef = receipt.hasRef;
      const msgId = msg.id;
      const type = msg.constructor.name;
      const oper = msg.payload?.operation;
      const origin = (receipt.stackMemo.stack.split('\n')[1].replace(/\/.*\//,'')).slice(7)
      console.log(`${pad(hasRef, 6)} ${pad(msgId, 21)} ${pad(type, 12)} ${pad(oper, 12)}  ${pad(origin, 60)}`);
    });

    console.log('='.padStart(117, '='));
    console.log('');
  }

  /**
   * Add/Remove an event-loop reference to keep the node process alive while we're waiting for the
   * response to a message over the network. We keep one reference and use it for the lifespan of all
   * messages. The reference is reference-counted and automatically unreferenced when the count is 0.
   *
   * Message-ledger references are independant of connection references.
   *
   * @param {boolean|number} delta - false to zero the reference count, otherwise pass a number to
   *                                 increase or decrease the reference count by.
   * @returns the current reference count
   *
   * @note this.#receipts should be mutated by /adding before/ the call to this routine and /deleting
   *       after/ the call to this routine, so that the set size assertion remains true.
   */
  #countReference(delta)
  {
    assert(typeof delta === 'number' || delta === false);

    const initial = this.#refCount;
    if (delta === false)
      this.#refCount = 0;
    else
    {
      this.#refCount = delta + (this.#refCount || 0);
      if (this.#refCount < 0)
        this.#refCount = 0;
    }
    if (this.#refCount === 0)
    {
      clearInterval(this.#countReference.__timer);
      delete this.#countReference.__timer;
    }
    else if (!this.#countReference.__timer)
      this.#countReference.__timer = setInterval(() => 1, 867530900 + (this.connection.role === role.target ? 12 : 2));

    debugging('message-ledger') && debugging('verbose') && console.debug(this.connection.debugLabel, `refCount ${initial} + ${delta} = ${this.#refCount}`, (new Error().stack || '').split('\n')[4]);
    assert(this.#refCount <= this.#receipts.size || typeof this.#refCount === 'undefined');

    return this.#refCount;
  }

  /**
   * Like fulfillMessagePromise but ensures only responses are fulfilled.
   * @param {Connection.Message} message The response that we are fulfilling.
   */
  fulfillResponsePromise(message) {
    if (message instanceof this.connection.Response) {
      this.fulfillMessagePromise(message.id, true)
    }
  }

  /**
   * This method resolves
   *
   * @param {Message.id|string} id
   * @param {*|Error} value - Error instance to reject, resolves with value otherwise
   */
  fulfillMessagePromise(id, value) {
    assert(id);
    assert(value);

    if (this.#receipts.has(id)) {
      const receipt = this.#receipts.get(id);
      this.removeMessage(id);
      debugging('message-ledger') && console.debug(`${this.debugLabel} resolving message promise for ${id}`);
      receipt.resolve(value);
    } else {
      /* Do nothing, we don't mind duplicate responses */
      debugging('message-ledger') && console.debug(this.debugLabel, 'received duplicate response', id);
    }
  }

  /**
   * When a message is sent, we don't know if it has been received or not until when receive a response
   * telling us that. This routine causes us to give up on waiting to receive that response for every
   * pending message, sent or unsent. As each receipt is processed, we de-memoize it, making it safe to
   * call this function multiple times during shutdown if necessary.
   *
  * @param {Error} err
   */
  failAllTransmissions(error)
  {
    assert(error instanceof Error);
    const commonErrorStack = (new Error('fail-all-transmissions-stack-memo').stack || '').split('\n').slice(1).join('\n');

    for (let id of this.#receipts.keys())
    {
      let opts, rejectError;
      const receipt = this.#receipts.get(id);

      debugging('message-ledger') && console.debug(this.debugLabel, 'failing transmission:', id,
                                                   `<${receipt.message.type}>`, 'oper:' + receipt.message.payload?.operation);
      debugging('message-ledger') && debugging('verbose') && console.debug(this.debugLabel, receipt.stackMemo);
      this.removeMessage(id);

      /* Synthesize a rejection error that looks like the real (common) rejection error,
       * except with a stack that contains the call-site (eg send() call) that created
       * the need for this rejection, so that devs can figure out where their unhandled
       * rejections originate easily.
       */
      if (error.cause)
        opts = { cause: error.cause };
      rejectError = new (error.constructor)(error.message, opts);
      if (typeof error.lineNumber !== 'undefined') /* spidermonkey */
      {
        rejectError.lineNumber = error.lineNumber;
        rejectError.fileName   = error.fileName;
      }
      if (typeof error.code !== 'undefined')
        rejectError.code = error.code;
      rejectError.stack = (error.stack || '')
        + '\n    --------------------'
        + '\n' + commonErrorStack
        + '\n    --------------------'
        + '\n' + (receipt.stackMemo?.stack || '').split('\n').slice(1).join('\n');

      /* Rejection is delayed by one tick to ensure that the application has at least had the chance
       * to deal with the close event before they have to deal with the rejection. This way, the
       * developer can, for example, re-establish a connection on a close event and resubmit the
       * message to the new connection when the rejection arrives.
       */
      setImmediate(() => receipt.reject(rejectError));
    }
  }
}

Object.assign(module.exports, {
  MessageLedger,
});
