'use strict';

const inspect = Symbol.for('nodejs.util.inspect.custom');
const { EventEmitter }      = require('events');
const { DCPError }          = require('dcp/common/dcp-error');
const { assert, assertHas } = require('dcp/common/dcp-assert');
const { requireNative }     = require('dcp/dcp-client/webpack-native-bridge');
const { performance }  = globalThis.performance ? globalThis : requireNative('perf_hooks');
const { setImmediate } = require('dcp/common/dcp-timers');

/**
 * Synchronizer constructor. Instance objects are used to accurately manage 
 * transitions between various states. Observing calls to set (possibly via testAndSet
 * or setIf) can allow a developer to develop an accurate state transition diagram.
 * Every mutation of a Synchronizer's state causes the lastStack and lastChange properties
 * be updated. These may be safely used by API consumers. LastStack is a string, and
 * lastChange is in milliseconds, from a monotonic timer that began when the process launched.
 *
 * @param {any}         initial         initial value of the synchronizer
 * @param {Array}       assertValues    [optional] if present, assert that all set values are in this 
 *                                      array when running a debug build
 */
function Synchronizer(initial, assertValues)
{
  this._ = initial; /* current/internal state of the synchronizer is stored on this._ */
  this.lastStack = new Error().stack;
  this.lastChanged = performance.now();

  if (!assertValues)
    return;

  for (let av of assertValues)
    assert(typeof av !== 'undefined');
  
  this.assertValues = [].concat(assertValues);
  assertHas(this.assertValues, this._);
}
exports.Synchronizer = Synchronizer; // Allows VSCode to see the members of Synchronizer.
Synchronizer.prototype = Object.create(EventEmitter.prototype);
Synchronizer.prototype.constructor = Synchronizer;
Synchronizer.prototype[inspect] = function ()
{
  return `[Object Synchronizer <${this._}>]`;
};

/**
 * Factory function which makes a new Synchronizer that has the same current value as this
 * synchronizer and the same assertValues (if applicable), but not the same event listeners.
 */
Synchronizer.prototype.duplicate = function concurrency$$Synchronizer$duplicate()
{
  return new Synchronizer(this._, this.assertValues);
}

/** 
 * Set the synchronizer a given state.
 *
 * @param       old     The state the synchronizer is currently in
 * @param       neu     The new state in which to place the synchronizer
 * @throws code DCP_SYNCHRONIZER_ESYNC if the synchronizer was not in the old state
 */
Synchronizer.prototype.set = function concurrency$$Synchronizer$set(old, neu)
{
  const that = this;
  assert(typeof old !== 'undefined', typeof neu !== 'undefined');

  if (!Array.isArray(old))
    assert(old !== neu);
  else
  {
    let idx = old.indexOf(this._);
    if (idx === -1)
      throwup();

    assert(old.indexOf(neu) === -1);
    for (let state of old)
      assertHas(this.assertValues, state);

    old = old[idx];
  }

  if (this._ !== old)
    throwup();

  this._ = neu;
  this.lastStack = new Error().stack;
  this.lastChanged = performance.now();
  assertHas(this.assertValues, this._);
  this.emit('change', this._, old);

  function throwup()
  {
    if (!that.lastStack)
      throw new DCPError(`Cannot transition synchronizer from ${old}->${neu}; was in ${that._}`, 'DCP_SYNCHRONIZER_ESYNC');
    else
    {
      let lastCaller = that.lastStack.split('\n')[2].replace(/^  *at /, '');
      throw new DCPError(`Cannot transition synchronizer from ${old}->${neu}; was in ${that._} from ${lastCaller}`, 'DCP_SYNCHRONIZER_ESYNC');
    }
  }
}

/**
 * Returns a promise which resolves when this Synchronizer achieves the desired state, or
 * rejects when the Synchronizer is destroyed.
 *
 * @param   {any}       which   The state we are waiting for
 * @returns {promise}
 */
Synchronizer.prototype.until = function concurrency$$Synchronizer$until(which)
{
  var that = this;
  
  function pWrapper(resolve, reject)
  {
    if (that._ === which)
    {
      setImmediate(resolve);
      return;
    }

    function changeHandlerOne(newState)
    {
      if (newState !== which || that._ !== which)
        return;

      that.removeListener('change',  changeHandlerOne);
      that.removeListener('destroy', destroyHandler);
      resolve();
    }

    function changeHandlerMany(newState)
    {
      if (which.indexOf(newState) === -1 && which.indexOf(that._) === -1)
        return;

      that.removeListener('change',  changeHandlerMany);
      that.removeListener('destroy', destroyHandler);
      resolve();
    }

    function destroyHandler()
    {
      that.removeListener('change', changeHandlerMany);
      that.removeListener('change', changeHandlerOne);
      that.removeListener('destroy', destroyHandler);
      reject();
    }

    that.on('change',  Array.isArray(which) ? changeHandlerMany : changeHandlerOne);
    that.on('destroy', destroyHandler);
  }

  return new Promise(pWrapper);
}

/**
 * Destroy a synchronizer. Once this function has been invoked, no further operations on
 * the synchronizer are permitted.
 *
 * Causes subsequent attempts to read or write the interval state to throw code DCP_SYNCHRONIZER_EINVAL .
 */
Synchronizer.prototype.destroy = function concurrency$$Synchronizer$destroy()
{
  Object.defineProperty(this, '_', {
    get: () => { throw new DCPError('synchronizer has been destroyed', 'DCP_SYNCHRONIZER_EINVAL'); },
    set: () => { throw new DCPError('synchronizer has been destroyed', 'DCP_SYNCHRONIZER_EINVAL'); },

    configurable: false,
    enumerable:   false,
  });

  this.on('destroy', () => this.removeAllListeners());
  this.emit('destroy');
}

/** 
 * Set the synchronizer instance to a given state, providing it was previously in
 * the supplied 'old' state
 *
 * @param       old     The state the synchronizer is currently in
 * @param       neu     The new state in which to place the synchronizer
 *
 * @returns true if the synchronizer state was changed, otherwise false
 */
Synchronizer.prototype.testAndSet = function concurrency$$Synchronizer$testAndSet(old, neu)
{
  assertHas(this.assertValues, old);
  assertHas(this.assertValues, neu);

  if (this._ !== old)
    return false;
  
  this.set(old, neu);
  
  return true;
}
Synchronizer.prototype.setIf = Synchronizer.prototype.testAndSet;

/**
 * Test to see if the synchronizer is in a given state.
 * @param {any}         test    the state we're checking
 *
 * @returns {boolean} true if synchronizer was in the test state
 */
Synchronizer.prototype.test = function concurrency$$Synchronizer$test(test) {
  assertHas(this.assertValues, test);
  return test === this._;
}
Synchronizer.prototype.is = Synchronizer.prototype.test;

Synchronizer.prototype.isNot = function concurrency$$Synchronizer$isNot(test)
{
  assertHas(this.assertValues, test);
  return test !== this._;
}

Synchronizer.prototype.in = function concurrency$$Synchronizer$in(list) {
  for (let item of list)
    assertHas(this.assertValues, item);

  return list.indexOf(this._) !== -1;
}

/**
 * `valueOf` functionality for the synchronizer; provides the value of the
 * underlying current state; can be used for equality comparisons, etc.
 */
Synchronizer.prototype.valueOf = function concurrency$$Synchronizer$valueOf() {
  return this._.valueOf();
}
Synchronizer.prototype.toString = Synchronizer.prototype.valueOf;
