/**
 *  @file       protocol/message.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @author     Wes Garland, wes@distributive.network
 *  @date       January 2020, Feb 2023
 *
 *  This message class is used as a base class for requests/responses/batches
 *  within a protocol connection. It contains common fields and methods to all
 *  message types, like id and payload.
 */
'use strict';

const { assert } = require('dcp/common/dcp-assert');
const { baseMessageCtorFactory } = require('./base-message');

exports.messageCtorFactory = function messageCtorFactory(connection)
{
  assert(connection instanceof require('./connection').Connection);

  const references = new Map();
  const BaseMessage = baseMessageCtorFactory(connection); /* per-connection constructor */

  class Message extends BaseMessage
  {
    constructor(messageId)
    {
      super(messageId);
      this.payload = null;
      assert(this.constructor.type);
    }

    unref()
    {
      delete references[this];
      return this;
    }

    ref()
    {
      references[this] = true;
      return this;
    }

    isRef()
    {
      return Boolean(references[this]);
    }

    /** 
     * Messages are signed with the Ethereum message signing code as they are sealed (turned into
     * strings) for transmission over the network. We add a nonce property which was recently 
     * received from the peer, which helps mitigate against MITM or CSRF attacks. We also send an
     * ackToken, which is used to track incoming Acks which tell us that this Message has been
     * received by the peer.
     *
     * @returns {Promise<string>}    the sealed message
     */
    async sign(nonce, ackToken)
    {
      const networkObj = await this.preSign(nonce, ackToken);
      return this.connection.identity.makeSignedMessage(networkObj);
    }

    /** 
     * @see sign()
     * @returns {Promise} a promise which resolves to a basic network object that is ready for signing
     */
    async preSign(nonce, ackToken)
    {
      var networkObj;
      
      if (this.connection.identityPromise)
        await this.connection.identityPromise;
      const identity = this.connection.identity;
      await identity.unlock(null, this.connection.options.identityUnlockTimeout, true);

      networkObj          = this.toNetwork();
      networkObj.nonce    = nonce;
      networkObj.ackToken = ackToken;

      return networkObj;
    }
    
    /**
     * This method is invoked when sending a message to a peer. It uses
     * the internal data of the message and generates an object that is ready
     * to be serialized and signed.
     */
    /* eslint-disable require-await */
    toNetwork()
    {
      return {
        id:      this.id,
        dcpsid:  this.connection.dcpsid,
        type:    this.constructor.type,
        time:    this.connection.currentTime(),
        payload: this.payload,
      };
    }

    static fromNetwork(networkObj)
    {
      assert(networkObj.type === this.type);

      const neu = Object.create(this.prototype, {
        constructor: {
          value:        this,
          enumerable:   false,
          writable:     false,
          configurable: false,
        }
      });
      Object.assign(neu, networkObj);
      delete neu.nonce;
      delete neu.ackToken;

      /* Replace payload.data with the deserialized version of payload.jsonData if present */
      if (neu.payload && neu.payload.hasOwnProperty('jsonData'))
      {
        neu.payload.data = JSON.parse(neu.payload.jsonData);
        delete neu.payload.jsonData;
      }

      return neu;
    }
  }

  return Message; /* newly-made per-connection constructor */
}
