'use strict';

const { EventEmitter }  = require('events');

/**
 * API to instantiate a new transport listener.
 *
 * @constructor
 * 
 * @param {string}      transportName           The name of the transport, eg "socketio" or "webrtc"
 * @param {object}      config                  has .listen and .location
 * @param {object}      target                  the instance of Target to bind to
 * @param {object}      options                 [optional]
 *
 * @returns instance of Listener, with specifics filled in from the transport implementation
 */
exports.Listener = function transport$$Listener(transportName, config, target, options)
{
  if (arguments.length === 0) /* building transport Listener prototype */
    return;
  
  if (!transportName.match(/^[A-Za-z0-9_-]+$/))
    throw new Error('Invalid transport name: ' + transportName);

  return new (require('./' + transportName).Listener)(config, target, options);
}

exports.Listener.prototype = Object.create(EventEmitter.prototype);
exports.Listener.prototype.constructor = exports.Listener;
