/**
 *  @file       protocol/connection/message.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @date       January 2020
 *
 *  The BaseMessage is a factory for a message class that is bound
 *  to a connection instance.
 *
 *  NOTE -----  this class is a superflous bad-design hangover, where 'ack' was a special type of 
 *              message, instead of a synchronization primitive. So Ack and Message both inherit from
 *              BaseMessage. The long-term plan is to eliminate this class entirely, by further
 *              refactoring Ack until it doesn't need these methods, and then moving the remaining
 *              smarts into Message.
 *
 *              Either that or this becomes SignedMessageBody, and we move all the eth logic into
 *              here, rather than handling it in the Connection class?
 *
 *  ---- /wg feb 2023
 */

const { EventEmitter } = require('events');
const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
const dcpEnv = require('dcp/common/dcp-env');
const nanoid = ((dcpEnv.platform === 'nodejs') ? requireNative('nanoid') : require('nanoid')).nanoid;
var baseMessageSeq = 0;

exports.baseMessageCtorFactory = function baseMessageCtorFactory(connection)
{
  return class BaseMessage extends EventEmitter
  {
    constructor(messageId)
    {
      super({ captureRejections: false });

      /* BaseMessage::id gets defined as a thunk which allows us to remove the property before it is
       * ever read or written, but after reading throws an exception if anybody tries to replace it.
       * This helps us ensure that we are never doing Bad Things<tm> because we should only ever be
       * generating a message Id once, and never re-using message objects.
       */
      Object.defineProperty(this, 'id', {
        get: () => {
          const thisId = messageId || String(connection.role)[0] + `${connection.id}-${baseMessageSeq++}-${Date.now()}-${nanoid()}`;
          delete this.id;
          Object.defineProperty(this, 'id', {
            get: () => thisId,
            enumerable: true,
            configurable: false,
          });
          return this.id;
        },
        enumerable: true,
        configurable: true,
      });
    }

    /** @returns the connection associated with the constructor */
    static get connection()
    {
      return connection;
    }

    /** returns the connection associated with the object - must be same as constructor! */
    get connection()
    {
      return connection;
    }

    /* NOTE - async interface here is a wart because of one use-pattern in a subclass. */
    /* eslint-disable-next-line require-await */
    toNetwork()
    {
      throw new Error('toNetwork needs implementation outside of the base class');
    }

    static fromNetwork()
    {
      throw new Error('fromNetwork needs implementation outside of the base class');
    }    

    /**
     * Helper function to send this message.
     */
    send()
    {
      return this.connection.send(this);
    }

    async sign()
    {
      if (this.connection.identityPromise)
        await this.connection.identityPromise;
      const identity = this.connection.identity;
      await identity.unlock(null, this.connection.options.identityUnlockTimeout, true);
      return identity.makeSignedMessage(this.toNetwork());
    }
  }
}
