// @ts-check
'use strict';

const { Synchronizer } = require('dcp/common/concurrency');
const { assert } = require('dcp/common/dcp-assert');
const debugging = require('dcp/debugging').scope('worker');
const { a$sleepMs, stringify } = require('dcp/utils');
const { truncateAddress, selectiveDebug } = require('./common');

const INITIAL  = 'INITIAL';
const READY    = 'READY';
const RESERVED = 'RESERVED';
const WORKING  = 'WORKING';
const WORKDONE = 'WORKDONE';
const COMPLETE = 'COMPLETE';
const FAILED   = 'FAILED';
const FINISHED = 'FINISHED';

/** @typedef {string} opaqueId */ // 22 character base64 string
/** @typedef {import('./job-manager').JobHandle} JobHandle               */
/** @typedef {import('./job-manager').JobManager} JobManager             */
/** @typedef {import('dcp/utils/jsdoc-types').AuthMessage} AuthMessage   */
/** @typedef {import('dcp/utils/jsdoc-types').SliceMessage} SliceMessage */

/** 
 * Object use to represent a given slice inside the Supervisor. This object's shape 
 * current inherits heavily from the message payload originating from the scheduler,
 * but should not /wg dec 2020.
 *
 * Caveat lector: this documentation was created without a 100% understanding of the code.
 *                Please improve when possible.
 * 
 * The read-only properties of this object are as follows:
 * - state                      INITIAL | READY | RESERVED | WORKING | WORKDONE | COMPLETE | FAILED | FINISHED
 * - sliceNumber                the number of the slice within this job
 * - jobAddress                 the address of the job that this slice belongs to
 * - isEstimation               true when slice is used in estimation
 * - isLong                     true when slice execution longer than supervisor.options.targetTaskDurationMs ms
 * - datum                      input set element for this slice this slice of the job; could be a data: URI or it could
 *                               be a URL we need to fetch; note that fetches  are limited to worker's allow list
 * - result
 * - result.request            'complete',...
 * - result.result              return value from work function
 * - result.timeReport          { total, CPU, webGL } ms
 * - error                      error info when slice FAILED
 * - jobManager                 wrapper for the job that owns this slice
 * - resultStorageType          'values'  => we are storing individual values,
 *                                           which could be data: URIs or URLs
 *                                           at the scheduler
 *                              'pattern' => user-specified pattern for result URLs.
 *                                           Data will be uploaded via POST to the
 *                                           URL matching the pattern, provided the
 *                                           worker is allowed to access it.
 * - resultStorageParams        user-supplied POST parameters sent to the result 
 *                               storage server when using resultStorageType = pattern.
 * - resultStorageDetails       the pattern when using resultStorageType = pattern.
 * - authorizationMessage       authorization from task distributor, sent to result submitter, etc...
 * 
 * - isUnassigned               true, when in state INITIAL
 * - isReady                    true, when in state READY
 * - isReserved                 true, when in state RESERVED
 * - isWorking                  true, when in state WORKING
 * - isWorkDone                 true, when in state WORKDONE <-- work has completed
 * - isComplete                 true, when in state COMPLETE <-- work has completed successfully
 * - isFailed                   true, when in state FAILED   <-- work has failed
 * - isFinished                 true, when in state FINISHED <-- Indicates result submission has succeeded.
 *
 * - isQueued                   true, when in state INITIAL, READY
 * - isActive                   true, when in state RESERVED, WORKING, WORKDONE, COMPLETE
 * - identifier                 string 'sliceNumber.jobAddress.state'
 * - timeReport                 accessor for this.result.timeReport that updates from this.rejectedTimeReport when appropriate
 *
 * The r/w properties of this object are as follows:
 * - startTime                  time when slice execution started
 * - hasBeenRejected            when true, slice has been rejected at least once
 * - rejectedTimeReport         rejected timeReport
 * 
 * NOTE: If you ever use a property with a leading underscore you are probably making a mistake.
 *       But if you must, please ask paul, yarn, bryan or eddie for a CR.
 *
 * INITIAL  -> READY:    - when slice data has been successfully fetched
 * INITIAL  -> BROKEN:   - when slice data has not been fetched successfully
 * READY    -> RESERVED: - when a slice has been scheduled to run on a sandbox
 * RESERVED -> WORKING:  - right before Sandbox2.work is called
 * WORKING  -> WORKDONE: - right after Sandbox2.work completes successfully or not
 * WORKDONE -> COMPLETE: - when Slice2.collectResults is called and Sandbox2.work completed successfully
 * WORKDONE -> FAILED:   - when Slice2.collectResults is called and Sandbox2.work did not completed successfully
 * COMPLETE -> FINISHED: - when submitting results succeeds
 * COMPLETE -> FAILED:   - when submitting results fails
 */
class Slice
{
  /** @type {Synchronizer} */
  #state;
  /** @type {JobManager} */
  #jobManager;
  /** @type {SliceMessage} */
  #sliceMessage;
  /** @type {Promise<void>} */
  #fetchSliceDataPromise;
  /** @type {AuthMessage} */
  #authorizationMessage;
  // private objects
  #datum;
  #result;
  #error;

  /**
   * @param {JobManager} jobManager
   * @param {SliceMessage} sliceMessage
   * @param {AuthMessage} authorizationMessage
   * @param {boolean} [fetchSlices=true]
   */
  constructor (jobManager, sliceMessage, authorizationMessage, fetchSlices = true)
  {
    this.#state = new Synchronizer(INITIAL, [ INITIAL, READY, RESERVED, WORKING, WORKDONE, COMPLETE, FAILED, FINISHED ]);
    this.#jobManager            = jobManager;
    this.#sliceMessage          = { ...sliceMessage }; /** XXXpfr @todo Do we have to clone the object? Pretty sure we don't. */
    this.#fetchSliceDataPromise = Promise.resolve();
    this.#authorizationMessage  = authorizationMessage;
    this.#datum                 = null;
    this.#result                = null;
    this.#error                 = null;
    /** @type {number} */
    this.startTime              = 0;
    /** @type {boolean} */
    this.hasBeenRejected        = false;
    /** @type {{ total: number, CPU: number, webGL: number, webGPU: number }} */
    this.rejectedTimeReport     = null;
    /** @type {number} */
    this.inputDataSize = 0;
    /** @type {boolean} */
    this.overdue = false;
  
    assert(this.jobAddress === String(this.#sliceMessage.jobAddress));
    if (!this.authorizationMessage)
      throw new Error(`Undefined authorization for slice ${this.identifier}.`);
  
    /** 
     * Start loading slice datum in the background. Once these are loaded, slice state will
     * transition to READY and the slice will be ready to transition to WORKING.
     */
    if (fetchSlices)
      this.#fetchSliceDataPromise = this.fetchSliceData();
  }

  /** @type {Synchronizer} */
  get state ()        { return this.#state; }
  /** @type {number} */
  get sliceNumber ()  { return this.#sliceMessage.sliceNumber; }
  /** @type {number} */
  get cotaskCount ()  { return this.#sliceMessage.cotaskCount; }
  /** @type {string} */
  get jobAddress ()   { return this.#jobManager.address; }
  /** @type {boolean} */
  get isEstimation () { return this.#sliceMessage.isEstimationSlice; }
  /** @type {boolean} */
  get isLong ()       { return this.#sliceMessage.isLongSlice; }
  /** @type {string} */
  get datumUri ()     { return this.#sliceMessage.datumUri; }
  /** @type {JobManager} */
  get jobManager ()   { return this.#jobManager; }
  /** @type {JobHandle} */
  get jobHandle ()    { return this.#jobManager.jobHandle; }
  /** @type {string} */
  get resultStorageType () { return this.#sliceMessage.resultStorageType; }
  /** @type {string} */
  get resultStorageDetails () { return this.#sliceMessage.resultStorageDetails; }
  /** @type {Promise<void>} */
  get fetchSliceDataPromise () { return this.#fetchSliceDataPromise; }
  /** @type {AuthMessage} */
  get authorizationMessage () { return this.#authorizationMessage; }
  /** @type {SliceMessage} */
  get sliceMessage () { return this.#sliceMessage; }

  /** Read-only properties of type object. */
  get datum ()                { return this.#datum; }
  get result ()               { return this.#result; }
  get error ()                { return this.#error; }
  get resultStorageParams ()  { return this.#sliceMessage.resultStorageParams; }

  /** @type {boolean} */
  get isUnassigned () { return this.state.is(INITIAL); }
  /** @type {boolean} */
  get isReady ()      { return this.state.is(READY); }
  /**
   * Mark a slice as RESERVED to remove it from the ready list, yet still able to transition to WORKING.
   * @type {boolean}
   **/
  get isReserved ()   { return this.state.is(RESERVED); }
  /** @type {boolean} */
  get isWorking ()    { return this.state.is(WORKING); }
  /** @type {boolean} */
  get isWorkDone ()   { return this.state.is(WORKDONE); }
  /** @type {boolean} */
  get isComplete ()   { return this.state.is(COMPLETE); }
  /** @type {boolean} */
  get isFailed ()     { return this.state.is(FAILED); }
  /** @type {boolean} */
  get isFinished ()   { return this.state.is(FINISHED); }
  /** @type {boolean} */
  get isQueued ()     { return this.isUnassigned || this.isReady; }
  /** @type {boolean} */
  get isActive ()     { return this.isReserved || this.isWorking || this.isWorkDone || this.isComplete; }
  /** @type {boolean} */
  get isQueuedOrActive () { return !(this.isFailed || this.isFinished); }

  /** @type {string} */
  get identifier () {
    return `${this.sliceNumber}.${truncateAddress(this.jobAddress)}.${this.state}`;
  }
  /**
   * A unique string characterizing a slice.  Used in key-value patterns.
   * @type {string}
   **/
  get key () {
    return `${this.sliceNumber}.${this.jobAddress}`;
  }
  /** 
   * timeReport accessor that optionally updates from this.rejectedTimeReport. 
   * @type {{ total: number, CPU: number, webGL: number, webGPU: number }}
   **/
  get timeReport ()
  {
    if (!this.result)
      throw new Error('Slice result is not ready'); // Should never fire.
    if (!this.result.timeReport)
      throw new Error('Slice timeReport is not ready'); // Should never fire.
    if (this.rejectedTimeReport?.total > 0 && this.result.timeReport)
    {
      // Data collected from sandboxes that rejected this slice.
      ['total', 'CPU', 'webGL', 'webGPU'].forEach((key) => {
        if (this.rejectedTimeReport[key])
          this.result.timeReport[key] += this.rejectedTimeReport[key];
      });
      this.rejectedTimeReport = null;
    }
    return this.result.timeReport;
  }
  /**
   * dataReport accessor for the IO part of CGIO.
   * @type {{ InDataSize: number, OutDataSize: number }}
   **/
  get dataReport ()
  {
    if (!this.result)
      throw new Error('Slice result is not ready'); // Should never fire.
    if (!this.result.dataReport)
      throw new Error('Slice dataReport is not ready'); // Should never fire.
    return this.result.dataReport;
  }
  /**
   * Return the elapsed time to estimated slice completion time.
   * @type {number}
   **/
  get etaMs ()
  {
    /** @todo XXXpfr Verify the startTime logic is correct. */
    if (this.startTime === null) return 0; // slice is either COMPLETE, FINISHED or FAILED
    let etaMs = this.jobManager.emaSliceTime;
    if (this.startTime) etaMs -= (Date.now() - this.startTime);
    if (etaMs < 0) etaMs = 0;
    return etaMs;
  }

  /**
   * Clone a WORKDONE slice to re-execute.
   * Used in handleWorkReject.
   */
  cloneReady ()
  {
    assert(this.isWorkDone);
    const clonedSlice = new Slice(this.jobManager, { ...this.sliceMessage }, this.authorizationMessage, false);
    clonedSlice.#datum = this.datum;
    clonedSlice.inputDataSize = this.inputDataSize;
    clonedSlice.hasBeenRejected = this.hasBeenRejected;
    clonedSlice.rejectedTimeReport = this.rejectedTimeReport;
    clonedSlice.state.set(INITIAL, READY);
    return clonedSlice;
  }

  /**
   * Need the ability to force WORKDONE in the catch handlers in sandbox.work.
   * DANGER: Do not call except in the catch handlers in sandbox.work.
   */
  forceWorkDone ()
  {
    if (this.isWorkDone) return;
    this.#state.removeAllListeners();
    this.#state = new Synchronizer(WORKDONE, [ INITIAL, READY, RESERVED, WORKING, WORKDONE, COMPLETE, FAILED, FINISHED ]);
  }

  /** 
   * Sets the slice status to RESERVED, called to remove slice from the ready list,
   * yet still able to transition to WORKING.
   * @returns {Slice}
   */
  markAsReserved ()
  {
    this.state.set(READY, RESERVED);
    this.startTime = Date.now(); // A ready slice has a finite lifetime (e.g. 5 minutes.)
    return this;
  }

  /** Sets the slice status to WORKING, called when the slice is getting ready to be handed to a worker. */
  markAsWorking()   { this.state.set(RESERVED, WORKING); }

  /** Something went wrong, but reuse the slice. */
  unReserve ()      { this.state.set(RESERVED, READY); }

  /**
   * Sets the slice status to WORKDONE, called in sandbox.work when slice has finished executiion.
   * This needs to be set before the sandbox 'complete' event fires, or else supervisor.roundRobinSlices
   * may miss scheduling another slice on the empty sandbox slot.
   **/
  markAsWorkDone()  { this.state.set(WORKING, WORKDONE); }

  /** Sets the slice status to FINISHED, called when the slice has completed and submitted results.  */
  markAsFinished()  { this.state.set(COMPLETE, FINISHED); }

  /** Sets the slice status to FINISHED, called when the slice is being returned to scheduler by Supervisor.repoMan.  */
  repoMan()         { this.state.set(READY, FINISHED); }

  /** Hide the result when returning slices. */
  killResult ()     { this.#result = null; }

  /**
   * Fetch slice data.
   * @returns {Promise<void>}
   */
  async fetchSliceData()
  {
    return this.jobManager.fetchSliceData(this.datumUri, this)
      .then ((sliceData) => {
        debugging('slice') && console.debug(`Slice ${this.identifier} is transitioning to READY`);
        this.inputDataSize = sliceData.size;
        this.#datum = sliceData.data;
        this.state.set(INITIAL, READY);
      })
      .catch((error) => {
        selectiveDebug() && console.debug(`fetchSliceData failed for slice ${this.identifier}`, error);
        this.#error = error;
        this.jobManager.returnSlice(this, `fetchSliceData: ${error?.message}`);
        this.state.set(INITIAL, FAILED);
        throw error;
      });
  }

  /**
   * Receives a result from the scheduler.
   * When success is true, it will set the result to this.#result.
   * When success is false, it will set the error to this.#error.
   * If this.#result is populated, it is possible to set the error, but setting the result will throw.
   * If this.#error is populated, then collectResult cannot be called w/o emitting an exception.
   *
   * @param {object|Error} result         - The result from the worker sandbox or an error.
   * @param {boolean}      [success=true] - True if result is considered successful, false if error occurred.
   */
  collectResult(result, success = true)
  {
    debugging('slice') && console.debug(`collectResult for slice ${this.identifier}`, success, this.error);

    this.startTime = null;
    if (success && this.result)
      throw new Error(`Slice ${this.identifier} already has a result.`);
    if (this.error)
      throw new Error(`Slice ${this.identifier} already has an error property.`);

    if (success)
    {
      this.state.set(WORKDONE, COMPLETE); // Work completed successfully.
      this.#result = result;
    }
    else
    {
      if (this.isComplete)
        this.state.set(COMPLETE, FAILED); // Failed to successfully submit results.
      else if (this.isWorkDone)
        this.state.set(WORKDONE, FAILED); // Work did not complete successfully.
      else
        this.state.set(WORKING, FAILED); // Work really did not complete successfully.
      this.#error = result;
    }
  }

  /**
   * Create basic message object as part of the payload to send back to the result-submitter's status operation.
   * @param {string}   status               - The kind of status operation
   * @param {object}   [extraProperties={}] - Extra properties for the payload object.
   * @returns {object}
   */
  getMessage(status, extraProperties = {})
  {
    return {
      sliceNumbers:         [this.sliceNumber],
      job:                  this.jobAddress,
      authorizationMessage: this.authorizationMessage,
      status,
      ...extraProperties,
    }; 
  }

  /**
   * Create basic payload object to send back to the result-submitter's status operation.
   * @param {opaqueId} worker               - The current worker's opaqueId
   * @param {string}   status               - The kind of status operation
   * @param {object}   [extraProperties={}] - Extra properties for the payload object.
   * @returns {object}
   */
  getMessagePayload(worker, status, extraProperties = {})
  {
    return {
      worker,
      slices: [ this.getMessage(status, extraProperties) ],
    }; 
  }

  /**
   * Create slice-return payload object to send to the result-submitter's status operation.
   * @param {opaqueId} worker   - The current worker's opaqueId
   * @param  {string}  [reason] - Optional reason for the return: 'ENOPROGRESS', 'EUNCAUGHT', 'ESLICETOOSLOW', 'unknown'.
   * @return {object}
   */
  getReturnMessagePayload(worker, reason)
  {
    this.killResult();

    debugging('slice') && console.debug(`getReturnMessagePayload for slice ${this.identifier} and reason ${reason}:`, this.error);
    if (!reason) reason = this.error ? 'EUNCAUGHT' : 'unknown';
    const extraProperties = {
      isEstimationSlice: this.isEstimation,
      error:             this.error,
      reason,
    };

    return this.getMessagePayload(worker, 'return', extraProperties);
  }
}
exports.Slice = Slice;
