// NOTE - need timeout/postmessage function
/**
 * @file dcp-client/worker/sandbox.js
 *
 * A sandbox that when constructed and assigned can do work for
 * a distributed slice. A sandbox runs for a single slice at a time.
 *
 * Usage:
 *  let sandbox = new Sandbox()
 *  await sandbox.start()
 *  let results = await sandbox.run(slice)
 *
 * Debug flags:
 *  Sandbox.debugWork = true // - turns off 30 second timeout to let user debug sandbox innards more easily
 *  Sandbox.debugState = true // - logs all state transitions for this sandbox
 *  Sandbox.debugEvents = true // - logs all events received from the sandbox
 *
 * @author Matthew Palma, mpalma@kingsds.network
 *         Ryan Rossiter, ryan@kingsds.network
 * @date May 2019
 * @module sandbox
 */
/* global dcpConfig */
// @ts-check
'use strict';

const debugging = require('dcp/debugging').scope('worker');
const { assert, assertEq3 } = require('dcp/common/dcp-assert');
const DCP_ENV = require('dcp/common/dcp-env');
const { rehydrateRange } = require("dcp/dcp-client/range-object");
const { allowOriginsPurposes } = require('dcp/common/worker-constants');
const kvin = require('kvin');

let timeDilation = 1;
if (DCP_ENV.platform === 'nodejs') {
  const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
  /** Make timers 10x slower when running in niim */
  timeDilation = (requireNative('module')._cache.niim instanceof requireNative('module').Module) ? 10 : 1;
}

/**
 * Wraps console.debug to emulate debug module prefixing messages on npm.
 * @param {...any} args
 */
const debug = (...args) => {
  if (debugging()) {
    console.debug('dcp-client:worker:sandbox', ...args);
  }
};

const nanoid = require('nanoid').nanoid;

const EventEmitter = require('events');
const { fetchURI, encodeDataURI } = require('dcp/utils');
const dcp_timers = require('dcp/common/dcp-timers');

// Sandbox states
const UNREADY = 'UNREADY' // No Sandbox (web worker, saworker, etc) has been constructed yet
const READYING = 'READYING' // Sandbox is being constructed and environment (bravojs, env) is being set up
const READY_FOR_ASSIGN = 'READY_FOR_ASSIGN' // Sandbox is ready to be assigned
const ASSIGNING = 'ASSIGNING' // Sandbox is running through assigning steps
const ASSIGNED = 'ASSIGNED' // Sandbox is assigned but not working
const WORKING = 'WORKING' // Sandbox is working
const TERMINATED = 'TERMINATED'
const EVAL_RESULT_PREFIX = 'evalResult::';

class SandboxError extends Error {}
class NoProgressError extends SandboxError { constructor(...args) { super(...args); this.errorCode = 'ENOPROGRESS'; } }
class SliceTooSlowError extends SandboxError { constructor(...args) { super(...args); this.errorCode = 'ESLICETOOSLOW'; } }
class UncaughtExceptionError extends SandboxError { constructor(...args) { super(...args); this.errorCode = 'EUNCAUGHT'; } }
class RemoteFetchError extends SandboxError { constructor(...args) { super(...args); this.errorCode = 'EPERM_ORIGIN'; }}

/** @typedef {string} opaqueId */ // 22 character base64 string
/** @typedef {import('./slice').Slice} Slice                                 */
/** @typedef {import('./supervisor-cache').SupervisorCache} SupervisorCache  */
/** @typedef {import('dcp/utils/jsdoc-types').SandboxOptions} SandboxOptions */

/**
 * Public event emitter.
 * https://gitlab.com/Distributed-Compute-Protocol/dcp-docs-wes/-/blob/wip/worker/worker-events.md
 */
class SandboxHandle extends EventEmitter
{
  /** @type {{ id: number, public: { name: string, description: string, link: string }, jobAddress: string, slice: Slice }} */
  #info;

  /**
   * @constructor
   * @param {Sandbox} sandbox
   */
  constructor (sandbox)
  {
    super({ captureRejections: false });
    this.#info = sandbox.info;
  }
  /** @type {number} */
  get id ()          { return this.#info.id; }
  /** @type {{ name: string, description: string, link: string }} */
  get public ()      { return this.#info.public ?? { name: '<unassigned>', description: '', link: '' }; }
  /** @type {string} */
  get jobAddress ()  { return this.#info.jobAddress; }
  /** @type {number} */
  get sliceNumber () { return this.#info.slice?.sliceNumber ?? -1; }
}
exports.SandboxHandle = SandboxHandle;

class Sandbox extends EventEmitter {
  /**
   * A Sandbox (i.e. a worker sandbox) which executes distributed slices.
   *
   * @constructor
   * @param {object} supervisor  the instance of Supervisor that owns this sandbox
   * @param {SandboxOptions} options
   */
  constructor (supervisor, options) {
    super({ captureRejections: false });

    this.supervisor = supervisor;
    /** @type {SupervisorCache} */
    this.supervisorCache = supervisor.cache;
    /** @type {SandboxOptions} */
    this.options = {
      ignoreNoProgress: false,
      ...options,
      SandboxConstructor: options.SandboxConstructor ||
        require('./evaluators').BrowserEvaluator,
    }

    /** @type {object} */
    this.evaluatorHandle = null;
    /** @type {object} */
    this.capabilities = null;

    /** @type {string} */
    this._state = UNREADY;
    /** @type {boolean} */
    this.allocated = false;
    /** @type {number?} */
    this.progress = 100;
    /** @type {object} */
    this.progressReports = null;
    /** @type {object} */
    this.progressTimeout = null;
    /** @type {object} */
    this.sliceTimeout = null;
    /** @type {object} */
    this.rejectionData = null;

    /** @type {number?} */
    this.started = null;
    /** @type {number?} */
    this.sliceStartTime = null;
    /** @type {boolean} */
    this.requiresGPU = false;
    /** @type {string|URL} */
    this.packageURL = dcpConfig.packageManager.location

    /** @type {{ id: number, public: { name: string, description: string, link: string }, jobAddress: string, slice: Slice }} */
    this.info = {
      id:         Sandbox.getNewId(),
      public:     null,
      jobAddress: null,
      slice:      null,
    };

    /**
     * Event emitter containing info that describes the sandbox.
     * @type {SandboxHandle}
     */
    this.sandboxHandle = new SandboxHandle(this);

    this.ringMessageHandlers = [
      this.handleRing0Message,
      this.handleRing1Message,
      this.handleRing2Message,
      this.handleRing3Message,
    ];

    this.resetSliceTimeReport();
  }

  get identifier() {
    if (this.allocated)
      return `${this.id}.${this.jobAddress}.${this.state}.${this.allocated}`;
    return `${this.id}.${this.jobAddress}.${this.state}`;
  }

  static getNewId() {
    return Sandbox.idCounter++;
  }

  /** @type {number} */
  get id ()         { return this.info.id; }
  /** @type {{ name: string, description: string, link: string }} */
  get public ()     { return this.info.public; }
  /** @type {{ name: string, description: string, link: string }} */
  set public (data) { this.info.public = data; }
  /** @type {string} */
  get jobAddress () { return this.info.jobAddress; }
  /** @type {string} */
  set jobAddress (address) { this.info.jobAddress = address; }
  /** @type {Slice} */
  get slice ()      { return this.info.slice; }
  /** @type {Slice} */
  set slice (slice) { this.info.slice = slice; }
  /** @type {number} */
  get sliceNumber () { return this.slice ? this.slice.sliceNumber : -1; }

  get state () {
    return this._state
  }

  set state (value) {
    if (Sandbox.debugState) {
      console.debug(`sandbox - changing state of ${this.id}... ${this._state} -> ${value}`)
    }

    if (this.state === TERMINATED && value !== TERMINATED) {
      // For safety!
      throw new Error(`Sandbox set state violation, attepted to change state from ${this.state} to ${value}`);
    }

    this._state = value;
  }

  get isReadyForAssign () {
    return this.state === READY_FOR_ASSIGN;
  }

  get isAssigned () {
    return this.state === ASSIGNED;
  }

  get isWorking () {
    return this.state === WORKING;
  }

  get isTerminated () {
    return this.state === TERMINATED;
  }

  changeWorkingToAssigned () {
    if (this.isWorking) {
      this.state = ASSIGNED;
      this.sandboxHandle.emit('ready');
    }
  }

  setIsAssigning () {
    this.state = ASSIGNING;
  }

  /**
   * Readies the sandbox. This will result in the sandbox being ready and not assigned,
   * it will need to be assigned with a job before it is able to do work.
   *
   * @todo maybe preload specific modules or let the cache pass in what modules to load?
   * @throws on failure to ready
   */
  async start(delay = 0) {
    this.started = Date.now();
    this.state = READYING;

    if (delay > 0) await new Promise((resolve) => dcp_timers.setTimeout(resolve, delay * timeDilation));

    try {
      // RING 0
      this.evaluatorHandle = new this.options.SandboxConstructor({
        name: `DCP Sandbox #${this.id}`,
      });
      this.evaluatorHandle.onerror = this.onerror.bind(this);

      const messageHandler = this.onmessage.bind(this);
      this.evaluatorHandle.onmessage = function onmessage(event)
      {
        let data;
        if (event.data.serialized)
        {
          data = kvin.parse(event.data.message);
        }
        else
        {
          data = kvin.unmarshal(event.data);
        }
        messageHandler({ data });
      }

      const evaluatorPostMessage = this.evaluatorHandle.postMessage.bind(this.evaluatorHandle);
      this.evaluatorHandle.postMessage = function postMessage(message)
      {
        evaluatorPostMessage(kvin.marshal(message));
      }

      const ceci = this;
      this.evaluatorHandle.addEventListener('end', () => {
        debugging() && console.debug('Sandbox evaluatorHandle-end-handler:', this.identifier);
        // Enter screensaver down logic.
        this.enterSandboxHandleEndHandler = true;
        ceci.terminate(true)
      });

      // Don't let an open sockets prevent clean worker exit.
      if (this.evaluatorHandle.unref)
        this.evaluatorHandle.unref();

      // Now in RING 1

      // Now in RING 2
      await this.describe();
      this.state = READY_FOR_ASSIGN;
    } catch (error) {
      console.warn('Failed to start the sandbox -', error.message);
      this.terminate(false);
      throw error;
    }
  }

  /**
   * This will assign the sandbox with a job, loading its sandbox code
   * into the sandbox.
   *
   * @param {string} jobAddress The address of the job to assign to
   * @throws on initialization failure
   */
  async assign(jobAddress) {
    this.jobAddress = jobAddress;
    this.job = await this.supervisorCache.fetchJob(jobAddress, this.supervisor.originManager);
    /* At this point, the worker has decided that this sandbox will be associated with a specific job. 
    Therefore, we emit the SandboxHandle<job> event. */
    this.sandboxHandle.emit('job', this.supervisor.jobHandles[this.jobAddress]);

    assertEq3(this.job.address, jobAddress);
    assert(typeof this.job === 'object');
    assert(typeof this.job.requirements === 'object');
    assert(Array.isArray(this.job.dependencies));
    assert(Array.isArray(this.job.requirePath));

    // Extract public data from job, with defaults
    this.public = Object.assign({
      name:        `Anonymous Job ${this.job.address.slice(0, 6)}`,
      description: 'Discreetly helping make the world smarter.',
      link:        'https://distributed.computer/about',
    }, this.job.public);

    // Future: We may want other filename tags for appliances // RR Nov 2019

    // Important: The order of applying requirements before loading the sandbox code
    // is important for modules and sandbox code to set globals over the whitelist.
    await this.applySandboxRequirements(this.job.requirements);
    await this.assignEvaluator();
    this.state = ASSIGNED;
    this.sandboxHandle.emit('ready');
  }

  async assignEvaluator() {
    debug('Begin assigning job to evaluator');
    const ceci = this;

    return new Promise(function sandbox$$assignEvaluatorPromise(resolve, reject) {
      const message = {
        request: 'assign',
        job: ceci.job,
        sandboxConfig: dcpConfig.supervisor.sandbox,
      };

      const onSuccess = (event) => {
        // eslint-disable-next-line no-use-before-define
        ceci.removeListener('reject', onFail);
        ceci.emit('assigned', event.jobAddress);
        debug('Job assigned to evaluator');
        resolve();
      };

      const onFail = (error) => {
        // eslint-disable-next-line no-use-before-define
        ceci.removeListener('assigned', onSuccess);
        reject(error);
      };

      ceci.once('assigned', onSuccess);
      ceci.once('reject', onFail);

      ceci.evaluatorHandle.postMessage(message);
    });
  }

  /**
   * Evaluates a string inside the sandbox.
   *
   * @param {string} code - the code to evaluate in the sandbox
   * @param {string} filename - the name of the 'file' to help with debugging,
   * no longer working though?
   * @returns {Promise} - resolves with eval result on success, rejects
   * otherwise
   */
  eval(code, filename) {
    var ceci = this;
    
    return new Promise(function sandbox$$eval$Promise(resolve, reject) {
      let msgId = nanoid();
      let msg = {
        request: 'eval',
        data: code,
        filename,
        msgId, 
      }

      const eventId = EVAL_RESULT_PREFIX + msgId;

      let onSuccess = (event) => {
        ceci.removeListener('reject', onFail)
        resolve(event)
      }

      let onFail = (event) => {
        ceci.removeListener(eventId, onSuccess)
        reject(event)
      }

      ceci.once(eventId, onSuccess);
      ceci.once('reject', onFail)

      ceci.evaluatorHandle.postMessage(msg)
    })
  }

  /**
   * Resets the state of the bootstrap, without resetting the sandbox function if assigned.
   * Mostly used to reset the progress status before reusing a sandbox on another slice.
   * Must be called after @start.
   *
   * @returns {Promise} - resolves with result on success, rejects otherwise
   */
  resetSandboxState () {
    var ceci = this;

    return new Promise(function sandbox$resetSandboxStatePromise(resolve, reject) {
      let failTimeout;
      let msg = {
        request: 'resetState',
      };

      function sandbox$resetSandboxState$success () {
        if (failTimeout === false)
          return; /* already rejected */
        dcp_timers.clearTimeout(failTimeout);
        failTimeout = false;
        resolve();
      }

      ceci.once('resetStateDone', sandbox$resetSandboxState$success);

      failTimeout = dcp_timers.setTimeout(function sandbox$resetSandboxState$fail() {
        if (failTimeout === false)
          return; /* already resolved */
        
        ceci.removeListener('resetStateDone', sandbox$resetSandboxState$success);
        ceci.terminate(false);
        failTimeout = false;

        reject(new Error('resetState never received resetStateDone event from sandbox'));
      }, 3000 * timeDilation); /* XXXwg need tuneable */

      assert(ceci.evaluatorHandle); // It is possible that ceci.terminate nulls out evaluatorHandle before getting here.
      ceci.evaluatorHandle.postMessage(msg);
    });
  }

  /**
   * Sends a post message to describe its capabilities.
   *
   * Side effect: Sets the capabilities property of the current sandbox.
   *
   * @returns {Promise} Resolves with the sandbox's capabilities. Rejects with
   * an error saying a response was not received.
   * @memberof Sandbox
   */
  describe() {
    debug('Beginning to describe evaluator');
    var ceci = this;
    
    return new Promise(function sandbox$describePromise(resolve, reject) {
      if (ceci.evaluatorHandle === null) {
        return reject(new Error('Evaluator has not been initialized.'));
      }

      /**
       * Opted to create a flag for the describe response being received so that
       * we don't have to *hoist* the timeout's id to clear it in the response
       * handler.
       */
      let didReceiveDescribeResponse = false;
      const describeResponseHandler = (data) => {
        didReceiveDescribeResponse = true;
        const { capabilities } = data;
        if (typeof capabilities === 'undefined') {
          reject(
            new Error('Did not receive capabilities from describe response.'),
          );
        }
        ceci.capabilities = capabilities;
        debug('Evaluator has been described');
        resolve(capabilities);
      };
      ceci.once('describe', describeResponseHandler); 

      const describeResponseFailedHandler = () => {
        if (!didReceiveDescribeResponse) {
          ceci.removeListener('describe', describeResponseHandler);
          ceci.terminate(false);
          reject(
            new Error(
              'Describe message timed-out. No describe response was received from the describe command.',
            ),
          );
        }
      };

      const message = {
        request: 'describe',
      };

      // Arbitrarily set the waiting time.
      dcp_timers.setTimeout(describeResponseFailedHandler, 6000 * timeDilation); /* XXXwg need tuneable */
      assert(ceci.evaluatorHandle); // It is possible that ceci.terminate nulls out evaluatorHandle before getting here.
      ceci.evaluatorHandle.postMessage(message);
    });
  }

  /**
   * Passes the job's requirements object into the sandbox so that the global
   * access lists can be updated accordingly.
   *
   * e.g. disallow access to OffscreenCanvas without
   * environment.offscreenCanvas=true present.
   *
   * Must be called after @start.
   *
   * @returns {Promise} - resolves with result on success, rejects otherwise
   */
  applySandboxRequirements(requirements) {
    var ceci = this;
    
    return new Promise(function sandbox$applySandboxRequirementsPromise(resolve, reject) {
      const message = {
        requirements,
        request: 'applyRequirements',
      };
      let wereRequirementsApplied = false;

      function sandbox$applyRequirements$success() {
        wereRequirementsApplied = true;
        resolve();
      };

      ceci.once('applyRequirementsDone', sandbox$applyRequirements$success);

      assert(typeof message.requirements === 'object');
      ceci.evaluatorHandle.postMessage(message);

      dcp_timers.setTimeout(function sandbox$finishApplySandboxRequirements() {
        if (!wereRequirementsApplied) {
          ceci.removeListener('applyRequirementsDone', sandbox$applyRequirements$success);
          ceci.terminate(false);
          reject(
            new Error(
              'applyRequirements never received applyRequirementsDone response from sandbox',
            ),
          );
        }
      }, 3000 * timeDilation); /* XXXwg needs tunable */
    });
  }

  /**
   * Executes a slice received from the supervisor.
   * Must be called after @start.
   *
   * @param {Slice} slice - bare minimum data required for the job/job code to be executed on
   * @param {number} [delay = 0] the delay that this method should wait before beginning work, used to avoid starting all sandboxes at once
   *
   * @returns {Promise} - resolves with result on success, rejects otherwise
   */

  async work (slice, delay = 0) {
    var ceci = this;

    if (!ceci.isAssigned) {
      throw new Error("Sandbox.run: Sandbox is not ready to work, state=" + ceci.state);
    }

    ceci.state = WORKING;
    ceci.slice = slice;
    assert(slice);

    this.sandboxHandle.emit('slice', slice.sliceNumber);

    // cf. DCP-1720
    this.resetSliceTimeReport();
    
    // Now wait for the delay if provided, prevents many sandboxes starting at once from crashing the supervisor
    if (delay > 0) await new Promise(resolve => dcp_timers.setTimeout(resolve, (delay + 1) * timeDilation));
    if (!ceci.isWorking) return; // sandbox.terminate could have been called during the delay timeout

    // Prepare the sandbox to begin work
    // will be replaced by `assign` message that should be called before emitting a `work` message
    if (ceci.jobAddress !== slice.jobAddress) {
      throw new Error(`Sandbox.run: Sandbox is already assigned and jobAddress doesn't match previous (${ceci.jobAddress} !== ${slice.jobAddress})`);
    }

    let sliceHnd = { job: ceci.public, sandbox: ceci };
    await ceci.resetSandboxState();
    if (!ceci.slice) {
      console.error(`Slice for job ${ceci.jobAddress} vanished during work initialization - aborting`);
      return;
    }

    let inputDatum;
    let dataError = false;
    try {
      if (ceci.slice.datumUri)
        inputDatum = await fetchURI(ceci.slice.datumUri, this.supervisor.originManager, allowOriginsPurposes.fetchData);
      else {
        let { mro } = await ceci.supervisorCache.fetchJob(
          ceci.jobAddress,
          this.supervisor.originManager
        );
        const ro = rehydrateRange(mro);
        // -1 to prevent an OBOE since slice numbers start at 1.
        inputDatum = ro[ceci.slice.sliceNumber - 1];
      }
    } catch (err) {
      dataError = err;
      if(err.code === 'EPERM_ORIGIN')
        dataError.errorCode = 'EPERM_ORIGIN'
      else
        dataError.errorCode = 'EUNCAUGHTERROR'
      ceci.emit('workEmit', {
        eventName: 'error',
        payload: {
          message: dataError.message,
          stack:dataError.stack,
          name: ceci.public.name
        }
      });
    }

    debugging('sandbox') && debug(`Fetched datum: ${inputDatum}`);

    if (!ceci.slice) {
      console.error(`Slice for job ${ceci.jobAddress} vanished after data fetch - aborting`);
      return;
    }

    ceci.resetProgressTimeout();
    ceci.resetSliceTimeout();

    return new Promise(function sandbox$$workPromise(resolve, reject) {
      function sandbox$$work$onSuccess (event) {
        ceci.removeListener('reject', sandbox$$work$onFail)
        resolve(event)
      };

      function sandbox$$work$onFail (err) {
        ceci.removeListener('resolve', sandbox$$work$onSuccess)
        reject(err)
      };

      ceci.once('resolve', sandbox$$work$onSuccess);

      ceci.once('reject', sandbox$$work$onFail);

      ceci.sliceStartTime = Date.now();
      ceci.progress = null;
      ceci.progressReports = {
        last: undefined,
        lastDeterministic: undefined,
      };

      ceci.resetProgressTimeout();
      ceci.resetSliceTimeout();
      ceci.emit('start', sliceHnd);
      
      if(dataError){
        ceci.removeListener('resolve', sandbox$$work$onSuccess);
        ceci.removeListener('reject', sandbox$$work$onFail);
        dcp_timers.setTimeout(() => reject(dataError), 0)

      } else {
        ceci.evaluatorHandle.postMessage({
          request: 'main',
          data: inputDatum,
        })
      }
    })
    .then(async function sandbox$$work$then(event) {
      debugging() && console.debug('Sandbox: sliceFinish', ceci.jobAddress, ceci.slice?.sliceNumber, event?.timeReport);
      ceci.sandboxHandle.emit('sliceEnd', ceci.slice?.sliceNumber); 
      ceci.emit('complete', ceci.jobAddress);

      ceci.changeWorkingToAssigned();
      ceci.slice = false;
      return event;
    })
    .catch((err) => {  
      if (err.name === 'EWORKREJECT') {
        this.rejectionData = err;
        this.rejectionData.timeReport = this.sliceTimeReport;
        this.emit('rejectedWorkMetrics', this.rejectionData);
        delete this.rejectionData;
      } else { // sandbox termination for rejected work happens in Supervisor.handleRejectedWork
        // Ceci is the reject callback for when the slice throws an error
        ceci.terminate(false);
      }

      ceci.supervisor.worker.emit('error', err, 'slice');

      if (err instanceof NoProgressError) {
        ceci.emit('workEmit', {
          eventName: 'noProgress',
          payload: {
            timestamp: Date.now() - ceci.sliceStartTime,
            data: ceci.slice.datumUri,
            progressReports: ceci.progressReports,
          }
        });
      }
      throw err;
    });
  }

  resetProgressTimeout() {
    if (this.progressTimeout) {
      dcp_timers.clearTimeout(this.progressTimeout);
      this.progressTimeout = null;
    }

    this.progressTimeout = dcp_timers.setTimeout(() => {
      if (this.options.ignoreNoProgress) {
        return console.warn("ENOPROGRESS silenced by localExec: In a remote worker, this slice would be stopped for not calling progress frequently enough.");
      }

      this.emit('reject', new NoProgressError(`No progress event was received in the last ${dcpConfig.supervisor.sandbox.progressTimeoutMs / 1000} seconds.`));
    }, +dcpConfig.supervisor.sandbox.progressTimeoutMs * timeDilation);
  }

  resetSliceTimeout() {
    if (this.sliceTimeout) dcp_timers.clearTimeout(this.sliceTimeout);

    this.sliceTimeout = dcp_timers.setTimeout(() => {
      if (Sandbox.debugWork) return console.warn("Sandbox.debugWork: Ignoring slice timeout");

      this.emit('reject', new SliceTooSlowError(`Slice took longer than ${dcpConfig.supervisor.sandbox.sliceTimeoutMs / 1000} seconds.`));
    }, +dcpConfig.supervisor.sandbox.sliceTimeoutMs * timeDilation);
  }
  
  async handleRing0Message(data) {
    debugging('event:ring-0') && debug('event:ring-0', data);
    //handling a true ring 0 message
    switch (data.request) {
      case 'scriptLoaded':
        if(data.result !== "success") {
          this.onerror(data);
        }
        break;
      case 'error':
        // Warning: rejecting here with just event.data.error causes issues
        // where the reject handlers modify the object so it interferes with the
        // workEmit event payload, wrapping in an Error instance copies the values
        let e = new Error(
          data.error.message,
          data.error.fileName,
          data.error.lineNumber);
        e.stack = data.error.stack;
        e.name = data.error.name;
        
        if (this.listenerCount('reject') > 0) {
          this.emit('reject', e);
        } else {
          // This will happen if the error is thrown during initialization
          throw e;
        }

        break;
      default:
        let error = new Error('Received unhandled request from sandbox: ' + data.request + '\n\t' + JSON.stringify(data));
        console.error(error);
        break;   
    }
  }

  async handleRing1Message(data) {
    switch (data.request) {
      case 'applyRequirementsDone':
        // emit internally
        this.emit(data.request, data)
        break;
      default:
        let error = new Error('Received unhandled request from sandbox ring 1: ' + data.request + '\n\t' + JSON.stringify(data));
        console.error(error)
        break; 
    }
  }

  async handleRing2Message(data) {
    debugging('event:ring-2') && debug('event:ring-2', data);
    switch (data.request) {
      case 'dependency': {
        let moduleData;
        try {
          moduleData = await this.supervisorCache.fetchModule(data.data);
        } catch (error) {
          /*
           * In the event of an error here, we want to let the client know there was a problem in
           * loading their module. However, there hasn't yet been an actual slice assigned to the sandbox.
           * Therefore, we assign 'slice 0' to the sandbox, a slice that will never exist, and is used
           * purely for this purpose. 
          */
          if (!this.slice)
            this.slice = {
              jobAddress: this.jobAddress,
              sliceNumber: 0,
            };

          const payload = {
            name: error.name,
            timestamp: error.timestamp,
            message: error.message,
          };

          this.emit('workEmit', {
            eventName: 'error',
            payload,
          });
          this.emit('reject', error);
          break;
        }
        this.evaluatorHandle.postMessage({
          request: 'moduleGroup',
          data: moduleData,
          id: data.id,
        });
        break;
      }
      case 'error':
        /*
         * Ring 2 error messages will only fire for problems inside of the worker that are separate from
         * the work function. In most cases there are other handlers for situations where 'error' may be emitted
         * such as timeouts if the expected message isn't recieved. Thus, we will output the error, but nothing else.
         */
        console.error(data.error);
        break;
      case 'describe':
      case 'evalResult':
      case 'resetStateDone':
      case 'assigned':
        // emit internally
        this.emit(data.request, data);
        break;
      case 'reject':
        // emit internally
        this.emit(data.request, data.error);
        break;
      default: {
        const error = new Error(
          `Received unhandled request from sandbox ring 2. Data: ${JSON.stringify(
            data,
            null,
            2,
          )}`,
        );
        console.error(error);
        break;
      }
    }
  }

  async handleRing3Message(data) {
    debugging('sandbox-ring-3') && console.debug('sandbox-ring-3 data:', data);
    switch (data.request) {
      case 'complete':
        dcp_timers.clearTimeout(this.progressTimeout);
        dcp_timers.clearTimeout(this.sliceTimeout);
        this.progressTimeout = this.sliceTimeout = null;

        if (this.progress === null) {
          if (this.options.ignoreNoProgress) {
            console.warn("ENOPROGRESS silenced by localExec: Progress was not called during this slice's execution, in a remote sandbox this would cause the slice to be failed");
          } else {
            // If a progress update was never received (progress === null) then reject
            this.emit('reject', new NoProgressError('Sandbox never emitted a progress event.'));
            this.rejectionData.timeReport = this.sliceTimeReport;
            this.emit('rejectedWorkMetrics', this.rejectionData);
            delete this.rejectionData; 
            break;
          }
        }
        
        this.progress = 100;
        this.completeData = data;

        this.completeData.timeReport = this.sliceTimeReport;
        this.emit('resolve', this.completeData);
        delete this.completeData;
        break;
      case 'progress':
        let { progress, indeterminate, throttledReports, value } = data;
        this.progress = progress;
        const progressReport = {
          timestamp: Date.now() - this.sliceStartTime,
          progress,
          value,
          throttledReports,
        }
        this.progressReports.last = progressReport;
        if (!indeterminate) {
          this.progressReports.lastDeterministic = progressReport;
        }

        this.resetProgressTimeout();
        
        this.sandboxHandle.emit('progress', data.indeterminate || data.progress < 0 || data.progress > 100 ? undefined : data.progress);
        break;

      case 'noProgress':
        let { message } = data;

        this.emit('reject', new NoProgressError(message));
        break;
      case 'console':
        data.payload.message = kvin.marshal(data.payload.message); 
        this.emit('workEmit', {
          eventName: 'console',
          payload: data.payload, 
        });
        break;

      case 'emitEvent':/* ad-hoc event from the sandbox (work.emit) */
        this.emit('workEmit', {
          eventName: 'custom',
          payload: data.payload
        })
        break;
      case 'measurement':
        this.updateTime(data);
        break;
      case 'sandboxError': /* the sandbox itself has an error condition */
      {
        this.emit('sandboxError', data.error);
        break;
      }
      case 'workError': { /* the work function threw/rejected */
        this.emit('workEmit', {
          eventName: 'error',
          payload: data.error,
        });

        // Warning: rejecting here with just .data.error causes issues
        // where the reject handlers modify the object so it interferes with the
        // workEmit  payload, wrapping in an Error instance copies the values
        const wrappedError = new UncaughtExceptionError(
          data.error.message,
          data.error.fileName,
          data.error.lineNumber,
        );
        wrappedError.stack = data.error.stack;
        wrappedError.name = data.error.name;

        if (this.listenerCount('reject') > 0) {
          this.emit('reject', wrappedError);
        } else {
          // This will happen if the error is thrown during initialization
          throw wrappedError;
        }
        break;
      }
      default:
        let error = new Error('Received unhandled request from sandbox ring 3: ' + data.request + '\n\t' + JSON.stringify(data));
        console.error(error)
        break; 
    }
  }

  /**
   * Handles progress and completion events from sandbox.
   * Unless explicitly returned out of this function will re-emit the event
   * where the name of the event is event.data.request.
   *
   * @param {object} event - event received from the sandbox
   */
  async onmessage(event) {
    debugging('event') && debug('event', event);
    if (Sandbox.debugEvents) {
      console.debug('sandbox - eventDebug:', {
        id: this.id,
        state: this.state,
        event: JSON.stringify(event)
      })
    }

    const { data } = event;
    const ringLevel = data.ringSource

    // Give the data to a handler depending on ring level
    if (ringLevel === -1) {
      console.error('Message sent directly from raw postMessage. Terminating worker...');
      console.debug(event);
      return this.terminate(true);
    } else {
      const handler = this.ringMessageHandlers[ringLevel];
      if (handler) {
        handler.call(this, data.value);
      } else {
        console.warn(`No handler defined for message from ring ${ringLevel}`);
        console.debug(event);
      }
    }
  }

  /**
   * Error handler for the internal sandbox.
   * Currently just logs the errors that the sandbox spits out.
   */
  onerror(event) {
    console.error('Sandbox emitted an error:', event);
    this.terminate(true, true);
  }

  /**
   * Clears the timeout and terminates the sandbox and sometimes emits a reject event.
   *
   * @param {boolean} [reject = true] - if true emit reject event
   * @param {boolean} [immediate = false] - passed to terminate, used by standaloneWorker to immediately close the connection
   */
  terminate (reject = true, immediate = false) {
    debugging() && console.debug(`Terminate sandbox ${this.identifier}`);
    const oldState = this.state;
    this.state = TERMINATED;
    
    dcp_timers.clearTimeout(this.progressTimeout);
    dcp_timers.clearTimeout(this.sliceTimeout);
    this.progressTimeout = this.sliceTimeout = null;
    
    if (this.evaluatorHandle && typeof this.evaluatorHandle.terminate === 'function') {
      try {
        this.evaluatorHandle.terminate(immediate);
        this.evaluatorHandle = null;
      } catch (e) {
        console.error(`Error terminating sandbox ${this.id} (${oldState}):`, e);
      } finally {
        this.emit('terminate', this);
      }
    }

    if (reject) {
      this.emit('reject', new Error(`Sandbox ${this.id} (${oldState}) was terminated.`));
    }

    this.sandboxHandle.emit('end');
  }

  /**
   * Attempts to stop the sandbox from doing completing its current
   * set of work without terminating the working.
   */
  stop () {
    throw new Error('Sandbox.stop is not yet implemented.')
  }

  /**
   * ringNPostMessage can send a `measurement` request and update these
   * totals.
   */
  updateTime (measurementEvent) {
    ['total', 'CPU', 'webGL', 'webGPU'].forEach((key) => {
      if (measurementEvent[key]) this.sliceTimeReport[key] += measurementEvent[key];
    })
  }

  resetSliceTimeReport () {
    this.sliceTimeReport = {
      total: 0,
      CPU: 0,
      webGL: 0,
      webGPU: 0,
    }
  }
}

Sandbox.idCounter = 1;
Sandbox.debugWork = false;
Sandbox.debugState = false;
Sandbox.debugEvents = false;

exports.Sandbox = Sandbox;
exports.SandboxError = SandboxError;
exports.NoProgressError = NoProgressError;
exports.SliceTooSlowError = SliceTooSlowError;
exports.UncaughtExceptionError = UncaughtExceptionError;
exports.RemoteFetchError = RemoteFetchError;
