const debugging = require('dcp/debugging').scope('dcp');

var schedulerConfigLocation; /* memo re where dcp-config originated; intended to be authoritative but possible to spoof */

  /**
   * This method clears the identity cache that is used by Connection.connect() to track (URL, identity) pairs.
   * 
   * @param {wallet.Keystore | wallet.Address | true} selector - Corresponding cache entry to clear, or all if true.
   */
exports.clearIdentityCache = function  clearIdentityCache(arg) {
  if (true) /* eslint-disable-line no-constant-condition */
  {
    const identityCache = exports.getGlobalIdentityCache();
    if (arg === true) {
      identityCache.clearAll();
    } else if (arg instanceof wallet.Address) {
      identityCache.clearIdentity(arg);
    } else if (arg instanceof wallet.Keystore) {
      identityCache.clearIdentity(arg.address);
    } else {
      throw new Error('Invalid input for clearIdentityCache()');
    }
  }
};

const utf8Re = /UTF-?8/i;
const haveUnicode = false
      || isBrowserPlatform
      || utf8Re.test(getenv('LANG'))
      || utf8Re.test(getenv('LANGUAGE'))
      || utf8Re.test(getenv('LC_ALL'));

/** 
 * Fancy debug log function to help visualize DCP message flow. Not cheap.
 *
 * @param {string} debugLabel
 * @param {string} sealedMessage    the message we are logging; expected to be in stringified-signed-message format
 * @param {string} dir              'send' or 'recv'
 * @param {string} [label]          an optional label for the message, default is caller's function name
 */
exports.wireLog = function wireLog(debugLabel, sealedMessage, dir, label)
{
  const process = require('process');
  const { getenv } = require('dcp/common/dcp-env');
  const cols = Math.max(100, Number(getenv('COLUMNS')) || process.stdout?.columns || 100);
  var arrow, destLabel, messageBody, msgInfo = '';
  const signedMessage = JSON.parse(sealedMessage);
  debugLabel = debugLabel.padEnd(20, ' ').slice(0,20);
  
  destLabel = signedMessage?.owner || '<peer>';
  if (signedMessage?.body?.dcpsid)
    destLabel = destLabel.slice(0,8) + ':' + signedMessage.body.dcpsid.slice(0,8);
  destLabel = destLabel.padEnd(17, ' ').slice(0, 17);
  
  if (!label)
  {
    const callerNameMatches = new Error().stack.split('\n')[2].match(/^\s+at\s+([A-Za-z0-9_$]+)(.*\.([A-Za-z0-9_$]+)\s)?/) 
                              ?? new Error().stack.split('\n')[2].match(/^(?:async\*)?(?<label>[a-zA-Z0-9_$]+)(?:\/<)?@webpack/);
    label = (callerNameMatches[3] || callerNameMatches[1]);
  }
  label = label.padEnd(21, ' ').slice(0, 21);
  
  switch(dir)
  {
    case 'recv':
      arrow = haveUnicode ? '\u2190' : '<-';
      break;
    case 'send':
      arrow = haveUnicode ? '\u2192' : '->';
      break;
    case 'expn':
      arrow = '-';
      break;
    default:
      arrow = haveUnicode ? '\ud83d\udca9' : '??';
      break;
  }

  messageBody = signedMessage?.body;
  if (messageBody.type === 'ack')
    msgInfo += 'ack@' + messageBody.messageId;
  if (!messageBody.type)
  {
    msgInfo += '<unk>:' + (typeof messageBody === 'string' ? messageBody : JSON.stringify(messageBody));
    if (debugging('nonce'))
      msgInfo += ` [${signedMessage?.body?.nonce}]`;
  }
  else
  {
    msgInfo += messageBody.type + ':';

    if (messageBody.type === 'batch')
      msgInfo += messageBody.payload?.length + ' [' + messageBody.payload?.map(msg => msg.type.slice(0,3)).join(' ') + ']';
    else if (messageBody.payload?.operation)
      msgInfo += messageBody.payload.operation;

    if (debugging('nonce'))
      msgInfo += ` [${signedMessage?.body?.nonce}]`;

    msgInfo += ' ' + JSON.stringify(messageBody);
  }
  msgInfo = msgInfo.padEnd(cols-79, ' ').slice(0, cols-79);
  
  const id = (signedMessage && messageBody && messageBody.id || '??????').slice(-6);

  if (!exports.wireLog.initialized)
  {
    const arr = haveUnicode ? '\u2194' : '-';
    exports.wireLog.initialized = true;
    console.debug('conn debug label     function name         type:operation',
                  'message body'.padEnd(cols-95, ' ').slice(0, cols-95),
                  ` ${arr} msgid     owner:dcpsid   len`);
    console.debug('-------------------- --------------------- --------------',
                  '-'.padEnd(cols-94, '-').slice(0, cols-94), '- ------ ----------------- -------');
  }
  console.debug(debugLabel, `${label} ${msgInfo} ${arrow} ${id} ${destLabel}`, + sealedMessage.length /* chars not bytes! */);
}

/** @param {DcpURL} location */
exports.fetchSchedulerConfig = async function dcp$$fetchSchedulerConfig(location)
{
  if (schedulerConfigLocation)
    throw new DCPError('Cannot re-fetch scheduler configuration', 'DCPP-1001'); /* security */

  schedulerConfigLocation = location;
  location = new DcpURL(location);
  location.searchParams.ver = '2.0.0'; /* 2->ask for serialized object else->ask for source code for object */

  const request = await require('dcp/utils').reallyJustFetch(location);

  return request.responseText;
}

/** @param {HTMLElement} scriptElement */
exports.setSchedulerConfigLocation_fromScript = function dcp$$setSchedulerConfigLocation_fromScript(scriptElement)
{
  schedulerConfigLocation = new (require('dcp/common/dcp-url').DcpURL)(scriptElement.src);
}

/** @returns DcpURL */
exports.getSchedulerConfigLocation = function dcp$$getSchedulerConfigLocation()
{
  return schedulerConfigLocation;
}

/* *Temporary API* to allow the portal to use the portal connection. This should be removed in the future since the connection should always be "usable". */
exports.usable = function dcp$$usable(theConnection) {
  return theConnection;
}

exports.version = {
  provides: '5.0.0', /* semver, must satisfy dcpConfig.scheduler.compatibility.minimum.dcp in dcp-client */
  api: '5.0.0'
};

/**
 * Version-sensitive thunks; choose Target and Connection versions based on the currently-loaded global
 * dcpConfig. Test programs needing to find the target's transports implementation should consult 
 * Target::transportRequire().
 */
Object.defineProperty(exports, 'Connection', {
  configurable: true,
  get() {
    const dcpConfig = globalThis.dcpConfig || {};
    const newInitiator = require('../common/dcp-env').getenv('DCP_INITIATOR_530') || dcpConfig.rollout?.dcp530 === 'initiator' || dcpConfig.rollout?.dcp530 === 'both';
    delete exports.Connection;
    exports.Connection = (!newInitiator ? require('./connection') : require('../protocol/connection')).Connection;
    debugging() && console.debug('DCP version thunk selected Connection =', exports.Connection.name);
    return exports.Connection;
  },
});

Object.defineProperty(exports, 'Target', {
  configurable: true,
  get() {
    const dcpConfig = globalThis.dcpConfig || {};
    const newTarget = require('../common/dcp-env').getenv('DCP_TARGET_530') || dcpConfig.rollout?.dcp530 === 'target' || dcpConfig.rollout?.dcp530 === 'both';
    delete exports.Target;
    exports.Target = (!newTarget    ? require('./target') : require('../protocol/target')    ).Target;
    debugging() && console.debug('DCP version thunk selected Target =', exports.Target.name);
    return exports.Target;
  },
});

