/**
 * @file worker/slice.js
 *
 * A wrapper for the slice object returned from the scheduler.
 * It has useful helper functions such as @getNextSlice and @getResultsMessage
 *
 *
 * @author Matthew Palma, mpalma@kingsds.network
 *         Ryan Rossiter, ryan@kingsds.network
 * @date May 2019
 */

/* global dcpConfig, protocol */

'use strict';
const SLICE_STATUS_UNASSIGNED = 'UNASSIGNED';
const SLICE_STATUS_WORKING = 'WORKING';
const SLICE_STATUS_COMPLETE = 'COMPLETE';
const SLICE_STATUS_FAILED = 'FAILED';

/** 
 * Object use to represent a given slice inside the Supervisor. This object's shape 
 * current inherits heavily from the message payload originating from the scheduler,
 * but should not /wg dec 2020.
 *
 * Caveat lector: this documentation was created without a 100% understanding of the
 *                code. Please improve as possible.
 *
 * The properties of this object are as follows:
 * - sliceNumber                the number of the slice within this job
 * - jobAddress                 the address of the job that this slice belongs to
 * - datumUri                   the URI describing the data (input set element) for 
 *                              this slice of the job; could be a data: URI or it
 *                              could be a URL we need to fetch; note that fetches 
 *                              are limited to worker's allow list
 * - resultStorageType          'values'  => we are storing individual values,
 *                                           which could be data: URIs or URLs
 *                                           at the scheduler
 *                              'pattern' => user-specified pattern for result URLs.
 *                                           Data will be uploaded via POST to the
 *                                           URL matching the pattern, provided the
 *                                           worker is allowed to access it.
 * - resultStorageParams        user-supplied POST parameters sent to the result 
 *                              storage server when using resultStorageType = pattern.
 * - resultStorageDetails       the pattern when using resultStorageType = pattern.
 * - result
 * - result.request             'complete' | ???
 * - result.result              return value from work function
 * - result.timeReport          { total, idle } ms 
 *
 * - status                     COMPLETE | FAILED | WORKING | UNASSIGNED
 */
class Slice {
  constructor (taskElement, authorizationMessage) {
    /** @deprecated - UNUSED */
    this.index                = taskElement.sliceNumber; /* deprecated - do not use */
    /** @type {string} */
    this.status               = SLICE_STATUS_UNASSIGNED;
    /** @type {boolean} */
    this.allocated            = false;
    /** @type {boolean} */
    this.isEstimationSlice    = taskElement.isEstimationSlice;
    /** @type {boolean} */
    this.isLongSlice          = taskElement.isLongSlice;
    /** @type {number} */
    this.sliceNumber          = taskElement.sliceNumber;
    this.jobAddress           = taskElement.jobAddress;
    this.datumUri             = taskElement.datumUri;
    this.resultStorageType    = taskElement.resultStorageType;
    this.resultStorageParams  = taskElement.resultStorageParams;
    this.resultStorageDetails = taskElement.resultStorageDetails;
    this.authorizationMessage = authorizationMessage;
    this.result               = null;
    this.error                = undefined;
    this.rejected             = null;
    this.rejectedTimeReport   = null;
  }

  get identifier() {
    if (this.allocated)
      return `${this.sliceNumber}.${this.jobAddress}.${this.status}.${this.allocated}`;
    return `${this.sliceNumber}.${this.jobAddress}.${this.status}`;
  }

  /**
   * @returns {boolean} - true if the slice is ready to be submitted 
   */
  get isFinished() {
    return this.status === SLICE_STATUS_COMPLETE || this.status === SLICE_STATUS_FAILED;
  }

  get failed () {
    return this.status === SLICE_STATUS_FAILED;
  }

  get completed () {
    return this.status === SLICE_STATUS_COMPLETE;
  }

  get isUnassigned () {
    return this.status === SLICE_STATUS_UNASSIGNED
  }

  /**
   * @returns {boolean} - true if the slice has been handed out, does not imply slice is complete
   */
  get isWorking () {
    return this.status === SLICE_STATUS_WORKING;
  }

  get timeReport () {
    const timeReport = this.result.timeReport;
    if (timeReport) {
      const rejectedTimeReport = this.rejectedTimeReport; // Data collected from sandboxes that rejected this slice.
      if (rejectedTimeReport && rejectedTimeReport.total > 0) {
        ['total', 'CPU', 'webGL', 'webGPU'].forEach((key) => {
          if (rejectedTimeReport[key]) timeReport[key] += rejectedTimeReport[key];
        });
      }
    }
    return timeReport;
  }

  // Sets the slice status to working, called when the slice is handed to a worker
  markAsWorking() {
    if (!this.isUnassigned) throw new Error(`Slice ${this.identifier} is already assigned, can't mark as working.`);
    this.status = SLICE_STATUS_WORKING;
  }

  /**
   * Receives a result from the supervisor.
   * It will then put the result in the appropriate place.
   * It could also eventually determine if the slice should be
   * retried before determining that it has failed.
   *
   * @param {object|Error} result - the result that came back from the worker
   * @param {boolean} [success = true] - true is result is considered successful, false if something went wrong computing
   */
  collectResult (result, success = true) {
    if (this.result)
      throw new Error(`Slice ${this.identifier} received more than one result.`);
    
    if (success) {
      this.status = SLICE_STATUS_COMPLETE;
      this.result = result;
    } else {
      this.status = SLICE_STATUS_FAILED;
      this.error = result;
    }
  }

  /**
   * (Currently unused.)
   * Create and return the payload object to send back to the result submitter
   */
  getResultMessagePayload () {
    if (!this.hasOwnProperty('result'))
      throw new Error(`Cannot create result message payload for slice ${this.identifier}.`);

    return {
      job:   this.jobAddress,
      slice: this.sliceNumber,
      result: this.result,
      authorizationMessage: this.getAuthorizationMessage(),
    }; 
  }

  /**
   *  Create and return a slice-return payload to send to the
   *    result-submitter's status operation
   *
   *  @param  {address} worker   The current worker's opaque
   *  @param  {string}  [reason] Optional reason for the return: 'ENOPROGRESS', 'EUNCAUGHT', 'ESLICETOOSLOW', 'unknown'.
   *  @return {object}           Message payload; still requires worker address
   */
  getReturnMessagePayload (worker, reason) {
    delete this.result;

    if (!reason)
      reason = this.error ? 'EUNCAUGHT' : 'unknown';

    return {
      worker,
      slices: [{
        job:                  this.jobAddress,
        sliceNumber:          this.sliceNumber,
        status:               'return',
        isEstimationSlice:    this.isEstimationSlice,
        authorizationMessage: this.getAuthorizationMessage(),
        reason,
        error:                this.error
      }],
    };
  }

  /**
   * This function helps enforce the equivalence:
   *     !this.authorizationMessage <==> sliceNumber === 0 .
   * @returns {object}  this.authorizationMessage
   */
  getAuthorizationMessage () {
    if (!this.authorizationMessage && this.sliceNumber > 0)
      throw new Error(`Undefined authorization for slice ${this.identifier}.`);
    return this.authorizationMessage;
  }
}

exports.Slice = Slice;
exports.SLICE_STATUS_UNASSIGNED = SLICE_STATUS_UNASSIGNED;
exports.SLICE_STATUS_WORKING = SLICE_STATUS_WORKING;
exports.SLICE_STATUS_COMPLETE = SLICE_STATUS_COMPLETE;
exports.SLICE_STATUS_FAILED = SLICE_STATUS_FAILED;
