/**
 *  @file       protocol/transport/index.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @date       January 2020
 *
 *  This module is the base class for transports used by protocol.
 *  A protocol transport knows how to communicate with peers using
 *  a specific method (WebSocket, HTTP, postMessage, etc).
 */
'use strict';

const { EventEmitter } = require('events');
const { assert } = require('dcp/common/dcp-assert');

/**
 * @class
 * @emits Transport#message        when a request is received from the peer.
 * @emits Transport#end            when the other end of the transport instance signals the end of transmission
 * @emits Transport#close          when the transport instance is fully closed
 * @emits Transport#connect-failed when transport's underlying connection could not be established (target)
 * @emits Transport#connect        when a socket connection is successfully established
 * @emits Transport#connection     when a new initiator connects
 * @emits Transport#drain          when the write buffer becomes empty (best effort)
 * @emits Transport#listening      when the transport first starts listening for new connections
 */
class Transport extends EventEmitter {
  constructor(transportName="Protocol Transport") {
    super({ captureRejections: false });
    // subclasses should override this with the module name to match
    // the dcp config key. Like `socketio`. But it defaults to this 
    // event-emitter style name for now since it's not spec'd, just helpful.
    this.name = transportName;
  }

  /**
   * This static method will essentially just require('') the
   * transport module but provides a space for logic / guards.
   * 
   * @param {string} moduleName - Identifier used to decide which transport module to load.
   */
  static require(moduleName) {
    // Make sure nobody is doing something sneaky like ../../something-secret
    // eslint-disable-next-line no-useless-escape
    if (!moduleName.match(/^[a-zA-Z0-9\-]+$/)) {
      throw new Error(`Module name contains invalid characters: "${moduleName}"`);
    }

    const transportModule = require(`./${moduleName}`);
    assert('TransportClass' in transportModule);

    return transportModule.TransportClass;
  }

  /**
   * - Close the underlying transport connection, freeing up all memory, etc.
   * - Emit a 'close' event when this happens
   * - Multiple calls do not generate errors nor dup events
   */
  close() {
    throw new Error("Transport.close should be overridden");
  }

  /**
   * @param {string} message - A signed message (will be transported as-is) to send.
   * @returns {object} - A plain object containing the raw response data.
   * @throws on a transmission error.
   */
  send(message) {
    throw new Error("Transport.send should be overridden");
  }
}

exports.Transport = Transport;
