/**
 * @file        connection/target.js
 *
 *              Implements the DCPv5 Target class. Instanciating this class lets the developers
 *              implement a basic network daemon that understands DCP; this is the basis for the
 *              Operation Router in current (Dec 2022) versions of the DCP scheduler and bank. The
 *              current implementation assumes that transports are built upon HTTP (with or without TLS)
 *              and provides a suitable bearer for this. Status URLs are automatically wired up, and a
 *              PseudoExpress (similar to a subset of Express.js) instance is provided for use of the
 *              transport Listener instances. We currently only support Socket.io listeners, but it
 *              should be possible to wire up other transports to the same bearer, provided they have a
 *              request which is differentiable from Socket.io's ?EIO pattern.
 *
 *              The basic architecture is that this class is responsible for providing a common bearer,
 *              and instanciating the Listener class from the available transports. Then we watch for
 *              transport-level connections, and use them to instanciate DCP sessions (Connection class).
 *              When the transport disconnect and reconnects, we wire up the new transport instance to
 *              the DCP session, provided it happens before linger timeout. This is how we support long-
 *              lived connections on devices whose network addresses change, network availability is
 *              intermittent, etc.
 *
 * @author      Wes Garland, wes@kingsds.network
 * @date        March 2022
 */
'use strict';

const { EventEmitter }  = require('events');
const { setImmediate,
        setTimeout,
        setInterval,
        clearTimeout,
        clearInterval } = require('dcp/common/dcp-timers');
const { assert }        = require('dcp/common/dcp-assert');
const { DcpURL }        = require('dcp/common/dcp-url');
const { DCPError }      = require('dcp/common/dcp-error');
const { PseudoExpress } = require('../node-libs/pseudo-express');
const { Connection }    = require('./connection');
const { Listener }      = require('./transport/listener');
const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
const { leafMerge }     = require('dcp/utils/obj-merge');
const { a$sleep }       = require('dcp/utils');
const { wireLog }       = require('.');

const wallet            = require('dcp/dcp-client/wallet');
const dcpEnv            = require('dcp/common/dcp-env');
const bearer            = require('./transport/http-bearer');
const debugging         = require('dcp/debugging').scope('dcp');

var   seqNum = 0;
var   usingDebugger = (dcpEnv.platform === 'nodejs' && requireNative('module')._cache.niim instanceof requireNative('module').Module);

/**
 * Instantiate a new Target. Targets listen for connections at the transport layer, and turns them into DCP Connections.
 * This class inherits from EventEmitter and PseudoExpress.
 *
 * @emits bearer-listening      when we are listening on a given bearer; argument is underlying bearer Server instance
 * @emits listening             when we are listening on at least one transport
 * @emits error                 when bad things happen
 *
 * @param {string[]}    transportNames          An array of names of transports,  ["socketio", "webrtc"] to use to create
 *                                              this Target.
 * @param {object}      config                  must have .identity and .location
 * @param {function}    listeningHandler        [optional] function to invoke once the transport is listening. Takes name of the
 *                                                         transport and server instance associated with the event.
 * @param {object}      options                 [optional] A DCP config options variable (like dcpConfig.dcp.connectionOptions.default)
 * @constructor
 */
exports.Target = function Target(transportNames, config, listeningHandler, options)
{
  const that = this;

  var initialTransportInstanceQueue = [];
  var idKs_unlocked = false; /* unlocked ks needed for daemon operation */
  var listening = false;
  var maintenanceIntervalMs = 1E3 * (options && options.connectionSweepInterval || 600);

  assert(config, config.identity, config.location);
  if (!options && typeof listeningHandler === 'object')
  {
    options = listeningHandler;
    listeningHandler = undefined;
  }

  if (config.identity instanceof Promise)
    config.identity.then(memoizeUnlockedIdentityKS);
  else
    memoizeUnlockedIdentityKS(config.identity);

  this.debugLabel = `target(${transportNames.join(' ')}:${++seqNum}):`;
  this.sessionMemos = {};
  this.connectionMemos = {};
  this.url = config.location;
  this.isClosed = false;

  /* Create a connection config as this.options which takes into
   * account system defaults and overrides for specific urls, origins, etc.
   */
  this.options = leafMerge(
    ({
      'transports':          transportNames,
      'lingerTimeout':       1800,  /* how long a target will hope to see the initiator again */
      'noSessionCloseDelay': 1.5,   /* rate-limit no-session closes */
      'connectTimeout':      10,    /* max time to wait for session start */
    }),
    dcpConfig.dcp.connectionOptions.default,
    dcpConfig.dcp.connectionOptions[config.listen  .hostname],
    dcpConfig.dcp.connectionOptions[config.location.hostname],
    dcpConfig.dcp.connectionOptions[config.listen  .origin],
    dcpConfig.dcp.connectionOptions[config.location.origin],
    options
  );

  /* Take care of multiple inheritance details. */
  Object.assign(this, new PseudoExpress());
  const ee = new EventEmitter();
  const eep = Object.assign({}, EventEmitter.prototype, PseudoExpress.prototype);
  Object.setPrototypeOf(eep, this.constructor.prototype);
  Object.setPrototypeOf(ee, eep);
  Object.setPrototypeOf(this, ee);
  this.on('error', () => {}); /* avoid "special" behaviour of NodeJS */

  /* Wire up bearer - shared amongst compatible transport listeners */
  this.httpServer = bearer.httpServerFactory(config, (server) => {
    if (server.listening && this.url.port == 0) /* DcpURL and URL type mismatch */  // eslint-disable-line eqeqeq
      this.url.port = server.address().port;
    this.emit('bearer-listening', server );
  });
  this.httpServer.on('error', error => this.emit('error', error));

  /* Wire up transport listeners */
  this.transportListeners = [];
  for (let transportName of transportNames)
  {
    const listener = new Listener(transportName, config, this, this.options[transportName]);

    listener.on('connection', startupTransportConnectionHandler);
    listener.on('listening',  (server) => startupListeningHandler(transportName, server));
    this.transportListeners.push(listener);
  }

  /* Wire up /status listeners - must happen after transport listeners hook httpServer */
  const statusUrl = new DcpURL(config.location).resolveUrl('./status');
  this.bindServer(this.httpServer);
  this.get(statusUrl.pathname, peShowStatus);
  this.get('/status', peShowStatus); /* outer server - not usually available via proxy */

  /* store an unlocked version of the idKs in instance-private memory for use by the Connection */
  async function memoizeUnlockedIdentityKS(idKs)
  {
    debugging('target') && console.debug(that.debugLabel, 'memoizeUnlockedIdentityKs: identity keystore unlocked. listening:', listening);

    if (!(idKs instanceof wallet.Keystore))
      throw new Error('Identity Keystore is not an instance of wallet.Keystore');

    const pk = await idKs.getPrivateKey();
    const ks = await new wallet.Keystore(pk, '');

    idKs_unlocked = ks;

    if (listening)
      rockAndRoll();
  }

  /**
   * Handler for transport-level 'connection' events during the startup (pre-listening) phase. We queue
   * up transport connnections until a listening event handler has fired and the idKs promise resolved,
   * then we de-queue and fire the actual target-level connection events.
   */
  function startupTransportConnectionHandler(transport)
  {
    debugging('target') && console.debug(that.debugLabel, 'startupTransportConnectionHandler; idKs unlocked:', Boolean(idKs_unlocked) + '; listening:', listening);
    if (that.isClosed)
    {
      transport.close();
      return;
    }

    if (!idKs_unlocked || !listening)
      initialTransportInstanceQueue.push(transport);
    else
    {
      rockAndRoll();
      that.handleNewTransportInstance(transport);
    }
  }

  /* handle listening event for each transport as it comes up */
  function startupListeningHandler(transportName, listeningServer)
  {
    debugging('target') && console.debug(that.debugLabel, 'startupListeningHandler; idKs unlocked:', Boolean(idKs_unlocked));

    if (that.isClosed)
      return;

    if (listeningHandler)
      listeningHandler(transportName, listeningServer);

    listening = true;
    if (idKs_unlocked)
      rockAndRoll();
  }

  /**
   * Listening event has fired for at least one transport, identity has resolved; target is fully up, 
   * event order has been synchronized with possible blast of incoming connections, get rid of the
   * intermediate events and get to work.
   */
  function rockAndRoll()
  {
    var queuedTransport;

    assert(idKs_unlocked);
    assert(listening);

    if (!rockAndRoll.ran)
    {
      rockAndRoll.ran = true;
      for (let listener of that.transportListeners)
      {
        listener.off('connection', startupTransportConnectionHandler);
        listener.on ('connection', (transport) => !that.isClosed && that.handleNewTransportInstance(transport));
      }
      that.identity = idKs_unlocked;
      debugging('target') && console.debug(that.debugLabel, 'identity is', that.identity.address);
      that.emit('listening', that);
    }

    // eslint-disable-next-line no-unmodified-loop-condition
    while (initialTransportInstanceQueue && (queuedTransport = initialTransportInstanceQueue.shift()))
      that.handleNewTransportInstance(queuedTransport);
    initialTransportInstanceQueue = null; /* detect push races, free RAM */
  }

  /* If it takes more than 5s to start up, we have a very serious problem */
  setTimeout(() => {
    if (rockAndRoll.ran || this.isClosed)
      return;
    const listeningError = new Error('unable to start listener');
    this.emit('error', listeningError);
    debugging('target') && console.debug(that.debugLabel, listeningError);
  }, 5022 * (usingDebugger ? 10 : 1)).unref();

  /* Occasionally sweep the connection list and clean up garbage. */
  this.maintenanceIntervalHnd = setInterval(() => this.doMaintenance(), maintenanceIntervalMs);
  this.maintenanceIntervalHnd.unref();
}

/**
 * API to shutdown the target and its currently-active connections.
 *
 * - Fires the end event when all connections have ended
 * - Fires the close event when all listeners have been torn down
 */
exports.Target.prototype.close = function Target$close()
{
  var ps = [];

  if (this.isClosed)
    return;
  this.isClosed = true;
  for (let listener of this.transportListeners)
  {
    listener.shutdown();
    listener.removeAllListeners();
  }
  clearInterval(this.maintenanceIntervalHnd);

  debugging('target') && console.debug(this.debugLabel, `closing ${this.getSessions('established').length} established and ${this.getSessions('disconnected').length} disconnected sessions`);

  for (let memo of Object.values(this.sessionMemos).concat(Object.values(this.connectionMemos)))
  {
    const conn = memo.connection;
    ps.push(new Promise((resolve, reject) => conn.on('close', resolve)));
    conn.close();
  }

  /* Prevent the server from accepting new connections and communicating with comet-style clients. 
   * WebSockets still need to be shutdown explicitly by the individual transports.
   * See https://nodejs.org/api/http.html#serverclosecallback
   */
  const serverClose = {};
  serverClose.promise = new Promise(resolve => serverClose.resolve = resolve);
  this.httpServer.close(() => serverClose.resolve());

  Promise.all(ps).then(() => {
    ps.length = 0;
    this.emit('end');

    for (let listener; listener = this.transportListeners.pop();) // eslint-disable-line no-cond-assign
    {
      const p = new Promise((resolve, reject) => {
        listener.on('close', resolve);
        listener.close();
      });
      ps.push(p);
    }
    this.transportListeners.length = 0;

    if (this.httpServer.listening)
      ps.push(serverClose.promise);
    Promise.all(ps).then(() => {
      this.unref();
      this.emit('close');
    });
  });
}

/**
 * Internal callback which is invoked whenever a new transport instance is created
 */
exports.Target.prototype.handleNewTransportInstance = function handleNewTransportInstance(transport)
{
  const that = this;

  debugging('target') && console.debug(this.debugLabel, 'adding new transport instance');

  /* new transport instances need their messages intercepted at this layer so that 
   * we can figure out if they are new DCP connections or simply reconnections.
   */
  function messageHandler(sealedMessage)
  {
    if (!that.isClosed)
      void that.a$interceptTransportMessage(sealedMessage, transport, messageHandler);
  }

  transport.on('message', messageHandler);

  /* Transport may have pending messages it didn't emit as there was no listener. Try here. */
  transport.emitReadyMessages();
}

/**
 * Internal method that memoizes a session for later use by the reconnect code.
 */
exports.Target.prototype.memoizeSession = function memoizeSession(connection)
{
  const dcpsid = connection.dcpsid;

  assert(dcpsid);
  assert(!this.sessionMemos.hasOwnProperty(dcpsid));

  debugging('target') && console.debug(this.debugLabel, 'target registered new session', dcpsid);
  this.sessionMemos[dcpsid] = { connection, firstMessageStampMs: performance.now() };
  connection.on('end', () => { delete this.sessionMemos[dcpsid] });
  delete this.connectionMemos[connection.id];
}

/**
 * Internal method that memoizes a connection so we can expire it later if it never establishes a session.
 */
exports.Target.prototype.memoizeConnection = function memoizeConnection(connection)
{
  if (connection.dcpsid) /* Already has a session (very fast startup) - don't bother memozing */
    return;

  this.connectionMemos[connection.id] = { connection, firstMessageStampMs: performance.now() };
  debugging('target') && console.debug(this.debugLabel, 'target registered new connection', connection.id);
}

/**
 * Internal method invoked when a connection connects
 */
exports.Target.prototype.noteConnectEvent = function noteConnectEvent(connection)
{
  const sm = this.sessionMemos[connection.dcpsid];
  assert(connection.dcpsid);

  if (!sm)
  {
    debugging('target') && console.debug(this.debugLabel, `target connected after session ${connection.dcpsid} culled`);
    connection.close();
    return;
  }

  delete sm.disconnectStampMs;
}

/**
 * Internal method invoked when a connection disconnects
 */
exports.Target.prototype.noteDisconnectEvent = function noteDisconnectEvent(connection)
{
  const sm = this.sessionMemos[connection.dcpsid];

  if (!sm)
  {
    debugging('target') && console.debug(this.debugLabel, `target disconnected after session ${connection.dcpsid} culled`);
    connection.close();
    return;
  }

  sm.disconnectStampMs = performance.now();
}

/**
 * Handle messages coming from the transport by associating them with an instance of Connection
 * and then having the Connection handle them.  It's possible that we might multi-trigger on
 * messages arriving in a flurry just as we connect; this is due to an architecture flaw where
 * we don't really have a way to know what connection a given message is for until it has sent
 * a DCP-level message; either a connect message or a message with an existing dcpsid. Multi-trigger
 * should just get picked up by the dup detection.
 *
 * Once we have figured out which connection should be associated with messages from that particular
 * transport instance, we remove existing and add new event handlers to get directly without intercept.
 *
 * @param {string}    sealedMessage   JSON-encoded DCP message
 * @param {object}    transport       a transport instance which is a child of this.transportListener
 * @param {function}  messageHandler  the function which is the transport message event handler that
 *                                    called this function.
 */
exports.Target.prototype.a$interceptTransportMessage = async function Target$interceptTransportMessage(sealedMessage, transport, messageHandler)
{
  var message;
  debugging('wire') && wireLog(this.debugLabel, sealedMessage, 'recv');
  
  /* _targetInfo memo on the transport instance indicates that we have already sorted out which 
   * dcp connection the transport connection is associated with - we must have arrived here via
   * event-dispatch race in very-fast-many-message connection startup.
   */
  if (transport._targetInfo)
    transport._targetInfo.interceptCount++;
  else
    transport._targetInfo = { interceptCount: 1 };
  debugging('target') && console.debug(this.debugLabel,`target intercepted ${sealedMessage.length}-byte message #${transport._targetInfo.interceptCount}`);

  transport.off('message', messageHandler);
  try
  {
    message = JSON.parse(sealedMessage);
  }
  catch (error)
  {
    console.error(`interceptTransportMessage: message #${transport._targetInfo.interceptCount} is not valid JSON (${String(sealedMessage).slice(0,15)}...):`, error);
    transport.close();
    return;
  }

  if (typeof message !== 'object' || !message.hasOwnProperty('body'))
  {
    console.error(`interceptTransportMessage: no body in message #${transport._targetInfo.interceptCount} (${String(sealedMessage).slice(0,15)}...)`);
    transport.close();
    return;
  }

  /* Sometimes, this transport has already been associated with a session, but messages were dispatched
   * before the intercept event handler was disabled. We pass them along to the connection either way,
   * but only try to do transport<>connection association for the first message. That is the *ONLY* 
   * reason this code should ever look at _targetInfo.connection.
   */
  if (!transport._targetInfo.connection)
  {
    try
    {
      if (!message.body.dcpsid)
        transport._targetInfo.connection = await this.a$initializeNewConnection(transport, message); // eslint-disable-line require-atomic-updates
      else
        transport._targetInfo.connection = this.locateExistingSession(transport, message);
    }
    catch(error)
    {
      console.error(error);
      if (transport._targetInfo.connection)
      {
        const conn = transport._targetInfo.connection;
        delete transport._targetInfo.connection;
        conn.close();
      }
    }

    if (!transport._targetInfo.connection)
    {
      debugging('target') && console.error(`${this.debugLabel} interceptTransportMessage: `
                                           + 'could not find or create session for message '
                                           + `#${transport._targetInfo.interceptCount} (${String(sealedMessage).slice(0,100)}...)`);
      if (message.body.dcpsid)
        this.sendNoSessionResponse(transport, message, sealedMessage);
      return;
    }
  }

  /* Message was intercepted, now we should have a Connection ready to handle it - handle
   * it immediately, so that it does not accidentally get handled out of order. The await
   * in the previous block will have allowed the 'connection' event to fire and the 
   * identityPromise to resolve by now for new connections.
   */
  transport._targetInfo.connection.handleRawMessage(sealedMessage, message)
}

/**
 * Initializes a Connection object for use by a target, based on a message from the transport layer.
 * This should be the first message from the transport connection (socket), and it must be a message
 * which contains a DCP 'connect' request.
 *
 * If the message is unsuitable for bootstrapping a Connection, a response message will be written 
 * back on the transport instance and the transport will be closed.
 *
 * @param {object}   transport          the instance of Transport which originated the message
 * @param {object}   transportMessage   a DCP message, from the transport layer, which has been parsed
 *                                      from JSON into an object but not otherwise modified.
 *
 * @returns - Connection  when the message is suitable for establishing a Connection, or 
 *          - false       when it is not; in that case the transport will be closed eventually
 *                        once an error response is sent, or it takes too long to send.
 */
exports.Target.prototype.a$initializeNewConnection = async function Target$initializeConnection(transport, transportMessage)
{
  var message;
  var connection;

  if (!transportMessage.body || transportMessage.body.type !== 'batch')
    message = transportMessage;
  else
  {
    const messages = transportMessage.body?.payload;
    if (!messages || !messages.length)
      throw new DCPError('invalid message - empty batch', 'EINVAL');
    message = messages[0];
  }

  if (!message.body)
    throw new DCPError('invalid message - no body', 'EINVAL');

  /* At this point, we have a transport message for a brand new DCP connection */
  connection = new Connection(this.url, this.identity, this.options);
  await connection.accept(transport);

  this.memoizeConnection(connection);
  connection.on('session',    () => this.memoizeSession     (connection));
  connection.on('connect',    () => this.noteConnectEvent   (connection));
  connection.on('disconnect', () => this.noteDisconnectEvent(connection));

  this.emit('connection', connection); /* does not imply session! */
  return connection;
}

/**
 * @param {object}    transport       a transport instance which is a child of this.transportListener
 * @param {string}    message         DCP session id sent in the first message from the peer
 *
 * @returns instance of Connection or false
 */
exports.Target.prototype.locateExistingSession = function Target$locateExistingSession(transport, message)
{
  const dcpsid = message.body.dcpsid;
  var sm;

  assert(transport, dcpsid);
  this.doMaintenance();
  sm = this.sessionMemos[dcpsid];

  if (!sm)
  {
    debugging('target') && console.debug(this.debugLabel, `target received message after session ${dcpsid} culled or target restarted`);
    return;
  }

  debugging('target') && console.debug(this.debugLabel, 'message is for session', dcpsid);
  if (sm.connection.transport)
    sm.connection.transport.close();
  sm.connection.replaceTransport(transport);

  return sm.connection;
}

/**
 * This function runs when a peer's transport connects to us, but we don't have a corresponding session
 * in memory.  This means that any application state that the peer was counting on does not exist in this
 * target, and the usual (but not only) way this happens is when the target daemon either crashes or is
 * recycled for maintenance.
 *
 * We bootstrap just enough of a session to a close message, using information from the peer's message.
 * No special OOB messaging, magic message types, or security-bypass schemes are necessary for this.
 * That said, we also don't bother authenticating the crypto on the message, etc, because we don't care:
 * it is never associated with anything outside of this function, and the only thing we do with the
 * newly-created session is close it.
 *
 * @param {object} transport       instance of an underlying transport
 * @param {object} signedMessage   raw message sent over the transport, after parsing from JSON
 */
exports.Target.prototype.sendNoSessionResponse = async function Target$$sendNoSessionResponse(transport, signedMessage, sealedMessage)
{
  const connection = new Connection(this.url, this.identity, this.options);
  const dcpsid = signedMessage.body.dcpsid;

  (debugging('target') || debugging('connection')) && console.debug(this.debugLabel, `no such session, telling peer to close ${dcpsid}`);

  try
  {
    connection.peerAddress = new wallet.Address(signedMessage.owner);
    await connection.accept(transport);
    connection.establishTarget(dcpsid);
    connection.unref();

    /* peer's notifyTransportReady should always sends us the last Message (if unack'd),
     * and the last ack (always). It's possible that transport-level buffers will carry
     * other messages as well, so we can't be certain this signedMessage is an ack - so
     * wait a short time for an ack before simply banging the connection shut. The ack
     * message in this context is needed to get a nonce we can use to tell the remote to
     * close.
     *
     * In the case where the transport buffer spews so much stuff that the timer expires,
     * the peer will wind up yoyoing until the transport buffer is empty and it eventually
     * sends an ack, then finally gets the close request which will cause it to stop
     * reconnecting.
     *
     * The default message handlers for the session are in left in place to handle any
     * unexpected incoming traffic and keep it synchronized wrt ackToken/nonces. Since
     * we listen to no non-default requests, this effectively puts application messages in
     * the bit bucket.
     *
     * Close message synchronization isn't really important, except that it tells the peer
     * end that we closed the transport-level connection on purpose and that trying to
     * reconnect is futile.
     */
    function checkAck(incomingSealedMessage, incomingSignedMessage)
    {
      assert(typeof incomingSealedMessage === 'string');

      if (!incomingSignedMessage)
        incomingSignedMessage = JSON.parse(incomingSealedMessage);
      debugging('wire') && wireLog(connection.debugLabel, incomingSealedMessage, 'recv');

      if (incomingSignedMessage.body.type === 'ack')
        checkAck.resolve(incomingSignedMessage.body.nonce);
    }
    checkAck.promise = new Promise((resolve, reject) => {
      checkAck.resolve = resolve;
      checkAck.reject = reject;
    });
    checkAck(sealedMessage, signedMessage);

    setTimeout(() => {
      checkAck.resolve('no-session-bad-nonce');
    }, 1234).unref(); /* TODO - make tunable - how long to wait for message decoding before giving up /wg jan 2023 */

    const nextNonce = await checkAck.promise;
    connection.sender.setNextNonce(nextNonce); /* consumed by connection.close */
    transport.off('message', checkAck);
  }
  catch(error)
  {
    console.error('Error during sendNoSessionResponse:', error);
  }
  finally
  {
    /* assert ensures we never accidentally leak this session outward in future code */
    assert(connection.listeners('request').length === 0);

    /* Delay close operation to rate-limit endless loops caused by broken initiators, but try to not
     * sleep if the process is exiting (implied by the fact that the Target instance has been asked to
     * close).
     */
    const sleepHnd = a$sleep(this.options.noSessionCloseDelay);
    connection.on('end',   () => sleepHnd.intr());
    connection.on('close', () => sleepHnd.intr());

    if (!this.isClosed)
      await sleepHnd;
    connection.close();
  }
}

/**
 * Retrieve a list of connections' dcpsids and their statuses.
 * @param {string} connectionStatus    [optional] connection.status to filter on
 * @returns {Array} list of { dcpsid, status }
 */
exports.Target.prototype.getSessions = function Target$$getSessions(connectionStatus)
{
  var sessions = [];

  for (let dcpsid in this.sessionMemos)
  {
    if (!connectionStatus || this.sessionMemos[dcpsid].connection.state.is(connectionStatus))
    {
      const session = { dcpsid, status: this.sessionMemos[dcpsid].status };
      if (dcpConfig.build === 'debug')
        session.__connection = this.sessionMemos[dcpsid]; /* troubleshooting only! */
      sessions.push(session);
    }
  }

  return sessions;
}

/**
 * Remove all connections from the target's memo list that have not have been
 * disconnected for more than lingerTimeout seconds and close connections which 
 * have not established a session without connectTimeout seconds.
 */
exports.Target.prototype.doMaintenance = function Target$doMaintenance()
{
  const now = performance.now();
  debugging('target') && debugging('verbose') && console.debug(this.debugLabel, 'performing connection maintenance');

  for (let id in this.connectionMemos)
  {
    const cm = this.connectionMemos[id];
    assert(cm.hasOwnProperty('firstMessageStampMs') && !cm.connection.dcpsid);

    if (cm.hasOwnProperty('firstMessageStampMs') && (now - cm.firstMessageStampMs) > cm.connection.options.connectTimeout * 1E3)
    {
      debugging('target') && console.debug(this.debugLabel, 'dropping connection which never established session');
      cm.connection.close(true);
      delete this.connectionMemos[id];
    }
  }

  for (let dcpsid in this.sessionMemos)
  {
    const sm = this.sessionMemos[dcpsid];
    if (!sm.hasOwnProperty('disconnectStampMs')) /* session is not disconnected */
      continue;
    const timeoutMs = sm.connection.options.lingerTimeout * 1000;

    if (now - sm.disconnectStampMs > timeoutMs)
    {
      debugging('target') && console.debug(`${this.debugLabel} culling session ${dcpsid}`);
      sm.connection.close();
      delete this.sessionMemos[dcpsid];
    }
  }
}

/** Remove any event loop references used by this target */
exports.Target.prototype.unref = function Target$unref()
{
  for (let listener of this.transportListeners)
    listener.unref();

  if (this.httpServer)
    this.httpServer.unref();

  return this;
}

/** Used for tests, not API */
exports.Target.transportRequire = mid => require(require('path').join(module.path, 'transport', mid));

/**
 * A handler for PseudoExpress which displays the status of the Target's process
 * @param {Object} request      the http request that was sent to the PseudoExpress server
 * @param {Object} response     the http response that will be sent back to the client
 * @returns false
 */
function peShowStatus(request, response)
{
  const process = requireNative('process');
  const os      = requireNative('os');

  function fancy(object)
  {
    const padLen  = 4 + Object.keys(object).reduce((curMax, key) => key.length > curMax ? key.length : curMax,  0);
    return '\n' + Object.entries(object).map(([key, value]) => ('  ' + key + ': ').padEnd(padLen) + value).join('\n');
  }

  response.status = 200;
  response.set('content-type', 'text/plain; charset=utf8');
  response.set('cache-control', 'no-cache');

  const output = `${new Date()}\n
request:        ${request.method} ${request.url}
program:        ${process.argv[1]}
pid:            ${process.pid}
debugPort:      ${process.debugPort}
hostname:       ${request.hostname} aka ${os.hostname()}
uptime:         ${process.uptime()}
loadavg:        ${os.loadavg()}
resources:      ${fancy(process.resourceUsage())}
memory:         ${fancy(process.memoryUsage())}
totalmem:       ${os.totalmem()}
headers:        ${fancy(request.headers)}

body:         \n${request.body || ''}
`;

  response.send(output);
}
