/**
 *  @file       passwordCreation.js
 *              Modal providing a way to create a password.
 * 
 *  @author     Andrew Fryer           - andrewf@kingsds.network
 *  @date       June 2020
 */
const utils = require('./utils');
const { setTimeout } = require('dcp/common/dcp-timers');

exports.config = {
  id: 'dcp-modal-password-create',
  required: [
    'dcp-modal-password-create-form',
    'dcp-modal-password-create-hidden-username',
    'dcp-modal-password-create-input',
    'dcp-modal-password-create-input-confirm',
    'dcp-modal-password-create-matching-error',
  ],
  path: "./templates/password-creation-modal.html",
};

/**
 * @param {string} username The hidden username provided to give a hint to password managers.
 * @throws If modal is closed without the form being submitted (submitting the form closes the modal).
 */
exports.passwordCreation = async function (username, onClose=null) {
  const [elements, formPromise] = await utils.initModal(exports.config, onClose);
  let [modal, form, hiddenUsername, passwordInput, passwordInputConfirm, matchingError] = elements;

  hiddenUsername.value = username;

  const validate = function() {
    if(passwordInput.value === passwordInputConfirm.value) {
      passwordInputConfirm.setCustomValidity("");
    } else {
      // This prevents the submit event from firing so that Firefox won't offer to save the password.
      passwordInputConfirm.setCustomValidity("Passwords must match");
    }
  };
  passwordInput.onchange = validate;
  passwordInputConfirm.onchange = validate;
  validate();

  const optionallyDisplayError = function() {
    if(passwordInput.value === passwordInputConfirm.value) {
      matchingError.classList.add("invisible");
    } else {
      matchingError.classList.remove("invisible");
    }
  };
  const removeError = function(e) {
    matchingError.classList.add("invisible");
  };
  passwordInput.onblur = optionallyDisplayError;
  passwordInputConfirm.onblur = optionallyDisplayError;
  passwordInput.onfocus = removeError;
  passwordInputConfirm.onfocus = removeError;
  passwordInput.oninput = removeError;
  passwordInputConfirm.oninput = removeError;
  optionallyDisplayError();

  const invalidHandler = function(e) {
    // supress tooltip
    e.preventDefault();

    // If the user hits "ENTER" in the input field, the blur event isn't fired, so we need to trigger error checking.
    // We removeError on the input event to cover this case because the field is focused, but the focus event isn't fired.
    optionallyDisplayError();
    passwordInputConfirm.value = "";
  };
  passwordInputConfirm.oninvalid = invalidHandler;

  const submitHandler = function(e) {
    setTimeout(function(){
      history.replaceState(null, document.title); // This should signal to the browser that the login was successful.
    }, 1);
  };
  // Don't overwrite the existing event handler!
  let existingSubmitHandler = form.onsubmit;
  form.onsubmit = function(e) {
    submitHandler(e);
    existingSubmitHandler(e);
  };

  passwordInput.focus();
  await formPromise;

  // At this point, form validation has ensured that the password input values match.

  utils.MicroModal.close(modal.id);
  return passwordInput.value;
};
