/**
 * @file        pseudo-express.js
 *
 *              A lightweight url->callback routing scheme which uses a syntax very similar to
 *              a subset of ExpressJS v4. This was designed explicitly for interoperation with
 *              the Target connection class and SocketIO, but could - in theory - be used with 
 *              any NodeJS http server. 
 *
 * @author      Wes Garland, wes@kingsds.network
 * @date        July 2021
 */
'use strict';

const os = require('os');

const debugging = require('dcp/debugging').scope('pseudo-express');

/**
 * Create, in ExpressJS terminology, an "app" or "router" that is bound to the given server.
 *
 * @param {object} [httpServer] server to bind to
 * @constructor
 */
exports.PseudoExpress = function PseudoExpress(httpServer)
{
  this._routes = [];

  if (httpServer)
    this.bindServer(httpServer);
}

/**
 * API to bind an instance to a specific http server. More than one server per instance is supported, just call
 * this function multiple times.
 *
 * @param {object}      server          a node http or https Server
 * @param {string}      [handledMarker] replaces request.url if the request has been routed successfully.
 */
exports.PseudoExpress.prototype.bindServer = function PseudoExpress$bindServer(server, handledMarker)
{
  if (!handledMarker)
    handledMarker = 'pseudo-express-handled';

  server.prependListener('request', (request, response) => this.routeRequest(request, response, handledMarker));
  server.on('request', (request, response) => {
    debugging('requests') && console.debug(`pe: finished processing ${request.url}`);
    if (request.url === handledMarker || request.handleOutsideExpress)
      return;
    
    setImmediate(() => {
      if (response.headersSent)
        console.warn('Warning: rogue listener handled request', request.url);
      else
      {
        debugging() && console.debug(`pe: request ${request.url} => 404`);
        sendHttpError(request, response, 404, `${request.url} not found.`);
      }
    });
  });
}

/**
 * Internal function  to mark a request as routed.
 * @param {object} request         Node HTTP request object
 * @param {string} handledMarker   see PseudoExpress$bindServer
 */
exports.PseudoExpress.prototype.markRequest = function PseudoExpress$markRequest(request, handledMarker)
{
  debugging('requests') && console.debug('pe: marking request', request.url, 'handled via', handledMarker);
  request.url = handledMarker;  
}

/**
 * Route a request to a request handler. We match request.url against previously-registered routes
 * (eg with .get) and run the first handler we find, then we mark the request (mutate request.url)
 * so that no other request handlers (I'm looking at you, socket.io) will want to touch it.
 *
 * If a request handler throws an exception, we handle the request by responding with an HTTP error.
 *
 * @param {object} request         Node HTTP request object
 * @param {object} response        Node HTTP response object
 * @param {string} handledMarker   see PseudoExpress$bindServer
 */
exports.PseudoExpress.prototype.routeRequest = function PseudoExpress$routeRequest(request, response, handledMarker)
{
  var retval;
  
  try
  {
    debugging() && console.debug(`pe: routing ${request.url}`);
    for (let i=0; i < this._routes.length; i++) 
    {
      let pathMatchRe = this._routes[i].match;
      
      if (!pathMatchRe.test(request.url))
        debugging('requests') && !debugging('all') && console.debug('pe:   does not match', pathMatchRe)
      else
      {
        if (this._routes[i].handleOutsideExpress)
        {
          request.handleOutsideExpress = true
          break
        }
        else
        {
          pseudoExpressRoute(this._routes[i], request, response);
          this.markRequest(request, handledMarker);
        }
        break;
      }
    }
  }
  catch(error)
  {
    sendHttpError(request, response, 500, `Error processing ${request.url}\n` + (error.stack || error.message));
    this.markRequest(handledMarker);
  }
}

/**
 * @param {RegExp}    match         regular expression that matches request url (pathname + search)
 */
/**
 * Register an interceptor for the HTTP get method
 *
 * @param {string}    match         string that matches request pathname exactly
 * @param {function}  callback      function to run when the route matches
 * @param {Boolean} [handleOutsideExpress=false] set to true if this route should be handled externally from the pseudoExpressRoute
 */
exports.PseudoExpress.prototype.get = function PseudoExpress$get(match, callback, handleOutsideExpress = false)
{
  if (typeof match === 'string')
    match = new RegExp(`^${match}($|\\?)`);

  debugging('requests') && console.debug(`pe: added GET method intercept ${match}: ${callback.name}`);
  this._routes.push({
    method: 'get',
    match,
    callback,
    handleOutsideExpress,
  });
}

/**
 * Register an interceptor for the HTTP post method
 * @see PseudoExpress$get
 * @param {Boolean} [handleOutsideExpress=false]  set to true if this route should be handled externally from the pseudoExpressRoute
 */
exports.PseudoExpress.prototype.post = function PseudoExpress$post(match, callback, handleOutsideExpress = false)
{
  if (typeof match === 'string')
    match = new RegExp(`^${match}$`);

  debugging('requests') && console.debug(`pe: added POST method intercept ${match}: ${callback.name}`);
  this._routes.push({
    method: 'post',
    match,
    callback,
    handleOutsideExpress,
  });
}

/**
 * Register an interceptor for all HTTP methods
 * @see PseudoExpress$get
 * @param {Boolean} [handleOutsideExpress=false]  set to true if this route should be handled externally from the pseudoExpressRoute
 */
exports.PseudoExpress.prototype.all = function PseudoExpress$all(match, callback, handleOutsideExpress = false)
{
  if (typeof match === 'string')
    match = new RegExp(`^${match}$`);

  debugging('requests') && console.debug(`pe: added all-method intercept ${match}: ${callback.name}`);
  this._routes.push({
    method: 'all',
    match,
    callback,
    handleOutsideExpress,
  });
}

/**
 * Register a middleware callback
 * @see PseudoExpress$get
 * @param {function}   next    third argument callback function
 */
exports.PseudoExpress.prototype.use = function PseudoExpress$use(match, callback, next)
{
  if (typeof match === 'string')
    match = new RegExp(`^${match}$`);

  function peUseCallbackWrapper(request, result)
  {
    callback(request, result, next);
    return; /* don't cancel bubble so we can chain to other routes */
  }

  debugging('requests') && console.debug(`pe: added use intercept ${match}: ${callback.name}`);
  this._routes.push({
    method: 'all',
    match,
    callback: peUseCallbackWrapper,
    retval: true
  });
}

function sendHttpError(request, response, code, text)
{
  const corsHeaders = {
    'access-control-allow-origin':  '*',
    'access-control-allow-headers': 'content-type',
  };

  response.setHeader('content-type', 'text/plain');
  response.setHeader('content-type', 'text/plain; charset=utf8');
  response.setHeader('cache-control', 'no-cache');
  for (let header in corsHeaders)
    response.setHeader(header, corsHeaders[header]);
  
  response.writeHead(code);
  response.write(`${code} - ${text}`);
  response.end();
}

/**
 * Utility function for use by the PseudoExpress class. Actually implements the "routing" behaviour.
 *
 * @param {object} descriptor     mapping for the behaviour of the "express" rule - e.g., 
 *                                send all GET queries at location /status to the status handler
 * @param {object} httpRequest    the http request to handle, from the node http or https modules
 * @param {object} httpResponse   the response object associated with httpRequest
 */
function pseudoExpressRoute(descriptor, httpRequest, httpResponse)
{
  const rMethod = httpRequest.method.toLowerCase();
  const requestPE  = new PseudoExpressRequest (httpRequest);
  const responsePE = new PseudoExpressResponse(httpResponse, requestPE);
  
  if (descriptor.method !== 'all' && descriptor.method !== rMethod)
    return; /* try next handler */

  try
  {
    if (rMethod === 'get')
    {
      let i = httpRequest.url.indexOf('?');
      requestPE.query = {};
      
      if (i !== -1) /* query string present - decode */
      {
        let queryString = httpRequest.url.slice(i + 1);
        for (let kvp of queryString.split('&'))
        {
          let [ key, value ] = kvp.split('=');
          requestPE.query[key] = value && decodeURIComponent(value.replace(/\+/g, ' '));
        }
      }
      descriptor.callback(requestPE, responsePE);
    }
    else if (rMethod === 'post')
    {
      const chunks = [];
      requestPE.on('data', chunk => chunks.push(chunk));
      requestPE.on('end', function pseudoExpress$postEnd() {
        requestPE.body = Buffer.concat(chunks);
        descriptor.callback(requestPE, responsePE);
      });
    }
    else
    {
      descriptor.callback(requestPE, responsePE);
    }
  }
  catch(error)
  {
    dumpError(requestPE, responsePE, error);
  }
  
  if (descriptor.hasOwnProperty('retval'))
    return descriptor.retval;
}

/**
 * Class to represent incoming http request
 * param {object} httpRequest  NodeJS request from httpServer
 * @constructor
 */
function PseudoExpressRequest(httpRequest)
{
  for (const key in httpRequest)
    this[key] = httpRequest[key];
  // headers is non-enumerable, inherited in node 16+, so need to explicitly assign it.
  this.headers = httpRequest.headers;
  this.__httpRequest = httpRequest;
  this.originalUrl = this.__httpRequest.url;
  this.path        = this.__httpRequest.url.replace(/\?.*$/, '');
  this.hostname    = this.__httpRequest.headers.host?.split(':')[0] ?? os.hostname();
}

/**
 * Class to represent outgoing http response
 * @constructor
 */
function PseudoExpressResponse(httpResponse, request)
{
  this.httpResponse = httpResponse;
  this.headers = {};
  this.request = request;
  this.headersSent = false;
}

/**
 * @param {object} field        Object containing multiple fields and values
 */
/**
 * Sets the response’s HTTP header field to value. To set multiple fields at once, pass an 
 * object as the parameter.
 * 
 * @note Headers are collapsed to lower case
 *
 * @param {string} field        Header name
 * @param {string} value        Value of header
 */
PseudoExpressResponse.prototype.set = function PseudoExpressResponse$$set(field, value)
{
  if (typeof field === 'string')  /* single header */
    this.headers[field.toLowerCase()] = value;
  else /* assume Object => multiple headers */
  {
    for (let entry of Object.values(field))
      this.headers[entry.field.toLowerCase()] = entry.value;
  }

  return this;
}

/** 
 * Returns the HTTP response header specified by field. The match is case-insensitive.
 *
 * @param {string} field
 * @returns {string}
 */
PseudoExpressResponse.prototype.get = function PseudoExpressResponse$$get(field)
{
  return this.headers[field.toLowerCase()];
}

/**
 * Send HTTP status and headers immediately, without the respsonse body.
 *
 * @note Express does not appear to have an API that does this. It is needed to allow
 *       streaming content.
 *
 * @param {object} defaultHeaders       Headers to send as though they were in an object passed to
 *                                      the set() method, unless they were already defined elsewhere
 * @param {object|string} body          The body, per .send(), for the message; only used to detect
 *                                      default header params; is not actually used in the response.
 * @returns this, to allow chaining
 */
PseudoExpressResponse.prototype.sendHeaders = function PseudoExpressResponse$$sendHeaders(defaultHeaders, body)
{
  var defaultContentType;

  if (!body)
    body = this.body;

  if (!this.headers['content-type'])
  {
    switch(typeof body)
    {
      case 'object':
      {
        if (Buffer.isBuffer(body))
          defaultContentType = 'application/octet-stream';
        else
          defaultContentType = 'application/json';
        break;
      }
      case 'string':      
        defaultContentType = 'text/plain; charset=utf-8';
        break;
      default:
        defaultContentType = 'application/octet-stream';
        break;
    }
  }
  
  this.httpResponse.writeHead(this.statusCode || 200, Object.assign({ 'content-type': defaultContentType }, defaultHeaders, this.headers))
  this.headersSent = true;

  return this;
}

/**
 * Sends the HTTP response.
 * The body parameter can be a Buffer object, a String, an object. Plain objects are serialized via
 * JSON.stringify. This method performs many useful tasks for simple non-streaming responses: For 
 * example, it automatically assigns the Content-Length HTTP response header field (unless previously 
 * defined).
 * 
 * When the parameter is a Buffer object, the method sets the Content-Type response header field 
 * to “application/octet-stream”, unless previously defined.
 *
 * @param {string} body         The body to send as the response.
 * @returns this, to allow chaining
 */
PseudoExpressResponse.prototype.send = function PseudoExpressResponse$$send(body)
{
  var defaultHeaders = {};
  var contentLength;
  var sendBody = body;
  var argv = Array.from(arguments);
  
  if (typeof sendBody === 'object' && sendBody !== null)
  {
    if (Buffer.isBuffer(sendBody))
      contentLength = Buffer.byteLength(sendBody);
    else
      sendBody = JSON.stringify(sendBody);
  }
  argv[0] = sendBody || '';

  if (typeof contentLength === 'undefined' && sendBody && typeof sendBody.length !== 'undefined')
    contentLength = sendBody.length;

  if (typeof contentLength !== 'undefined')
    defaultHeaders['content-length'] = contentLength;
  
  if (!this.headersSent)
    this.sendHeaders(defaultHeaders, body);

  try {
    this.httpResponse.end.apply(this.httpResponse, argv);
  }
  catch (error) {
    if (error.code === 'ERR_STREAM_WRITE_AFTER_END')
      console.warn('Pseudo-express tried to write after end. Suppressing here so we don\'t crash');
    else {
      console.error('Unexpected error in pseudo-express', error);
      throw error;
    }

  }

  return this;
}

/**
 * Ends the response process. This method actually comes from Node core, specifically the 
 * response.end() method of http.ServerResponse.
 *
 * Use to quickly end the response without any data. If you need to respond with data, instead 
 * use methods such as res.send() and res.json().
 *
 * @param {string} [_data]
 * @param {string} [_encoding]
 *
 * @returns this, to allow chaining
 */
PseudoExpressResponse.prototype.end = function PseudoExpressResponse$$end(_data, _encoding)
{
  this.httpResponse.end.apply(this.httpResponse, arguments);

  return this;
}

/** 
 * Sends a JSON response. This method sends a response (with the correct content-type) that is the 
 * parameter converted to a JSON string using JSON.stringify().
 *
 * @param {object} bodyObject   The object to send as the body of the response
 * @returns this, to allow chaining
 */
PseudoExpressResponse.prototype.json = function PseudeoExpressResponse$$json(bodyObject)
{
  this.send(JSON.stringify(bodyObject || typeof bodyObject));
  return this;
}

/**
 * Sets the HTTP status for the response. It is a chainable alias of Node’s response.statusCode.
 *
 * @param {number} statusCode
 * @returns this, to allow chaining
 */
PseudoExpressResponse.prototype.status = function PseudoExpressResponse$$status(statusCode)
{
  this.statusCode = statusCode;
  return this;
}
    
/**
 * Sets the response Location HTTP header to the specified path parameter.
 * A path value of “back” has a special meaning, it refers to the URL specified in the Referer
 * header of the request. If the Referer header was not specified, it refers to “/”.
 *
 * @param {string|URL|DcpURL} location
 * @returns this, to allow chaining
 */
PseudoExpressResponse.prototype.location = function PseudoExpressResponse$$location(location)
{
  if (location === '..')
    location = this.request.url.replace(/\/[^/]*$/, '') || '/';
  if (location === 'back')
    location = this.request.headers['http-referer'] || '/';

  return this.set('location', location).send(`Redirecting to ${location}`);
}

/**
 * Sets the Content-Type HTTP header to the MIME type as determined by the specified type.
 *
 * If the type starts with 'text/' and the value does not contain a charset attribute, the attribute
 * charset=utf-8 will be added to the value.
 *
 * @param {string} contentType
 * @returns this, to allow chaining
 */
PseudoExpressResponse.prototype.type = function PseudoExpressResponse$$type(contentType)
{
  if (contentType.startsWith('text/') && contentType.includes('charset='))
    contentType += '; charset="utf-8"';
  return this.set('content-type', contentType);
}

/**
 * Redirects to the URL derived from the specified path, with specified status, a positive integer
 * that corresponds to an HTTP status code. If not specified, status defaults to 302.
 *
 * @param {number} [status]
 * @param {string|URL} [path]
 * @returns this, to allow chaining
 */
PseudoExpressResponse.prototype.redirect = function PseudoExpressResponse$$redirect(status, path)
{
  if (typeof status !== 'number')
  {
    path = status;
    status = 302;
  }

  return this.status(status).location(path);
}

/* Try to tell user why pseudo-express "route" failed */
function dumpError(requestPE, responsePE, error)
{
  responsePE.set('content-type', 'text/plain; charset=utf8');
  responsePE.set('cache-control', 'no-cache');
  responsePE.set('access-control-allow-origin',  '*');
  responsePE.set('access-control-allow-headers', 'content-type');
  responsePE.statusCode = 500;
  responsePE.send(`500 Internal Server Error accessing ${requestPE.url} (${new Date()})\n\n` + error.stack);
}
