/**
 * @file worker/supervisor-cache.js
 *
 * A cache for the supervisor, anything the supervisor
 * may request that is cacheable (the same every time its requested)
 * can be cached in this class.
 *
 * Currently only jobs and modules are cached.
 *
 * @author Matthew Palma, mpalma@kingsds.network
 * @date May 2019
 */

/* global dcpConfig */

const debugging = require('dcp/debugging').scope('worker');
const { fetchURI, dumpObject } = require('dcp/utils');
const EventEmitter = require('events');
const { allowOriginsPurposes } = require('dcp/common/worker-constants');

const kvin = require('kvin');
const scopedKvin = new kvin.KVIN({Object: ({}).constructor,
                                  Array: ([]).constructor, 
                                  Function: (()=>{}).constructor});
                                  
class SupervisorCache extends EventEmitter {
  constructor (supervisor) {
    super({ captureRejections: false });

    this.supervisor = supervisor;
    this.cache = {
      job: {},
      module: {},
      dependency: {},
    }

    this.promises = {
      job: {},
      module: {},
      dependency: {},
    }

    this.lastAccess = {}
    for (let key in this.cache) {
      this.lastAccess[key] = {}
    }
  }

  /**
   * Returns an object listing what jobs and modules are currently cached.
   * @returns {object} - in the form: { job: [0xgen1, 0xgen2,...], modules: [modGroup1, modGroup2,...] }
   */
  get cacheDescription () {
    let description = {}
    for (let key in this.cache) {
      description[key] = Object.keys(this.cache[key])
    }
    return description
  }

  /**
   * Returns an array of all jobId currently cached
   * @returns {Array} all the jobId's in the cache
   */
  get jobs () {
    return Object.keys(this.cache.job);
  }

  /**
   * Attempts to look up an item from the cache.
   * If item is found its last access time is updated.
   *
   * @param {string} key - the cache to look in (job or module)
   * @param {string} id - the items identifier (jobAddress or module group name)
   *
   * @returns {any} The value of the stored item or null if nothing is found
   */
  fetch(key, id) {
    if (typeof this.cache[key] === 'undefined') {
      throw new Error(`${key} does not relate to any cache.`);
    }
    if (this.cache[key][id]) {
      this.lastAccess[key][id] = Date.now();
      return this.cache[key][id];
    }
    return null;
  }

  /**
   * Stores a fetched value for one of the caches.
   *
   * @param {string} key - the cache to store the item in
   * @param {string} id - the items identifier (job Address or module group name)
   * @param {any} value - the item to store
   *
   * @returns {any} - @value passed in
   */
  store (key, id, value) {
    if (typeof this.cache[key] === 'undefined') {
      throw new Error(`${key} does not relate to any cache.`)
    }
    this.cache[key][id] = value
    this.lastAccess[key][id] = Date.now()
    return value
  }

  /**
   * Removes a job or module group from the cache.
   *
   * @param {string} key - the cache to remove the item from (jobs or module groups)
   * @param {string} id - the items identifier (job Address or module group name)
   *
   * @returns {string} - @id passed in
   */
  remove (key, id) {
    if (typeof this.cache[key] === 'undefined') {
      throw new Error(`${key} does not relate to any cache.`)
    }
    delete this.cache[key][id];
    delete this.lastAccess[key][id];
    return id;
  }

  /** 
   * Fetch a job from the job cache.  If the job has components which are 
   * which need to be fetched over the network, they are fetched before the
   * returned promise is resolved.
   *
   * The job cache is initially populated during fetchTask.
   */
  async fetchJob(address, originManager) {
    let job = this.fetch('job', address);

    if (!job) {
      let e = new Error(`No job in supervisor cache with address ${address}`);
      e.code = 'ENOJOB';
      throw e;
    }

    // XXXpfr Excellent tracing.
    if (debugging('worker')) {
      dumpObject(job, 'SupervisorCache.fetchJob: job', 128);
    }

    if (!job.workFunction) {
      job.workFunction = await fetchURI(job.codeLocation, originManager, allowOriginsPurposes.fetchWorkFunctions);
      if(job.requirements.useStrict)
        job.useStrict  = true;
      delete job.codeLocation;
    }
    if (!job.arguments) {
      let promises = [];
      let uris = job.argumentsLocation;
      if (uris)
        for (let i = 0; i < uris.length; i++)
          promises.push(fetchURI(uris[i].value, originManager, allowOriginsPurposes.fetchArguments));

      job.arguments = await Promise.all(promises);

      delete job.argumentsLocation;
    }
    // if job input data is range object, we send the range object URI to the worker
    if (!job.mro && job.MROLocation) {
      job.mro = await fetchURI(job.MROLocation, originManager, allowOriginsPurposes.fetchData);
      delete job.MROLocation;
    }
    
    return job;
  }

  /**
   * Attempts to fetch a module group from the cache and
   * if it's not found it attempts to fetch then store
   * the module group from the package manager.
   *
   * @param {array} modulesArray - the array of modules requested 
   *        - (when stringified it's the identifier of the module group)
   *
   * @returns {Promise<object>} - the module group
   * @throws when the module group can not be fetched
   */
  async fetchModule(modulesArray) {
    const cacheKey = JSON.stringify(modulesArray);
    let modules = this.fetch('module', cacheKey);
    if (modules !== null) {
      return modules;
    }

    if (this.promises.module[cacheKey]) {
      return this.promises.module[cacheKey];
    }

    const {
      success,
      payload: responsePayload,
    } = await this.supervisor.packageManagerConnection.request('fetchModule', {
      modules: modulesArray,
    });

    if (!success) {
      /**
       * Preserving the error message by not rewrapping it with DCPError incase
       * we want to let clients know which module couldn't be fetched.
       */
      throw responsePayload;
    }

    this.promises.module[cacheKey] = responsePayload;
    modules = await this.promises.module[cacheKey];
    delete this.promises.module[cacheKey];
    return this.store('module', cacheKey, modules);
  }
}

exports.SupervisorCache = SupervisorCache;
