/**
 *  @file       protocol/connection/receiver.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @date       January 2020
 *
 *  The receiver class is responsible for listening on a transport instance
 * for messages, and for parsing and validating messages as they are received.
 * Upon a valid message, it will do the following:
 *    On Request: emit on the 'request' event
 *    On Response: resolve the request receipt that corresponds to the message ID
 */

const semver = require('semver');
const { assert, securityAssert } = require('dcp/common/dcp-assert');

/** @typedef {import('./connection').Connection} Connection */

let nanoid = require('nanoid').nanoid;

const { validityStampCache } = require('./validity-stamp-cache');
const { DCPError } = require('dcp/common/dcp-error');
const debugging = require('dcp/debugging').scope('dcp');

class Receiver {
  constructor(connection) {

    this.connection = connection;
    Object.defineProperty(this, 'debugLabel', { get: () => this.connection.debugLabel });

    // Used by non-ntp connections to determine "the present"
    // time: seconds since epoch when response was sent
    // receivedMs: monotonically increasing timestamp of receipt in milliseconds
    this.lastResponseTiming = {
      time: Date.now() / 1000,
      receivedMs: performance.now(),
    }
  }

  /**
   * This examines the payload's validity object and the Connection's validity stamp cache 
   * configuration.
   *
   * @param {Connection.Request} req
   * @returns {DCPError|false} false if the message is valid, instance of Error otherwise. When returning Error,
   *                    the code property will be set:
   * EDUP:        this request has already been seen; eg possibly part of a replay attack
   * EEXPIRED:    this request is too old to process, our cache doesn't go back that far
   * ETIMETRAVEL: this request claims to be from the future
   * EINVAL:      this request is not correctly formatted.
   */
  checkValidity(req) {
    const validity = req.payload.validity;
    if (!validity || !validity.stamp || typeof validity.time !== 'number') {
      return new DCPError(
        'Invalid request. Validity property must have `time` and `stamp`.',
        'EINVAL',
      );
    } else {
      // determine ttl of the request
      let ttl;
      if (!validity.ttl || typeof validity.ttl !== 'number') {
        ttl = this.connection.options.ttl.default || this.connection.options.ttl.min;
      } else {
        if (validity > this.connection.options.ttl.max) ttl = this.connection.options.ttl.max;
        else if (validity.ttl < this.connection.options.ttl.min) ttl = this.connection.options.ttl.min;
        else ttl = validity.ttl;
      }

      const now = this.connection.currentTime();
      const minimumPresent = now - dcpConfig.dcp.validitySlopValue;
      const maximumPresent = now + dcpConfig.dcp.validitySlopValue;
      const expirationTime = validity.time + ttl;

      if (validity.time > maximumPresent) {
        return new DCPError(
          `Request was sent from the future (${validity.time} > ${maximumPresent})`,
          'ETIMETRAVEL',
        );
      } else if (expirationTime < minimumPresent) {
        return new DCPError(
          `Request validity has expired (${expirationTime} < ${minimumPresent})`,
          'EEXPIRED',
          {
            timestamp: validity.time,
            offset: now - validity.time,
          },
        );
      }

      if (validityStampCache.insert(validity.stamp, expirationTime) !== true)
      {
        return new DCPError(
          `Duplicate request validity stamp: ${validity.stamp}`,
          'EDUP',
        );
      }
    }

    return false;
  }

  /**
   * @param batchInfo {string} [optional]
   */
  messageBodyDebugLogger(body, batchInfo)
  {
    const dcpsid = this.connection.dcpsid || '<new>';

    function now()
    {
      const d = new Date();
      var ms = String(d % 1000);
      var ds;

      switch (ms.length)
      {
        case 1:
          ms = '00' + ms;
          break;
        case 2:
          ms = '0' + ms;
          break;
      }

      ds = d.toLocaleTimeString().replace(/ .*/, '.' + ms);
      return ds;
    }

    if (typeof batchInfo === 'undefined')
      batchInfo = '';

    if (body.type === 'response') {
      debugging() && console.debug(this.debugLabel, `${now()}: session ${dcpsid.slice(0,6)}${batchInfo} sent response`, (body.payload && body.payload.operation) || '');
    } else if (body.type === 'request') {
      debugging() && console.debug(this.debugLabel, `${now()}: session ${dcpsid.slice(0,6)}${batchInfo} sent request ${body.payload && body.payload.operation}`);
    } else if (body.type === 'batch') {
      debugging() && console.debug(this.debugLabel, `${now()}: session ${dcpsid.slice(0,6)}${batchInfo} sent batch of length ${body.payload.length}, ${body.id.slice(-6)}`);
    } else {
      debugging() && console.debug(this.debugLabel, `${now()}: session ${dcpsid.slice(0,6)}${batchInfo} sent invalid message body`, body);
    }
  }

  /**
   * Central implementation for dispatching events based on message bodies. This routine understands all
   * signed message body types except 'ack' messages.
   * @throws {Error}
   */
  dispatchMessageBody(messageBody, batchDebugLabel)
  {
    debugging('messages') && this.messageBodyDebugLogger(messageBody, batchDebugLabel);

    switch(messageBody.type)
    {
      case 'response':
        this.onResponse(messageBody);
        break;
      case 'request':
        this.onRequest(messageBody);
        break;
      case 'batch':
        this.onBatch(messageBody);
        break;
      default:
        throw new DCPError(`Signed message has unknown type: ${messageBody.type}`, 'DCPC-1309');
    }
  }

  /**
   * This method is invoked when the connection receives a new request. It handles the special-case
   * operations like 'connect', 'keepalive', and 'close', otherwise emitting the "request" event for
   * API consumers to catch. Should only be invoked once we have a session.
   *
   * @param {Object}            messageBody   the message body from ether a signed message or a batch request
   * @param {object<Request>}   [req]         Request object corresponding to messageBody
   */
  onRequest(messageBody, req)
  {
    const that = this;

    if (!req)
      req = this.connection.Request.fromNetwork(messageBody);

    switch (req.payload.operation) {
      case 'close':
        this.connection.handleCloseRequest(req);
        break;
      case 'connect':
        debugging() && console.debug(this.debugLabel, 'Warning: request operation "connect" received after session established - closing');
        this.connection.__close(new DCPError('Received connection request on established session', 'DCPC-1321'));
        break;
      case 'keepalive':
        req.respond({ success: true, operation: 'keepalive' }).catch(keepaliveErrorHandler);
        break;
      default:
        securityAssert(this.connection.dcpsid);
        try
        {
          this.connection.emit('request', req);
        }
        catch(error)
        {
          debugging() && console.error(this.debugLabel, 'request handler error: ', error);
          this.connection.emit('error', error);
        }
        break;
    }

    function keepaliveErrorHandler(error)
    {
      debugging() && console.debug(that.debugLabel, `handleOperation could not respond to ${req.payload.operation} message: ${error.message} (${error.code})`);
      that.connection.__close(error);
    }
  }

  /**
   * Handle a request from the peer. Must only be invoked after the session has been established.
   *
   * @param {Object} signedMessage
   */
  handleRequest_haveSession(signedMessage)
  {
    const req = this.connection.Request.fromNetwork(signedMessage.body);
    const invalidError = this.checkValidity(req);

    assert(this.connection.dcpsid);
    assert(invalidError instanceof Error || !invalidError);

    if (invalidError)
    {
      debugging() && console.debug(this.debugLabel, `Request has invalid TTL (${invalidError.code}); ignoring request. Validity=`, req.payload.validity);
      req.respond(invalidError).catch(error => {
        debugging() && console.error('Error responding to message with invalid TTL:', error);
        this.connection.__close(error);
      });
      return;
    }

    this.onRequest(signedMessage.body, req);
  }

  /**
   * Handle a request from the peer. Must only be invoked before the session has not been established.
   * If the request is not a connect request, the connection is closed.
   *
   * @param {Object} signedMessage
   */
  async handleRequest_noSession(signedMessage)
  {
    const cacheSize = 10;       /* 0 should be enough */
    var cache;                  /* we keep a cache of recently-seen half sid in case sender retransmits a connect message */
    var bottomHalfSid;

    assert(!this.connection.dcpsid);

    if (signedMessage.body.payload?.operation === 'close')
    {
      debugging('receiver') && console.error(this.debugLabel, 'got close request with no session');
      this.connection.__close(new DCPError('connection closed', 'ECONNRESET'), true);
      return;
    }

    if (signedMessage.body.payload?.operation !== 'connect')
    {
      debugging('receiver') && console.error(this.debugLabel, `expected connect operation, got ${signedMessage.body.payload?.operation}`);
      this.connection.__close(new DCPError("Request operation received from peer was not 'connect'", 'DCPC-1307'));
      return;
    }

    const req = this.connection.Request.fromNetwork(signedMessage.body);
    debugging('receiver') && console.debug(this.debugLabel, 'received connect request.');
    /* NOTE - I think this is a cache across all instances of Receiver because handleRequest_noSession 
     * is on the prototype chain. Is that right? It should implemented better either way. /wg dec 2022 
     */
    if (!this.handleRequest_noSession.cache) 
      this.handleRequest_noSession.cache = {};
    cache = this.handleRequest_noSession.cache;

    const initiatorVersion = req.payload.data.version;
    const targetCompatibility = this.connection.constructor.VERSION_COMPATIBILITY;
    if (!semver.satisfies(initiatorVersion, targetCompatibility))
    {
      debugging('receiver') && console.debug(this.debugLabel, `Initiator version ${initiatorVersion} does not meet target targetCompatibility '${targetCompatibility}'`);
      const versionErr = new DCPError(`Initiator version ${initiatorVersion} does not meet target targetCompatibility '${targetCompatibility}'`, 'EVERSION');
      const connectResponse = new this.connection.Response(req, versionErr);
      await this.connection.sender.a$sendConnectMessage(connectResponse).catch(error => 'dont care');
      this.connection.__close(versionErr);
      return;
    }
    this.connection.peerVersion = initiatorVersion;

    const topHalfSid = req.payload.data.sid;
    if (cache.hasOwnProperty(topHalfSid)) {
      bottomHalfSid = cache[topHalfSid];
      /* This is so astronomically improbable except in the case that someone is trying to brute-force
       * a session key that it's worth writing to the user's console without invitation.
       */
      console.error(`*** Warning: remote presented recently-seen half sid ${topHalfSid}; reusing ${bottomHalfSid}`);
    } else {
      bottomHalfSid = nanoid();
      cache[topHalfSid] = bottomHalfSid;
      if (Object.keys(cache).length > cacheSize) {
        for (let prop in cache) {
          delete cache[prop];
          break;
        }
      }
    }

    if (typeof topHalfSid !== 'string' || topHalfSid.length < bottomHalfSid.length) {
      throw new DCPError(`Initiator sent an invalid DCPSID: ${topHalfSid}`, 'EDCPSID');
    }

    // Play silly buggers with the protocol version, so 5.0.0 clients will still
    // respect us, but more recent clients will behave better
    const version = (this.connection.peerVersion === '5.0.0')
      ? '5.0.0'   // how do you do, fellow 5.0.0
      : this.connection.constructor.VERSION;

    // Append our half of the dcpsid
    const dcpsid = topHalfSid + bottomHalfSid;
    const connectResponse = new this.connection.Response(req, {
      version,
      operation: 'connect'
    });

    this.connection.establishTarget(dcpsid);
    return this.connection.sender.a$sendConnectMessage(connectResponse).catch(error => this.connection.__close(error, true));
  }

  handleResponse_noSession(signedMessage)
  {
    const originalMessageBody = this.connection.messageLedger.findMessage(signedMessage.body.id);
    const operation = originalMessageBody && originalMessageBody.payload?.operation;

    if (operation !== 'connect')
      throw new Error(`received response for '${operation}' before session fully established`, 'EINVAL');

    this.onResponse(signedMessage.body);
  }

  handleResponse_haveSession(signedMessage)
  {
    this.onResponse(signedMessage.body);
  }

  /**
   * Handle an ack message from the peer. The signifies that the Message which is currently on the
   * flight deck has been received. Ack messages coincidentally carry a new sender nonce for the
   * connection in them, but that is handled at the connection level. This routine is concerned
   * strictly with message receipt acknowledgement.
   *
   * message-ledger promises are resolved here for Messages which are not Requests. Requests
   * have their message-ledger promises resolved when the Response arrives from the peer.
   *
   * Messages which were sent as part of a batch also have their receipt acknowledged here. Part of
   * this acknowledgment is the emission of the 'sent' event.
   *
   * @param {Object} signedMessage
   */
  handleAck(signedMessage)
  {
    const last = this.connection.sender.finishDelivery(signedMessage.body.messageId);

    if (!last) /* not expecting ack - must be dup */
    {
      debugging('sender') && console.debug(this.debugLabel, `finishDelivery had nothing for ${signedMessage.body.messageId}`);
      return;
    }

    if (last.ackToken !== signedMessage.body.token)
    {
      debugging('connection') && console.debug(`wanted ack token ${last.ackToken}; got ackToken ${signedMessage.body.token}`);
      const error = new DCPError('received invalid ack - closing connection', 'EINVAL');
      this.connection.__close(error);
      return;
    }

    this.connection.sender.setNextNonce(signedMessage.body.nonce);
    this.connection.emit('sent', last.message);

    if (!(last.message instanceof this.connection.Request))
      this.connection.messageLedger.fulfillMessagePromise(last.message.id, true);

    if (last.message instanceof this.connection.Batch)
    {
      for (let innerMessageBody of last.message.messages)
      {
        this.connection.emit('sent', this.connection.messageLedger.findMessage(innerMessageBody.id));
        if (innerMessageBody.type !== 'request')
          this.connection.messageLedger.fulfillMessagePromise(innerMessageBody.id, true);
      }
    }
  }

  /**
   * This method is invoked when the connection receives a new response.
   * It should validate the response against the session state.
   *
   * @param {Object} messageBody - either the message body from a signed message, or a batch request
   */
  onResponse(messageBody)
  {
    const resp = this.connection.Response.fromNetwork(messageBody);

    debugging('receiver') && console.debug(this.debugLabel, 'received response', messageBody.type, resp.payload?.operation || '');

    this.lastResponseTiming.time = resp.time;
    this.lastResponseTiming.receivedMs = performance.now();

    if (!resp || !resp.id)
    {
      this.connection.__close(new DCPError('received invalid response from peer', 'DCPC-1301'));
      return;
    }
    
    this.connection.emit('recvResponse', resp);
    this.connection.messageLedger.fulfillMessagePromise(resp.id, resp);
  }

  /**
   * This method handles rehydrating Batch Requests and then
   * passes internal messages on to appropriate handlers.
   *
   * @param {Object} messageBody - either the message body from a signed message, or a batch request
   */
  onBatch(messageBody)
  {
    const batch = this.connection.Batch.fromNetwork(messageBody);
    var batchDebugLabel;

    debugging() && (batchDebugLabel = ' batch ' + batch.id.slice(-6));

    for (let innerMessageBody of batch.messageObjects)
      this.dispatchMessageBody(innerMessageBody, batchDebugLabel);
  }
}

Object.assign(module.exports, {
  Receiver,
});
