/**
 *  @file       dcp-localstorage.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *              Wes Garland, wes@distributive.network
 *  @date       March 2020, Sep 2022
 *
 * This module is used to provide a uniform localStorage
 * interface on node and the browser. In node it uses the
 * node-localstorage npm package, and in the browser it uses
 * the built-in localstorage API.
 */

const debugging = require('dcp/debugging').scope('localStorage');

/** Fall back to host environment's implementation when not nodejs */
if (require('./dcp-env').platform !== 'nodejs')
{
  exports.localStorage = (globalThis || window || self).localStorage;

  if (typeof exports.localStorage === 'undefined' || exports.localStorage === null)
    throw new Error(`Host environment is ${require('./dcp-env').platform} but localStorage is not defined!`);
}
else
{
  // These are the properties and methods of localStorage
  // that would do nothing if there was no localStorage data
  const emptyLocalStorageStub = {
    length: 0,
    key: () => null,
    getItem: () => null,
    removeItem: () => {},
    clear: () => {},
  }

  const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
  const process = requireNative('process');
  const fs      = requireNative('fs');
  const hash    = require('./hash');
  const applicationStorageId = process.mainModule ? hash.calculate(hash.eh1, process.mainModule.filename) : 'default';

  /** 
   * Deferring this calculation as late as possible lets us change the homedir after loading dcp-client,
   * but before reading/writing to local storage.
   */
  function calculateLocalStoragePath()
  {
    const path = requireNative('path');
    return path.join(require('./dcp-dot-dir').dotDcpDir, 'localStorage', applicationStorageId);
  }

  /**
   * Create disk storage. This is deferred as late as possible to avoid
   * writing to the hard disk just to check to see if a property in an
   * empty object exists.
   */
  function createBackingStore()
  {
    const { LocalStorage } = requireNative('node-localstorage');

    if (!fs.existsSync(exports.localStoragePath))
    {
      debugging() && console.log("Creating localStorage path:", exports.localStoragePath);
      fs.mkdirSync(exports.localStoragePath, { recursive: true });
    }

    return new LocalStorage(exports.localStoragePath);
  }

  var backingStore;
  /**
   * Strategy: localStorage proxy in front of the node-localstorage::LocalStorage object, so that
   * can avoid actually creating the local storage until it is truly necesary.
   */
  exports.localStorage = new Proxy({}, {
    get(target, prop)
    {
      debugging() && console.debug(`localStorage: resolving ${prop}`);
      
      /* fast-path - already instanciated backing store */
      if (backingStore && prop !== 'getPath')
        return backingStore[prop].bind(backingStore);

      if (!exports.localStoragePath)
      {
        exports.localStoragePath = calculateLocalStoragePath();
        if (fs.existsSync(exports.localStoragePath))
        {
          /* Storage already on disk => intantiate immediately. */
          backingStore = createBackingStore();
          if (prop in backingStore)
            return backingStore[prop].bind(backingStore);
        }
      }

      if (emptyLocalStorageStub.hasOwnProperty(prop))
        return emptyLocalStorageStub[prop];

      if (prop === 'getPath') /* debug helper, not API */
      {
        return function localStorage$$getPath() {
          return exports.localStoragePath;
        };
      }

      /* real storage does not exist, prop not in stubs => this is a method we can't fake,
       * so we must instantiate the real deal
       */
      backingStore = createBackingStore();
      return backingStore[prop].bind(backingStore);
    }
  });

  exports.localStoragePath = false;
}
