/**
 *  @file       protocol/connection/batch.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @date       January 2020
 *
 *  The ConnectionBatch is a factory for a batch message class that is bound
 *  to a connection instance.
 * 
 *  The batch message is a type of message that can contain an array of request
 *  and response messages.
 */
'use strict';

exports.batchCtorFactory = function batchCtorFactory(Message)
{
  class Batch extends Message
  {
    static type = 'batch';

    constructor(messages=[])
    {
      super();
      // batch messages are internal so auto-assign ID on construction
      this.type = 'batch';
      this.messages = messages;
      this.messageObjects = null;
    }

    /**
     * This static method is used by the connection to rehydrate a batch that was received.
     * Note that the messageObjects property is populated instead of the messages property
     * because the messages are still in their dehydrated object format.
     *
     * @param {object} networkObj    An object which represents the network form of a Batch message;
     *                               typically a signed message body.
     */
    static fromNetwork(networkObj)
    {
      const batch = super.fromNetwork(networkObj);
      batch.messageObjects = networkObj.payload;
      return batch;
    }

    /**
     * This method is used to dehydrate the request into a plain object before it is sent to the peer.
     * @returns {object} - An object that will be sent as-is to the peer
     */
    toNetwork()
    {
      const obj = super.toNetwork();
      obj.type = 'batch';
      obj.payload = (this.messages || []).map(msg => msg.toNetwork());

      return obj;
    }
  }

  return Batch;
}
