/* global dcpConfig */ // eslint-disable-line no-redeclare
// @ts-check
'use strict';

const debugging = require('dcp/debugging').scope('worker');
const { ms } = require('dcp/utils');

/**
 * It is important that config properties can be changed dynamically
 * and have the new values reflected in supervisor/worker operations.
 */
class Config
{
  constructor ()
  {
    if (debugging('supervisor'))
    {
      console.debug('progressReportIntervalMs', Number(this.sandboxConfig?.progressReportIntervalMs));
      console.debug('progressTimeoutMs', Number(this.sandboxConfig?.progressTimeoutMs));
      console.debug('generalTimeoutMs', Number(this.sandboxConfig?.generalTimeoutMs));
      console.debug('sliceTimeoutMs', Number(this.sandboxConfig?.sliceTimeoutMs));
      console.debug('maxSandboxUse', Number(this.sandboxConfig?.maxSandboxUse));

      console.debug('repoManMultiplier', Number(this.hive.repoMan?.thresholdMultiplier));
      console.debug('repoManFrequencyMs', Number(this.hive.repoMan?.frequencyMs));

      console.debug('minSandboxSlack', Number(this.hive.tuning?.minSandboxSlack));
      console.debug('maxSandboxSlack', Number(this.hive.tuning?.maxSandboxSlack));
      console.debug('maxExtraSandboxes', Number(this.hive.tuning?.maxExtraSandboxes));

      console.debug('cachedJobsThreshold', Number(this.hive.tuning?.cachedJobsThreshold));
      console.debug('mustPruneMultiplier', Number(this.hive.tuning?.mustPruneMultiplier));
      console.debug('prefetchIntervalMs', ms(Number(this.hive.tuning?.prefetchInterval)));
      console.debug('maxSliceRetries', Number(this.hive.tuning?.maxSandboxSliceRetries));
      console.debug('pruneFrequencyMs', Number(this.hive.tuning?.pruneFrequencyMs));
      console.debug('defaultDelayIncrementMs', Number(this.hive.tuning?.defaultDelayIncrementMs));
      console.debug('reservedSliceLifetimeMs', Number(this.hive.tuning?.reservedSliceLifetimeMs));
      console.debug('-------------------------------------------------------------------------');
      console.debug('progressReportIntervalMs', this.progressReportIntervalMs);
      console.debug('progressTimeoutMs', this.progressTimeoutMs);
      console.debug('generalTimeoutMs', this.generalTimeoutMs);
      console.debug('sliceTimeoutMs', this.sliceTimeoutMs);
      console.debug('maxSandboxUse', this.maxSandboxUse);

      console.debug('sandboxConfig', this.sandboxConfig);
      console.debug('connectionOptions', this.connectionOptions);

      console.debug('repoManMultiplier', this.repoManMultiplier);
      console.debug('repoManFrequencyMs', this.repoManFrequencyMs);

      console.debug('minSandboxSlack', this.minSandboxSlack);
      console.debug('maxSandboxSlack', this.maxSandboxSlack);
      console.debug('maxExtraSandboxes', this.maxExtraSandboxes);

      console.debug('cachedJobsThreshold', this.cachedJobsThreshold);
      console.debug('mustPruneMultiplier', this.mustPruneMultiplier);
      console.debug('prefetchIntervalMs', this.prefetchIntervalMs);
      console.debug('maxSliceRetries', this.maxSliceRetries);
      console.debug('pruneFrequencyMs', this.pruneFrequencyMs);
      console.debug('defaultDelayIncrementMs', this.defaultDelayIncrementMs);
      console.debug('reservedSliceLifetimeMs', this.reservedSliceLifetimeMs);

      console.debug('detectSuspensionIntervalMs', this.detectSuspensionIntervalMs);
      console.debug('detectSuspensionLateMultiplier', this.detectSuspensionLateMultiplier);
    }
  }

  get hive () { return dcpConfig.supervisor; }
  //
  // The dcpConfig.supervisor accessors
  //
  get progressReportIntervalMs () { return Number(this.sandboxConfig?.progressReportIntervalMs || ms(10 * 60)); }
  get progressTimeoutMs ()        { return Number(this.sandboxConfig?.progressTimeout || ms(5 * 60)); }
  get generalTimeoutMs ()         { return Number(this.sandboxConfig?.generalTimeoutMs || ms(6)); }
  get sliceTimeoutMs ()           { return Number(this.sandboxConfig?.sliceTimeoutMs || ms(24 * 60 * 60)); }

  get maxSandboxUse ()            { return Number(this.sandboxConfig?.maxSandboxUse ?? 1000); }
  get sandboxConfig ()            { return this.hive.sandbox; }
  get connectionOptions ()        { return this.hive.dcp.connectionOptions; }

  get repoManMultiplier ()        { return Number(this.hive.repoMan?.thresholdMultiplier || 2); }
  get repoManFrequencyMs ()       { return Number(this.hive.repoMan?.frequencyMs || ms(60)); }

  get minSandboxSlack ()          { return Number(this.hive.tuning?.minSandboxSlack ?? 0.2); }
  get maxSandboxSlack ()          { return Number(this.hive.tuning?.maxSandboxSlack ?? 0.5); }
  get maxExtraSandboxes ()        { return Number(this.hive.tuning?.maxExtraSandboxes ?? 8); }

  get cachedJobsThreshold ()      { return Number(this.hive.tuning?.cachedJobsThreshold ?? 0); }
  get mustPruneMultiplier ()      { return Number(this.hive.tuning?.mustPruneMultiplier ?? 1.3); }
  get prefetchIntervalMs ()       { return ms(Number(this.hive.tuning?.prefetchInterval ?? 20)); }
  get maxSliceRetries ()          { return Number(this.hive.tuning?.maxSandboxSliceRetries ?? 1); }
  get pruneFrequencyMs ()         { return Number(this.hive.tuning?.pruneFrequencyMs ?? ms(30)); }

  get reservedSliceLifetimeMs ()  { return Number(this.hive.tuning?.reservedSliceLifetimeMs || ms(10 * 60)); }
  get defaultDelayIncrementMs ()  { return Number(this.hive.tuning?.defaultDelayIncrementMs || 50); }
  get maxProportionOfLongJobs ()  { return Number(this.hive.tuning?.maxProportionOfLongJobs || 0.6); }

  get detectSuspensionIntervalMs     () { return Number(this.hive.tuning?.detectSuspensionIntervalMs || ms(5)); }
  get detectSuspensionLateMultiplier () { return Number(this.hive.tuning?.detectSuspensionLateMultiplier || 2); }
}
exports.Config = Config;
