/**
 *  @file       protocol/connection/response.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @date       January 2020
 *
 *  The ConnectionResponse is a factory for a response class that extends a bound
 *  Message class.
 */
'use strict';

const wallet = require('dcp/dcp-client/wallet');
const debugging = require('dcp/debugging').scope('dcp');

/** @typedef {import('./connection').Connection} Connection */

/**
 * @param {*} Message      Message constructor (per-connection)
 * @returns Response constructor derived from the passed Message constructor
 */
exports.responseCtorFactory = function responseCtorFactory(Message)
{
  class Response extends Message
  {
    static type = 'response';

    /**
     * @param {Connection.Request} request - The request that this instance will be a response to
     * @param {*|Error} payload - The payload data, or an instance of Error if the response should contain an ErrorPayload
     *
     * @note a null request is used internally to 
     */
    constructor(request, payload)
    {
      super(request?.id);

      if (payload instanceof Error)
        payload = new this.connection.ErrorPayload(payload);

      this.success = !(payload instanceof this.connection.ErrorPayload);
      this.payload = payload;
      this.type = 'response';
    }
    
    /**
     * This static method is used by the connection to rehydrate a response that was received.
     * @param {object} networkObj
     *
     * @returns {object|boolean}   object is returned when it can be converted from network 
     *                             representation, otherwise we return false
     * @note - treat as infallible
     */
    static fromNetwork(networkObj)
    {
      const res = super.fromNetwork(networkObj);
      
      /* refuse to convert a network object that is wrong */
      if (!res || typeof res.success !== 'boolean')
        return false;
      if (res.success === false && (typeof res.payload?.message !== 'string' || !res.payload?.origin || !res.payload?.name))
        return false;
      
      /* Create ErrorPayload as needed */
      if (res.success === false)
      {
        const payload = Object.create(Message.connection.ErrorPayload.prototype, {
          constructor:  {
            value:        Message.connection.ErrorPayload,
            enumerable:   false,
            writable:     false,
            configurable: false,
          }
        });
        Object.assign(payload, res.payload);
        res.payload = payload;

        try
        {
          payload.origin = new wallet.Address(payload.origin);
        }
        catch(error)
        {
          debugging() && console.error('problem with response payload origin:', error);
          return false;
        }
      }
      
      return res;
    }

    /**
     * This method is used to dehydrate the response into a plain object before it is sent to the peer.
     * @returns {object} - An object that will be sent as-is to the peer
     */
    toNetwork()
    {
      const obj = super.toNetwork();
      obj.success = this.success;
      return obj;
    }
  }

  return Response;
}
