/**
 * Polyfill for Promise.any
 * @param {Promise[]} promiseArray
 * @returns {Promise}
 */
exports.Promise_any = function polyfill$$Promise_any(promiseArray)
{
  if (typeof Promise.any === 'function')
    return Promise.any(promiseArray);
  return new Promise((resolve, reject) => {
    const promiseErrors = new Array(promiseArray.length);
    let counter = 0;
    for (let index = 0; index < promiseArray.length; index++)
    {
      Promise.resolve(promiseArray[index])
        .then(resolve) // Resolve when any of the input promise resolves.
        .catch((error) => {
          promiseErrors[index] = error;
          counter = counter + 1;
          if (counter === promiseArray.length) // All promises rejected, reject outer promise.
            reject(promiseErrors);
        });
    }
  });
}
