/**
 *  @file       protocol/connection/ack.js
 *  @author     KC Erb, kcerb@kingsds.network
 *  @date       January 2021
 *
 *  The ConnectionAck is a factory for an ACK message class that is bound
 *  to a connection instance.
 * 
 *  The ACK message is a type of message that bears the minimal information needed
 *  to confirm to the recipient that the sender has received a message/batch.
 * 
 *  ACKs are a little different depending on weather they are being sent or received.
 *  When sent, an ack is acknowledging a message that has been received.
 *  When received, an ack corresponds to a message that the receiver has sent.
 * 
 *  This asymmetry is reflected in the constructor.
 */
'use strict';

const { assert } = require('dcp/common/dcp-assert');
const { baseMessageCtorFactory } = require('./base-message');

let nanoid = require('nanoid').nanoid;
let nonceSerialId = 0;

/** @typedef {import('./connection').Connection} Connection */

exports.ackCtorFactory = function ackCtorFactory(connection)
{
  const BaseMessage = baseMessageCtorFactory(connection); /* per-connection constructor */
  class Ack extends BaseMessage
  {
    /**
     * Create an AckMessage using details from the messaging we are ACKing.
     * @param {Connection.Message|object} signedMessage The message we are acknowledging receipt of.
     */
    constructor(signedMessage)
    {
      super();
      assert(signedMessage.body.type !== 'ack');
      let message = signedMessage;
      this.token = message.body.ackToken || message.body.token;
      this.messageId = message.body.id;
      this.type = 'ack';
      this.nonce = `${this.connection.id}-${nonceSerialId++}-${nanoid()}`;
      this.ref = undefined;
      this.unref = undefined;
    }

    /**
     * This method is used to dehydrate the ack into a plain object before it is sent to the peer.
     * @returns {object} - An object that will be sent as-is to the peer.
     */
    toNetwork()
    {
      const obj = {};
      obj.id = this.id;
      obj.nonce = this.nonce;
      obj.messageId = this.messageId;
      obj.token = this.token;
      obj.type = this.type;
      if (this.connection.dcpsid)
        obj.dcpsid = this.connection.dcpsid; /* dcpsid used to find Connection during target reconnect */
      return obj;
    }
  }
  return Ack; /* newly-made per-connection constructor */
}
