exports.DEFAULT_REQUIREMENTS = {
  engine: {
    es7: null,
    spidermonkey: null
  },
  environment: {
    webgpu: null,
    offscreenCanvas: null,
    fdlibm: null
  },
  browser: {
    chrome: null
  },
  details: {
    offscreenCanvas: {
      bigTexture4096: null,
      bigTexture8192: null,
      bigTexture16384: null,
      bigTexture32768: null,
    }
  },
  discrete: null,
  useStrict: null,
};

/* takes a requirements object and trims it in place to remove any properties that are not in the default requirements */
exports.removeBadRequirements = function removeBadRequirements (testRequirements, defaultRequirements)
{
  Object.keys(testRequirements).forEach(requirement =>
  {
    if (typeof defaultRequirements[requirement] === 'object' && defaultRequirements[requirement] !== null)
      return removeBadRequirements(testRequirements[requirement], defaultRequirements[requirement]);
    
    else if(typeof defaultRequirements[requirement] === 'undefined' || typeof testRequirements[requirement] !== 'boolean')
      delete testRequirements[requirement];
  });
};

/* takes a requirements object and builds it into a proper requirement object that can be used by the protocol */
exports.buildProtocolRequirements = function buildProtocolRequirements (testRequirements, defaultRequirements)
{
  Object.keys(testRequirements).forEach(requirement =>
  {
    if (typeof defaultRequirements[requirement] === 'object' && defaultRequirements[requirement] !== null)
      return buildProtocolRequirements(testRequirements[requirement], defaultRequirements[requirement]);
    
    else if(typeof defaultRequirements[requirement] !== 'undefined' && typeof testRequirements[requirement] === 'boolean')
      defaultRequirements[requirement] = testRequirements[requirement];
  });
};