/**
 *  @file       confirm.js
 *              Replacement for native `window.confirm` to fit in with the rest of our modal system.
 *              Our version allows you to customize the text of the buttons associated to returning true
 *              or false from the modal.
 * 
 *  @author     Nazila Kharazian - nazila@kingsds.network
 *  @date       Apr 2020
 */
const utils = require('./utils');

exports.config = {
  id: 'dcp-modal-confirm',
  required: ['dcp-modal-confirm-form', 'dcp-modal-confirm-prompt', "dcp-modal-confirm-positive-button", "dcp-modal-confirm-negative-button"],
  optional: ['dcp-modal-confirm-title'],
  path: "./templates/confirm-modal.html",
};

/**
 * @param {string} message The text which will be alerted.
 * @param {Object} options
 * @param {string} [options.positive="OK"] Text label of 'positive' button.
 * @param {string} [options.negative="Cancel"] Text label of 'negative' button.
 * @param {string} [options.title=""] Text in the title area.
 * @param {function} [options.onClose] Override default onClose behavior. An instance of `modal` is handed to the function.
 * @memberof module:dcp/client-modal
 * @returns {boolean} True if the 'positive' button was selected, false if the negative button was.
 * @throws If modal is closed without the form being submitted (submitting the form closes the modal).
 * @async
 * @alias confirm
 * @access public
 */
exports.confirm = async function (prompt, {positive = "OK", negative = "Cancel", title = "", onClose = null} ={}) {
  const [elements, formPromise, optionalElements] = await utils.initModal(exports.config, onClose);
  const [modal, form, formPrompt, positiveButton, negativeButton] = elements;
  const [modalTitle] = optionalElements;

  formPrompt.innerText = prompt;
  positiveButton.innerText = positive;
  negativeButton.innerText = negative;
  if (modalTitle) modalTitle.innerText = title;

  // Reverse order of buttons on windows (L <-> R)
  const platformIsWindows = window.navigator.platform.includes("Win");
  if (platformIsWindows) {
    const footer = document.querySelector('.dcp-modal footer');
    if (footer) footer.classList.add('dcp-platform-win');
  };

  let formResult = true;
  // don't need to hook up positive button because the
  // 1st button's default behaviour is to submit the form
  // positiveButton.onclick = () => form.submit();
  negativeButton.onclick = () => {
    formResult = false;
    form.submit();
  };

  await formPromise;
  utils.MicroModal.close(modal.id);
  return formResult;
}