/**
 *  @file     events/event-subscriber.js
 *  @author   Ryan Rossiter <ryan@kingsds.network>
 *  @date     March 2020
 * 
 *  This file is the client-side companion to the event-router.
 *  It maintains a map of subscription tokens that the event router has provisioned
 *  for it, and calls the associated callbacks when the event router emits a new event.
 */

const protocolV4 = require('dcp/protocol-v4');
const { DcpURL } = require('dcp/common/dcp-url');
const { DCPError } = require('dcp/common/dcp-error');
const debugging = require('dcp/debugging').scope('event-subscriber');
const { v4: uuidv4 } = require('uuid');
const { leafMerge } = require('dcp/utils');
const dcpEnv = require('dcp/common/dcp-env');

/** @typedef {import('./common-types').DcpEvent} DcpEvent */
/** @typedef {import('./common-types').SubscriptionToken} SubscriptionToken */
/** @typedef {import('./common-types').EventLabel} EventLabel */
/** @typedef {import('./common-types').SubscriptionOptions} SubscriptionOptions */


/**
 * A container for callback and SubscriptionToken pairs
 * @typedef {Object} CallbackHandle
 * @property {SubscriptionToken} token
 * @property {function} callback
 */

/**
 * @typedef {Object} Subscription
 * @property {EventLabel} label - Event label
 * @property {function[]} callbacks - The callbacks that will be invoked when an event is received for this subscription
 * @property {SubscriptionOptions} options - Additional options
 * @property {string} optionsStr - A string used to memoize stringifying the options object
 */

/**
 * @constructor
 * @param {object}      options         configuration options for this instance of the EventSubscriber. Default
 *                                      options are given via dcpConfig.eventSubscriber.
 */
class EventSubscriber
{
  constructor(eventEmitter, options)
  {
    this.options = options = leafMerge(options, dcpConfig.eventSubscriber);
    this.eventEmitter = eventEmitter;
    this.subscriptions = new Map();
    this.seenEventIds = [];
    this.nextSeenEventIdSlot = 0;
    
    /**
     * Interval to keep the connection alive when no messages are being
     * received.
     * @type {NodeJS.Timer}
     */
    this._keepaliveIntervalHnd = null;

    this.onEventRouterConnectionInterrupted = () => {
      this.openEventRouterConn();
      this.setupEventRouterConnectionEvents();
      this.reestablishSubscriptions();
    }

    const ceci = this;

    this.eventRouterConnection = null;
    this.openEventRouterConn = function openEventRouterConn()
    {
      ceci.eventRouterConnection = new protocolV4.Connection(dcpConfig.scheduler.services.eventRouter);
      ceci.eventRouterConnection.on('end', ceci.onEventRouterConnectionInterrupted);
    }
    this.openEventRouterConn();
    this.setupEventRouterConnectionEvents();
  }

  async close() {
    debugging() && console.log(`event-subscriber: closing EventSubscriber connection`);

    let subs = this.subscriptions.entries();
    const ps = [];
    for (let [label] of subs) {
      ps.push(this.unsubscribe(label));
    }
    await Promise.all(ps);

    this.eventRouterConnection.off('end', this.onEventRouterConnectionInterrupted);

    this.setKeepalive(false);

    debugging() && console.log('event-subscriber: closing event-router connection...');
    this.eventRouterConnection.close();
    this.subscriptions.clear();
    this.hookedEventRouterConnectionEvents = false;
  }

  async reestablishSubscriptions() {
    let subs = this.subscriptions.entries();
    debugging() && console.log(`event-subscriber: reestablishing ${this.subscriptions.size} subscriptions`);

    const eventTypes = require('dcp/common/dcp-events').eventTypes;
    const reliableEvents = [];
    const optionalEvents = [];
    for (let [label, oldToken] of subs) {
      if (oldToken.options)
      {
        // schedmsg special case
        await this.provisionSubscriptionToken(label, oldToken.options);
      }
      else if (eventTypes[label] && eventTypes[label].reliable)
      {
        reliableEvents.push(label);
      }
      else
      {
        optionalEvents.push(label);
      }
    }
    try
    {
      if (reliableEvents.length || optionalEvents.length) {
        const message = {
          reliableEvents,
          optionalEvents,
          options: this.options
        }

        await this.provisionSubscriptionTokens(message);
      }
      
    }
    catch (error)
    {
      debugging() && console.warn(`event-subscriber: error establishing subscription (${sub.label}):`, error);
    }
  }

  setupEventRouterConnectionEvents() {
    debugging() && console.log(`event-subscriber: setupEventRouterConnectionEvents`)
    this.eventRouterConnection.on('request', (req) => {
      const { operation } = req.payload;
      if (operation === 'event') this.onEventRequest(req);
      else req.respond(new Error(`Unknown EventSubscriber operation: ${operation}`));
    });
  }

  async onEventRequest(req) {
    debugging('verbose') && console.log(`event-subscriber: onEventRequest`);
    // data = req.payload.data.event
    const { token, event: data } = req.payload.data;
    const event = data.data;
    const eventId = data.eventId;

    debugging() && console.debug(`131: event ${eventId} (${event.eventName}):`, req.payload.data);
    if (this.subscriptions.has(event.eventName))
    {
      const { token: eventToken } = this.subscriptions.get(event.eventName);
      debugging('verbose') && console.log(`event-subscriber: event: ${event.eventName}`);
      if (eventToken !== token)
        req.respond(new Error(`No subscription registered for token ${token}`));
      else if (eventId && this.seenEventIds.includes(eventId))
        req.respond(new Error(`This event has already been sent: ${eventId}`));
      else
      {
        const label = event.eventName;
        // on each request, we push the eventIds to keep track of events we have seen.
        // this will be filtered in the re-established events.
        if (eventId)
        {
          this.seenEventIds[this.nextSeenEventIdSlot] = eventId;
          this.nextSeenEventIdSlot = (this.nextSeenEventIdSlot + 1) % Number(this.options.seenListSize);
        }
        
        delete event.eventName;
        if (!this.eventEmitter.eventIntercepts)
          this.eventEmitter.emit(label, event);
        else
        {
          if (this.eventEmitter.eventIntercepts[label])
            this.eventEmitter.eventIntercepts[label](event)
          else
            this.eventEmitter.emit(label, event);
        }
        req.respond('success');
      }
    }
    else
    {
      console.warn(`No subscription registered for label ${event.eventName}`);
      req.respond(new Error(`No subscription registered for token ${event.eventName}`));
    }
  }

  /**
   * Registers this subscription with the event router, and saves the returned
   * subscription token into the this.subscriptions map.
   * @param {EventLabel} label
   * @param {SubscriptionOptions} options
   */
  async provisionSubscriptionToken(label, options) {
    debugging('verbose') && console.log(`event-subscriber: provisionSubscriptionToken(${label})`);

    if (this.eventRouterConnection.state.in(['closed','closing']))
    {
      this.openEventRouterConn();
      this.setupEventRouterConnectionEvents();
    }
    let res = await this.eventRouterConnection.request('subscribe', {
      label, options,
    }).catch(async (error) => {
      debugging('verbose') && console.error(`Failed to send subscription request to scheduler for the event ${label}: ${error}. Will try again.`);
      this.eventRouterConnection.close();
    });
    
    if (res) {
      const token = res.payload?.token;
      this.subscriptions.set(label, { token, options });
    }

  }

  async provisionSubscriptionTokens(message) {
    debugging('verbose') && console.log(`event-subscriber: provisionSubscriptionTokens(${JSON.stringify(message)})`);
    let res = await this.eventRouterConnection.request('subscribeMany', message).catch(async (e) => {
      debugging('verbose') && console.error(`Failed to send subscribeMany request to scheduler: ${e}. Will try again`);
      this.eventRouterConnection.close();
    });
    
    if (res && res.success) {
      const tokenEventPairs = res.payload.tokens;
      tokenEventPairs.forEach((tokenAndEvent) => {
        const label = tokenAndEvent.event;
        const token = tokenAndEvent.token;
        this.subscriptions.set(label, { token });
      })
    } else if (res && !res.success) {
      throw new Error(`Failed to subscribe to events, ${res.payload}`);
    }
    
  }

  /**
   * Unregisters a subscription from the event router
   * @param {EventLabel} label
   * @param {SubscriptionToken} token 
   */
  async releaseSubscriptionToken(label, token) {
    debugging('verbose') && console.log(`event-subscriber: releaseSubscriptionToken(${label})`);
    await this.eventRouterConnection.request('unsubscribe', {
      label, token,
    }).catch(async (e) => {
      debugging('verbose') && console.error(`Failed to unsubscribe from event ${label}: ${e}. Will try again.`)
      this.eventRouterConnection.close();
    });
  }

  /**
   * @param {EventLabel} label - Event label
   * @param {function} callback
   * @param {SubscriptionOptions} options - Additional options
   */
  async subscribeManyEvents(reliableEvents, optionalEvents, options={}) {
    this.options = options;
    const noSubReliableEvents = [];
    reliableEvents.forEach((ev) => {
      for (let [t, sub] of this.subscriptions)
      {
        // search for a subscription with identical label,
        // to avoid making duplicate subscriptions
        if (ev === sub.label)
        {
          return;
        }
      }
      if (!noSubReliableEvents.includes(ev)) {
        noSubReliableEvents.push(ev);
      }
    })

    const noSubOptionalEvents = [];
    optionalEvents.forEach((ev) => {
      for (let [t, sub] of this.subscriptions)
      {
        // search for a subscription with identical label,
        // to avoid making duplicate subscriptions
        if (ev === sub.label)
        {
          return;
        }
      }
      if (!noSubOptionalEvents.includes(ev)) {
        noSubOptionalEvents.push(ev);
      }
    })

    if (reliableEvents.length || optionalEvents.length)
    {
      const message = {
        reliableEvents: noSubReliableEvents,
        optionalEvents: noSubOptionalEvents,
        options,
      }
      debugging() && console.log('event-subscriber: provisioning:', message);
      await this.provisionSubscriptionTokens(message);
    }
    
    // Start the keepalive interval
    this.setKeepalive();
  }
  
  async subscribe(label, options={}) {
    debugging() && console.log(`event-subscriber: subscribe(${label})`);
    let token;
    for (let [subLabel, t] of this.subscriptions) {
      // search for a subscription with identical label and filter,
      // to avoid making duplicate subscriptions
      if (label === subLabel) {
        token = t;
        break;
      }
    }

    if (!token) {
      await this.provisionSubscriptionToken(label, options);
    }

    // Start the keepalive interval
    this.setKeepalive();
  }

  /**
   * @param {string} label
   */
  async unsubscribe(label) {
    debugging() && console.log(`event-subscriber: unsubscribe)${label})`);
    if (!this.subscriptions.has(label)) {
      return;
    }
    
    const token = this.subscriptions.get(label)
    await this.releaseSubscriptionToken(label, token);
    this.subscriptions.delete(label);

    // If no subscriptions remain, disable the keepalive and allow the Connection
    // to expire
    if (this.subscriptions.size === 0)
      this.setKeepalive(false);
  }

  /**
   *  De/activate an interval to send keepalives over the event-router connection
   *
   *  @param {Boolean} keepalive If true, activate the interval. If false, remove it
   */
  setKeepalive(activate = true)
  {
    const that = this;
    const keepaliveInterval = Number(this.options.keepaliveInterval) || 3 * 60;  /* seconds */

    if (!activate /* => deactivate */)
    {
      /* clear the watchdog interval, and neuter already-queued doKeepalive()s */
      if (this._keepaliveIntervalHnd)
        clearInterval(this._keepaliveIntervalHnd);
      this._keepaliveIntervalHnd = null;
      return;
    }

    if (activate && !keepaliveInterval)
    {
      debugging() && console.debug('event-subscriber: configured for no keepalive interval');
      return;
    }

    if (!this._keepaliveIntervalHnd)
      this._keepaliveIntervalHnd = setInterval(doKeepalive, keepaliveInterval * 1000)
      
    if (dcpEnv.platform === 'nodejs')
      this._keepaliveIntervalHnd.unref();

    async function doKeepalive()
    {
      if (that._keepaliveIntervalHnd)
      {
        try
        {
          that.eventRouterConnection.keepalive();
        }
        catch(error)
        {
          /* ignore errors if the watchdog was cancelled while were waiting for the
           * keepalive to complete; this implies the connection was purposefully closed.
           */
          if (!that._keepaliveIntervalHnd)
            return;

          debugging() && console.debug('Event subscriber watchdog detected connection in error state', error.code || error.message);
          debugging('verbose') && console.debug(error);

          that.eventRouterConnection.close(); /* trigger ER connection recycle */
        }
      }
    }
  }
}

exports.EventSubscriber = EventSubscriber;
