// @ts-check
'use strict';

const { Synchronizer } = require('dcp/common/concurrency');

/**
 * Evaluator down management.
 **/
class EvaluatorManager
{
  constructor()
  {
    /**
     * Possible states for EvaluatorManager
     * Transitions:
     *  normal --> shuttingDown --> reallyDown --> normal
     *                          --> normal
     *
     * normal:       Sandboxes can be created and used.
     * shuttingDown: Sandbox.evaluator handle 'end' event has fired.
     * reallyDown:   Sandboxes cannot be created and all existing sandboxes are terminated.
     */
    /** @type { Synchronizer } */
    this.state = new Synchronizer('normal', [ 'normal', 'shuttingDown', 'reallyDown' ]);
    /**
     * Used to mitigate terminated handler being called too many times.
     * @type {boolean}
     */
    this.downInterlock = false;
    /**
     * Used to enter the sandbox handle 'end' event handler, which enables the
     * evaluator shutdown (viz., is-screen-saver-active) logic.
     * @type {boolean}
     */
    this.enterSandboxHandleEndHandler = false;
    /**
     * The # of spinning createSandbox instances.
     * @type {number}
     */
    this.createSandboxRefCount = 0;
  }
  /**
   * True when the sandboxHandle 'end' handler decides the evaluator is really down.
   * @type {boolean}
   */
  get reallyDown ()
  {
    return this.state.is('reallyDown');
  }
  /**
   * Indicates whether the evaulator is really down or in the process of shutting down.
   * @type {boolean}
   */
  get down ()
  {
    return this.state.is('shuttingDown') || this.reallyDown;
  }
  /**
   * Call in the Sandbox evaluatorHandle 'end' handler in Sandbox.start to enable
   * the is-screen-saver-down logic in the sandbox handle 'end' event handler
   * in Supervisor.hookUpSandboxListeners.
   */
  beginShutDown ()
  {
    this.enterSandboxHandleEndHandler = true;
    if (this.state.isNot('shuttingDown'))
      this.state.set('normal', 'shuttingDown');
  }
  /**
   * Clear sandboxHandle 'end' event handler flags.
   */
  clearEndHandlerFlags ()
  {
    this.downInterlock = false;
    this.enterSandboxHandleEndHandler = false;
  }
  /**
   * Reset all properties to their default state,
   * except for createSandboxRefCount.
   */
  reset ()
  {
    this.clearEndHandlerFlags();
    if (this.state.isNot('normal'))
      this.state.set([ 'shuttingDown','reallyDown' ], 'normal');
  }
  /**
   * Reset all properties to their default state.
   */
  initialize ()
  {
    this.createSandboxRefCount = 0;
    this.reset();
  }
}
exports.EvaluatorManager = EvaluatorManager;
