// @ts-check
'use strict';

/** @type {Array<{ dt: number, t0: number }>} */
let _gpu_statistics = [];

/**
 * Collect GPU runtimes from the recent past.
 * @param {number} GPUTime
 */
function updateGPUStatistics (GPUTime)
{
  const now = Date.now();
  const past = 20 * 60 * 1000;
  // Eliminate entries older than past.
  let k = 0;
  for (; k < _gpu_statistics.length; k++)
    if (_gpu_statistics[k].t0 + past >= now)
      break;
  if (k > 0)
  {
    const oldStatus = _gpu_statistics;
    _gpu_statistics = [];
    for (; k < _gpu_statistics.length; k++)
      _gpu_statistics.push(oldStatus[k]);
  }
  _gpu_statistics.push({ dt: GPUTime, t0: now });
  //console.debug('updateGPUStatistics', _gpu_statistics);
}
/**
 * Checks whether recent history of GPU scheduling conforms to GPUDensity.
 * @param {number} maxWorkingGPUs - the value of cores.gpu
 * @returns {boolean}
 */
function canScheduleGPU (maxWorkingGPUs)
{
  let scheduleGPU = true;
  if (_gpu_statistics.length > 0)
  {
    let gpuRunningTime = 0;
    for (const stat of _gpu_statistics)
      gpuRunningTime += stat.dt;
    scheduleGPU = (gpuRunningTime <= maxWorkingGPUs * (Date.now() - _gpu_statistics[0].t0));
    //console.debug(`canScheduleGPU(${maxWorkingGPUs})`, scheduleGPU, gpuRunningTime, (Date.now() - _gpu_statistics[0].t0));
  }
  //else console.debug(`canScheduleGPU(${maxWorkingGPUs}):`, scheduleGPU);
  return scheduleGPU;
}

exports.updateGPUStatistics = updateGPUStatistics;
exports.canScheduleGPU = canScheduleGPU;
