/** @file       error-payload.js
 *  @author     Eddie Roosenmaallen <eddie@kingsds.network>, Wes Garland <wes@kingsds.network.
 *  @date       January 2020, Jan 2021
 *
 *  This module exports the ErrorPayload class, which encapsulates errors for
 *  transmission to the client.
 */
'use strict';

const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
const wallet  = require('dcp/dcp-client/wallet');
const inspect = Symbol.for('nodejs.util.inspect.custom');

/**
 * Create a per-connection ErrorPayload constructor.  The ErrorPayload is used to build
 * objects for instance of Error which can be stringified in dcp4 message payloads.
 *
 * @param {object} connection   an instance of Connection
 * @returns {function} the constructor
 * @see Protocol-v4 Connection.ErrorPayload.
 */
exports.errorPayloadCtorFactory = function connection$$ErrorPayloadCtorFactory(connection)
{
  var process;
  
  if (require('dcp/common/dcp-env').isBrowserPlatform)
    process = 'browser'
  else
    process = requireNative('path').basename(requireNative('process').argv[1] || 'node');

  /**
   * Connnection.ErrorPayload constructor, form 1.
   * @param {Error}        error  instanceof Error to turn into a ConnectionErrorpayload.
   *
   * Connnection.ErrorPayload constructor, form 2.
   * @param {string}      message Error message
   * @param {string}      code    Optional error code
   * @param {object}      ctor    Optional constructor. Default: Error
   * 
   * Connnection.ErrorPayload constructor, form 3.
   * @param {object}      object   plain object and must be Error-shaped, with `message` and `name` being required
   */
  function ErrorPayload()
  {
    var error;
    if (arguments.length === 1) // form 1 and 3
    {
      let isErrorShaped = !!arguments[0].message && !!arguments[0].name;
      // It should be instance of Error- form 1
      // or error-shaped object(must have both `name` or 'message` property)- form 3
      if (typeof arguments[0] === 'object' && (arguments[0] instanceof Error || isErrorShaped))
        error = arguments[0];
      else
      {
        error = new TypeError(`${typeof arguments[0]} is not error-shaped`);
        if (typeof arguments[0] === 'object')
          Object.assign(error, arguments[0]);
      }
      try
      {
        if (typeof error.timestamp === 'string')
          error.timestamp = new Date(error.timestamp);
        if (typeof error.origin === 'string')
          error.origin = new wallet.Address(error.origin);
      }
      catch(e) { /* ignore  */ }
    }
    else // form 2
    {    
      let [ message, code, Ctor ] = arguments;
      if (Ctor !== undefined && !(new Ctor() instanceof Error))
        error = new TypeError(`${Ctor} is not an instance of Error`);
      else
      {
        if (!Ctor)
          Ctor = Error;

        error = new Ctor(message);
        if (code)
          error.code = code;
      }
    }

    this.name    = error.name;

    for (let prop of Object.getOwnPropertyNames(error))
      this[prop] = error[prop];
  }

  /* for use by console.log */
  ErrorPayload.prototype[inspect] = errorPayloadInspect;

  /* for use by JSON.stringify() */
  ErrorPayload.prototype.toJSON = function errorPayloadToJSON()
  {
    const jsonProto = {
      type: 'protocol',
      process,
      origin: connection.identity && connection.identity.address,
    };

    Object.assign(jsonProto, this);
    return jsonProto;
  }
  
  return ErrorPayload;
}

/**
 * node inspect function - for use by instances of Connection.ErrorPayload, this formats error payloads
 * to display pretty much the same as instances of Error when console logging.
 */
function errorPayloadInspect()
{
  /* eslint-disable no-shadow, no-invalid-this */
  const chalk = require('dcp/utils').chalk();
  var stack = this.stack ? this.stack.replace(/^(\s+at\s+[A-Za-z]+\s[(]internal[/].*)/gm, chalk.grey('$1')) : '';

  for (let prop of Object.getOwnPropertyNames(this)
           .filter(prop => true 
                   && prop !== 'stack'
                   && prop !== 'name'
                   && prop !== 'message'))
  {
    stack += `\n  ${prop}: ` + typeDecor(this[prop]);
  }

  function typeDecor(value)
  {
    switch(typeof value)
    {
      case 'string':
        return chalk.green(value);
      case 'number':
      case 'boolean':
        return chalk.yellow(value);
      case 'object':
        if (value instanceof Date)
          return chalk.magenta(value);
        if (value instanceof wallet.Address)
          return chalk.yellow(value);
        return chalk.red(value);
      default:
        return chalk.inverse.red(value);
    }
  }

  return stack;
}
