// @ts-check
'use strict';

const debugging = require('dcp/debugging').scope('worker');
const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
const { SchedMsg } = require('dcp/dcp-client/schedmsg');
const EventEmitter = require('events');
const { localStorage } = require('dcp/common/dcp-localstorage');
const { confirmPrompt } = require('dcp/utils');
const { Address } = require('dcp/dcp-client/wallet/eth');
const { Keystore } = require('dcp/dcp-client/wallet/keystore');
const dcpEnv = require('dcp/common/dcp-env');
const dcp_timers = require('dcp/common/dcp-timers');
const DISABLE_WORKER_CACHE_KEY = 'disable_worker';
var Supervisor;      /* Supervisor ctor - this will die when we kill sup1 */

// Supervisor2 typedefs
/** @typedef {import('./supervisor2/slice2').Slice} Slice       */
/** @typedef {import('./supervisor2/sandbox2').Sandbox} Sandbox */
/** @typedef {import('./supervisor2/options').Options} Options  */

// Supervisor1 typedefs
// /** @typedef {import('./sandbox').Sandbox} Sandbox */
// /** @typedef {import('./slice').Slice} Slice       */

/** @typedef {string} opaqueId */ // 22 character base64 string
/** @typedef {import('dcp/dcp-client/wallet/eth').Address} Address                 */
/** @typedef {import('dcp/dcp-client/wallet/keystore').Keystore} Keystore          */
/** @typedef {import('dcp/utils/jsdoc-types').SandboxOptions} SandboxOptions       */
/** @typedef {import('dcp/utils/jsdoc-types').SupervisorOptions} SupervisorOptions */
/** @typedef {import('dcp/dcp-client/worker/origin-access-manager').OriginAccessManager} OriginAccessManager */

function disableWorker ()
{
  localStorage.setItem(DISABLE_WORKER_CACHE_KEY, true);
}

/** XXXwg remove this when we kill sup 1 */
function determineSupervisorType()
{
  if (Supervisor)
    return;

  if (false
      || require('dcp/common/dcp-env').getenv('USE_SUPERVISOR1')
      || (Number(dcpConfig.rollout?.supervisorVersion) === 1))
    Supervisor = require('./supervisor').Supervisor;
  else
    Supervisor = require('./supervisor2').Supervisor;
}

/**
 * Fired when the worker begins fetching slices from the scheduler.
 * @access public
 */
class Worker extends EventEmitter
{
  /** Private class fields */
  #supervisor;
  #hasRef; /* event loop reference; undefined=>auto, false=>never, timer=>holding */

  /**
   * Returns a new Worker instance.
   * This constructor may alter the workerOptions object, for version-based polyfilling and/or providing
   * key API properties, such as the cores object.
   *
   * @access public
   * @param {Keystore} identity               - identity of the Worker; used for signing messages to
   *                                            task distributor etc.
   * @param {SupervisorOptions} workerOptions - options specified for the worker; may be mutated
   */
  constructor(identity, workerOptions)
  {
    super({ captureRejections: false });

    if (typeof workerOptions !== 'object')
      throw new Error('workerOptions argument must be object; is ' + typeof workerOptions);
    if (typeof identity !== 'object' || !(identity instanceof Keystore))
      throw new Error(`identity argument must be Keystore; is ${typeof identity === 'object' ? identity.constructor.name : typeof identity}`);

    determineSupervisorType();

    this.on('error', (error) => { debugging() && console.debug('event:', error); }); /* side-effect; avoid emit->throw lunacy */

    /**
     * @type {boolean}
     * @access public
     */
    this.working = false;
    /**
     * @type {SchedMsg}
     * @access public
     */
    this.schedMsg = new SchedMsg(this);
    /**
     * It is important that dynamic changes in workerOptions are reflected in Supervisor operations. In the case where
     * cores are derived solely from defaultCoreDensity, defaultCores provides an object which stays up to date with
     * defaultCoreDensity changes until a value is explicitly set.
     *
     * @type {SupervisorOptions}
     * @access public
     */
    this.workerOptions = workerOptions;
    if (!this.workerOptions.hasOwnProperty('cores') || !this.workerOptions.cores.hasOwnProperty('cpu'))
      this.workerOptions.cores = Worker.defaultCores(this.workerOptions);
    else
      Worker.defaultInitialization(this.workerOptions);
    if (this.workerOptions.hasOwnProperty('maxWorkingSandboxes') && this.workerOptions.maxWorkingSandboxes !== undefined)
      Worker.handleMaxWorkingSandboxes(this.workerOptions); /** XXXwg deprecate this API once all apps use sup2 conf */

    /* Correct cores object is now plumbed in; patently-absurd configs are changed to have 0 cores so users can debug */
    if (!(this.workerOptions.cores.cpu >= 0))
      this.workerOptions.cores.cpu = 0;
    if (!(this.workerOptions.cores.gpu >= 0))
      this.workerOptions.cores.gpu = 0;

    /**
     * @todo XXXpfr Rip out the sup2/sup1 special-casing when we finally kill sup1.
     * @type {Supervisor}
     * @access public
     */
    this.#supervisor = new Supervisor(this, identity, this.workerOptions);

    debugging() && console.debug(`Worker options(sup-version:${this.supervisorVersion}):`, this.workerOptions.cores.cpu, this.workerOptions.cores.gpu, this.workerOptions);
  }

  /** @type {string} */
  get supervisorVersion() { return this.#supervisor.version };

  /**
   * Disables worker instances from being started. The user will need to manually intervene to re-enable workers.
   * @access public
   */
  static disableWorker ()
  {
    disableWorker();
  }

  /**
   * Starts the worker.
   * @access public
   */
  async start()
  {
    debugging() && console.debug('Starting worker');
    if (this.working)
    {
      debugging() && console.debug('Worker already working, ignoring start request');
      return;
    }

    if (localStorage.getItem(DISABLE_WORKER_CACHE_KEY))
    {
      await confirmPrompt(`Worker has been disabled by the DCP Security Team; check the @DCP_Protocol Twitter feed for more information before continuing.`)
      if (await confirmPrompt('Are you sure you would like to restart the worker?'))
      {
        localStorage.removeItem(DISABLE_WORKER_CACHE_KEY);
        console.log("Starting worker...");
      }
      else
        return;
    }
    
    try
    {
      let dontStart = false;

      this.emit('beforeStart', function cancel() { dontStart = true });
      if (dontStart)
        return;

      this.#supervisor.work();
      this.working = true;
      this.schedMsg.start();
      if (this.#hasRef !== false)
        this.ref();
      this.emit('start');
    }
    catch(error)
    {
      debugging() && console.error(error);
      this.emit('error', error);
      this.stop(true);
    }
  }

  /**
   * Stops the worker.
   * The reason for this.#hasRef === false state is for
   *    await start
   *    stop   <-- #end isn't called until after the 2nd start
   *    start
   *           <-- #end is called here because #supervisor.stopWork is placed on the microtask queue.
   * @access public
   * @param {boolean} [forceTerminate=false] Whether the worker should stop imediately or allow the current slices to finish.
   */
  async stop(forceTerminate = false)
  {
    if (!this.working) 
    {
      debugging() && console.debug('Worker already stopping, ignoring stop request');
      return;
    }
    this.working = false;

    try 
    {
      // We're using synchronous event emitters, so if the abort function is called immediately,
      // then #supervisor.stopWork(forceTerminate) will be called with forceTerminate === true.
      this.emit('stop', function abort() { forceTerminate = true });

      debugging('shutdown') && console.debug(`Worker.stop(${forceTerminate}): stopping schedMsg...`);
      await this.schedMsg.stop();
      debugging('shutdown') && console.debug(`Worker.stop(${forceTerminate}): schedmsg stopped ok; stopping supervisor...`);

      return this.#supervisor.stopWork(forceTerminate).finally(() => {
        debugging('shutdown') && console.debug(`Worker.stop(${forceTerminate}): supervisor stopped ok`);
        this.#end();
      });
    }
    catch (error) 
    {
      debugging() && console.error(error);
      this.emit('error', error);
    }
  }

  #end()
  {
    if (this.#hasRef !== false)
    {
      this.unref();
      this.ref();
    }
    this.emit('end');
  }
  
  /**
   * Set the worker's event loop reference to "auto" - the default behaviour - which holds a reference as
   * long as we are working.
   */
  ref()
  {
    if (this.#hasRef === false)
      this.#hasRef = undefined;
    if (this.#hasRef === undefined && this.working)
    {
      this.#hasRef = dcp_timers.setInterval(function workerRef(){}, 314159);
      debugging('refs') && console.debug('worker - making event-loop reference');
    }
  }

  /**
   * Tell the worker to not hold an event loop reference, whether it is working or not.
   */
  unref()
  {
    if (this.#hasRef)
    {
      dcp_timers.clearInterval(this.#hasRef);
      debugging('refs') && console.debug('worker - clearing event-loop reference');
    }
    this.#hasRef = false;
  }

  /**
   * Calls this.stop(false) and places this.stop(true) in a timer so there is a deterministic
   * upper bound on how long it takes to stop.
   * @param {number} timeLimit - deterministic upper bound on stopping time
   * @returns {Promise<any>}
   */
  controlledStop (timeLimit = 5 * 60 * 1000)
  {
    return new Promise((resolve) => {
      let handle = dcp_timers.setTimeout(async () => {
        handle = null;
        await this.stop(true);
        debugging() && console.debug('Worker.controlledStop: Deterministic worker.stop(true) has completed.');
        resolve();
      }, timeLimit);

      handle.unref();

      return this.stop(false)
        .finally(() => {
          debugging() && console.debug('Worker.controlledStop: Non-deterministic worker.stop(false) has completed.');
          if (handle)
            dcp_timers.clearTimeout(handle);
          resolve();
        });
    });
  }

  /**
   * We have been handed a v1-style configuration object, so we use it to generate v2-style info. Then
   * we add a getter/setter on maxWorkingSandboxes so that it always reflects cores.cpu, and so that its
   * mutations (from the worker-app) update cores.cpu.
   *
   * @deprecated
   * Get rid of this when all the workers are updated so that worker options do not have property maxWorkingSandboxes.
   * Please use options.defaultCoreDensity or options.cores instead.
   * @param {SupervisorOptions} options
   */
  static handleMaxWorkingSandboxes (options)
  {
    function translateMWStoCores(maxWorkingSandboxes)
    {
      maxWorkingSandboxes = Number(maxWorkingSandboxes);
      if (typeof maxWorkingSandboxes !== 'undefined')
        options.cores.cpu = maxWorkingSandboxes;
      debugging('maxWorkingSandboxes') && console.debug(`translateMWStoCores: options.cores.cpu = ${options.cores.cpu}`);
    }

    translateMWStoCores(options.maxWorkingSandboxes);

    /* Slide in a maxWorkingSandboxes property whose backing store is v2-style configuration info. This property
     * is used by Worker applications that don't understand v2-style configuration yet.
     */
    Object.defineProperty(options, 'maxWorkingSandboxes', {
      get: () => options.cores.cpu,
      set: (value) => translateMWStoCores(value),
      configurable: true,
      enumerable: true,
    });
  }

  /** @type {OriginAccessManager} */
  get originManager () { return this.#supervisor.originManager; }
  //
  // This is the official supported interface for accessing supervisor.
  //  When Sup1 dies, it will be simplified.
  //
  /** @type {Sandbox[]} */
  get sandboxes ()        { return this.#supervisor.sandboxes; }
  /** @type {Sandbox[]} */
  get workingSandboxes () { return this.#supervisor.workingSandboxes; }
  /** @type {Slice[]} */
  get slices ()           { return this.#supervisor.slices; }
  /** @type {Slice[]} */
  get queuedSlices ()     { return this.#supervisor.queuedSlices; }
  /** @type {Slice[]} */
  get workingSlices ()    { return this.#supervisor.workingSlices; }
  /** @type {Keystore} */
  get identityKeystore () { return this.#supervisor.identityKeystore; }
  /** @type {Keystore} */
  set identityKeystore (ks)
  {
    if (!(ks instanceof Keystore))
      throw new Error('Worker.identityKeystore: must be an instance of Keystore.');
    this.#supervisor.identityKeystore = ks;
    this.emit('identityChange', ks);
  }

  /** 
   * @deprecated - use options.paymentAddress
   * @type {Address} 
   */
  get paymentAddress () { return this.workerOptions.paymentAddress; }

  /** 
   * @deprecated - use options.paymentAddress
   * @type {Address} 
   */
  set paymentAddress (addr)
  {
    if (!(addr instanceof Address))
      throw new Error('Worker.paymentAddress: must be an instance of Address.');
    this.workerOptions.paymentAddress = addr;
    this.emit('paymentAddressChange', addr);
  }

  /** @type {opaqueId} */
  get workerId ()      { return this.#supervisor.workerId; }
  /** @type {opaqueId} */
  set workerId (id)    { this.#supervisor.workerId = id; }
  
  /**
   * Ignore localStorage and set workerId directly.
   * When using multiple workers with different workerId's we don't want to
   * write to the localStorage 'workerId'; localWorkerId ignores localStorage.
   * @type {opaqueId|null}
   */
  set localId (id) { this.#supervisor.localWorkerId = id; }

  /**
   * @deprecated
   * Please do not use this.
   * @type {Supervisor}
   */
  get badSupervisorBackdoor () { return this.#supervisor; }
  /** @type {SupervisorOptions|Options} */
  get options () { return this.#supervisor.options; }
  /**
   * Tries to fetch a task from TD (task distributer).
   * @todo Get rid of this (XXXpfr)
   * @param {number} [numCores]
   * @returns {Promise<any>}
   */
  fetchTask (numCores)
  {
    return this.#supervisor.fetchTask();
  }
  /**
   * Remove sandbox from supervisor and terminate it.
   * @param {Sandbox} sandbox
   */
  returnSandbox (sandbox)
  {
    return this.#supervisor.returnSandbox(sandbox);
  }
  /**
   * Remove sandbox from supervisor and return it to the scheduler.
   * @param {Slice} slice
   * @param {string} reason
   * @returns {Promise<any>}
   */
  returnSlice (slice, reason = 'unknown')
  {
    return this.#supervisor.returnSlice(slice, reason);
  }

  /**
   * When paused, the worker will not execute new slices or fetch new work.
   * But it will be alive and well, waiting to be unpaused.
   * No slices will be returned to scheduler.
   */
  pause ()
  {
    (this.supervisorVersion === '2.0.0') && this.#supervisor.pause();
  }
  /**
   * Only valid to call unpause after pause has been called.
   * The worker will now execute new slices and fetch new work.
   */
  unpause ()
  {
    (this.supervisorVersion === '2.0.0') && this.#supervisor.unpause();
  }

  /**
   * Build an object suitable for use as options.cores based on the presumed number of logical cores in
   * the machine, and options.defaultCoreDensity. This is the only place options.defaultCoreDensity
   * should be used, all other calculations throughout the worker should be based on options.cores. The
   * default defaultCoreDensity is usually supplied via dcpConfig.worker in dcp-worker repo's
   * etc/dcp-worker-config.js 
   *
   * options.hardware can be used to override the detected number of cores
   *
   * @note We current assume the machine has one GPU of infinite capability, and use evaluator capability
   *       detection to use or not use this amazing GPU. That will obviously change as our capabilities 
   *       evolves.
   *
   * @note There are very important notes re core-count selection in How-supervisor-works.md.
   *
   * @note This is a static property of Worker because it is based on the physical properties of the
   *       machine and the options object and does not have any relationship to a particular instance
   *       of Worker.
   *
   * @param {SupervisorOptions} options
   * @returns {{ cpu: number, gpu: number }}
   */
  static defaultCores (options)
  {
    Worker.defaultInitialization(options);

    /** Create an "active" return object suitable for use as options.cores. Any writes to this object
     * persist as-is, but in the usual case, reading from the object causes the values to change
     * when hardware.vCores and/or defaultCoreDensity change.
     * @type {{ cpu: number, gpu: number }}
     */
    var ret = { cpu: 0, gpu: 0 };

    Object.defineProperty(ret, 'cpu', {
      get: ()      => Math.floor(options.defaultCoreDensity.cpu * options.hardware.vCores),
      set: (value) => {
        delete ret.cpu;
        ret.cpu = value;
      },
      configurable: true,
      enumerable: true,
    });

    Object.defineProperty(ret, 'gpu', {
      get: ()      => options.defaultCoreDensity.gpu * 1, /* one GPU until we know better */
      set: (value) => {
        delete ret.gpu;
        ret.gpu = value;
      },
      configurable: true,
      enumerable: true,
    });

    if (options.cores?.cpu)
      ret.cpu = options.cores.cpu;
    if (options.cores?.gpu)
      ret.gpu = options.cores.gpu;

    return ret;
  }
  
  /**
   * Required initialization.
   * @param {SupervisorOptions} options
   */
  static defaultInitialization (options)
  {
    if (!options.defaultCoreDensity)
      options.defaultCoreDensity = { cpu: 1, gpu: 0.75 };
    if (!options.hardware)
      options.hardware = { vCores: 0 };
    if (!options.hardware.vCores)
    {
      switch(dcpEnv.platform)
      {
        case 'nodejs':
          options.hardware.vCores = requireNative('os').cpus().length;
          break;
        case 'vanilla-web':
        case 'bravojs':
          options.hardware.vCores = navigator.hardwareConcurrency; /* can be less than actual hardware capabilities */

          if (options.hardware.vCores > 2 && /(Android).*(Chrome|Chromium)/.exec(navigator.userAgent))
            options.hardware.vCores = 2; /* Restricted on Android-Chrome due to bad OOM-handling; see DCP-3241 */

          if (navigator?.deviceMemory)
            options.hardware.vCores = Math.min(options.hardware.vCores, navigator.deviceMemory * 4); /* Restrict to max one vCore per 256MB RAM */
          break;
        default:
          options.hardware.vCores = 1;
      }
    }
  }
}

exports.Worker = Worker;
exports.disableWorker = disableWorker;

exports.version = {
  api: '1.0.0',
  provides: '1.0.0'  /* dcpConfig.scheduler.compatibility.operations.work */
};
