/**
 *  @file       dcp-dot-dir.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @date       March 2020
 *
 * This module is a utility for resolving the dotDcpDir,
 * the user's configuration directory, which is usually
 * located at ~/.dcp
 *
 * To programmatically determine the correct place to read the .dcp directory,
 * we should look at exports.dotDcpDir, whose initial value can be affected
 * via the DCP_HOMEDIR environment variable. It can be changed by changing
 * the homedir.
 *
 * To respect the XDG Base Directory Specification, the value of `XDG_DATA_HOME`
 * (typically `~/.local/share`) is used for the homedir when `DCP_HOMEDIR` is
 * unset. If the homedir ends up being the same as the value of `XDG_DATA_HOME`,
 * `dcp` is used instead of `.dcp` as the basename of the `dotDcpDir`.
 *
 * Note: caching this module's dcpDcpDir is discouraged, as setHomeDir() will
 *       not be able to affect your cache!
 */
const DCP_ENV = require('./dcp-env');

if (DCP_ENV.platform === 'nodejs') {
  const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
  const path = requireNative('path');
  const os = requireNative('os');
  const process = requireNative('process');
  let _homedir;
  
  /** Override DCP's idea of the home directory, expanding tildes and adjusting exports.dotDcpDir as necessary */
  exports.setHomeDir = function dcpDotDir$$setHomeDir(homedir) {
    _homedir = require('dcp/utils').expandPath(homedir);
    let dcpDir = '.dcp';
    if (_homedir === process.env.XDG_DATA_HOME)
      dcpDir = dcpDir.substring(1);
    exports.dotDcpDir = path.resolve(_homedir, dcpDir);
  }

  exports.setHomeDir(process.env.DCP_HOMEDIR ||
                     process.env.XDG_DATA_HOME ||
                     os.homedir());

  /** Returns where DCP thinks the homedir is */
  exports.getHomeDir = () => _homedir;
}
