/**
 *  @file       protocol/connection/sender.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @date       January 2020
 *
 *  The sender class is responsible for accepting Connection.Message instances,
 * and sending them to the peer via the provided transport instance.
 * Messages are queued in an array, and are sent in FIFO order - with the exception
 * of requests being skipped until there is a nonce available to send them with.
 */
'use strict';

const semver       = require('semver');
const debugging    = require('dcp/debugging').scope('dcp');
const isDebugBuild = require('dcp/common/dcp-build').build === 'debug';

let nanoid = require('nanoid').nanoid;

const { wireLog }       = require('..');
const { assert }        = require('dcp/common/dcp-assert');
const { a$sleep }       = require('dcp/utils');
const { DCPError }      = require('dcp/common/dcp-error');
const { setImmediate, setTimeout, clearTimeout }  = require('dcp/common/dcp-timers');

/** @typedef {import('./connection').Connection} Connection */

class Sender {
  #nonce;                  /* nonce for next msg: null->send connect; false->consumed; string->from last-received ack */
  #queue;                  /* Messages which are ready for transmission on next queue service */
  #queueServicePending;    /* True when we know we will service the queue on the next tick */

  constructor(connection) {
    this.connection = connection;

    this.#queue = [];
    this.#nonce = false;
    this._ackTokenId = 0;

    /* inFlight holds details re message are transmitting. The messageId property is the id property of
     * the original message that is being transmitted. The sealedMessage property is a string which captures
     * the state of the message at signing time.
     */
    this.inFlight = null;  

    Object.defineProperty(this, 'debugLabel', { get: () => this.connection.debugLabel });
    this.#queueServicePending = false;
  }

  /**
   * We generate a unique token with each message we send so that 
   * the peer can quickly ack the message and prove identity/uniqueness
   */
  makeAckToken() {
    return `${this.connection.id}-${this._ackTokenId++}-${nanoid()}`;
  }

  /**
  * Initiates the session by sending the 'connect' operation.
  * Once the response has been received, the session is established.
  * Lots of one-off code in here since it's difficult to re-use the 
  * same methods meant for normal messages.
  * 
  * The basic algorithm is that we sign and send a connect message. This message contains
  * our dcpsid proposal (1/2 of the eventual dcpsid), along with our public address and a
  * signature to prove that we are who we say we are.
  *
  * @returns {string} new session id (dcpsid)
  */
  async initiate()
  {
    assert(this.connection.transport);
    assert(this.connection.state.is('connecting'));
    assert(!this.connection.dcpsid);

    const halfSid = nanoid();
    const initiatorVersion = this.connection.constructor.VERSION;
    const connectRequest = new this.connection.Request('connect', {
      version: initiatorVersion,
      sid: halfSid,
    });

    debugging('sender') && console.debug(this.debugLabel, 'sending initial connect message');
    const resp = await this.a$sendConnectMessage(connectRequest);
    if (typeof resp !== 'object' || typeof resp.payload !== 'object')
      throw new DCPError('Target responded to establish message without payload', 'DCPC-1218');
    if (resp.payload instanceof this.connection.ErrorPayload)
    {
      const theirError = resp.payload;
      const myError = new DCPError(`remote error ${theirError.code} while initiating session (${theirError.message})`, 'DCPC-1224');
      myError.stack += '\n --- remote stack: -------------\n' + theirError.stack;
      throw myError;
    }
    const targetVersion = resp.payload.version;
    const initiatorCompatibility = this.connection.constructor.VERSION_COMPATIBILITY;
    debugging('sender') && console.debug(this.debugLabel, `Target's version s ${targetVersion}; we want ${initiatorCompatibility}`);
    if (!semver.satisfies(targetVersion, initiatorCompatibility))
      throw new DCPError(`Target's version (${targetVersion}) is not compatible (must meet ${initiatorCompatibility})`, 'EVERSION');
    this.connection.peerVersion = targetVersion;

    // verify that our dcpsid half is still there, followed by a string
    // provided by the target that is at least the same length.
    if (typeof resp.dcpsid !== 'string'
        || !(resp.dcpsid.startsWith(halfSid))
        || resp.dcpsid.length < halfSid.length * 2)
      throw new DCPError(`Target responded with invalid DCPSID: ${resp.dcpsid}`, 'DCPC-1208');

    debugging('sender') && console.debug(this.debugLabel, `session initiated, peer is version ${this.connection.peerVersion}`);

    return resp.dcpsid;
  }

  /**
   * Invoked when the connection class becomes aware that a transport is available upon which
   * we can deliver traffic, this method either re-sends the current in-flight message, services
   * the queue if there are messages pending, or sends a keepalive to pump the queue if there's nothing
   * to send.
   *
   * @param {boolean} reconnectFlag          true when this is not the initial transport connection for session
   */
  notifyTransportReady(reconnectFlag)
  {
    debugging('sender') && console.debug(this.debugLabel, `Notified transport is ready. inflight ${!!this.inFlight}, state ${this.connection.state}`)
    this.connection.emit('connect', this.url); /* UI hint: internet available" */

    if (reconnectFlag && this.connection.last)
      this.connection.sendAck(this.connection.last.ackMessage);
    if (this.inFlight)
      this.sendInFlightMessage();
    else if (this.#queue.length > 0)
      this.serviceQueue();
  }

  /**
   * Send either a Request or a Response for a Connect message. We don't use Connection::send because
   * that function will queue up messages sent before session establishment rather than sending them.
   *
   * @param {Connection.Message} message
   * @returns a promise that will be resolved when the message's lifecycle has completed, or rejects
   *          when the connection closes
   */
  a$sendConnectMessage(message)
  {
    assert(message.payload?.operation === 'connect' || message.payload instanceof this.connection.ErrorPayload);
    assert(message instanceof this.connection.Message);

    if (!this.#nonce)
      this.#nonce = null;
    this.forceClearPendingTx();
    this.enqueue(message);
    return this.connection.messageLedger.addMessage(message, new Error('send-connect-message-stack-memo'));
  }

  /**
   * Places message into `queue` but only schedules queue to be serviced
   * if connection is ready to send. Otherwise other tools will have to
   * handle making it ready to send again.
   *
   * Enqueueing a message on a Connection which is not connected (but connectable) will trigger connect().
   *
   * @param {Connection.Request|Connection.Response} message
   */
  enqueue(message)
  {
    if (message.payload && message.payload.operation)
      debugging('connection') && console.debug(this.debugLabel, `enqueueing ${message.constructor.name} message for operation:`, message.payload.operation);
    else
      debugging('connection') && console.debug(this.debugLabel, `enqueueing ${message.constructor.name} message`);

    this.#queue.push(message);

    /* Request a queue service on the next tick, provided we are in a state that allows queue service
     * already. Otherwise, the queue will be serviced when the connection becomes ready next.
     */
    if (!(this.connection.state.is('disconnected')))
      this.requestQueueService();
  }

  /**
   * Pulls a message from the queue. If batching is enabled, we pause for a short time ms to allow other 
   * messages to enter the queue, and then continues dequeuing messages (similar to Nagle Algorithm).
   *
   * Treat as infallible, re-entrant.
   */
  async serviceQueue()
  {
    const totalPayloadSizeTarget = 100E6;
    const canBatch = this.connection.state.is('established') && this.connection.options.allowBatch;
    assert(this.nonce !== null || !this.connection.is('established')); /* first nonce is null can only happen before we have a session */

    try
    {
      const top = this.#queue.length ? this.#queue[0] : undefined;

      /* maybe wait briefly for the queue to fill up, a la Nagle */
      if (canBatch && this.#queue.length < this.maxBatchSize
          && !(top && top instanceof this.connection.Batch)
          && !(top && top.payload?.jsonData?.length > totalPayloadSizeTarget)) /* don't wait if top of queue is pre-serialized and really big */
      {
        let batchWaitTime = this.connection.options.batchWaitTime;

        if (this.connection.messageLedger.size === 1 && top && top instanceof this.connection.Response)
          batchWaitTime = 0; /* sending a response, there are no other pending requests, assume no point in waiting long */
        else
          batchWaitTime = 0.001 + (batchWaitTime / (this.#queue.length + 1)); /* don't wait too much when we already have lots to do */

        debugging('sender') && console.debug(`${this.debugLabel} serviceQueue: sleeping for ${batchWaitTime * 1000}ms`);
        await a$sleep(batchWaitTime); /* queue length can increase while we sleep, even for 0s */
      }

      if (!this.#queue.length || this.#nonce === false)
      {
        debugging('sender') && console.debug(this.debugLabel, `Quitting queue service; length=${this.#queue.length}, nonce=${this.#nonce}`);
        return;
      }
    }
    catch(error)
    {
      debugging() && console.error(this.debugLabel, 'Could not create message batch:', error);
      this.connection.__close(error);
      return;
    }
    finally
    {
      this.#queueServicePending = false;
    }

    if (this.inFlight)
    {
      debugging('sender') && console.debug(this.debugLabel, 'Quitting queue service; there is already a message in-flight');
      return; /* queue will be serviced as soon as ack for in-flight message comes in */
    }

    /* We know for sure we are sending: grab the nonce now so that another "thread" doesn't => mutex */
    const nextNonce = this.#consumeNonce();

    try
    {
      let messageToSend = null;

      if (canBatch && this.#queue.length > 1)
      {
        let totalPayloadLen = 0;

        /* Note - the size measurement misses a lot of cases here so that we don't need to throw away
         * serialization. At this time, it doesn't really matter, as it catches the case I care about;
         * slice uploads. /wg feb 2023
         */
        messageToSend = new this.connection.Batch([], this.makeAckToken());
        while (this.#queue.length && messageToSend.messages.length < this.maxBatchSize)
        {
          const nextMessage = this.#queue[0];
          if (nextMessage.payload?.jsonData)
            totalPayloadLen += nextMessage.payload.jsonData.length;
          if (nextMessage instanceof this.connection.Batch || totalPayloadLen > totalPayloadSizeTarget)
            break;

          messageToSend.messages.push(this.#queue.shift());
        }
      }

      if (!messageToSend || !messageToSend.messages.length) /* didn't make a batch -> just send the next message */
        messageToSend = this.#queue.shift();
      else
      {
        const stackMemo = new Error('service-queue-stack-memo');
        /* Add a ledger entry for batch; acts as a pointer to the ledger entries carried by the batch,
         * which is what we really care about.
         */
        this.connection.messageLedger.addMessage(messageToSend, stackMemo).catch(error => {
          debugging() && console.error(this.debugLabel, 'error waiting for batch ack:', error);
        });
      }
      await this.deliverMessage(messageToSend, nextNonce);
    }
    catch(error)
    {
      debugging() && console.error(this.debugLabel, 'Could not service queue:', error);
      /* At this point, we can't service the queue. This mostly likely means that the underlying
       * transport has disconnected and we can't connection::a$_reconnect(). This can leave a message
       * on the flight deck; when that happens, Connection#close won't have a nonce available, either,
       * we will wind up closing the connection without telling the remote.
       */
      this.connection.__close(error, Boolean(this.inFlight));
    }
  }

  /**
   * Consume the next nonce. The nonce is required to transmit a message, and is provided by the most
   * recent ack message from the peer.
   *
   * @throws if there is no nonce available
   */
  #consumeNonce()
  {
    const nextNonce = this.#nonce;
    this.#nonce = false;
    if (nextNonce === false)
      throw new Error('nonce not available');
    return nextNonce;
  }

  /**
   * Wait until a nonce becomes available and consume it.
   * Conditions to check if nonce available:
   * - immediately (release build only)
   * - message from transport
   * - transport reconnection
   * - timer expiry
   * - state change
   *
   * Conditions which can cause us to give up checking:
   * - in 'closed' state at start
   * - timer expiry
   * - state change to 'closing'
   * - can consume nonce
   *
   * @see consumeNonce()
   *
   * @param {number} timeout    maximum number of seconds to wait, or false to wait forever.
   * @returns a promise which resolves to the new nonce and rejects if the connection closes before
   *          this happens, or if the timeout expires.
   */
  a$waitConsumeNonce(timeout)
  {
    const that = this;
    const conn = this.connection;
    var   lastTransport;
    const nonceReady = {};

    assert(typeof timeout !== 'undefined');

    nonceReady.promise = new Promise((resolve, reject) => {
      nonceReady.resolve = resolve;
      nonceReady.reject  = reject;
    });

    if (this.connection.state.is('closed'))
    {
      nonceReady.reject(new DCPError('connection closed', 'DCPC-1220'));
      return nonceReady.promise;
    }

    if (this.#nonce && !isDebugBuild) /* fast shortcut path */
    {    
      nonceReady.resolve(this.#consumeNonce());
      return nonceReady.promise;
    }

    const timer = timeout !== false && setTimeout(endWait, timeout * 1000).unref();
    conn.on('connect', hookTransport);
    conn.state.on('change', tryGetNonce);
    hookTransport();

    function hookTransport()
    {
      if (lastTransport !== conn.transport)
      {
        if (lastTransport)
          lastTransport.off('message', tryGetNonce);
        conn.transport.on('message', tryGetNonce);
        lastTransport = conn.transport;
      }

      tryGetNonce();
    }

    function tryGetNonce()
    {
      if (that.#nonce)
        endWait();
    }

    /* We need to be able to wait for a new nonce in 'closing' state, so that we can send the close
     * request; however, anything waiting for a nonce before we entered the 'closing' state will not
     * be going out the door.
     */
    function handleStateTransition(newState)
    {
      if (newState === 'closing')
        endWait();
    }

    function endWait()
    {
      conn.off('connect', hookTransport);
      conn.state.off('change', handleStateTransition);
      if (lastTransport)
        lastTransport.off('message', tryGetNonce);
      clearTimeout(timer);

      if (that.#nonce)
        nonceReady.resolve(that.#consumeNonce());
      else
        nonceReady.reject(new DCPError('no nonce available', 'DCPC-1219'));
    }

    return nonceReady.promise;
  }

  /**
   * Schedule serviceQueue() to run on the next tick, unless it has already been scheduled to do so.
   */
  requestQueueService()
  {
    const that = this;

    if (this.#queueServicePending)
      return;

    function __serviceQueue() {
      that.serviceQueue();
    }

    setImmediate(__serviceQueue);
    this.#queueServicePending = true;
  }

  /**
   * Sign, seal, and a deliver a message to the flight deck. The message is mutated to add the nonce
   * before signing. This function kicks off a process which is finished via finishDelivery(). A timer
   * is started that kills the current transport if the loop isn't closed fast enough.
   *
   * @param {object} message          The message to send. The flight deck must be clear.
   * @param {string} nonce            The nonce to use to send the message
   * @param {boolean} [oob=false]     Use out-of-band signaling for this message (CLOSE ONLY!)
   *
   * @returns a Promise which is resolved as soon as the message is sealed.
   *
   * @note Treat as infallible
   */
  async deliverMessage(message, nonce, oob = false)
  {
    assert(message instanceof this.connection.Message);
    assert(!this.inFlight);
    assert(typeof message === 'object');

    this.connection.emit('beforeSend', message);
    const inFlight = { message };
    this.inFlight = inFlight; /* functions as mutex - nobody else can deliver now */
    inFlight.ackToken = this.makeAckToken();
    inFlight.sealedMessage = await message.sign(nonce, this.inFlight.ackToken);

    if (this.inFlight && this.inFlight !== inFlight)
      throw new Error('detected flight-deck mutex violation during message signing');

    if (this.inFlight) /* could be cancelled during forceClearPendingTx */
      this.sendInFlightMessage(oob);
  }

  /**
   * Sends the message stored in the `inFlight` var over the transport.
   * `finishDelivery` is the only method that should be resetting this.inFlight
   * and thus closing the loop; this happens when the other end sends us an ack.
   *
   * @param {boolean} [oob=false]     Use out-of-band signaling for this message (CLOSE ONLY!)
   * @note Treat as infallible
   */
  sendInFlightMessage(oob = false)
  {
    assert(this.inFlight);
    
    const message = this.inFlight.message;
    debugging('sender') && console.debug(this.debugLabel, `sending in-flight message ${message.id} (oob=${oob})`);

    if (!this.connection.transport)
    {
      debugging('sender') && console.debug(this.debugLabel, `no transport for ${message.constructor.name}; not sending`, message.id,
                                           `(${this.inFlight.sealedMessage.length} bytes)`);
      return;
    }

    try
    {
      const activeTransport = this.connection.transport;
      const maxRTT = this.connection.options.maxRTT || 0; /** @todo: calculate reasonable default during connect() /wg feb 2023 */

      debugging('wire') && wireLog(this.debugLabel, this.inFlight.sealedMessage, 'send');
      debugging('sender') && console.debug(this.debugLabel, `Sending message with maximum send->ack RTT ${maxRTT || 'Infinity'}`);

      this.#monitorTransmissionAttempts();
      if (!oob)
        this.connection.transport.send(this.inFlight.sealedMessage);
      else
        this.connection.transport.sendOutOfOrder(this.inFlight.sealedMessage);

      if (maxRTT)
      {
        /* Set a timer to disconnect the underlying transport if ack takes too long to arrive (triggers reconnect). */
        this.inFlight.timer = setTimeout(() => {
          debugging() && console.debug(this.debugLabel, 'sendInFlightMessage timeout; closing transmitting transport');
          activeTransport.close();
        }, maxRTT * 1e3);
        this.inFlight.timer.unref();
      }
      this.connection.emit('send', message);
    }
    catch (error)
    {
      this.connection.__close(error, true); /* sending close message will be impossible with a message on the flight deck */
      debugging() && console.error(`Error while sending message ${message.id} to ${this.connection.peerAddress}:`, error);
    }
  }

  /**
   * In some cases -- generally a broken implementation -- we can try to send the same DCP message on
   * the same session many times, over multiple transport instances. At some point, we have to give up.
   * We give up by closing the Connection (session).
   */
  #monitorTransmissionAttempts()
  {
    const transmitAttempts = this.inFlight.transmitAttempts || 0;
    this.inFlight.transmitAttempts = transmitAttempts + 1;

    debugging('sender') && console.debug(this.debugLabel, `message transmit attempt #${this.inFlight.transmitAttempts}`);

    if (true
        && this.connection.options.maxTransmitAttempts /* falsey => infinite retries */
        && transmitAttempts > this.connection.options.maxTransmitAttempts)
    {
      debugging() && console.debug(this.debugLabel, `Too many (${transmitAttempts}) transmission attempts for message ${this.inFlight.message.id}; giving up`);
      throw new DCPError(`Message exceeded ${this.connection.options.maxTransmitAttempts} send attempts`, 'DCPC-1223');
    }
  }

  /**
   * Clear all pending message transmissions, throwing them away. Their message-ledger promises are
   * ignored here, but will eventually be rejected during connection.close(). This routine also
   * clears the flight deck, regardless of content.
   */
  forceClearPendingTx()
  {
    this.#queue.length = 0;
    if (this.inFlight)
      clearTimeout(this.inFlight.timer);
    this.inFlight = null;
  }

  setNextNonce(nonce)
  {
    debugging('nonce') && console.debug(this.debugLabel, 'Nonce for next transmission will be', nonce);
    this.#nonce = nonce;
    this.serviceQueue();
  }

  /**
   * Finish the delivery of a message; this tells the sender that we know that the peer has received our
   * message (presumably because it sent back an Ack message). This means we can clear it from the
   * flight deck and prepare to transmit something else. This closes the loop begun with deliverMessage().
   *
   * @param {string} messageId     the id of the message whose delivery we are finishing
   * @returns {object}     the last Message we transmitted or false when messageId doesn't match it (or
   *                       it doesn't exist)
   */
  finishDelivery(messageId)
  {
    const retval = this.inFlight;

    /* If there is no inflight message, it means either
     * - we received an ack before we sent anything on this connection (bad-sid reconnect?)
     * - we ran forceClearPendingTx, which means we don't care about this ack
     */
    if (!this.inFlight)
      return false;

    if (this.inFlight.message.id !== messageId)
    {
      debugging() && console.debug(this.debugLabel, `expected ack for message ${this.inFlight.message.id} but got ack for ${messageId}`);
      return false;
    }

    clearTimeout(this.inFlight.timer);
    this.inFlight = false;

    return retval;
  }

  /**
   * When a connection is closed the sender needs to cancel its send efforts.
   */
  shutdown() {
    debugging('sender') && console.debug(this.debugLabel, 'shutting down.');
    this.#nonce = false;
    this.forceClearPendingTx();
  }

  get maxBatchSize()
  {
    return (this.connection.options.allowBatch && this.connection.dcpsid)
      ? Math.max(this.connection.options.maxMessagesPerBatch, 1)
      : 1;
  }

  hasPendingTx()
  {
    return Boolean(this.inFlight || this.#queue.length);
  }
}

exports.Sender = Sender;
