/** @typedef {import('./slice2').Slice} Slice                          */
/** @typedef {import('./index').Supervisor} Supervisor                 */
/** @typedef {import('dcp/utils/jsdoc-types').SliceObj} SliceObj       */
/** @typedef {import('dcp/utils/jsdoc-types').RetSliceObj} RetSliceObj */

/**
 * Adjust delay times when debugging.
 * The adjustment for niim is automatic, other debuggers must manually change this value.
 */
let timeDilation = 1;
if (DCP_ENV.platform === 'nodejs')
{
  /** Make timers 20x slower when running in niim */
  timeDilation = (requireNative('module')._cache.niim instanceof requireNative('module').Module) ? 20 : 1;
}

//
// Global constants
//
const schedulingSlop = 0.25;
const doNotSchedule = 1.0; // Require a full unused cpu core before calling TD.
const debugBuild = (require('dcp/common/dcp-build').build === 'debug');
const addressTruncationLength = 20;

//
// Flags for tracing.
//
const selectiveEnable = false;
const selectiveEnableEx = false;
function selectiveDebug ()  { return _selectiveSup() || debugging() || selectiveEnable; }
function selectiveSupEx ()  { return _selectiveSupEx() || selectiveDebug() || selectiveEnableEx; }
function selectiveDebug2 () { return false || debugging('supervisor'); }
function debugQuanta ()     { return false || selectiveDebug2(); }

/**
 * Remove element from array.
 * @param {Array<*>} array
 * @param {*}        element
 * @return {boolean} - False when element is not in array.
 */
function removeElement (array, element)
{
  let index = array.indexOf(element);
  if (index === -1)
    return false;
  array.splice(index, 1);
  return true;
}

/**
 * JSDoc type descriptor checking needs to interpret Inventory as an Array.
 * @param {string} tag
 * @returns {Array}
 */
function InventoryArray (tag)
{
  // @ts-ignore
  return new Inventory(tag);
}

/**
 * Add a slice to the slice bucket being built. If a sliceBucket already exists for the
 * job-status-authMessage tuple, then the slice will be added to that, otherwise a new
 * sliceBucket will be added to the buckets.
 *
 * @param {Slice[]} slices - The slices.
 * @param {String}  status - Status update, eg. progress or scheduled.
 * @param {SliceObj[]} [sliceBuckets] - Slice buckets being built. Will be mutated in place.
 * @returns {SliceObj[]}   - mutated sliceBuckets array
 */
function constructSliceBuckets (slices, status, sliceBuckets)
{
  /** @type {Object<string, SliceObj[]>} */
  const jobMap = {};
  for (const slice of slices)
  {
    assert(slice.sliceNumber > 0 );
    if (!jobMap[slice.jobAddress]) jobMap[slice.jobAddress] = [];

    // Try to find a sliceBucket in the buckets which matches the job, status, and auth message.
    let sliceBucket = jobMap[slice.jobAddress].find(desc => {
      return desc.status === status
        && desc.authorizationMessage === slice.authorizationMessage;
    });

    if (!sliceBucket)
      jobMap[slice.jobAddress].push(slice.getMessage(status));
    else sliceBucket.sliceNumbers.push(slice.sliceNumber);
  }

  if (!sliceBuckets)
    sliceBuckets = [];
  for (const value of Object.values(jobMap))
    sliceBuckets.push(...value);
  return sliceBuckets;
}

/**
 * Add a slice to the returnSlice bucket being built. If a sliceBucket already exists for the
 * job-isEstimation-authMessage-reason tuple, then the slice will be added to that, otherwise a new
 * sliceBucket will be added to the buckets.
 *
 * @param {Slice[]} slices  - The slices.
 * @param {String}  reason  - Optional reason to further characterize status; e.g. 'ENOPROGRESS', 'EUNCAUGHT', 'ESLICETOOSLOW', 'unknown'.
 * @param {RetSliceObj[]} [sliceBuckets] - Optional slice buckets being built. Will be mutated in place.
 * @returns {RetSliceObj[]} - mutated sliceBuckets array
 */
function constructReturnSliceBuckets (slices, reason, sliceBuckets)
{
  /** @type {Object<string, RetSliceObj[]>} */
  const jobMap = {};
  for (const slice of slices)
  {
    assert(slice.sliceNumber > 0 );
    slice.killResult();
    if (!jobMap[slice.jobAddress]) jobMap[slice.jobAddress] = [];

    // Try to find a sliceBucket in the buckets which matches the job, estimation status, reason, and auth message.
    let sliceBucket = jobMap[slice.jobAddress].find(desc => {
      return desc.isEstimationSlice === slice.isEstimation
        && desc.authorizationMessage === slice.authorizationMessage
        && desc.reason === reason;
    });

    if (!sliceBucket)
      jobMap[slice.jobAddress].push(slice.getMessage('return', { isEstimationSlice: slice.isEstimation, reason }));
    else sliceBucket.sliceNumbers.push(slice.sliceNumber);
  }

  if (!sliceBuckets)
    sliceBuckets = [];
  for (const value of Object.values(jobMap))
    sliceBuckets.push(...value);
  return sliceBuckets;
}

/**
 * Compress array of slice-like objects.
 * XXXpfr @todo TEMP -- Simplify sup2 replaces sup1; since compressSlices is hardcoded to use Supervisor which is abmiguous from worker/USE_SUPERVISOR2.
 * @param {Array<{ sliceNumber: number, jobAddress: string }>} sliceArray
 * @returns {string}
 */
function compressSlices (sliceArray)
{
  const jobSliceMap = utils.toJobMap(sliceArray, slice => slice.sliceNumber);
  return utils.compressJobMap(jobSliceMap, addressTruncationLength);
}

/**
 * If obj: jobAddress -> slice then compressJobMap(obj, (slice) => slice.sliceNumber).
 * @param {*} obj - Object whose properties are jobAddress strings and values are array of slice-like objects.
 * @param {Function} [functor]
 * @returns {string}
 */
function compressJobMap (obj, functor)
{
  return utils.compressJobMap(obj, addressTruncationLength, functor);
}

/**
 * Check whether access with which is valid connection name for supervisor.
 * @param {string} which - 'taskDistributor', 'resultSubmitter', 'eventRouter', or 'packageManager'
 */
function checkConnectionName (which)
{
  const candidates = [ 'taskDistributor', 'resultSubmitter', 'eventRouter', 'packageManager' ];
  if (!candidates.includes(which))
    throw new Error(`${which} is not a vaild name of a supervisor connection`);
}

/**
 * Forward truncation pattern to Slice, Sandbox and JobManager.
 * @param {string[]|string} address
 * @returns {string[]|string}
 */
function truncateAddress (address)
{
  if (address instanceof Array)
    return address.map((x) => utils.truncateAddress(x, addressTruncationLength));
  return utils.truncateAddress(address, addressTruncationLength);
}

/**
 * @param {Slice[]} sliceInventory
 * @returns {{ ready: number, reserved: number, working: number, workdone: number, complete: number, failed: number, finished: number, unassigned: number }}
 */
function sliceCounts (sliceInventory)
{
  let ready = 0, reserved = 0, working = 0, workdone = 0, complete = 0, failed = 0, finished = 0, unassigned = 0;
  for (const slice of sliceInventory)
    if (slice.isReady) ready++;
    else if (slice.isReserved) reserved++;
    else if (slice.isWorking)  working++;
    else if (slice.isWorkDone) workdone++;
    else if (slice.isComplete) complete++;
    else if (slice.isFailed)   failed++;
    else if (slice.isFinished) finished++;
    else if (slice.isUnassigned) unassigned++;
    else throw new Error(`sliceCounts: Unexpected kind a slice; ${slice.identifier}`);
  return { ready, reserved, working, workdone, complete, failed, finished, unassigned };
}

/**
 * Flag to display detailed debug info in diagnostics.
 * @return {boolean}
 */
function displayMaxDiagInfo ()
{
  return (Boolean(DCP_ENV.getenv('DCP_SUPERVISOR_DEBUG_DISPLAY_MAX_INFO')) || debugBuild);
}

//
// Tools for debugging supervisor2.
//
class DebuggingTools
{
  /**
   * @constructor
   * @param {Supervisor} supervisor
   */
  constructor (supervisor)
  {
    /** @type {Supervisor} */
    this.supervisor = supervisor;
    /**
     * History of CPUTime + GPUTime
     * @type {string[]}
     */
    this.localRawData = [];
    /**
     * History of EMA time series entries for CPUTime + GPUTime
     * @type {string[]}
     */
    this.localData = [];
    /**
     * History of EMA time series entries for sliceCPUTime + sliceGPUTime
     * @type {string[]}
     */
    this.globalData = [];
  }

  /**
   * Remove all entries containing jobAddress.
   * @param {string} jobAddress
   */
  cleanUpDeadJob (jobAddress)
  {
    jobAddress = truncateAddress(jobAddress).toLowerCase();
    this.localRawData = this.localRawData.filter((entry) => !entry.toLowerCase().includes(jobAddress));
    this.localData = this.localData.filter((entry) => !entry.toLowerCase().includes(jobAddress));
    this.globalData = this.globalData.filter((entry) => !entry.toLowerCase().includes(jobAddress));
    selectiveDebug() && console.debug('cleanUpDeadJob', jobAddress, this.globalData);
  }

  /**
   * Count the # of assigned, working, terminated, read_for_assign sandboxes.
   * @returns {{ assigned: number, working: number, terminated: number, read_for_assign: number }}
   */
  dumpSandboxState ()
  {
    const assigned = [], working = [], terminated = [], read_for_assign = [];
    for (const sandbox of this.supervisor.sandboxInventory)
    {
      if (sandbox.isAssigned) assigned.push(sandbox);
      else if (sandbox.isWorking) working.push(sandbox);
      else if (sandbox.isTerminated) terminated.push(sandbox);
      else if (sandbox.isReadyForAssign) read_for_assign.push(sandbox);
    }
    return { assigned: assigned.length, working: working.length, terminated: terminated.length, read_for_assign: read_for_assign.length };
  }

  /** @type {{ ready: number, reserved: number, working: number, workdone: number, complete: number, failed: number, finished: number }} */
  get sliceCounts ()
  {
    let ready = 0, reserved = 0, working = 0, workdone = 0, complete = 0, failed = 0, finished = 0;
    for (const jobMan of this.supervisor.jobManagerInventory)
      for (const slice of jobMan.sliceInventory)
        if (slice.isReady) ready++;
        else if (slice.isReserved) reserved++;
        else if (slice.isWorking)  working++;
        else if (slice.isWorkDone) workdone++;
        else if (slice.isComplete) complete++;
        else if (slice.isFailed)   failed++;
        else if (slice.isFinished) finished++;
    return { ready, reserved, working, workdone, complete, failed, finished };
  }
  /** @type {string} */
  get sliceSandboxStr ()
  {
    return `${this.sliceStr('r/rsv/w/wd/c/fail/fin/wsbx/sbx')}/${this.supervisor.workingSandboxCount}/${this.supervisor.sandboxInventory.length}`;
  }
  /** @type {string} */
  get workingSliceSandboxStr ()
  {
    return `${this.workingSliceStr('r/rsv/w/wsbx/sbx')}/${this.supervisor.workingSandboxCount}/${this.supervisor.sandboxInventory.length}`;
  }
  /**
   * @param {string} [tag='']
   * @returns {string}
   */
  workingSliceStr (tag='')
  {
    if (tag.length < 1) tag = 'r/rsv/w';
    const { ready, reserved, working } = this.sliceCounts;
    return `${tag} ${ready}/${reserved}/${working}`;
  }
  /**
   * @param {string} [tag='']
   * @returns {string}
   */
  sliceStr (tag='')
  {
    if (tag.length < 1) tag = 'r/rsv/w/wd/c/fail/fin';
    const { ready, reserved, working, workdone, complete, failed, finished } = this.sliceCounts;
    return `${tag} ${ready}/${reserved}/${working}/${workdone}/${complete}/${failed}/${finished}`;
  }
  /**
   * @param {Slice} slice
   * @param {{sliceCPUTime: number, sliceGPUTime: number, sliceCPUDensity: number, sliceGPUDensity: number, alpha: number}} metrics
   */
  addGlobal(slice, metrics)
  {
    this.globalData.push(`${slice.identifier}: ${wd.globalTime(metrics)}: alpha: ${metrics.alpha}`);
  }
  /**
   * @param {Slice}  slice
   * @param {{CPUTime: number, GPUTime: number, CPUDensity: number, GPUDensity: number}} metrics
   * @param {number} alpha
   */
  addRawLocal (slice, metrics, alpha)
  {
    this.localRawData.push(`${slice.identifier}: ${wd.localTime(metrics)}: alpha: ${alpha}`);
  }
  /**
   * @param {Slice}  slice
   * @param {number} emaSliceTime
   * @param {number} alpha
   */
  addLocal (slice, emaSliceTime, alpha)
  {
    this.localData.push(`${slice.identifier}: ${emaSliceTime}: alpha: ${alpha}`);
  }
}
exports.DebuggingTools = DebuggingTools;

