const { leafMerge } = require('dcp/utils/obj-merge');
const { rehydrateRange } = require("dcp/dcp-client/range-object");
const { encodeDataURI, generateOpaqueId } = require("dcp/utils");
const { sha256 } = require('dcp/dcp-client/wallet/keystore')._internalEth.util;

/** 
 * Make a URI for the given the storage type and details.
 * @param {string}  storageType     The storage type (range|pattern)
 * @param {string}  storageDetails  Details about the storage and/or data, which
 *                                  varies based on storageType.
 *                  - range → storageDetails is a range descriptor. The 'slice' parameter is used to specify
 *                    element of the range to create the URL for.
 *                  - pattern → storageDetails is a pattern to form a URI-encoded URI that can be fetched
 *                    by the supervisor, created by substituting parameters into the pattern.
 * @param {object}  parameters      An object used for making substitutions in URIs. Each object key is
 *                                  treated as a label which can appear between curly braces in the pattern;
 *                                  the corresponding value is then substituted into the string.
 *
 *                                  A special key, hash, is used to indicate that the substituted value
 *                                  should be the the result of calculating the hash of all the other values,
 *                                  appended together in alphabetical order of their keys.
 *
 *                                  Another special key, unique, is used to generate a random string of
 *                                  characters which is probably unique.
 *
 *                                  Both hash and unique are lazily-generated to avoid overhead. This
 *                                  routine guarantees that parameters will not be mutated.
 *
 * @returns {string} the slice URI. This could be any URI suitable for the fetchURI function, including
 *                   http:, https: and data: URIs.
 */
exports.makeValueURI = function makeValueURI(storageType, storageDetails, parameters) {
  const uriRegex = /^[a-z]+:[^ ]*/; /* note: debug only, not comprehensive */;

  if (!parameters || !(typeof parameters === 'object')) {
    throw new Error('parameters object is required');
  }

  if (!storageDetails) {
    throw new Error('storageDetails is required');
  }

  switch (storageType) {
    case 'range': {
      const ro = rehydrateRange(storageDetails);
      if (!parameters.slice) {
        throw new Error('Slice parameter is required for range storageType');
      }

      // -1 to prevent an OBOE since slice numbers start at 1.
      return encodeDataURI(ro[parameters.slice - 1]);
    }
    case 'pattern':
    {
      const { assert } = require('dcp/common/dcp-assert');
      assert(uriRegex.test(storageDetails)); /* ensure storageDetails is (probably) a URI pattern */

      /** @todo XXXwg - {key:1,2} should eventually have the args  after the colon become parameters to string.slice */
      let uri = Object.entries(parameters).reduce(
        (uri, [key, value]) => {
          const re = new RegExp(`{${key}}`, 'g');
          return uri.replace(re, value)
        },
        storageDetails
      );
      
      if (uri.indexOf('{hash}') !== -1)
      {
        const hash = sha256(Buffer.from(JSON.stringify(parameters))).toString('hex');
        uri = uri.replace(/{hash}/g, hash);
      }

      if (uri.indexOf('{unique}') !== -1)
      {
        const unique = generateOpaqueId();
        uri = uri.replace(/{unique}/g, unique);
      }
      return uri;
    }
    default:
      throw new Error(`Unknown storageType parameter "${storageType}"`);
  }
}

/**
 * Factory function which returns the curated parameters associated with a given given job/slice; these
 * patterns are used for the makeValueURI etc function to expand a URI pattern into a URI. See DCP-1480.
 *
 * @param   {object}  job             The jobs table row corresponding to the job
 * @param   {object}  extraParams     An object with extra parameters (eg sliceNumber) to add to the 
 *                                    returned value.
 */
 exports.makePatternParams = function utils$$makePatternParams(job, extraParams)
 {
   return leafMerge({
     job:     job.address,
     jobId:   job.uuid,
   }, extraParams);
 }
