/**
 * @file        env.js
 *              Module to return information about the DCP host environment
 *
 * @note        Maintenance note - this module used by debugging() during other modules'
 *              initialization - this means we should avoid debugging() calls during our
 *              own init.
 *
 * @author      Wes Garland, wes@kingsds.network
 * @date        Oct 2019
 */
const { hasNativeRequire } = require('./dcp-env-capabilities')
const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
const bundleScript = typeof document === 'object' ? document.currentScript : false;
var platform = "unknown";

// @todo - dcp-env.isBrowserPlatform is not set unless the platform is _explicitly_ set,
// using the default detected platform doesn't set it.
// Fixing that causes an error in the wallet module's startup on web platform, which I
// probably can't fix in a reasonable time this morning.
// ~ER2020-02-20

exports.platformList = [
  "unknown",
  "nodejs",
  "bravojs",
  "cjs2-generic",
  "vanilla-web"
];

exports.browserPlatformList = [
  "bravojs",
  "vanilla-web"
]

Object.defineProperty(exports, 'platform', {
  get: function dcpEnv$$platform_getter() {

    /** On initial load, the platform is 'unknown', unless you either
     *  1. are in a CJS env, in which case we use requireNative('dcp/env-native').platform, or
     *  2. this script (webpack bundle) was loaded from a script tag whose dcp-env attribute was set
     */
    if (platform === 'unknown') {
      if (hasNativeRequire) {
        try {
          // we inject this module in dcp-client
          exports.setPlatform(requireNative('dcp/env-native').platform)
        } catch (e) {
          console.warn(e);
        }
      } else if (bundleScript) {
        exports.setPlatform((platform = bundleScript.getAttribute('dcp-env') || platform))
      }
    }
    return platform
  },
  enumerable: true,
});

Object.defineProperty(exports, 'isBrowserPlatform', {
  get: function dcpEnv$$isBrowserPlatform_getter() {
    // use exports.platform, so if it is called before platform is initialized, 
    // that will be done rather than using an uninitialized value
    return exports.browserPlatformList.indexOf(exports.platform) !== -1;
  },
  enumerable: true,
});

Object.defineProperty(exports, 'isBrowserChrome', {
  get: function dcpEnv$$isBrowserChrome_getter() {
    let isBrowser = exports.browserPlatformList.indexOf(exports.platform) !== -1;
    if(isBrowser){
      return !!window.navigator.userAgent.match(/Chrome\//g);
    } 
  },
  enumerable: true,
});

exports.setPlatform = function(newPlatform) {
  if (exports.platformList.indexOf(newPlatform) === -1) {
    throw new Error('Invalid platform: ' + newPlatform);
  }
  platform = newPlatform;
  exports.setPlatformDebugStack = new Error('\rPlatform set').stack  /* Breadcrumbs in case platform gets set wrong by somebody */

  exports.initPolyfills(platform);
  return platform;
}

exports.setPlatformDebugStack = new Error('Never set')

/** Return a value based on the current platform
 *
 *  @param      cases           key-value-pair object where the key is the
 *                              name of the platform and the value is the value
 *                              to return.  An extra key, "default", is supported
 *                              in case the current platform does not match any
 *                              other key/
 *  @throws     {Error}         when the current platform is completely unhandled
 *                              (implies default key not provided)
 */
exports.switch = function env$switch(cases) {
  for (let prop in cases) {
    if (!cases.hasOwnProperty(prop))
      continue;

    if (prop === exports.platform) {
      return cases[prop]
    }
  }

  if (exports.platform === 'unknown') {
    const stack = new Error().stack;

    if (stack)
      console.warn('Warning: platform unknown in env module at', stack.split('\n')[2].replace(/^.*\(/, '').replace(/\) *$/, ''))
    else
      console.warn('Warning: platform unknown in env module');
  }

  if (cases.hasOwnProperty('default'))
    return cases.default

  throw new Error(`Platform ${exports.platform} not handled in cases object`)
}

/**
 * Add global symbols normally present in browser env but not normally
 * present in node env
 */
function addNodePolyfills()
{
  exports.global.btoa = requireNative('btoa');
  exports.global.performance = requireNative('perf_hooks').performance;
}

/**
 * Set up polyfills, which we use to set our base capabilities.
 */
exports.initPolyfills = function env$initPolyfills(platform) {
  if (platform === 'nodejs')
  {
    exports.global = global;
    addNodePolyfills();
  }
  else if (typeof globalThis !== 'undefined')
    exports.global = globalThis;
  else if (typeof window !== 'undefined')
    exports.global = window;
  else if (typeof global !== 'undefined')
    exports.global = global;
  else if (typeof self !== 'undefined')
      exports.global = self;
  if (!exports.global)
    throw new Error('Could not locate global object');
}

/**
 * Get an environment variable. On NodeJS, this is the usual process environment. On the web, the
 * process environment is emulated via the contents of window.sessionStorage.env
 *
 * @param {string}      which            the environment variable whose value we want to return
 * @returns {string}
 */
exports.getenv = function dcpEnv$$getenv(which) {
  if (exports.isBrowserPlatform) {
    try {
      let env = {};
      let envJSON = window.sessionStorage.getItem('env');
      if (envJSON)
        Object.assign(env, JSON.parse(envJSON));

      envJSON = window.localStorage.getItem('env');
      if (envJSON)
        Object.assign(env, JSON.parse(envJSON));

      return env.hasOwnProperty(which) ? env[which] : '';
    } catch(error) {
      console.error(`Could not get environment variable ${which}; ${error.message}`, error.stack || '');
    }
  } else if (exports.platform === 'nodejs') {
    const { requireNative } = require('dcp/dcp-client/webpack-native-bridge');
    return requireNative('process').env[which];
  } else {
    console.error('Could not locate platform environment');
  }
  return undefined;
}

/**
 * Get an environment variable. On NodeJS, this is the usual process environment. On the web, the
 * process environment is emulated via the contents of window.sessionStorage.env
 *
 * @param {string}      which            the environment variable whose value we want to set
 * @param {any}         value            the value we want to set it to - coerced to string before setting;
 * @param {boolean}     persist          truey to use session storage instead of local storage 
 *                                       on browser; unused for other platforms
 * @returns {string}
 */
exports.setenv = function dcpEnv$$setenv(which, value, persist)
{
  value = String(value);
  
  if (!exports.isBrowserPlatform)
    process.env[which] = value;
  else
  {
    try
    {
      let envJSON = persist ? window.sessionStorage.getItem('env') : window.localStorage.getItem('env');
      let env = envJSON ? JSON.parse(envJSON) : {};

      env[which] = value;
      (persist ? window.sessionStorage : window.localStorage).setItem('env', JSON.stringify(env));
    }
    catch(error)
    {
      console.error(`Could not set environment variable ${which}; ${error.message}`, error.stack || '');
    }
  }
}
