/**
 *  @file       origin-access-manager.js
 *              The Origin Access Manager is responsible for managing lists of origins with a given
 *              purpose and key. It contains methods to add, remove and get origins based on the `purpose`
 *              and `key`.
 * 
 *  @author     Wes Garland <wes@distributive.newtwork>
 *  @author     Kirill Kirnichansky <kirill@distributive.newtwork>
 */
'use strict';

const __any = Symbol('magic any prop');

/**
 * This class provides manages lists of origins for a given `purpose` and `key`.
 */
class OriginAccessManager {
  /**
   * @constructor
   */
  constructor () {
    this.cache = {};
    this.origins = {};
  }
  
  /**
   * This method returns a list of origins for a given purpose and key.
   * Purpose must be a string.
   * When a request is made:
   * the list will be cached internally, so that identical requests return the same list
   * A previously-added origin for the purpose null matches any purpose
   * A previously-added origin with the key null matches any key
   * 
   * @param {string} purpose
   * @param {string|null|__any} key
   * 
   * @returns {string[]} - Array containing origin(s)
   */
  getAllowList(purpose, key)
  {
    if (typeof purpose !== 'string')
      throw new Error('purpose must be a string.');
    if (key === null)
      key  = __any;
    
    const cacheKey = `${purpose}$$${typeof key === 'symbol' ? '__any' : key}`;
    
    if (!this.cache[cacheKey])
    {
      this.cache[cacheKey] = [];
      
      let purposeKeys = [key];
      let __anyKeys = [key];
      
      if (key === __any)
      {
        // __any symbol will NOT be returned with Object.keys
        if (this.origins[purpose])
          purposeKeys = Object.keys(this.origins[purpose]);
        if (this.origins[__any])
          __anyKeys   = Object.keys(this.origins[__any]);
      }
      
      purposeKeys.forEach((purposeKey) => {
        if (this.origins[purpose] && this.origins[purpose][purposeKey])
          this.cache[cacheKey] = this.cache[cacheKey].concat(this.origins[purpose][purposeKey]);
      });
      
      __anyKeys.forEach((__anyKey) => {
        if (this.origins[__any] && this.origins[__any][__anyKey])
          this.cache[cacheKey] = this.cache[cacheKey].concat(this.origins[__any][__anyKey]);
      });
      
      if (this.origins[purpose] && this.origins[purpose][__any])
        this.cache[cacheKey] = this.cache[cacheKey].concat(this.origins[purpose][__any]);
      
      if (this.origins[__any] && this.origins[__any][__any])
        this.cache[cacheKey] = this.cache[cacheKey].concat(this.origins[__any]  [__any]);
    }
    
    return this.cache[cacheKey];
  }
  
  /** 
   * This method returns True when the origin is allowed for a given purpose and key.
   * Purpose must be a string.
   * 
   * @param {string} origin
   * @param {string} purpose
   * @param {string|null|__any} [key=null]
   * 
   * @returns {boolean} - True if the origin is allowed, false if not.
   */ 
  isAllowed(origin, purpose, key = null)
  {
    if (typeof purpose !== 'string')
      throw new Error('purpose must be a string.');
    if (key === null)
      key  = __any;
    else if (typeof key !== 'string')
      throw new Error('key must be a string or null.');
    
    if (this.origins[purpose] && this.origins[purpose][key] && this.origins[purpose][key].indexOf(origin) !== -1)
      return true;
    const allowList = this.getAllowList(purpose, key);
  
    return allowList.indexOf(origin) !== -1;
  }
  
  /**
   * This method adds an origin with a specified purpose and key to the OriginAccessManager.
   * Purpose and key can be either strings or null.
   * 
   * @param {string} origin
   * @param {string|null|__any} purpose
   * @param {string|null|__any} key
   */
  add(origin, purpose, key)
  {
    this.cache = {};
    
    if (purpose === null)
      purpose = __any;
    else if (typeof purpose !== 'string')
      throw new Error('purpose must be a string or null.');
    
    if (key === null)
      key = __any;
    else if (typeof key !== 'string')
      throw new Error('key must be a string or null.');
    
    if (!this.origins.hasOwnProperty(purpose))
      this.origins[purpose] = {};
    if (!this.origins[purpose].hasOwnProperty(key))
      this.origins[purpose][key] = [];
  
    if (this.origins[purpose][key].indexOf(origin) === -1)
      this.origins[purpose][key].push(origin);
  }
  
  /**
   * This method removes an origin with the given purpose and key.
   * null purpose and/or key will NOT match any purpose and key.
   * 
   * @param {string} origin
   * @param {string|null|__any} purpose
   * @param {string|null|__any} key
   * 
   * @returns {boolean} - false if origin, purpose and/or key doesn't exist.
   */
  remove(origin, purpose, key)
  {
    this.cache = {};
    
    if (purpose === null)
      purpose = __any;
    else if (typeof purpose !== 'string')
      throw new Error('purpose must be a string or null.');
    
    if (key === null)
      key = __any;
    else if (typeof key !== 'string')
      throw new Error('key must be a string or null.');
    
    if (!this.origins[purpose])
      return false;
    if (!this.origins[purpose][key])
      return false;
  
    const idx = this.origins[purpose][key].indexOf(origin);
    if (idx === -1)
      return false;
    
    this.origins[purpose][key].splice(idx, 1);
  }

  /**
   * This method removes all origins for all purposes for a given String key.
   * 
   * @param {string} key
   */
  remove_byKey(key)
  {
    if (typeof key !== 'string')
      throw new Error('key must be a string.');
    
    this.cache = {};
    
    let purposes = Object.keys(this.origins);
    for (let purpose of purposes)
      delete this.origins[purpose][key];
    
    delete this.origins[__any][key];
  }

  /**
   * Creates an instance of OriginAccessManager and adds origins from supervisor options accordingly.
   *
   * Note: this could be moved to the constructor of OriginAccessManager, however, we would need
   * to make assumptions on the origins object passed to the ctor (that it will always be like
   * options.allowOrigins). Since we also define a relationship between 'any' in options.allowOrigins
   * and a null purpose, this is another special behaviour that the OAM class directly may not care about.
   *
   * @param {{any: string[],
   *          fetchData: string[],
   *          fetchWorkFunctions: string[],
   *          fetchArguments: string[],
   *          sendResults: string[]}} allowOrigins - Either Supervisor1.options.allowOrigins or Supervisor2.options.allowOrigins
   *
   * @returns {OriginAccessManager}
   */
  static construct(allowOrigins) {
    const originManager = new OriginAccessManager();

    if (allowOrigins)
    {
      for (let prop of Object.getOwnPropertyNames(allowOrigins))
        allowOrigins[prop].forEach(origin => originManager.add(origin, (prop === 'any' ? null : prop), null));
    }

    return originManager;
  }

}

exports.OriginAccessManager = OriginAccessManager;
