/**
 *  @file       protocol/connection/request.js
 *  @author     Ryan Rossiter, ryan@kingsds.network
 *  @date       January 2020
 *
 *  The ConnectionRequest is a factory for a request class that extends a bound
 *  Message class.
 */
'use strict';

let nanoid = require('nanoid').nanoid;

const { assert }        = require('dcp/common/dcp-assert');
const wallet = require('dcp/dcp-client/wallet');

exports.requestCtorFactory = function requestCtorFactory(Message)
{
  class Request extends Message
  {
    static type = 'request';

    /**
     * There are 3 forms for this constructor (new Connection.Request()):
     *  1. Request(): A new request is constructed
     *  2. Request({object} payload, {Keystore} [keystore]): Request is constructed with the given payload (operation, data)
     *  3. Request({string} operation, {any} [data], {Keystore} [keystore])
     *
     *  @todo see if we can eliminate form 3 /wg aug 2023
     */
    constructor(...args)
    {
      super();

      this.ref();
      this.resourceKeystores = new Map(); // resourceAddress => keystore
      this.type = 'request';
      this.auth = {};
      this.payload = {
        operation: null,
        allow: [],
        validity: {
          stamp: nanoid(),
          ttl: Message.connection.options.ttl.default,
          time: null, // set on send
        }
      };

      let ks;
      if (args[args.length - 1] instanceof wallet.Keystore) {
        ks = args.pop();
      }

      if (typeof args[0] === 'object')
        Object.assign(this.payload, args[0]);
      else if (typeof args[0] === 'string')
      {
        Object.assign(this.payload, {
          operation: args[0],
          data: args[1],
        });
      }

      if (typeof this.payload.operation !== 'string' && this.payload.operation !== null)
        throw new Error('Invalid Request operation');

      if (ks instanceof wallet.Keystore)
        this.ctorAuthPromise = this.authorize(ks); // Defer awaiting this promise until sign()
    }

    /**
     * Sign a Request Message which is about to be sent to the peer. This differs from regular Message
     * signing in that Requests can have authorization sections which need to be signed at the same time
     * as the outer envelope, potentially with different keystores.
     */
    async sign(nonce, ackToken)
    {
      var networkObj = await super.preSign(nonce, ackToken);

      await this.ctorAuthPromise;       // Since we can't await authorize in the constructor, do it here

      networkObj.auth = this.auth || {};
      for (const [resourceAddress, ks] of this.resourceKeystores)
        networkObj.auth[resourceAddress] = await ks.makeSignature(networkObj.payload);

      return Message.connection.identity.makeSignedMessage(networkObj);
    }

    /**
     * This static method is used by the connection to rehydrate a request that was received.
     * @param {object} requestObj
     */
    static fromNetwork(networkObj)
    {
      const req = super.fromNetwork(networkObj);

      req.auth    = req.auth    || {};
      req.payload = req.payload || {};

      return req;
    }

    /**
     * This method is used to dehydrate the request into a plain object before it is sent to the peer.
     * @returns {object} - An object that will be sent as-is to the peer
     */
    toNetwork()
    {
      const networkObj = super.toNetwork();
      if (!networkObj.payload.validity.time)
        networkObj.payload.validity.time = Message.connection.currentTime();
      return networkObj;
    }

    /**
     * Resolves when the remote has acknowledged receipt of the response. Rejects if the network
     * connection is closed before that happens.
     */
    respond(...args)
    {
      const res = new Message.connection.Response(this, ...args);
      return res.send();
    }

    /**
     * Resolves when the remote has responded to the message. Rejects if the network connection is
     * closed before that happens.
     *
     * @param {wallet.Keystore} [resourceKeystore] - optional resource keystore to provide authorization with,
     *      shorthand for this.authorize(resourceKeystore)
     */
    async send(resourceKeystore)
    {
      if (resourceKeystore)
        await this.authorize(resourceKeystore);

      return super.send();
    }

    /**
     * This method authorizes `guardian` to use `resource` if `guardian`'s peer is `accessor`.
     *
     * @note: If the guardianAddress is not specified, the default is the peer address.
     *  If the connection is not established, this method will complete the connection
     *  then complete the authorization.
     *
     * @param {wallet.Keystore} [resourceKeystore=wallet.get()]
     * @param {wallet.Address} [guardianAddress=this.connection.peerAddress]
     * @param {wallet.Address} [accessorAddress=this.connection.identity.address]
     */
    async authorize(resourceKeystore, guardianAddress, accessorAddress)
    {
      if (!resourceKeystore)
        resourceKeystore = await wallet.get();

      if (!(resourceKeystore instanceof wallet.Keystore))
        throw new Error("First argument to authorize must be instance of wallet.Keystore");

      // to supply default guardian and accessor, the connection must be established
      if (!guardianAddress || !accessorAddress && Message.connection.state.in(['initial', 'connecting']))
        await Message.connection.connect();

      assert(accessorAddress || Message.connection.identity);
      assert(guardianAddress || Message.connection.peerAddress);

      if (!guardianAddress)
        guardianAddress = wallet.Address(Message.connection.peerAddress);

      if (!accessorAddress)
        accessorAddress = wallet.Address(Message.connection.identity.address);

      guardianAddress = wallet.Address(guardianAddress);
      accessorAddress = wallet.Address(accessorAddress);

      const resourceAddress = resourceKeystore.address;
      if (!this.doesAuthorize(resourceAddress, guardianAddress, accessorAddress, false))
      {
        this.payload.allow.push({
          resource: resourceAddress.toString(),
          guardian: guardianAddress.toString(),
          accessor: accessorAddress.toString(),
        });

        if (!this.resourceKeystores.has(resourceAddress.toString()))
        {
          // Call unlock once so that we know it will be available to sign with
          await resourceKeystore.unlock();
          this.resourceKeystores.set(resourceAddress.toString(), resourceKeystore);
        }
      }
    }

    /**
     * This method is primarily used by the recipient of a message to verify
     * that it has been signed by the owner of the resource in question.
     *
     * @param {wallet.Address} resourceAddress
     * @param {wallet.Address} [guardianAddress=Message.connection.identity.address]
     * @param {wallet.Address} [accessorAddress=Message.connection.peerAddress]
     * @param {boolean} [validateSignature=true] - whether or not to also validate the signature provided on the auth object
     * @returns {boolean}
     */
    doesAuthorize(resourceAddress, guardianAddress = Message.connection.identity.address, accessorAddress = Message.connection.peerAddress, validateSignature=true)
    {
      resourceAddress = wallet.Address(resourceAddress);
      guardianAddress = wallet.Address(guardianAddress);
      accessorAddress = wallet.Address(accessorAddress);

      const inAllowList = this.payload.allow.some(({ resource, guardian, accessor }) => {
        return resourceAddress.eq(resource)
          && guardianAddress.eq(guardian)
          && accessorAddress.eq(accessor);
      });

      let isGuardianAuthorized = inAllowList;
      if (isGuardianAuthorized && validateSignature)
      {
        const signature = this.auth[resourceAddress.toString()];
        isGuardianAuthorized = !!(signature && resourceAddress.verifySignature(this.payload, signature));
      }

      return isGuardianAuthorized;
    }
  }

  return Request;
}
