/**
 *  @file       protocol/connection/identity-cache.js
 *  @author     Nazila Akhavan, Nazila@kingsds.network
 *  @date       January 2020
 *
 * The identity cache is used to ensure that for any connection baseHref and identity are match,
 * then insert them into the cache (browser/ node). It is also used to clear the cache. 
 * 
 * @todo: Consider replacing the node API calls with dcp-localstorage // RR March 2020
 */
'use strict';

const IDENTITY_CACHE_LOCAL_STORAGE_KEY = 'idCache';
const env = require('dcp/common/dcp-env');
const { fs, requireNative } = require('dcp/dcp-client/webpack-native-bridge');
const { Address } = require('dcp/dcp-client/wallet');
const debugging = require('dcp/debugging').scope('dcp');

class IdentityCache {
  constructor() {
    this.identities = { /* baseHref: address */};

    if (env.isBrowserPlatform) {
      try {
        this.identities = JSON.parse(window.localStorage.getItem(IDENTITY_CACHE_LOCAL_STORAGE_KEY)) || {};
        this.initIdentities();
      } catch (e) {
        debugging() && console.warn('Failed to parse identity cache from local storage', e);
      }
    } else if (fs.existsSync(this.cacheFilePath)) {
      let fd = fs.openSync(this.cacheFilePath)
      let stat = fs.fstatSync(fd);
      let buffer = Buffer.alloc(stat.size);
      fs.readSync(fd, buffer, 0, buffer.length, 0);
      fs.closeSync(fd);
      
      const cacheFile = buffer.toString('ascii');
      if (buffer.length) {
        this.identities = JSON.parse(cacheFile);
        this.initIdentities();
      }
    }
  }

  get cacheFolder() {
    return require('dcp/common/dcp-dot-dir').dotDcpDir;
  }

  get cacheFilePath() {
    const path = requireNative('path');
    return path.resolve(this.cacheFolder, dcpConfig.dcp.identityCache?.filename || 'identity-cache.json');
  }

  /**
   * Initialize Address instances for the identities after they are
   * retrieved from the cache.
   */
  initIdentities() {
    for (let baseHref in this.identities) {
      this.identities[baseHref] = new Address(this.identities[baseHref]);
    }
  }

  /**
   * Learn a new identity.  In DCP, we always assume that the first identity we see for a given baseHref
   * is the authoritative one, unless contradicted at some point in the future by a presharedAddress. In
   * the case where the the psA is in conflict with what we already knew, we emit a log warning.
   *
   * @param {object} url                a URL containing the base href (origin and pathname) associated 
   *                                    with this identity
   * @param {object} identity           instance of eth::Address 
   * @param {object} presharedAddress   optional - address which is shared out-of-band (eg https) that we
   *                                    *know* is safe for this resource and so can override our extant
   *                                    knowledge
   *
   * @return false if what we have learned is in conflict with what's already in the cache (and not psA)
   *         true  if we were allowed to learn that this is the identity associated with
   * 
   */
  learnIdentity (url, identity, presharedAddress)
  {
    const baseHref = url.origin + url.pathname;

    if (presharedAddress && identity.eq(presharedAddress))
    {
      if (!this.identities.hasOwnProperty(baseHref) || !identity.eq(this.identities[baseHref]))
      {
        /* This should never happen unless the server has changed its private key, or we are in a MITM attack */
        if (this.identities[baseHref])
          console.warn(`**** Warning: preshared peer address ${presharedAddress} replaces ${this.identities[baseHref]} in identity cache ****`);
        this.identities[baseHref] = String(identity);
      }
      return true;
    }

    if (this.identities.hasOwnProperty(baseHref))
      return identity.eq(this.identities[baseHref]);

    this.identities[baseHref] = String(identity);
    return true;
  }

  /**
   * Return the identity associated with a given URL.
   *
   * @param {object} url                a URL containing the base href (origin and pathname) for
   *                                    the identity we seek
   */
  getIdentity(url) {
    const baseHref = url.origin + url.pathname;
    return this.identities[baseHref];
  }

  /** Save identities to the local storage or identity-cache.json */
  saveIdentities() {
    if (false
        || dcpConfig.dcp.identityCache?.disable === true
        || dcpConfig.dcp.identityCache?.disable === 'write'
        || env.getenv('DCP_IDENTITY_CACHE_WRITE_DISABLE'))
      return;
    if (env.isBrowserPlatform) {
      window.localStorage.setItem('idCache', JSON.stringify(this.identities, null, 2));

    } else if (env.platform === 'nodejs') {
      try {
        if (!fs.existsSync(this.cacheFolder)){
          fs.mkdirSync(this.cacheFolder, { recursive: true });
        }

        fs.writeFileSync(this.cacheFilePath, JSON.stringify(this.identities));

        fs.chmodSync(this.cacheFilePath, 0o700);
      } catch (e) {
        debugging() && console.error('Failed to save identity cache to file:', e.message);
      }
    }
  }

  clearAll () {
    this.identities = { };
    this.saveIdentities();
  }

  clearIdentity (id) {
    for (let baseHref in this.identities) {
      if (this.identities[baseHref].eq(id)) {
        delete this.identities[baseHref];
      }
    }
    this.saveIdentities();
  }
}

let singleton = null;

/** @returns {IdentityCache} */
exports.getGlobalIdentityCache = function() {
  if (!singleton) {
    singleton = new IdentityCache();
  }

  return singleton;
}
