{
  if (transport !== this.transport || this.state.is('closed')) /* event no longer relevant */
    return;

  debugging('connection') && console.debug(this.debugLabel, 'hangupHandler invoked in state', String(this.state));
  this.transport = false;
  this.emit('disconnect', this.targetDescriptor.location); /* UI hint: "internet unavailable" */

  /* Gate; either transition established|connecting -> disconnected or bail */
  switch(String(this.state))
  {
    case 'initial':
    default:
      assert(false);
      break;
    case 'disconnected':
    case 'closing':
    case 'closed':
      return; /* transports may fire this handler more than once */
    case 'connecting': /* network interrupt during re-connection attempt, keep reconnecting until connectTimeout */
      if (this.connectingPromiseHnd)
        return; /* implies we are already in connect(); this situation handled in enlistTransport */
      /* fallthrough */
    case 'established':
      debugging('connection') && console.debug(this.debugLabel, `Transport disconnected from ${this.targetDescriptor.location} while ${this.state}`);
      this.state.set(['established', 'connecting'], 'disconnected');
      break;
  }

  if (this.role.is('target'))
  {
    /* targets generally can't reconnect due to NAT and more - instead we linger */
    if (this.dcpsid)
      debugging('connection') && console.debug(this.debugLabel, `Waiting for initiator to reconnect for ${this.dcpsid}`);
    else
    {
      debugging('connection') && console.debug(this.debugLabel, 'target connection has no dcpsid; cannot linger for reconnect');
      this.close(); /* can't linger when no dcpsid */
    }
    return;
  }

  if (this.options.onDemand && !this.hasPendingTx())
  {
    debugging('connection') && console.debug(this.debugLabel, `Not reconnecting ${this.dcpsid} until next message`);
    return;
  }

  /* At this point, we initiate a (re)connect attempt because either
   * - we have something to send, or
   * - we are not an on-demand connection
   */
  debugging('connection') && console.debug(this.debugLabel, 'hangupHandler invoking connect');
  this.connect().catch((error) => {
    if (error.code !== 'ETIMEDOUT' && error.code !== 'EPIPE')
      debugging('connection') && console.debug(this.debugLabel, 'unexpected error handling disconnect:', error);
  });
}

/**
 * Perform basic sanity checking on connection options.
 * @throws TypeError if insane options are specified
 */
function optionsSanityCheck(options)
{
  function notNegativeNumber(prop)
  {
    var value, path;

    for (value = options, path = prop.split('.');
         path.length;
         value = value[path.shift()])
      ; /* walk the dot path to the end */
    if (!(value > 0))
      throw new TypeError(`option ${prop} has invalid value ${options[prop]}`);
  }

  notNegativeNumber('identityUnlockTimeout');
  notNegativeNumber('connectTimeout');
  notNegativeNumber('reconnectTimeout');
  notNegativeNumber('lingerTimeout');
  notNegativeNumber('closeTimeout');
  notNegativeNumber('ttl.min');
  notNegativeNumber('ttl.max');
  notNegativeNumber('ttl.default');
}
