 /**
  * Writes object properties into another object matching shape.
  * For example: if obj = { a: { b: 1, c: 2}}
  * and             source = { a: {c: 0, d: 1}}
  * then obj will be updated to { a: { b: 1, c: 0, d: 1 } }
  * compare this to Object.assign which gives { a: { c: 0, d: 1 } }
  */
const setObjProps = module.exports.setObjProps = (obj, source) => {
  for (let p in source) {
    if (typeof source[p] === 'object') setObjProps(obj[p], source[p]);
    else obj[p] = source[p];
  }
}


/**
 * Generates a new random opaqueId i.e. a 22-character base64 string.
 * Used for job and slice ids.
 */
module.exports.generateOpaqueId = function utils$$generateOpaqueId()
{
  const schedulerConstants = require('dcp/common/scheduler-constants');
  if (!utils$$generateOpaqueId.nanoid)
  {
    const nanoidModule = require('nanoid');
    utils$$generateOpaqueId.nanoid = nanoidModule.customAlphabet('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789+', schedulerConstants.workerIdLength);
  }

  return utils$$generateOpaqueId.nanoid();
}

/**
 * Accepts an object and a list of properties to apply to the object to retreive a final value.
 * E.g.
 *  object = { a: { b: { c: 4 } } }
 *  listOfProperties = ["a", "b", "c"]
 *  return = 4
 */
module.exports.getNestedFromListOfProperties = function (object, listOfProperties) {
  return listOfProperties.reduce((o, k) => {
    if (typeof o !== 'object') return undefined;
    return o[k];
  }, object);
}

/**
 * Accepts an object and a dot-separated property name to retrieve from the object.
 * E.g.
 *  object = { a: { b: { c: 4 } } }
 *  property = 'a.b.c'
 *  return = 4
 *
 * @param {object} object 
 * @param {string} property 
 */
module.exports.getNestedProperty = function (object, property) {
  if (typeof property !== 'string') return undefined;
  return module.exports.getNestedFromListOfProperties(object, property.split("."));
}

/**
 * Accepts an object and a list of properties and a value and mutates the object
 * to have the specified value at the location denoted by the list of properties.
 * Similar to getNestedFromListOfProperties, but sets instead of gets.
 */
module.exports.setNestedFromListOfProperties = function (object, listOfProperties, value) {
  if(!listOfProperties.length || listOfProperties.length < 1) {
    throw new Error("listOfProperties must be an array of length >= 1");
  }
  const indexOfLastProp = listOfProperties.length - 1;
  const pathToParent = listOfProperties.slice(0, indexOfLastProp);
  const parent = module.exports.getNestedFromListOfProperties(object, pathToParent);
  if(!parent) {
    throw new Error("Could not find value at:", pathToParent, "in object:", object);
  }
  const lastProperty = listOfProperties[indexOfLastProp];
  parent[lastProperty] = value;
}

/**
 * Block the event loop for a specified time
 * @milliseconds        the number of milliseconds to wait (integer)
 */
exports.msleep = function utils$$msleep(milliseconds) {
  try
  {
    let sab = new SharedArrayBuffer(4);
    let int32 = new Int32Array(sab);
    Atomics.wait(int32, 0, 0, milliseconds);
  }
  catch(error)
  {
    console.error('Cannot msleep;', error);
  }
}

/**
 * Block the event loop for a specified time
 * @seconds     the number of seconds to wait (float)
 */
exports.sleep = function utils$$sleep(seconds) {
  return exports.msleep(seconds * 1000);
}

/** 
 * Resolve a promise after a specified time.
 * 
 * @param {number} ms      the number of milliseconds after which to resolve the promise.
 * @returns Promise with an extra property, intr(). Calling this function causes the promise
 *          to resolve immediately. If the promise was interrupted, it will resolve with false;
 *          otherwise, true.
 */
exports.a$sleepMs = function a$sleepMs(ms)
{
  var interrupt, timerHnd;
  
  const ret = new Promise((resolve, reject) => {
    var resolved = false;
    timerHnd = setTimeout(function __a$sleepMs() { resolved=true; resolve(false) }, ms);
    function a$sleepMs_intr()
    {
      clearTimeout(timerHnd);
      if (!resolved)
        resolve(true);
    }
      
    interrupt = a$sleepMs_intr;
  });

  ret.intr = () => interrupt();
  ret.unref = () => {
    timerHnd.unref();
    return ret;
  }
  return ret;
}

/** 
 * @see: a$sleepMs
 * @param {number} ms      the number of milliseconds after which to resolve the promise.
 */
exports.a$sleep = function a$sleep(seconds) {
  return exports.a$sleepMs(seconds * 1000);
}

/** 
 * Returns the number of millisecond in a time expression.
 * @param s {number}    The number of seconds
 * @returns {number}
 */
/**
 * @param s {string|number} - A complex time expression using m, w, d, s, h. '10d 6h 1s' means 10 days, 6 hours, and 1 second.
 */
exports.ms = function utils$$ms(s)
{
  let ms = 0;
  
  if (typeof s === 'number')
    return s * 1000;

  assert(typeof s === 'string');
  
  for (let expr of s.match(/[0-9.]+[smhdw]/g))
  {
    let unit = expr.slice(-1);
    let value = +expr.slice(0, -1);

    switch(unit)
    {
      case 's': {
        ms += value * 1000;
        break;
      }
      case 'm': {
        ms += value * 1000 * 60;
        break;
      }
      case 'h': {
        ms += value * 1000 * 60 * 60;
        break;
      }
      case 'd': {
        ms += value * 1000 * 60 * 60 * 24;
        break;
      }
      case 'w': {
        ms += value * 1000 * 60 * 60 * 24 * 7;
        break;
      }
      default: {
        throw new Error(`invalid time unit ${unit}`);
      }
    }
  }

  return ms;
}

