/**
 * Returns a percentage as a number.
 * @param n {number|string}    this number is returned
 * @returns {number}
 */
exports.pct = function utils$$pct(n)
{
  if (typeof n === 'number')
    return n / 100;

  if (n.match(/%$/))
    return +n / 100;

  return +n;
}

/**
 * Coerce human-written or registry-provided values into Boolean in a sensisble way.
 */
exports.booley = function utils$$booley(check)
{
  switch (typeof check)
  {
    case 'undefined':
      return false;
    case 'string':
      return check && (check !== 'false');
    case 'boolean':
      return check;
    case 'number':
    case 'object':
      return Boolean(check);
    default:
      throw new Error(`can't coerce ${typeof check} to booley`);
  }
}

