/** 
 * Factory function which constructs an error message relating to version mismatches
 * @param {string}     oldThingLabel           The name of the thing that is too old
 * @param {string}     upgradeThingLabel       [optional] The name of the thing that needs to be upgraded to fix that; if
 *                                             unspecified, we use oldThingLabel.
 * @param {string}     newThingLabel           What the thing is that is that is newer than oldThingLabel
 * @param {string}     minimumVersion          The minimum version of the old thing that the new thing supports. 
 *                                             Obstensibibly semver, but unparsed.
 * @param {string}     code                    [optional] A code property to add to the return value
 *
 * @returns instance of Error
 */
exports.versionError = function dcpClient$$versionError(oldThingLabel, upgradeThingLabel, newThingLabel, minimumVersion, code)
{
  function repeat(what, len) {
      let out = '';
      while (len--)
        out += what;
      return out;
    }

  function bold(string) {
    if (require('dcp/common/dcp-env').platform === 'nodejs') {
      const chalk = new (requireNative('chalk').Instance)({level: exports.useChalk ? 1 : 0});

      return chalk.yellow(string);
    }

    return string;
  }
  
  var mainMessage = `${oldThingLabel} is too old; ${newThingLabel} needs version ${minimumVersion}`;
  var upgradeMessage = bold(`Please upgrade ${upgradeThingLabel || oldThingLabel}${repeat(" ", mainMessage.length - 15 - upgradeThingLabel.length)}`);
  var error = new Error(`
****${repeat('*', mainMessage.length)}****
*** ${repeat(' ', mainMessage.length)} ***
*** ${mainMessage} ***
*** ${upgradeMessage} ***
*** ${repeat(' ', mainMessage.length)} ***
****${repeat('*', mainMessage.length)}****
`);

  if (code)
    error.code = code;
  return error;
}

