/**
 * Randomly shuffle array.
 * @param {Array<any>} array
 */
exports.shuffle = function utils$$shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const temp = array[i];
    array[i] = array[j];
    array[j] = temp;
  }
}

exports.hashGeneration = function utils$$hashGeneration(object) {
  const { sha256 } = require('dcp/dcp-client/wallet/keystore')._internalEth.util;
  return sha256(Buffer.from(JSON.stringify(object)));
}

