/**
 *  @file       alert.js
 *              Replacement for native `window.alert` to fit in with the rest of our modal system.
 * 
 *  @author     Nazila Kharazian - nazila@kingsds.network
 *  @date       Apr 2020
 */
const utils = require('./utils');

exports.config = {
  id: 'dcp-modal-alert',
  required: ['dcp-modal-alert-form', 'dcp-modal-alert-message', 'dcp-modal-alert-submit-button'],
  optional: ['dcp-modal-alert-title'],
  path: "./templates/alert-modal.html",
};

/**
 * @param {string} message The text which will be alerted.
 * @param {Object} message An instanceof Error whose message will be alerted, and stack trace made available.
 * @param {Object} options
 * @param {string} [options.submit="OK"] Text on the submit button.
 * @param {string} [options.title=""] Text in the title area.
 * @param {function} [options.onClose] Override default onClose behavior. An instance of `modal` is handed to the function.
 * @throws If modal is closed without the form being submitted (submitting the form closes the modal).
 * @memberof module:dcp/client-modal
 * @alias alert
 * @async
 * @access public
 */
exports.alert = async function (message, {submit = "OK", title = "", onClose = null} ={}) {
  const [elements, formPromise, optionalElements] = await utils.initModal(exports.config, onClose);
  const [modal, form, formMessage, submitButton] = elements;
  const [modalTitle] = optionalElements;
  
  if(message instanceof Object && !(message instanceof Error))
    message =JSON.stringify(message, null, 2);

  formMessage.innerText = message;
  submitButton.textContent = submit;
  if (modalTitle) modalTitle.innerText = title;

  if (message instanceof Error) {
    let bug = modal.querySelector('.dcp-bug-icon');
    let stack = modal.querySelector('.dcp-stack-trace');
    
    modal.classList.add('exception');
    if (bug)
      bug.addEventListener('click', () => modal.classList.toggle('dcp-show-stack'));
    if (stack && message.stack)
      stack.textContent = message.stack.replace(new RegExp('@webpack:/*', 'g'), '@');
  } else {
    modal.classList.remove('exception');
  }
  
  await formPromise;
  utils.MicroModal.close(modal.id);
}
